-- TheBest v016: packed resources loaded from companion files.
local function readTheBestPackedResource(id)
 local file="thebest/runtime-v016/resources/"..id..".b64"
 local ok,content=pcall(readfile,file)
 assert(ok and type(content)=="string" and #content>0,"TheBest v016: missing resource "..id.."; restore the runtime-v016 folder.")
 return content
end
-- Settings ownership fix: retire the previous generation before reading saved settings.
do
 local previousShutdown=rawget(_G,"TheBestEmergencyShutdown")
 if type(previousShutdown)=="function" then pcall(previousShutdown) end
end
local SaveConfig,SaveKeybinds
-- TheBest v015 (2026-10-19): requested item/quest/parry repairs, catalog model recovery, Colosseum markers and Blue Jack outfit.
-- TheBest: public, keyless full source build.
-- The complete readable menu is embedded in this file and runs without a key,
-- HWID binding, an expiry date, or a remote code loader.

local ASSET_URL = "https://fingernail-loader.assqwesersed.workers.dev/"
local CONFIG_DIRECTORY = "thebest"
local CONFIG_FILE = "thebest/config.json"
local KEYBINDS_FILE = "thebest/keybinds.json"
local ASTOLFO_BACKGROUND_FILE = "thebest/astolfo-background.jpg"
local HOMELANDER_FINISHER_NAME = "Homelander Lightning"
local HOMELANDER_FINISHER_FILE = "thebest/homelander-lightning.jpg"
local GOLDA_FINISHER_NAME = "Golda"
local GOLDA_FINISHER_IMAGE_FILE = "thebest/golda-finisher-v1.png"
local GOLDA_FINISHER_SOUND_FILE = "thebest/golda-finisher-v1.mp3"
local GOLDA_FINISHER_IMAGE_BASE64 = readTheBestPackedResource("0819773c991e75e140c036dfb6da9a0d3c18a429ba6c06e71154a552b95fc0ec")
local GOLDA_FINISHER_SOUND_BASE64 = readTheBestPackedResource("3debaa78baf011eca055ec73d8216dd155c41dd3dc6db06634cdd3dcc5afa5dd")
local HOMELANDER_FINISHER_BASE64 = readTheBestPackedResource("54080ecd544e2d2d0e45ad5a05eead19bc2f0cbffac79ecca82856ee8480544f")

local LoadingScreenBox = (function()
	local SOURCE_NAME = "LoadingScreen"
	local TEMPLATE_ATTRIBUTE = "TheBestLoadingScreenTemplate"
	local SPAWN_ATTRIBUTE = "TheBestSpawnedLoadingScreen"
	local PLATFORM_NAME = "TheBest_LoadingScreenPlatform"
	local PLATFORM_ATTRIBUTE = "TheBestLoadingScreenPlatform"
	local Workspace = game:GetService("Workspace")
	local RunService = game:GetService("RunService")
	local Players = game:GetService("Players")
	local template = nil
	local spawned = nil
	local platform = nil
	local cameraPoint = nil
	local captureConnections = {}
	local cameraConnection = nil
	local savedCameraState = nil
	local api = {}

	if _G.TheBestLoadingScreenCaptureConnection then
		pcall(function()
			_G.TheBestLoadingScreenCaptureConnection:Disconnect()
		end)
		_G.TheBestLoadingScreenCaptureConnection = nil
	end
	if type(_G.TheBestLoadingScreenCaptureConnections) == "table" then
		for _, connection in ipairs(_G.TheBestLoadingScreenCaptureConnections) do
			pcall(function()
				connection:Disconnect()
			end)
		end
		_G.TheBestLoadingScreenCaptureConnections = nil
	end

	local function disconnectCaptureConnections()
		for _, connection in ipairs(captureConnections) do
			pcall(function()
				connection:Disconnect()
			end)
		end
		table.clear(captureConnections)
		_G.TheBestLoadingScreenCaptureConnection = nil
		_G.TheBestLoadingScreenCaptureConnections = nil
	end

	local function getPartBottomY(part)
		local frame = part.CFrame
		local halfHeight = math.abs(frame.RightVector.Y) * part.Size.X * 0.5
			+ math.abs(frame.UpVector.Y) * part.Size.Y * 0.5
			+ math.abs(frame.LookVector.Y) * part.Size.Z * 0.5
		return part.Position.Y - halfHeight
	end

	local function getObjectCFrame(object)
		if typeof(object) ~= "Instance" then
			return nil
		end
		if object:IsA("BasePart") then
			return object.CFrame
		elseif object:IsA("Attachment") then
			return object.WorldCFrame
		elseif object:IsA("CFrameValue") then
			return object.Value
		elseif object:IsA("ObjectValue") and typeof(object.Value) == "Instance" then
			return getObjectCFrame(object.Value)
		elseif object:IsA("Model") then
			local succeeded, pivot = pcall(function()
				return object:GetPivot()
			end)
			if succeeded then
				return pivot
			end
		end

		local attachment = object:FindFirstChildWhichIsA("Attachment", true)
		if attachment then
			return attachment.WorldCFrame
		end
		local part = object:FindFirstChildWhichIsA("BasePart", true)
		return part and part.CFrame or nil
	end

	local function findNamedDescendant(root, expectedName)
		if typeof(root) ~= "Instance" then
			return nil
		end
		if root.Name == expectedName then
			return root
		end
		local exact = root:FindFirstChild(expectedName, true)
		if exact then
			return exact
		end
		local expectedLower = expectedName:lower()
		local partial = nil
		for _, descendant in ipairs(root:GetDescendants()) do
			local lowerName = descendant.Name:lower()
			if lowerName == expectedLower then
				return descendant
			elseif not partial and lowerName:find(expectedLower, 1, true) then
				partial = descendant
			end
		end
		return partial
	end

	local function findDiavolo(root)
		local found = findNamedDescendant(root, "Diavolo")
		if not found then
			return nil
		end
		if found:IsA("Model") or found:IsA("BasePart") then
			return found
		end
		return found:FindFirstAncestorWhichIsA("Model") or found
	end

	local function getFeetLevel(subject)
		if typeof(subject) ~= "Instance" then
			return nil
		end
		local preferredParts = {}
		local allParts = {}
		local function registerPart(part)
			local lowerName = part.Name:lower()
			if not lowerName:find("camera", 1, true) and part:GetAttribute(PLATFORM_ATTRIBUTE) ~= true then
				table.insert(allParts, part)
				if
					lowerName:find("foot", 1, true)
					or lowerName:find("feet", 1, true)
					or lowerName:find("leg", 1, true)
					or lowerName:find("shoe", 1, true)
					or lowerName:find("boot", 1, true)
					or lowerName:find("ankle", 1, true)
				then
					table.insert(preferredParts, part)
				end
			end
		end

		if subject:IsA("BasePart") then
			registerPart(subject)
		end
		for _, descendant in ipairs(subject:GetDescendants()) do
			if descendant:IsA("BasePart") then
				registerPart(descendant)
			end
		end

		local candidates = #preferredParts > 0 and preferredParts or allParts
		local lowest = math.huge
		for _, part in ipairs(candidates) do
			lowest = math.min(lowest, getPartBottomY(part))
		end
		return lowest < math.huge and lowest or nil
	end

	local function createPlatform(copy)
		local diavolo = findDiavolo(copy)
		local anchor = diavolo or copy
		local anchorFrame = getObjectCFrame(anchor) or getObjectCFrame(copy)
		local feetLevel = getFeetLevel(diavolo) or getFeetLevel(copy)
		if not anchorFrame or not feetLevel then
			return nil, "Could not locate Diavolo's position for the platform."
		end

		local floor = Instance.new("Part")
		floor.Name = PLATFORM_NAME
		floor:SetAttribute(PLATFORM_ATTRIBUTE, true)
		floor.Anchored = true
		floor.CanCollide = true
		floor.CanTouch = true
		floor.CanQuery = true
		floor.CastShadow = false
		floor.Size = Vector3.new(64, 1, 64)
		floor.Material = Enum.Material.SmoothPlastic
		floor.Color = Color3.fromRGB(24, 17, 31)
		floor.Transparency = 0
		floor.TopSurface = Enum.SurfaceType.Smooth
		floor.BottomSurface = Enum.SurfaceType.Smooth
		floor.CFrame = CFrame.new(anchorFrame.Position.X, feetLevel - floor.Size.Y * 0.5, anchorFrame.Position.Z)
		floor.Parent = copy
		return floor
	end

	local function findCameraPoint(root)
		local point = findNamedDescendant(root, "CameraPoint")
		if point and getObjectCFrame(point) then
			return point
		end
		return nil
	end

	local function getFallbackCameraSubject()
		local localPlayer = Players.LocalPlayer
		local character = localPlayer and localPlayer.Character
		return character and character:FindFirstChildOfClass("Humanoid") or nil
	end

	local function getCharacterFootOffset(character, root)
		local feetLevel = getFeetLevel(character)
		if feetLevel then
			return math.clamp(root.Position.Y - feetLevel, 2, 7)
		end
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		return math.clamp((humanoid and humanoid.HipHeight or 2) + root.Size.Y * 0.5, 2, 7)
	end

	local function isSource(instance)
		if typeof(instance) ~= "Instance" then
			return false
		end
		local succeeded, result = pcall(function()
			return instance.Name == SOURCE_NAME
				and (instance:IsA("Folder") or instance:IsA("Model"))
				and instance:FindFirstChildWhichIsA("BasePart", true) ~= nil
				and instance:GetAttribute(TEMPLATE_ATTRIBUTE) ~= true
				and instance:GetAttribute(SPAWN_ATTRIBUTE) ~= true
		end)
		return succeeded and result
	end

	local function clonePreservingArchivable(source)
		local changed = {}
		local candidates = { source }
		for _, descendant in ipairs(source:GetDescendants()) do
			table.insert(candidates, descendant)
		end

		for _, instance in ipairs(candidates) do
			local succeeded, archivable = pcall(function()
				return instance.Archivable
			end)
			if succeeded and not archivable then
				local changedSuccessfully = pcall(function()
					instance.Archivable = true
				end)
				if changedSuccessfully then
					table.insert(changed, instance)
				end
			end
		end

		local succeeded, copy = pcall(function()
			return source:Clone()
		end)
		for _, instance in ipairs(changed) do
			pcall(function()
				instance.Archivable = false
			end)
		end
		return succeeded, copy
	end

	local function captureSource(source)
		if not isSource(source) then
			return false
		end
		local succeeded, copy = clonePreservingArchivable(source)
		if not succeeded or typeof(copy) ~= "Instance" then
			return false
		end
		copy.Parent = nil
		copy:SetAttribute(SPAWN_ATTRIBUTE, nil)
		copy:SetAttribute(TEMPLATE_ATTRIBUTE, true)
		if template and template ~= copy then
			pcall(function()
				template:Destroy()
			end)
		end
		template = copy
		_G.TheBestLoadingScreenTemplate = copy
		disconnectCaptureConnections()
		return true
	end

	local function captureFromRoot(root)
		if typeof(root) ~= "Instance" then
			return false
		end
		if captureSource(root) then
			return true
		end
		local succeeded, descendants = pcall(function()
			return root:GetDescendants()
		end)
		if not succeeded then
			return false
		end
		for _, descendant in ipairs(descendants) do
			if captureSource(descendant) then
				return true
			end
		end
		return false
	end

	local function captureFromNilInstances()
		local provider = nil
		pcall(function()
			if type(getnilinstances) == "function" then
				provider = getnilinstances
			elseif type(get_nil_instances) == "function" then
				provider = get_nil_instances
			end
		end)
		if type(provider) ~= "function" then
			return false
		end

		local succeeded, instances = pcall(provider)
		if not succeeded or type(instances) ~= "table" then
			return false
		end
		for _, instance in ipairs(instances) do
			if captureSource(instance) then
				return true
			end
		end
		return false
	end

	local storedTemplate = rawget(_G, "TheBestLoadingScreenTemplate")
	if typeof(storedTemplate) == "Instance" then
		local succeeded, testCopy = pcall(function()
			return storedTemplate:Clone()
		end)
		if succeeded and typeof(testCopy) == "Instance" then
			testCopy:Destroy()
			template = storedTemplate
		else
			_G.TheBestLoadingScreenTemplate = nil
		end
	end

	function api.Capture()
		if captureFromRoot(Workspace) then
			return true
		end
		for _, serviceName in ipairs({ "ReplicatedStorage", "ReplicatedFirst", "Lighting", "StarterGui" }) do
			local succeeded, service = pcall(game.GetService, game, serviceName)
			if succeeded and captureFromRoot(service) then
				return true
			end
		end
		local localPlayer = Players.LocalPlayer
		if localPlayer and captureFromRoot(localPlayer:FindFirstChildOfClass("PlayerGui")) then
			return true
		end
		if captureFromNilInstances() then
			return true
		end
		return template ~= nil
	end

	function api.IsCaptured()
		return typeof(template) == "Instance"
	end

	function api.IsSpawned()
		return typeof(spawned) == "Instance" and spawned.Parent == Workspace
	end

	function api.GetPlatform()
		if
			typeof(platform) == "Instance"
			and platform:IsA("BasePart")
			and typeof(spawned) == "Instance"
			and platform:IsDescendantOf(spawned)
		then
			return platform
		end
		return nil
	end

	function api.IsCameraEnabled()
		return cameraConnection ~= nil and savedCameraState ~= nil
	end

	function api.DisableCamera()
		if cameraConnection then
			cameraConnection:Disconnect()
			cameraConnection = nil
		end
		if rawget(_G, "TheBestExclusiveSceneCameraRelease") == api.DisableCamera then
			_G.TheBestExclusiveSceneCameraRelease = nil
		end

		local state = savedCameraState
		savedCameraState = nil
		if not state then
			return
		end

		local currentCamera = Workspace.CurrentCamera or state.camera
		if currentCamera then
			pcall(function()
				currentCamera.CFrame = state.cframe
				currentCamera.Focus = state.focus
				currentCamera.FieldOfView = state.fieldOfView
				local subject = state.subject
				if typeof(subject) ~= "Instance" or subject.Parent == nil then
					subject = getFallbackCameraSubject()
				end
				if subject then
					currentCamera.CameraSubject = subject
				end
				currentCamera.CameraType = state.cameraType or Enum.CameraType.Custom
			end)
		end
	end

	function api.EnableCamera()
		if not api.IsSpawned() then
			return false, "Spawn the LoadingScreen box first."
		end
		cameraPoint = findCameraPoint(spawned)
		local pointFrame = getObjectCFrame(cameraPoint)
		if not cameraPoint or not pointFrame then
			return false, "CameraPoint was not found inside LoadingScreen."
		end

		local activeRelease = rawget(_G, "TheBestExclusiveSceneCameraRelease")
		if type(activeRelease) == "function" and activeRelease ~= api.DisableCamera then
			pcall(activeRelease)
		end
		api.DisableCamera()
		local currentCamera = Workspace.CurrentCamera
		if not currentCamera then
			return false, "Workspace.CurrentCamera is unavailable."
		end
		savedCameraState = {
			camera = currentCamera,
			cameraType = currentCamera.CameraType,
			subject = currentCamera.CameraSubject,
			cframe = currentCamera.CFrame,
			focus = currentCamera.Focus,
			fieldOfView = currentCamera.FieldOfView,
		}
		_G.TheBestExclusiveSceneCameraRelease = api.DisableCamera

		local function updateCamera()
			pcall(function()
				local camera = Workspace.CurrentCamera
				local frame = getObjectCFrame(cameraPoint)
				if camera and frame then
					camera.CameraType = Enum.CameraType.Scriptable
					camera.CFrame = frame
					camera.Focus = frame * CFrame.new(0, 0, -12)
				end
			end)
		end
		updateCamera()
		cameraConnection = RunService.RenderStepped:Connect(updateCamera)
		return true
	end

	function api.GetPlatformTeleportCFrame()
		local floor = api.GetPlatform()
		if not floor then
			return nil, "LoadingScreen platform is not spawned."
		end
		local localPlayer = Players.LocalPlayer
		local character = localPlayer and localPlayer.Character
		local root = character and character:FindFirstChild("HumanoidRootPart")
		if not character or not root then
			return nil, "Your HumanoidRootPart is unavailable."
		end

		local footOffset = getCharacterFootOffset(character, root)
		local destination = floor.CFrame
			* CFrame.new(0, floor.Size.Y * 0.5 + footOffset + 0.15, floor.Size.Z * 0.28)
		return destination
	end

	function api.Remove()
		api.DisableCamera()
		if spawned then
			pcall(function()
				spawned:Destroy()
			end)
			spawned = nil
		end
		platform = nil
		cameraPoint = nil
		for _, child in ipairs(Workspace:GetChildren()) do
			local succeeded, tagged = pcall(function()
				return child:GetAttribute(SPAWN_ATTRIBUTE) == true
			end)
			if succeeded and tagged then
				pcall(function()
					child:Destroy()
				end)
			end
		end
	end

	function api.Spawn()
		api.Remove()
		if not template and not api.Capture() then
			return nil, "LoadingScreen was not found in the game, its storage, or removed instances."
		end
		local succeeded, copy = clonePreservingArchivable(template)
		if not succeeded or typeof(copy) ~= "Instance" then
			template = nil
			_G.TheBestLoadingScreenTemplate = nil
			if api.Capture() then
				succeeded, copy = clonePreservingArchivable(template)
			end
		end
		if not succeeded or typeof(copy) ~= "Instance" then
			return nil, "Could not clone LoadingScreen: " .. tostring(copy)
		end
		copy.Name = SOURCE_NAME
		copy:SetAttribute(TEMPLATE_ATTRIBUTE, nil)
		copy:SetAttribute(SPAWN_ATTRIBUTE, true)
		for _, descendant in ipairs(copy:GetDescendants()) do
			if descendant:IsA("Sound") or descendant.ClassName == "AudioPlayer" then
				pcall(function()
					descendant:Destroy()
				end)
			elseif descendant:IsA("BaseScript") then
				pcall(function()
					descendant.Disabled = true
				end)
			end
		end
		local createdPlatform, platformError = createPlatform(copy)
		if not createdPlatform then
			copy:Destroy()
			return nil, platformError
		end
		cameraPoint = findCameraPoint(copy)
		copy.Parent = Workspace
		spawned = copy
		platform = createdPlatform
		return copy
	end

	local function watchForSource(instance)
		if isSource(instance) then
			captureSource(instance)
		end
	end
	if not template then
		table.insert(captureConnections, Workspace.DescendantAdded:Connect(watchForSource))
		table.insert(captureConnections, Workspace.DescendantRemoving:Connect(watchForSource))
		_G.TheBestLoadingScreenCaptureConnection = captureConnections[1]
		_G.TheBestLoadingScreenCaptureConnections = captureConnections
	end
	api.Capture()
	if template then
		disconnectCaptureConnections()
		for _, child in ipairs(Workspace:GetChildren()) do
			if isSource(child) then
				task.delay(0.5, function()
					if child.Parent == Workspace then
						captureSource(child)
					end
				end)
				break
			end
		end
	end

	return api
end)()

local SkillTreeScene = (function()
	local SOURCE_NAME = "Skill Tree"
	local SCENE_NAME = "TheBest_SkillTreeScene"
	local TEMPLATE_ATTRIBUTE = "TheBestSkillTreeTemplate"
	local SPAWN_ATTRIBUTE = "TheBestSpawnedSkillTree"
	local PLATFORM_NAME = "TheBest_SkillTreePlatform"
	local PLATFORM_ATTRIBUTE = "TheBestSkillTreePlatform"
	local SAFE_TOP_LEVEL = {
		skills = true,
		start = true,
		title = true,
		box = true,
		camerasubject = true,
		camerapoint = true,
	}
	local Workspace = game:GetService("Workspace")
	local RunService = game:GetService("RunService")
	local Players = game:GetService("Players")
	local template = nil
	local spawned = nil
	local platform = nil
	local captureConnection = nil
	local cameraConnection = nil
	local savedCameraState = nil
	local capturedCameraState = rawget(_G, "TheBestSkillTreeCapturedCamera")
	local api = {}

	if type(_G.TheBestSkillTreeSceneCleanup) == "function" then
		pcall(_G.TheBestSkillTreeSceneCleanup)
		_G.TheBestSkillTreeSceneCleanup = nil
	end
	if _G.TheBestSkillTreeCaptureConnection then
		pcall(function()
			_G.TheBestSkillTreeCaptureConnection:Disconnect()
		end)
		_G.TheBestSkillTreeCaptureConnection = nil
	end

	local function findNamedDescendant(root, expectedName)
		if typeof(root) ~= "Instance" then
			return nil
		end
		local expectedLower = expectedName:lower()
		if root.Name:lower() == expectedLower then
			return root
		end
		local partial = nil
		for _, descendant in ipairs(root:GetDescendants()) do
			local lowerName = descendant.Name:lower()
			if lowerName == expectedLower then
				return descendant
			elseif not partial and lowerName:find(expectedLower, 1, true) then
				partial = descendant
			end
		end
		return partial
	end

	local function getObjectCFrame(object, searchRoot, depth)
		depth = depth or 0
		if typeof(object) ~= "Instance" or depth > 4 then
			return nil
		end
		if object:IsA("BasePart") then
			return object.CFrame
		elseif object:IsA("Attachment") then
			return object.WorldCFrame
		elseif object:IsA("Model") then
			local succeeded, pivot = pcall(function()
				return object:GetPivot()
			end)
			if succeeded then
				return pivot
			end
		elseif object:IsA("ValueBase") then
			local succeeded, value = pcall(function()
				return object.Value
			end)
			if succeeded then
				if typeof(value) == "Instance" then
					return getObjectCFrame(value, searchRoot, depth + 1)
				elseif typeof(value) == "CFrame" then
					return value
				elseif typeof(value) == "Vector3" then
					return CFrame.new(value)
				elseif type(value) == "string" and searchRoot then
					local referenced = findNamedDescendant(searchRoot, value)
					if referenced and referenced ~= object then
						return getObjectCFrame(referenced, searchRoot, depth + 1)
					end
				end
			end
		end

		local attachment = object:FindFirstChildWhichIsA("Attachment", true)
		if attachment then
			return attachment.WorldCFrame
		end
		local part = object:FindFirstChildWhichIsA("BasePart", true)
		return part and part.CFrame or nil
	end

	local function getPartBottomY(part)
		local frame = part.CFrame
		local halfHeight = math.abs(frame.RightVector.Y) * part.Size.X * 0.5
			+ math.abs(frame.UpVector.Y) * part.Size.Y * 0.5
			+ math.abs(frame.LookVector.Y) * part.Size.Z * 0.5
		return part.Position.Y - halfHeight
	end

	local function getObjectBottomY(object)
		if typeof(object) ~= "Instance" then
			return nil
		end
		local visibleBottom = math.huge
		local anyBottom = math.huge
		local function register(part)
			if part:GetAttribute(PLATFORM_ATTRIBUTE) == true then
				return
			end
			local bottom = getPartBottomY(part)
			anyBottom = math.min(anyBottom, bottom)
			if part.Transparency < 0.98 then
				visibleBottom = math.min(visibleBottom, bottom)
			end
		end
		if object:IsA("BasePart") then
			register(object)
		end
		for _, descendant in ipairs(object:GetDescendants()) do
			if descendant:IsA("BasePart") then
				register(descendant)
			end
		end
		if visibleBottom < math.huge then
			return visibleBottom
		end
		return anyBottom < math.huge and anyBottom or nil
	end

	local function getVisualBounds(root)
		local minX, minY, minZ = math.huge, math.huge, math.huge
		local maxX, maxY, maxZ = -math.huge, -math.huge, -math.huge
		local count = 0
		for _, descendant in ipairs(root:GetDescendants()) do
			if
				descendant:IsA("BasePart")
				and descendant:GetAttribute(PLATFORM_ATTRIBUTE) ~= true
				and descendant.Transparency < 0.98
				and not descendant.Name:lower():find("camera", 1, true)
			then
				count += 1
				for xSign = -1, 1, 2 do
					for ySign = -1, 1, 2 do
						for zSign = -1, 1, 2 do
							local corner = descendant.CFrame:PointToWorldSpace(
								Vector3.new(
									descendant.Size.X * xSign * 0.5,
									descendant.Size.Y * ySign * 0.5,
									descendant.Size.Z * zSign * 0.5
								)
							)
							minX = math.min(minX, corner.X)
							maxX = math.max(maxX, corner.X)
							minY = math.min(minY, corner.Y)
							maxY = math.max(maxY, corner.Y)
							minZ = math.min(minZ, corner.Z)
							maxZ = math.max(maxZ, corner.Z)
						end
					end
				end
			end
		end
		if count == 0 then
			return nil
		end
		return minX, maxX, minZ, maxZ, minY, maxY
	end

	local function getFallbackCameraSubject()
		local localPlayer = Players.LocalPlayer
		local character = localPlayer and localPlayer.Character
		return character and character:FindFirstChildOfClass("Humanoid") or nil
	end

	local function getCharacterFootOffset(character, root)
		local bottom = getObjectBottomY(character)
		if bottom then
			return math.clamp(root.Position.Y - bottom, 2, 7)
		end
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		return math.clamp((humanoid and humanoid.HipHeight or 2) + root.Size.Y * 0.5, 2, 7)
	end

	local function isSource(instance)
		if typeof(instance) ~= "Instance" then
			return false
		end
		local succeeded, result = pcall(function()
			return instance.Name == SOURCE_NAME
				and instance:GetAttribute(TEMPLATE_ATTRIBUTE) ~= true
				and instance:GetAttribute(SPAWN_ATTRIBUTE) ~= true
		end)
		return succeeded and result
	end

	local function recordCameraIfRelevant(source)
		if not isSource(source) or source.Parent ~= Workspace then
			return false
		end
		local currentCamera = Workspace.CurrentCamera
		local sourceFrame = getObjectCFrame(source, source)
		if not currentCamera or not sourceFrame then
			return false
		end
		if (currentCamera.CFrame.Position - sourceFrame.Position).Magnitude > 2500 then
			return false
		end
		capturedCameraState = {
			cframe = currentCamera.CFrame,
			focus = currentCamera.Focus,
			fieldOfView = currentCamera.FieldOfView,
		}
		_G.TheBestSkillTreeCapturedCamera = capturedCameraState
		return true
	end

	local function scheduleCameraCapture(source)
		for _, delaySeconds in ipairs({ 0.1, 0.35, 0.8 }) do
			task.delay(delaySeconds, function()
				recordCameraIfRelevant(source)
			end)
		end
	end

	local function captureSource(source)
		if not isSource(source) then
			return false
		end
		local originalArchivable = true
		pcall(function()
			originalArchivable = source.Archivable
			source.Archivable = true
		end)
		local succeeded, copy = pcall(function()
			return source:Clone()
		end)
		pcall(function()
			source.Archivable = originalArchivable
		end)
		if not succeeded or typeof(copy) ~= "Instance" then
			return false
		end
		copy.Parent = nil
		copy:SetAttribute(SPAWN_ATTRIBUTE, nil)
		copy:SetAttribute(TEMPLATE_ATTRIBUTE, true)
		if template and template ~= copy then
			pcall(function()
				template:Destroy()
			end)
		end
		template = copy
		_G.TheBestSkillTreeTemplate = copy
		recordCameraIfRelevant(source)
		scheduleCameraCapture(source)
		return true
	end

	local function sanitizeCopy(copy)
		for _, child in ipairs(copy:GetChildren()) do
			if not SAFE_TOP_LEVEL[child.Name:lower()] then
				child:Destroy()
			end
		end

		local safeBox = copy:FindFirstChild("Box") or findNamedDescendant(copy, "Box")
		for _, descendant in ipairs(copy:GetDescendants()) do
			if descendant:IsA("Sound") or descendant.ClassName == "AudioPlayer" then
				pcall(function()
					descendant:Destroy()
				end)
			elseif descendant:IsA("LuaSourceContainer") or descendant:IsA("ScreenGui") then
				pcall(function()
					descendant:Destroy()
				end)
			elseif
				descendant:IsA("ProximityPrompt")
				or descendant:IsA("ClickDetector")
				or descendant:IsA("TouchTransmitter")
			then
				pcall(function()
					descendant:Destroy()
				end)
			elseif
				safeBox
				and descendant:IsDescendantOf(safeBox)
				and (
					descendant:IsA("Decal")
					or descendant:IsA("Texture")
					or descendant:IsA("SurfaceGui")
					or descendant:IsA("BillboardGui")
				)
			then
				pcall(function()
					descendant:Destroy()
				end)
			elseif descendant:IsA("BasePart") then
				descendant.Anchored = true
				descendant.CanCollide = false
				descendant.CanTouch = false
				descendant.CanQuery = false
				descendant.CastShadow = false
				if safeBox and descendant:IsDescendantOf(safeBox) then
					descendant.Transparency = 1
					descendant.LocalTransparencyModifier = 0
				end
			end
		end
	end

	local function createPlatform(copy)
		local skills = copy:FindFirstChild("Skills") or findNamedDescendant(copy, "Skills")
		local worthiness = skills and findNamedDescendant(skills, "Worthiness") or nil
		local start = copy:FindFirstChild("Start") or findNamedDescendant(copy, "Start")
		local levelObject = worthiness or start or skills
		local levelY = getObjectBottomY(levelObject)
		local minX, maxX, minZ, maxZ = getVisualBounds(copy)
		if not levelY or not minX then
			return nil, "Could not locate Worthiness/skill parts for the platform."
		end

		local floor = Instance.new("Part")
		floor.Name = PLATFORM_NAME
		floor:SetAttribute(PLATFORM_ATTRIBUTE, true)
		floor.Anchored = true
		floor.CanCollide = true
		floor.CanTouch = true
		floor.CanQuery = true
		floor.CastShadow = false
		floor.Size = Vector3.new(
			math.clamp(maxX - minX + 24, 80, 320),
			1,
			math.clamp(maxZ - minZ + 48, 72, 180)
		)
		floor.Material = Enum.Material.SmoothPlastic
		floor.Color = Color3.fromRGB(31, 19, 72)
		floor.Transparency = 0.1
		floor.TopSurface = Enum.SurfaceType.Smooth
		floor.BottomSurface = Enum.SurfaceType.Smooth
		floor.CFrame = CFrame.new((minX + maxX) * 0.5, levelY - floor.Size.Y * 0.5, (minZ + maxZ) * 0.5)
		floor.Parent = copy
		return floor
	end

	local function getSurfaceFacingNormal(root)
		local normalByFace = {
			[Enum.NormalId.Front] = Vector3.new(0, 0, -1),
			[Enum.NormalId.Back] = Vector3.new(0, 0, 1),
			[Enum.NormalId.Left] = Vector3.new(-1, 0, 0),
			[Enum.NormalId.Right] = Vector3.new(1, 0, 0),
			[Enum.NormalId.Top] = Vector3.new(0, 1, 0),
			[Enum.NormalId.Bottom] = Vector3.new(0, -1, 0),
		}
		for _, preferredName in ipairs({ "Title", "Start" }) do
			local preferred = findNamedDescendant(root, preferredName)
			local surfaceGui = preferred and preferred:FindFirstChildWhichIsA("SurfaceGui", true)
			if surfaceGui then
				local adornee = surfaceGui.Adornee
				if typeof(adornee) ~= "Instance" or not adornee:IsA("BasePart") then
					adornee = surfaceGui:FindFirstAncestorWhichIsA("BasePart")
				end
				if adornee then
					local localNormal = normalByFace[surfaceGui.Face] or Vector3.new(0, 0, -1)
					return adornee.CFrame:VectorToWorldSpace(localNormal).Unit
				end
			end
		end
		return Vector3.new(0, 0, -1)
	end

	local function resolveCameraView(scene)
		if
			type(capturedCameraState) == "table"
			and typeof(capturedCameraState.cframe) == "CFrame"
		then
			return capturedCameraState.cframe,
				typeof(capturedCameraState.focus) == "CFrame"
					and capturedCameraState.focus
					or capturedCameraState.cframe * CFrame.new(0, 0, -12),
				capturedCameraState.fieldOfView
		end

		local explicitPoint = findNamedDescendant(scene, "CameraPoint")
		if explicitPoint then
			local explicitFrame = getObjectCFrame(explicitPoint, scene)
			if explicitFrame then
				return explicitFrame, explicitFrame * CFrame.new(0, 0, -12), nil
			end
		end

		local minX, maxX, minZ, maxZ, minY, maxY = getVisualBounds(scene)
		if not minX then
			return nil
		end
		local boundsPosition = Vector3.new((minX + maxX) * 0.5, (minY + maxY) * 0.5, (minZ + maxZ) * 0.5)
		local boundsSize = Vector3.new(maxX - minX, maxY - minY, maxZ - minZ)
		local cameraSubject = findNamedDescendant(scene, "CameraSubject")
		local subjectFrame = cameraSubject and getObjectCFrame(cameraSubject, scene) or nil
		local targetPosition = subjectFrame and subjectFrame.Position or boundsPosition
		local facingNormal = getSurfaceFacingNormal(scene)
		if math.abs(facingNormal:Dot(Vector3.yAxis)) > 0.95 then
			facingNormal = Vector3.new(0, 0, -1)
		end
		local distance = math.max(boundsSize.X, boundsSize.Y) * 0.9 + 20
		local cameraPosition = targetPosition + facingNormal * distance
		local cameraFrame = CFrame.lookAt(cameraPosition, targetPosition, Vector3.yAxis)
		return cameraFrame, CFrame.new(targetPosition), nil
	end

	local storedTemplate = rawget(_G, "TheBestSkillTreeTemplate")
	if typeof(storedTemplate) == "Instance" then
		local succeeded, testCopy = pcall(function()
			return storedTemplate:Clone()
		end)
		if succeeded and typeof(testCopy) == "Instance" then
			testCopy:Destroy()
			template = storedTemplate
		else
			_G.TheBestSkillTreeTemplate = nil
		end
	end

	function api.Capture()
		for _, child in ipairs(Workspace:GetChildren()) do
			if isSource(child) and captureSource(child) then
				return true
			end
		end
		if type(getnilinstances) == "function" then
			local succeeded, instances = pcall(getnilinstances)
			if succeeded and type(instances) == "table" then
				for _, instance in ipairs(instances) do
					if isSource(instance) and captureSource(instance) then
						return true
					end
				end
			end
		end
		return template ~= nil
	end

	function api.IsCaptured()
		return typeof(template) == "Instance"
	end

	function api.IsSpawned()
		return typeof(spawned) == "Instance" and spawned.Parent == Workspace
	end

	function api.GetPlatform()
		if
			typeof(platform) == "Instance"
			and platform:IsA("BasePart")
			and typeof(spawned) == "Instance"
			and platform:IsDescendantOf(spawned)
		then
			return platform
		end
		return nil
	end

	function api.IsCameraEnabled()
		return cameraConnection ~= nil and savedCameraState ~= nil
	end

	function api.DisableCamera()
		if cameraConnection then
			cameraConnection:Disconnect()
			cameraConnection = nil
		end
		if rawget(_G, "TheBestExclusiveSceneCameraRelease") == api.DisableCamera then
			_G.TheBestExclusiveSceneCameraRelease = nil
		end

		local state = savedCameraState
		savedCameraState = nil
		if not state then
			return
		end
		local currentCamera = Workspace.CurrentCamera or state.camera
		if currentCamera then
			pcall(function()
				currentCamera.CFrame = state.cframe
				currentCamera.Focus = state.focus
				currentCamera.FieldOfView = state.fieldOfView
				local subject = state.subject
				if typeof(subject) ~= "Instance" or subject.Parent == nil then
					subject = getFallbackCameraSubject()
				end
				if subject then
					currentCamera.CameraSubject = subject
				end
				currentCamera.CameraType = state.cameraType or Enum.CameraType.Custom
			end)
		end
	end

	function api.EnableCamera()
		if not api.IsSpawned() then
			return false, "Spawn the filtered Skill Tree scene first."
		end
		local cameraFrame, focusFrame, fieldOfView = resolveCameraView(spawned)
		if not cameraFrame then
			return false, "Could not resolve the Skill Tree camera view."
		end

		local activeRelease = rawget(_G, "TheBestExclusiveSceneCameraRelease")
		if type(activeRelease) == "function" and activeRelease ~= api.DisableCamera then
			pcall(activeRelease)
		end
		api.DisableCamera()
		local currentCamera = Workspace.CurrentCamera
		if not currentCamera then
			return false, "Workspace.CurrentCamera is unavailable."
		end
		savedCameraState = {
			camera = currentCamera,
			cameraType = currentCamera.CameraType,
			subject = currentCamera.CameraSubject,
			cframe = currentCamera.CFrame,
			focus = currentCamera.Focus,
			fieldOfView = currentCamera.FieldOfView,
		}
		_G.TheBestExclusiveSceneCameraRelease = api.DisableCamera

		local function updateCamera()
			pcall(function()
				local camera = Workspace.CurrentCamera
				if camera then
					camera.CameraType = Enum.CameraType.Scriptable
					camera.CFrame = cameraFrame
					camera.Focus = focusFrame or cameraFrame * CFrame.new(0, 0, -12)
					if type(fieldOfView) == "number" then
						camera.FieldOfView = fieldOfView
					end
				end
			end)
		end
		updateCamera()
		cameraConnection = RunService.RenderStepped:Connect(updateCamera)
		return true
	end

	function api.GetPlatformTeleportCFrame()
		local floor = api.GetPlatform()
		if not floor then
			return nil, "Skill Tree platform is not spawned."
		end
		local localPlayer = Players.LocalPlayer
		local character = localPlayer and localPlayer.Character
		local root = character and character:FindFirstChild("HumanoidRootPart")
		if not character or not root then
			return nil, "Your HumanoidRootPart is unavailable."
		end
		local footOffset = getCharacterFootOffset(character, root)
		return floor.CFrame
			* CFrame.new(0, floor.Size.Y * 0.5 + footOffset + 0.15, floor.Size.Z * 0.28)
	end

	function api.Remove()
		api.DisableCamera()
		if spawned then
			pcall(function()
				spawned:Destroy()
			end)
			spawned = nil
		end
		platform = nil
		for _, child in ipairs(Workspace:GetChildren()) do
			local succeeded, tagged = pcall(function()
				return child:GetAttribute(SPAWN_ATTRIBUTE) == true
			end)
			if succeeded and tagged then
				pcall(function()
					child:Destroy()
				end)
			end
		end
	end

	function api.Spawn()
		api.Remove()
		if not template and not api.Capture() then
			return nil, "Skill Tree was not captured. Open Skill Tree once while TheBest is running."
		end
		local succeeded, copy = pcall(function()
			return template:Clone()
		end)
		if not succeeded or typeof(copy) ~= "Instance" then
			return nil, "Could not clone Skill Tree: " .. tostring(copy)
		end
		copy.Parent = nil
		copy.Name = SCENE_NAME
		copy:SetAttribute(TEMPLATE_ATTRIBUTE, nil)
		copy:SetAttribute(SPAWN_ATTRIBUTE, true)
		sanitizeCopy(copy)
		local skills = copy:FindFirstChild("Skills") or findNamedDescendant(copy, "Skills")
		if not skills then
			copy:Destroy()
			return nil, "Captured Skill Tree does not contain the Skills folder."
		end
		local createdPlatform, platformError = createPlatform(copy)
		if not createdPlatform then
			copy:Destroy()
			return nil, platformError
		end
		copy.Parent = Workspace
		spawned = copy
		platform = createdPlatform
		return copy
	end

	api.Capture()
	captureConnection = Workspace.ChildAdded:Connect(function(child)
		if child.Name == SOURCE_NAME then
			task.defer(captureSource, child)
			scheduleCameraCapture(child)
		end
	end)
	_G.TheBestSkillTreeCaptureConnection = captureConnection
	local cameraProbeToken = {}
	_G.TheBestSkillTreeCameraProbeToken = cameraProbeToken
	task.spawn(function()
		while rawget(_G, "TheBestSkillTreeCameraProbeToken") == cameraProbeToken do
			if
				type(capturedCameraState) == "table"
				and typeof(capturedCameraState.cframe) == "CFrame"
			then
				break
			end
			for _, child in ipairs(Workspace:GetChildren()) do
				if isSource(child) and recordCameraIfRelevant(child) then
					break
				end
			end
			task.wait(0.5)
		end
	end)

	return api
end)()

