local normalizeTheBestSettings = (function(target, defaults, options)
	options = options or {}
	local function finite(value) return type(value) == "number" and value == value and value ~= math.huge and value ~= -math.huge end
	local function copy(value)
		if type(value) ~= "table" then return value end
		local result = {}; for key, child in pairs(value) do result[key] = copy(child) end; return result
	end
	if type(target) ~= "table" then target = {} end
	local ranges = {
		targetSelectionRadius = {40,400}, targetVisionHeight = {-200,200}, Resolution = {1,6},
		maxVisibilityDistance = {10,5000}, xenonItemCollectionDelay = {0.2,3}, xenonPityAmount = {20,125},
		speedhackValue = {0,20}, flySpeed = {10,500}, speedExploitsVal = {1,50}, meStrafeSpeed = {1,100},
		timeSkipAngle = {0,1}, shuffleCd = {0,8}, shuffleDist = {0,10}, prediction = {0.01,1},
		standPilotSpeed = {1,500}, standPilotYPos = {1,20}, standPilotUnderground = {1,50},
		targetLockPredict = {0,20}, standOnlyTimeout = {0,5}, classicPilotSpeed = {0.5,5},
		classicPilotJumpPower = {0.5,5}, classicPilotBodyDistance = {1,100}, antiTimeStopDelay = {0,0.8},
		xenonSbrDelay1 = {1,60}, xenonSbrDelay2 = {1,60}, xenonSbrDelay3 = {1,60}, xenonSbrDelay4 = {1,60},
		xenonSbrDelay5 = {1,20}, xenonSbrHideDelay = {1,10}, xenonHorseWalkSpeed = {0,120},
		xenonHorseJumpPower = {0,100}, fovValue = {60,120}, clocktime = {1,24}, goldaKills = {0,1e15},
		hitboxSize = {1,1000000}, xenonStandAttachDistance = {0,3.5}, xenonPredictionStrength = {0,0.5},
	}
	local stringLists = { hitboxWhitelist=true, xenonSelectedItems=true, xenonSelectedStands=true,
		xenonSelectedShinies=true, xenonSelectedSellItems=true, playerOutfitFavorites=true, xenonItemEspItems=true }
	local function normalizeList(value)
		local result, seen, indices = {}, {}, {}
		for index in pairs(value) do if type(index)=="number" and index>=1 and index%1==0 then indices[#indices+1]=index end end
		table.sort(indices)
		for _, index in ipairs(indices) do
			local item = value[index]
			if type(item)=="string" and item~="" and not seen[item] then result[#result+1]=item; seen[item]=true end
		end
		return result
	end
	for key, default in pairs(defaults) do
		local value = target[key]
		-- User explicitly excluded Auto Parry from this repair. Keep its legacy merge behavior exactly.
		if not options.Keybinds and string.sub(key,1,9)=="autoParry" then
			if value==nil then target[key]=default end
		elseif options.Keybinds then
			local valid = type(value)=="string"
			if valid and type(options.IsKeyCode)=="function" then local ok, result=pcall(options.IsKeyCode,value); valid=ok and result==true end
			if not valid then target[key]=default end
		elseif (key=="xenonWaypoint" or key=="xenonSpawnpoint") and value~=nil and value~=false then
			local components, valid = {}, type(value)=="table"
			if valid then
				for index=1,12 do local number=tonumber(value[index]); if not finite(number) then valid=false; break end; components[index]=number end
			end
			target[key]=valid and components or false
		elseif key=="xenonSpawnpointName" and type(value)=="string" then
			target[key]=value
		elseif stringLists[key] and type(value)=="table" then
			target[key]=normalizeList(value)
		elseif type(default)=="number" then
			local number=tonumber(value)
			if not finite(number) then number=default end
			local range=ranges[key]
			if not range and (string.match(key,"[RGB]$") and (string.find(key,"box",1,true) or string.find(key,"name",1,true) or string.find(key,"distance",1,true) or string.find(key,"skeleton",1,true) or string.find(key,"tracer",1,true) or string.find(key,"selectedTag",1,true) or string.find(key,"standAura",1,true))) then range={0,255} end
			if range then number=math.clamp(number,range[1],range[2]) end
			target[key]=number
		elseif value==nil or type(value)~=type(default) then
			target[key]=copy(default)
		end
	end
	return target
end)
local function mergeDefaults(target, defaults)
	return normalizeTheBestSettings(target, defaults, { Keybinds = defaults == DEFAULT_KEYBINDS, IsKeyCode = function(name) return Enum.KeyCode[name] ~= nil end })
end

local function ensureConfigFolder()
	if isfolder and isfolder(CONFIG_DIRECTORY) then
		return true
	end
	if makefolder then
		return pcall(makefolder, CONFIG_DIRECTORY)
	end
	return false
end

local safeTheBestJSON = (function(deps)
	local api = { Version = 1 }
	local states = {}
	local function stateFor(path)
		if not states[path] then states[path] = {} end
		return states[path]
	end
	local function report(path, message)
		stateFor(path).error = message
		if type(deps.Warn) == "function" then deps.Warn("[TheBest settings] " .. path .. ": " .. message) end
	end
	local function decodeObject(raw)
		if type(raw) ~= "string" or not string.match(raw, "^%s*{") then return nil, "Expected a JSON object" end
		local ok, value = pcall(deps.Decode, raw)
		if not ok or type(value) ~= "table" then return nil, ok and "Expected an object" or tostring(value) end
		for key in pairs(value) do
			if type(key) ~= "string" then return nil, "Expected object field names" end
		end
		return value
	end
	local function readCandidate(path)
		if type(deps.Read) ~= "function" or type(deps.IsFile) ~= "function" then return { absent = true } end
		local existsOK, exists = pcall(deps.IsFile, path)
		if not existsOK then return { error = tostring(exists) } end
		if not exists then return { absent = true } end
		local ok, raw = pcall(deps.Read, path)
		if not ok then return { error = tostring(raw) } end
		local value, err = decodeObject(raw)
		return { raw = raw, value = value, error = err }
	end
	local function writeVerified(path, raw, json)
		local ok, err = pcall(deps.Write, path, raw)
		if not ok then return false, tostring(err) end
		local readOK, observed = pcall(deps.Read, path)
		if not readOK or observed ~= raw then return false, "Written data did not pass read-back verification" end
		if json and not decodeObject(observed) then return false, "Written JSON did not pass verification" end
		return true
	end
	local function preserveCorrupt(path, main)
		if main.absent or main.value then return true end
		if type(main.raw) ~= "string" then return false, "Cannot preserve the unreadable original; it was left untouched" end
		for index = 0, 99 do
			local archive = path .. ".corrupt" .. (index == 0 and "" or "." .. index)
			local candidate = readCandidate(archive)
			if candidate.raw == main.raw then return true end
			if candidate.absent then
				local ok, err = writeVerified(archive, main.raw, false)
				if ok then report(path, "Preserved damaged original at " .. archive) end
				return ok, err
			end
		end
		return false, "No free recovery archive path; original was left untouched"
	end
	function api.Load(path)
		local state = stateFor(path)
		local main, staging, backup = readCandidate(path), readCandidate(path .. ".tmp"), readCandidate(path .. ".bak")
		local selected, selectedPath
		if main.value then selected, selectedPath = main, path
		elseif staging.value then selected, selectedPath = staging, path .. ".tmp"
		elseif backup.value then selected, selectedPath = backup, path .. ".bak" end
		state.blocked = not selected and not (main.absent and staging.absent and backup.absent)
		state.source = selectedPath
		if selected then
			state.error = nil
			if selectedPath ~= path then report(path, "Recovered settings from " .. selectedPath .. "; no default reset was written") end
			return selected.value
		end
		if state.blocked then report(path, "No valid recovery copy. Existing files were left untouched; saving is blocked until a valid copy is restored") end
		return nil
	end
	function api.LoadPrimary(path)
		-- One-shot markers must never reappear from recovery files after their primary is deleted.
		return readCandidate(path).value
	end
	local function encodeObject(value)
		if type(value) ~= "table" then return nil, "Settings must be a table" end
		for key in pairs(value) do if type(key) ~= "string" then return nil, "Settings must contain named fields" end end
		local visiting = {}
		local function canEncode(child)
			local kind = type(child)
			if kind == "number" then return child == child and child ~= math.huge and child ~= -math.huge end
			if kind == "string" or kind == "boolean" or kind == "nil" then return true end
			if kind ~= "table" or visiting[child] then return false end
			visiting[child] = true
			for _, nested in pairs(child) do if not canEncode(nested) then visiting[child] = nil; return false end end
			visiting[child] = nil
			return true
		end
		if not canEncode(value) then return nil, "Settings contain a non-finite number, unsupported value, or cycle" end
		local ok, raw = pcall(deps.Encode, value)
		if not ok then return nil, tostring(raw) end
		local decoded, err = decodeObject(raw)
		if not decoded then return nil, err end
		return raw
	end
	local function commit(path, raw)
		local state = stateFor(path)
		local main = readCandidate(path)
		if state.blocked and not main.value then return false, "Saving is blocked to preserve damaged settings" end
		local preserved, preserveError = preserveCorrupt(path, main)
		if not preserved then return false, preserveError end
		local staged, stagingError = writeVerified(path .. ".tmp", raw, true)
		if not staged then return false, "Staging failed: " .. tostring(stagingError) end
		-- Never replace the last good backup with an invalid or partially written primary.
		local previousBackup = readCandidate(path .. ".bak")
		local backupRaw = main.value and main.raw or previousBackup.raw
		if not backupRaw or not decodeObject(backupRaw) then backupRaw = raw end
		if previousBackup.raw ~= backupRaw or not previousBackup.value then
			local backedUp, backupError = writeVerified(path .. ".bak", backupRaw, true)
			if not backedUp then return false, "Backup failed: " .. tostring(backupError) end
		end
		local saved, saveError = writeVerified(path, raw, true)
		if not saved then return false, "Primary write failed; verified staging and backup remain: " .. tostring(saveError) end
		state.blocked, state.error, state.source = false, nil, path
		-- A matching staging copy is intentionally retained, including on executors without renamefile/delfile.
		return true
	end
	function api.Save(path, value)
		if type(deps.Write) ~= "function" or type(deps.Read) ~= "function" or type(deps.IsFile) ~= "function" then return false, "File read/write verification is unavailable" end
		local raw, encodeError = encodeObject(value)
		if not raw then report(path, "Encoding failed; files were left untouched: " .. tostring(encodeError)); return false, encodeError end
		local state = stateFor(path)
		if state.writing then state.queued = raw; return true end
		state.writing = true
		local succeeded, err = true, nil
		repeat
			state.queued = nil
			local callOK, result, failure = pcall(commit, path, raw)
			succeeded, err = callOK and result == true, callOK and failure or tostring(result)
			if not succeeded then break end
			raw = state.queued
		until raw == nil
		state.writing = false
		if not succeeded then report(path, tostring(err)) end
		return succeeded, err
	end
	function api.Status(path) return stateFor(path) end
	return api
end)({
	Read=readfile, Write=writefile, IsFile=isfile,
	Encode=function(value) return HttpService:JSONEncode(value) end,
	Decode=function(value) return HttpService:JSONDecode(value) end, Warn=warn,
})
_G.TheBestSafeJSON = safeTheBestJSON
local function loadJsonFile(filePath)
	if filePath == CONFIG_FILE or filePath == KEYBINDS_FILE then return safeTheBestJSON.Load(filePath) end
	return safeTheBestJSON.LoadPrimary(filePath)
end

local TheBestConfigPersistenceFrozen = false
function SaveConfig()
	if TheBestConfigPersistenceFrozen then
		return false
	end
	if _G.TheBestBuildingUI then
		_G.TheBestConfigSavePending = true
		return true
	end
	if not writefile then
		return false
	end
	ensureConfigFolder()
	local succeeded, saveError = safeTheBestJSON.Save(CONFIG_FILE, _G.Config)
	if not succeeded then
		_G.ConfigSaveError = saveError
		warn("[CONFIG] Save failed: " .. tostring(saveError))
		return false
	end
	_G.ConfigSaveError = nil
	return true
end

function SaveKeybinds()
	if _G.TheBestBuildingUI then
		_G.TheBestKeybindSavePending = true
		return true
	end
	if not writefile then
		return false
	end
	ensureConfigFolder()
	local succeeded, saveError = safeTheBestJSON.Save(KEYBINDS_FILE, _G.Keybinds)
	if not succeeded then
		_G.KeybindSaveError = saveError
		warn("[KEYBINDS] Save failed: " .. tostring(saveError))
		return false
	end
	_G.KeybindSaveError = nil
	return true
end

function keyCode(name)
	local keyName = _G.Keybinds[name] or DEFAULT_KEYBINDS[name]
	return keyName and Enum.KeyCode[keyName] or nil
end

function getKey(name)
	return keyCode(name)
end

local function decodeBase64(value)
	local decoders = {}
	if type(crypt) == "table" and type(crypt.base64) == "table" and type(crypt.base64.decode) == "function" then
		table.insert(decoders, crypt.base64.decode)
	end
	if
		type(syn) == "table"
		and type(syn.crypt) == "table"
		and type(syn.crypt.base64) == "table"
		and type(syn.crypt.base64.decode) == "function"
	then
		table.insert(decoders, syn.crypt.base64.decode)
	end
	if type(base64) == "table" and type(base64.decode) == "function" then
		table.insert(decoders, base64.decode)
	end
	local hasHttpDecoder, httpDecoder = pcall(function()
		return HttpService.Base64Decode
	end)
	if hasHttpDecoder and type(httpDecoder) == "function" then
		table.insert(decoders, function(encoded)
			return HttpService:Base64Decode(encoded)
		end)
	end
	for _, decoder in ipairs(decoders) do
		local succeeded, decoded = pcall(decoder, value)
		if succeeded and type(decoded) == "string" and #decoded > 0 then
			return decoded
		end
	end
	local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	value = value:gsub("[^" .. alphabet .. "=]", "")
	local lookup = {}
	for index = 1, #alphabet do
		lookup[alphabet:sub(index, index)] = index - 1
	end
	local output = {}
	for index = 1, #value, 4 do
		local characterA = value:sub(index, index)
		local characterB = value:sub(index + 1, index + 1)
		local characterC = value:sub(index + 2, index + 2)
		local characterD = value:sub(index + 3, index + 3)
		local valueA = lookup[characterA]
		local valueB = lookup[characterB]
		if valueA == nil or valueB == nil then
			continue
		end
		local valueC = lookup[characterC] or 0
		local valueD = lookup[characterD] or 0
		local combined = valueA * 262144 + valueB * 4096 + valueC * 64 + valueD
		output[#output + 1] = string.char(math.floor(combined / 65536) % 256)
		if characterC ~= "=" and characterC ~= "" then
			output[#output + 1] = string.char(math.floor(combined / 256) % 256)
		end
		if characterD ~= "=" and characterD ~= "" then
			output[#output + 1] = string.char(combined % 256)
		end
	end
	return table.concat(output)
end

local function prepareAstolfoBackground()
	if not (writefile and isfile) then
		return nil
	end
	ensureConfigFolder()
	if not isfile(ASTOLFO_BACKGROUND_FILE) then
		local succeeded, decoded = pcall(decodeBase64, ASTOLFO_BACKGROUND_BASE64)
		if not succeeded or type(decoded) ~= "string" or #decoded == 0 then
			return nil
		end
		local wrote = pcall(writefile, ASTOLFO_BACKGROUND_FILE, decoded)
		if not wrote then
			return nil
		end
	end
	local assetLoader = getcustomasset or getsynasset
	if type(assetLoader) ~= "function" then
		return nil
	end
	local succeeded, asset = pcall(assetLoader, ASTOLFO_BACKGROUND_FILE)
	return succeeded and asset or nil
end

local function prepareHomelanderFinisherAsset()
	if not (writefile and isfile) then
		return nil
	end
	ensureConfigFolder()
	local function writeEmbeddedAsset()
		local decodedSuccessfully, decoded = pcall(decodeBase64, HOMELANDER_FINISHER_BASE64)
		if not decodedSuccessfully or type(decoded) ~= "string" or #decoded == 0 then
			return false
		end
		return pcall(writefile, HOMELANDER_FINISHER_FILE, decoded)
	end
	if not isfile(HOMELANDER_FINISHER_FILE) and not writeEmbeddedAsset() then
		return nil
	end
	local assetLoader = getcustomasset or getsynasset
	if type(assetLoader) ~= "function" then
		return nil
	end
	local succeeded, asset = pcall(assetLoader, HOMELANDER_FINISHER_FILE)
	if not succeeded or not asset then
		if not writeEmbeddedAsset() then
			return nil
		end
		succeeded, asset = pcall(assetLoader, HOMELANDER_FINISHER_FILE)
	end
	return succeeded and asset or nil
end

local function prepareGoldaFinisherAssets()
	local assets = {
		Image = nil,
		Sound = nil,
	}
	if not (writefile and isfile) then
		return assets
	end
	ensureConfigFolder()
	local assetLoader = getcustomasset or getsynasset
	if type(assetLoader) ~= "function" then
		return assets
	end

	local function prepareEmbeddedAsset(filePath, encodedData)
		local function writeEmbeddedAsset()
			local decodedSuccessfully, decoded = pcall(decodeBase64, encodedData)
			if not decodedSuccessfully or type(decoded) ~= "string" or #decoded == 0 then
				return false
			end
			return pcall(writefile, filePath, decoded)
		end

		if not isfile(filePath) and not writeEmbeddedAsset() then
			return nil
		end
		local succeeded, asset = pcall(assetLoader, filePath)
		if not succeeded or not asset then
			if not writeEmbeddedAsset() then
				return nil
			end
			succeeded, asset = pcall(assetLoader, filePath)
		end
		return succeeded and asset or nil
	end

	assets.Image = prepareEmbeddedAsset(GOLDA_FINISHER_IMAGE_FILE, GOLDA_FINISHER_IMAGE_BASE64)
	assets.Sound = prepareEmbeddedAsset(GOLDA_FINISHER_SOUND_FILE, GOLDA_FINISHER_SOUND_BASE64)
	return assets
end

local themeBackgroundCache = {}

local function prepareThemeBackground(themeName)
	if themeBackgroundCache[themeName] then
		return themeBackgroundCache[themeName]
	end
	local source = THEME_BACKGROUND_DATA[themeName]
	local assets = {
		sheets = {},
		frameWidth = source and source.frameWidth or 0,
		frameHeight = source and source.frameHeight or 0,
		columns = source and source.columns or 1,
		rows = source and source.rows or 1,
		frameCount = source and source.frameCount or 0,
		fps = source and source.fps or 1,
	}
	if not source then
		return assets
	end
	if not (writefile and isfile) then
		return assets
	end
	ensureConfigFolder()
	if makefolder and (not isfolder or not isfolder(THEME_BACKGROUND_DIRECTORY)) then
		pcall(makefolder, THEME_BACKGROUND_DIRECTORY)
	end
	local assetLoader = getcustomasset or getsynasset
	if type(assetLoader) ~= "function" then
		return assets
	end
	for sheetIndex, encoded in ipairs(source.sheets or {}) do
		if type(encoded) ~= "string" or #encoded == 0 then
			continue
		end
		local filePath = string.format(
			"%s/%s-atlas-%s-%02d.jpg",
			THEME_BACKGROUND_DIRECTORY,
			source.slug,
			source.assetVersion or "v2",
			sheetIndex
		)
		if not isfile(filePath) then
			local decodedSuccessfully, decoded = pcall(decodeBase64, encoded)
			if not decodedSuccessfully or type(decoded) ~= "string" or #decoded == 0 then
				continue
			end
			local wroteSuccessfully = pcall(writefile, filePath, decoded)
			if not wroteSuccessfully then
				continue
			end
		end
		local loadedSuccessfully, asset = pcall(assetLoader, filePath)
		if loadedSuccessfully and asset then
			assets.sheets[#assets.sheets + 1] = asset
		end
	end
	if #assets.sheets > 0 then
		assets.frameCount = math.min(assets.frameCount, #assets.sheets * assets.columns * assets.rows)
		themeBackgroundCache[themeName] = assets
		source.sheets = nil
	end
	return assets
end



