	local priorities = { Manual = 100, AntiTS = 95, Fly = 85, Pilot = 80, ClassicPilot = 80,
		Speedhack = 75, Sale = 90, Shop = 90, SpeedExploits = 65, NpcFarm = 60,
		StandAttach = 55, Mobile = 50, AutoSBR = 45, StandFarm = 40, ItemFarm = 90 }
	local function valid(token)
		return alive and token ~= nil and not token.Cancelled and token.Root ~= nil
			and token.Root.Parent ~= nil and roots[token.Root] == token
			and generations[token.Owner] == token.Generation and deps.Clock() <= token.Until
	end
	local function revoke(token)
		if not token or token.Cancelled then return end
		token.Cancelled = true
		if roots[token.Root] == token then roots[token.Root] = nil end
		if token.OnLost then pcall(token.OnLost) end
	end
	function api.Claim(owner, root, category, duration, onLost)
		if not alive or not root or not root.Parent then return nil end
		local current = roots[root]
		local priority = priorities[category or owner] or 40
		if current and valid(current) then
			if current.Owner == owner then
				current.Until = deps.Clock() + (duration or 0.2)
				if onLost then current.OnLost = onLost end
				return current
			end
			-- Equal priority is deliberately stable: two enabled farms queue instead of fighting.
			if current.Priority >= priority and priority ~= priorities.Manual then return nil end
		end
		revoke(current)
		sequence += 1
		generations[owner] = generations[owner] or 0
		local token = { Owner = owner, Root = root, Generation = generations[owner],
			Priority = priority, Until = deps.Clock() + (duration or 0.2), Sequence = sequence, OnLost = onLost }
		roots[root] = token
		return token
	end
	function api.Current(token) return valid(token) end
	function api.Renew(token, duration)
		if not valid(token) then return false end
		token.Until = deps.Clock() + (duration or 0.2)
		return true
	end
	function api.Write(token, frame)
		if not valid(token) then return false end
		token.Root.CFrame = frame
		return true
	end
	function api.Release(token) revoke(token) end
	function api.Cancel(owner)
		generations[owner] = (generations[owner] or 0) + 1
		for _, token in pairs(roots) do if token.Owner == owner then revoke(token) end end
	end
	function api.Cleanup()
		alive = false
		for _, token in pairs(roots) do revoke(token) end
	end
