local startupExtras = (function()
	local environment = _G
	if type(getgenv) == "function" then
		local ok, value = pcall(getgenv)
		if ok and type(value) == "table" then environment = value end
	end
	local shared = environment.TheBestInfiniteYieldStartup
	if type(shared) ~= "table" then
		shared = { status = "idle" }
		environment.TheBestInfiniteYieldStartup = shared
	end
	local ownToken, stopped
	local api = {}
	local function alreadyLoaded()
		return shared.status == "loaded" or environment.IY_LOADED or _G.IY_LOADED or IY_LOADED
	end
	local function report(stage, message)
		local text = "Infinite Yield " .. stage .. ": " .. tostring(message)
		local diagnostics = _G.TheBestDiagnostics
		if diagnostics and type(diagnostics.Record) == "function" then
			pcall(diagnostics.Record, "STARTUP ERROR", text)
		end
		warn("[THEBEST] " .. text)
	end
	function api.StartInfiniteYield(reason)
		if stopped then return false, "stopped" end
		if reason ~= "manual" and _G.Config and _G.Config.startupInfiniteYieldEnabled == false then
			return false, "disabled"
		end
		if alreadyLoaded() then return false, "loaded" end
		if shared.status == "loading" then return false, "loading" end
		local token = { cancelled = false }
		ownToken = token
		shared.status, shared.token = "loading", token
		task.spawn(function()
			local stage = "fetch"
			local ok, failure = pcall(function()
				local source = game:HttpGet("https://raw.githubusercontent.com/EdgeIY/infiniteyield/master/source")
				if token.cancelled or stopped or shared.token ~= token then return end
				assert(type(source) == "string" and #source > 0, "empty response")
				stage = "compile"
				local chunk, compileError = loadstring(source, "@InfiniteYield")
				assert(type(chunk) == "function", compileError or "compilation failed")
				if token.cancelled or stopped or shared.token ~= token or alreadyLoaded() then return end
				stage = "runtime"
				chunk()
				if shared.token == token then shared.status = "loaded" end
			end)
			if shared.token == token then
				if shared.status ~= "loaded" then shared.status = "idle" end
				shared.token = nil
			end
			if ownToken == token then ownToken = nil end
			if not ok and not token.cancelled and not stopped then report(stage, failure) end
		end)
		return true, "loading"
	end
	function api.AutoStart()
		return api.StartInfiniteYield("autostart")
	end
	function api.StopPending()
		stopped = true
		if ownToken then
			ownToken.cancelled = true
			if shared.token == ownToken then
				shared.token = nil
				if shared.status == "loading" then shared.status = "idle" end
			end
			ownToken = nil
		end
	end
	return api
end)()


