				removeDrawing(v.healthBack)
				removeDrawing(v.healthFill)
				removeDrawing(v.healthText)
				removeDrawing(v.tracer)
				for _, line in pairs(v.skeleton) do
					removeDrawing(line)
				end
			end
			visuals[player] = nil
			playerCache[player] = nil
		end
		local function getVisual(player)
			if not visuals[player] then
				visuals[player] = makeVisual()
			end
			return visuals[player]
		end
		local bodyPartNames = {
			"Head",
			"UpperTorso",
			"LowerTorso",
			"Torso",
			"Left Arm",
			"Right Arm",
			"Left Leg",
			"Right Leg",
			"LeftUpperArm",
			"LeftLowerArm",
			"LeftHand",
			"RightUpperArm",
			"RightLowerArm",
			"RightHand",
			"LeftUpperLeg",
			"LeftLowerLeg",
			"LeftFoot",
			"RightUpperLeg",
			"RightLowerLeg",
			"RightFoot",
		}
		local fallbackMap = {
			UpperTorso = "Torso",
			LowerTorso = "UpperTorso",
			LeftUpperArm = "Left Arm",
			LeftLowerArm = "LeftUpperArm",
			LeftHand = "LeftLowerArm",
			RightUpperArm = "Right Arm",
			RightLowerArm = "RightUpperArm",
			RightHand = "RightLowerArm",
			LeftUpperLeg = "Left Leg",
			LeftLowerLeg = "LeftUpperLeg",
			LeftFoot = "LeftLowerLeg",
			RightUpperLeg = "Right Leg",
			RightLowerLeg = "RightUpperLeg",
			RightFoot = "RightLowerLeg",
		}
		local function ensureNativeHumanoidDisplay(humanoid)
			if not humanoid or not humanoid.Parent then
				return
			end
			pcall(function()
				if humanoid.DisplayDistanceType ~= Enum.HumanoidDisplayDistanceType.Subject then
					humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.Subject
				end
				if humanoid.NameDisplayDistance ~= 100 then
					humanoid.NameDisplayDistance = 100
				end
				if humanoid.HealthDisplayDistance ~= 100 then
					humanoid.HealthDisplayDistance = 100
				end
				if humanoid.HealthDisplayType ~= Enum.HumanoidHealthDisplayType.AlwaysOn then
					humanoid.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOn
				end
				if humanoid.NameOcclusion ~= Enum.NameOcclusion.NoOcclusion then
					humanoid.NameOcclusion = Enum.NameOcclusion.NoOcclusion
				end
			end)
		end
		local function cacheCharacterParts(player, character)
			local root = character:FindFirstChild("HumanoidRootPart")
			local humanoid = character:FindFirstChildOfClass("Humanoid")
			if not root or not humanoid then
				return
			end
			local previousCache = playerCache[player]
			if previousCache and previousCache.partConnections then
				for _, connection in ipairs(previousCache.partConnections) do
					connection:Disconnect()
				end
			end
			if previousCache and previousCache.nativeDisplayConnection then
				previousCache.nativeDisplayConnection:Disconnect()
			end
			if previousCache and previousCache.nativeDisplayConnections then
				for _, connection in ipairs(previousCache.nativeDisplayConnections) do
					connection:Disconnect()
				end
			end
			ensureNativeHumanoidDisplay(humanoid)
			local nativeDisplayConnections = {}
			for _, propertyName in ipairs({
				"DisplayDistanceType",
				"NameDisplayDistance",
				"HealthDisplayDistance",
				"HealthDisplayType",
				"NameOcclusion",
			}) do
				table.insert(
					nativeDisplayConnections,
					humanoid:GetPropertyChangedSignal(propertyName):Connect(function()
						ensureNativeHumanoidDisplay(humanoid)
					end)
				)
			end
			local parts = {}
			for _, name in ipairs(bodyPartNames) do
				local part = character:FindFirstChild(name)
				if not part and fallbackMap[name] then
					part = character:FindFirstChild(fallbackMap[name])
				end
				if not part and fallbackMap[fallbackMap[name]] then
					part = character:FindFirstChild(fallbackMap[fallbackMap[name]])
				end
				if part and part:IsA("BasePart") then
					parts[name] = part
				end
			end
			-- R6 fallback aliases point to the same limbs. Bounds must include
			-- each real part once, not again for every R15 alias.
			local boundsParts, seen = {}, {}
			for _, name in ipairs(bodyPartNames) do
				local part = parts[name]
				if part and not seen[part] then
					seen[part] = true
					boundsParts[#boundsParts + 1] = part
				end
			end
			local cache = {
				character = character,
				root = root,
				humanoid = humanoid,
				parts = parts,
				boundsParts = boundsParts,
				projectedParts = {},
				partsDirty = false,
				nativeDisplayConnections = nativeDisplayConnections,
			}
			local function invalidateParts(child)
				if child:IsA("BasePart") or child:IsA("Humanoid") then
					cache.partsDirty = true
				end
			end
			cache.partConnections = {
				character.ChildAdded:Connect(invalidateParts),
				character.ChildRemoved:Connect(invalidateParts),
			}
			playerCache[player] = cache
		end
		local projection = {}
		local function updateProjection(camera)
			local viewport = camera.ViewportSize
			if viewport.X <= 0 or viewport.Y <= 0 then
				return false
			end
			local cf = camera.CFrame
			projection.view = cf:Inverse()
			projection.position = cf.Position
			projection.width, projection.height = viewport.X, viewport.Y
			projection.halfX, projection.halfY = viewport.X * 0.5, viewport.Y * 0.5
			-- Calibrate from the actual camera once per update. This also follows
			-- FOV, viewport and CurrentCamera changes without per-corner API calls.
			local sample = camera:WorldToViewportPoint(cf:PointToWorldSpace(Vector3.new(1, 1, -1)))
			projection.scaleX = sample.X - projection.halfX
			projection.scaleY = projection.halfY - sample.Y
			return true
		end
		local function getBodyBounds(_, parts)
			local minX, minY, maxX, maxY = math.huge, math.huge, -math.huge, -math.huge
			local view = projection.view
			local halfX, halfY = projection.halfX, projection.halfY
			local scaleX, scaleY = projection.scaleX, projection.scaleY
			for _, part in ipairs(parts) do
				if part.Parent then
					local size = part.Size
					local hx, hy, hz = size.X * 0.5, size.Y * 0.5, size.Z * 0.5
					local x, y, z, r00, r01, r02, r10, r11, r12, r20, r21, r22 = (view * part.CFrame):GetComponents()
					-- Same eight limb corners as before, projected with scalar math.
					-- No point tables or Vector3 allocations in this inner loop.
					for sx = -1, 1, 2 do
						for sy = -1, 1, 2 do
							local px = x + sx * hx * r00 + sy * hy * r01
							local py = y + sx * hx * r10 + sy * hy * r11
							local pz = z + sx * hx * r20 + sy * hy * r21
							for sz = -1, 1, 2 do
								local depth = -(pz + sz * hz * r22)
								if depth > 0.01 then
									local screenX = halfX + (px + sz * hz * r02) * scaleX / depth
									local screenY = halfY - (py + sz * hz * r12) * scaleY / depth
									minX, minY = math.min(minX, screenX), math.min(minY, screenY)
									maxX, maxY = math.max(maxX, screenX), math.max(maxY, screenY)
								end
							end
						end
					end
				end
			end
			if minX == math.huge or maxX < -32 or maxY < -32 or minX > projection.width + 32 or minY > projection.height + 32 then
				return nil
			end
			local padX = math.clamp((maxX - minX) * 0.035, 2, 7)
			local padY = math.clamp((maxY - minY) * 0.025, 2, 6)
			return minX - padX, minY - padY, maxX + padX, maxY + padY
		end
		local projectedParts = nil
		local function worldToScreen(_, part)
			if not part or not part.Parent then
				return nil
			end
			local cached = projectedParts[part]
			if cached ~= nil then
				return cached or nil
			end
			local point = projection.view:PointToWorldSpace(part.Position)
			local result = false
			if point.Z < -0.01 then
				local x = projection.halfX + point.X * projection.scaleX / -point.Z
				local y = projection.halfY - point.Y * projection.scaleY / -point.Z
				if x >= 0 and x <= projection.width and y >= 0 and y <= projection.height then
					result = Vector2.new(x, y)
				end
			end
			projectedParts[part] = result
			return result or nil
		end
		local function getOrCreateSkeletonLine(v, name)
			if not v.skeleton[name] then
				v.skeleton[name] = makeLine(1)
			end
			return v.skeleton[name]
		end
		local function drawSkeletonLine(camera, v, color, name, aPart, bPart, transparency)
			local line = getOrCreateSkeletonLine(v, name)
			local a = worldToScreen(camera, aPart)
			local b = worldToScreen(camera, bPart)
			if a and b then
				line.From = a
				line.To = b
				line.Color = color
				line.Transparency = transparency or 0.85
				line.Visible = true
			else
				line.Visible = false
			end
		end
		local function setLine(line, from, to, color, transparency)
			line.From = from
			line.To = to
			line.Color = color
			line.Transparency = transparency or 1
			line.Visible = true
		end
		local function getDistanceFade(distance)
			if not _G.Config.espFadeByDistance then
				return 1
			end
			local fadeDistance = math.clamp(tonumber(_G.Config.maxVisibilityDistance) or 500, 50, 10000)
			local progress = math.clamp(distance / fadeDistance, 0, 1)
			return 1 - progress * 0.78
		end
		local function getAnimatedEspColor(baseColor, player, phase)
			if not _G.Config.espAnimatedGradient or baseColor == white then
				return baseColor
			end
			local userOffset = ((player and player.UserId or 0) % 97) / 97
			local wave = (math.sin(animationTime + userOffset * math.pi * 2 + (phase or 0)) + 1) * 0.5
			return baseColor:Lerp(white, 0.1 + wave * 0.32)
		end
		local function drawCornerBox(lines, minX, minY, maxX, maxY, color, transparency, offset)
			offset = offset or 0
			local width = maxX - minX
			local height = maxY - minY
			local corner = math.clamp(math.min(width, height) * 0.28, 8, 18)
			local left = minX - offset
			local right = maxX + offset
			local top = minY - offset
			local bottom = maxY + offset
			local function segmentColor(index)
				return type(color) == "function" and color(index) or color
			end
			setLine(lines.topLeftH, Vector2.new(left, top), Vector2.new(left + corner, top), segmentColor(1), transparency)
			setLine(lines.topLeftV, Vector2.new(left, top), Vector2.new(left, top + corner), segmentColor(2), transparency)
			setLine(lines.topRightH, Vector2.new(right - corner, top), Vector2.new(right, top), segmentColor(3), transparency)
			setLine(lines.topRightV, Vector2.new(right, top), Vector2.new(right, top + corner), segmentColor(4), transparency)
			setLine(
				lines.bottomLeftH,
				Vector2.new(left, bottom),
				Vector2.new(left + corner, bottom),
				segmentColor(5),
				transparency
			)
			setLine(
				lines.bottomLeftV,
				Vector2.new(left, bottom - corner),
				Vector2.new(left, bottom),
				segmentColor(6),
				transparency
			)
			setLine(
				lines.bottomRightH,
				Vector2.new(right - corner, bottom),
				Vector2.new(right, bottom),
				segmentColor(7),
				transparency
			)
			setLine(
				lines.bottomRightV,
				Vector2.new(right, bottom - corner),
				Vector2.new(right, bottom),
				segmentColor(8),
				transparency
			)
		end
		local function drawSkeleton(camera, parts, v, player, visibility)
			if not _G.Config.showSkeleton then
				for _, line in pairs(v.skeleton) do
					line.Visible = false
				end
				return
			end
			local head = parts.Head
			local torso = parts.UpperTorso or parts.Torso
			local lowerTorso = parts.LowerTorso or torso
			local color = getAnimatedEspColor(cachedColors.skeleton, player, 1.4)
			local lineTransparency = 0.85 * (visibility or 1)
			if head and torso then
				drawSkeletonLine(camera, v, color, "headTorso", head, torso, lineTransparency)
			end
			if torso and lowerTorso then
				drawSkeletonLine(camera, v, color, "torsoLower", torso, lowerTorso, lineTransparency)
			end
			local function drawArm(side)
				local upper = parts[side .. "UpperArm"]
				local lower = parts[side .. "LowerArm"]
				local hand = parts[side .. "Hand"]
				if torso and upper then
					drawSkeletonLine(camera, v, color, side .. "Arm1", torso, upper, lineTransparency)
				end
				if upper and lower then
					drawSkeletonLine(camera, v, color, side .. "Arm2", upper, lower, lineTransparency)
				end
				if lower and hand then
					drawSkeletonLine(camera, v, color, side .. "Arm3", lower, hand, lineTransparency)
				end
			end
			local function drawLeg(side)
				local upper = parts[side .. "UpperLeg"]
				local lower = parts[side .. "LowerLeg"]
				local foot = parts[side .. "Foot"]
				if lowerTorso and upper then
					drawSkeletonLine(camera, v, color, side .. "Leg1", lowerTorso, upper, lineTransparency)
				end
				if upper and lower then
					drawSkeletonLine(camera, v, color, side .. "Leg2", upper, lower, lineTransparency)
				end
				if lower and foot then
					drawSkeletonLine(camera, v, color, side .. "Leg3", lower, foot, lineTransparency)
				end
			end
			drawArm("Left")
			drawArm("Right")
			drawLeg("Left")
			drawLeg("Right")
		end
		local function updatePlayer(camera, player, nearestPlayer)
			local cache = playerCache[player]
			if not cache then
				local char = player.Character
				if char then
					cacheCharacterParts(player, char)
					cache = playerCache[player]
				end
				if not cache then
					return
				end
			end
			local character = cache.character
			local root = cache.root
			local humanoid = cache.humanoid
			local parts = cache.parts
			if player.Character ~= character or not character.Parent or not root or not humanoid or not root.Parent or not humanoid.Parent or humanoid.Health <= 0 then
				local v = visuals[player]
				if v then
					hideVisual(v)
				end
				return
			end
			local offset = projection.position - root.Position
			local distSquared = offset.X * offset.X + offset.Y * offset.Y + offset.Z * offset.Z
			local maxDist = _G.Config.changeMaxVisibilityDistance and math.max(tonumber(_G.Config.maxVisibilityDistance) or 500, 0) or math.huge
			if distSquared > maxDist * maxDist then
				hideVisual(visuals[player])
				return
			end
			local minX, minY, maxX, maxY = getBodyBounds(camera, cache.boundsParts)
			if not minX then
				hideVisual(visuals[player])
				return
			end
			local v = getVisual(player)
			v.hidden = false
			local distance = math.sqrt(distSquared)
			local visibility = getDistanceFade(distance)
			local boxColor = getAnimatedEspColor(cachedColors.box, player, 0)
			local boxSize = Vector2.new(math.max(maxX - minX, 1), math.max(maxY - minY, 1))
			if _G.Config.showBox then
				if _G.Config.espFilledBox then
					v.boxFill.Position = Vector2.new(minX, minY)
					v.boxFill.Size = boxSize
					v.boxFill.Color = boxColor
					v.boxFill.Transparency = 0.13 * visibility
					v.boxFill.Visible = true
				else
					v.boxFill.Visible = false
				end
				if _G.Config.espFullBox then
					v.boxFull.Position = Vector2.new(minX, minY)
					v.boxFull.Size = boxSize
					v.boxFull.Color = getAnimatedEspColor(cachedColors.box, player, 2.1)
					v.boxFull.Transparency = 0.9 * visibility
					v.boxFull.Visible = true
				else
					v.boxFull.Visible = false
				end
				if _G.Config.espCornerBox then
					drawCornerBox(v.boxShadow, minX, minY, maxX, maxY, black, 0.55 * visibility, 1)
					drawCornerBox(v.box, minX, minY, maxX, maxY, function(index)
						return getAnimatedEspColor(cachedColors.box, player, index * 0.55)
					end, 0.95 * visibility, 0)
				else
					for _, line in pairs(v.box) do
						line.Visible = false
					end
					for _, line in pairs(v.boxShadow) do
						line.Visible = false
					end
				end
			else
				v.boxFill.Visible = false
				v.boxFull.Visible = false
				for _, line in pairs(v.box) do
					line.Visible = false
				end
				for _, line in pairs(v.boxShadow) do
					line.Visible = false
				end
			end
			if _G.Config.showName then
				v.name.Text = player.Name
				v.name.Position = Vector2.new((minX + maxX) * 0.5, minY - 18)
				v.name.Color = getAnimatedEspColor(cachedColors.name, player, 0.8)
				v.name.Transparency = 0.95 * visibility
				v.name.Visible = true
			else
				v.name.Visible = false
			end
			if _G.Config.showDistance then
				v.distance.Text = string.format("%dm", math.floor(distance))
				v.distance.Position = Vector2.new((minX + maxX) * 0.5, maxY + 4)
				v.distance.Color = getAnimatedEspColor(cachedColors.distance, player, 1.6)
				v.distance.Transparency = 0.9 * visibility
				v.distance.Visible = true
			else
				v.distance.Visible = false
			end
			do
				local target = type(getLockedTarget) == "function" and getLockedTarget() or nil
				local tagY = _G.Config.showSelectedTag and target == player
					and getTargetTagY(minY, maxY, camera.ViewportSize.Y, _G.Config)
				if tagY then
					v.selectedTag.Text = "[TARGET]"
					v.selectedTag.Position = Vector2.new((minX + maxX) * 0.5, tagY)
					v.selectedTag.Color = getAnimatedEspColor(cachedColors.selectedTag, player, 2.4)
					v.selectedTag.Transparency = 0.95 * visibility
					v.selectedTag.Visible = true
				else
					v.selectedTag.Visible = false
				end
			end
			if _G.Config.showHealthBar then
				local ratio = math.clamp(humanoid.Health / math.max(humanoid.MaxHealth, 1), 0, 1)
				local height = maxY - minY
				local fillHeight = height * ratio
				local x = minX - 6
				v.healthBack.From = Vector2.new(x, minY)
				v.healthBack.To = Vector2.new(x, maxY)
				v.healthBack.Color = black
				v.healthBack.Transparency = 0.55 * visibility
				v.healthBack.Visible = true
				v.healthFill.From = Vector2.new(x, maxY - fillHeight)
				v.healthFill.To = Vector2.new(x, maxY)
				local healthColor = Color3.fromRGB(
					math.clamp(math.floor(255 * (1 - ratio) * 2), 0, 255),
					math.clamp(math.floor(255 * ratio * 2), 0, 255),
					0
				)
				v.healthFill.Color = getAnimatedEspColor(healthColor, player, 3.2)
				v.healthFill.Transparency = 0.95 * visibility
				v.healthFill.Visible = true
				if _G.Config.showHealthText then
					v.healthText.Text = string.format("%d HP", math.floor(humanoid.Health + 0.5))
					v.healthText.Position = Vector2.new(minX - 22, maxY - fillHeight - 6)
					v.healthText.Color = getAnimatedEspColor(healthColor, player, 3.8)
					v.healthText.Transparency = 0.92 * visibility
					v.healthText.Visible = true
				else
					v.healthText.Visible = false
				end
			else
				v.healthBack.Visible = false
				v.healthFill.Visible = false
				v.healthText.Visible = false
			end
			if _G.Config.showTracers and (not _G.Config.tracerToNearPlayer or nearestPlayer == player) then
				local viewport = camera.ViewportSize
				v.tracer.From = Vector2.new(viewport.X * 0.5, viewport.Y)
				v.tracer.To = Vector2.new((minX + maxX) * 0.5, maxY)
				v.tracer.Color = getAnimatedEspColor(cachedColors.tracer, player, 4.6)
				v.tracer.Transparency = 0.75 * visibility
				v.tracer.Visible = true
			else
				v.tracer.Visible = false
			end
			if _G.Config.showSkeleton then
				projectedParts = cache.projectedParts
				table.clear(projectedParts)
				drawSkeleton(camera, parts, v, player, visibility)
			else
				for _, line in pairs(v.skeleton) do
					line.Visible = false
				end
			end
		end
		local playerList = {}
		local function updatePlayerList()
			local newList = Players:GetPlayers()
			playerList = newList
		end
		updatePlayerList()
		trackConnection(Players.PlayerAdded:Connect(updatePlayerList))
		trackConnection(Players.PlayerRemoving:Connect(function(player)
			cleanupPlayer(player)
			local index = table.find(playerList, player)
			if index then
				table.remove(playerList, index)
			end
		end))
		local function getNearestPlayer(camera)
			local nearest, nearestDistSq = nil, math.huge
			for _, player in ipairs(playerList) do
				if player ~= LocalPlayer then
					local cache = playerCache[player]
					if cache and cache.character == player.Character and cache.root.Parent and cache.humanoid.Parent and cache.humanoid.Health > 0 then
						local offset = projection.position - cache.root.Position
						local distSq = offset.X * offset.X + offset.Y * offset.Y + offset.Z * offset.Z
						if distSq < nearestDistSq then
							nearestDistSq = distSq
							nearest = player
						end
					end
				end
			end
			return nearest
		end
		local frameCount = 0
		local drawingEnabled = false
		local nextColorUpdate = 0
		local function updateEsp()
			if not active then
				return
			end
			local cfg = _G.Config
			local hasDrawing = cfg and cfg.mhud and (
				(cfg.showBox and (cfg.espFilledBox or cfg.espFullBox or cfg.espCornerBox))
				or cfg.showName or cfg.showDistance or cfg.showSkeleton or cfg.showHealthBar or cfg.showTracers
				or cfg.showSelectedTag
			)
			if not hasDrawing then
				if drawingEnabled then
					for _, visual in pairs(visuals) do
						hideVisual(visual)
					end
				end
				drawingEnabled = false
				frameCount = 0
				return
			end
			local wasEnabled = drawingEnabled
			drawingEnabled = true
			frameCount = frameCount + 1
			local resolution = math.clamp(math.floor(tonumber(cfg.Resolution) or 1), 1, 6)
			if wasEnabled and resolution > 1 and frameCount % resolution ~= 0 then
				return
			end
			local camera = workspace.CurrentCamera
			if not camera or not updateProjection(camera) then
				for _, visual in pairs(visuals) do
					hideVisual(visual)
				end
				return
			end
			local now = os.clock()
			animationTime = now * 2
			if now >= nextColorUpdate then
				nextColorUpdate = now + 0.15
				updateCachedColors()
			end
			-- Refresh streamed/respawned characters before selecting the nearest one.
			for _, player in ipairs(playerList) do
				if player ~= LocalPlayer then
					local char = player.Character
					local cache = playerCache[player]
					if not char or (cache and cache.character ~= char) then
						cleanupPlayer(player)
						cache = nil
					end
					if char then
						if not cache or cache.partsDirty then
							hideVisual(visuals[player])
							cacheCharacterParts(player, char)
						end
					end
				end
			end
			local nearestPlayer = cfg.showTracers and cfg.tracerToNearPlayer and getNearestPlayer(camera) or nil
			for _, player in ipairs(playerList) do
