		function getStandPilotCharacterParts()
			local char = LocalPlayer.Character
			if not char then
				return nil
			end
			local root = char:FindFirstChild("HumanoidRootPart")
			return char, nil, root
		end
		function getGroundHeight(pos)
			local rayOrigin = pos + Vector3.new(0, 5, 0)
			local rayDirection = Vector3.new(0, -50, 0)
			local rayParams = RaycastParams.new()
			rayParams.FilterType = Enum.RaycastFilterType.Blacklist
			local ignoreList = { LocalPlayer.Character }
			local living = Workspace:FindFirstChild("Living")
			if living then
				for _, obj in ipairs(living:GetChildren()) do
					if obj:IsA("Model") then
						table.insert(ignoreList, obj)
					end
				end
			end
			rayParams.FilterDescendantsInstances = ignoreList
			local rayResult = Workspace:Raycast(rayOrigin, rayDirection, rayParams)
			if rayResult then
				return rayResult.Position.Y
			end
			return pos.Y
		end
		function getStandPilotTargetRoot()
			if npcPilotOwned then
				local hum=npcPilotTarget and npcPilotTarget:FindFirstChildOfClass("Humanoid")
				return hum and hum.Health>0 and (npcPilotTarget:FindFirstChild("HumanoidRootPart") or npcPilotTarget.PrimaryPart) or nil
			end
			return getTargetRoot(findTargetByName(_G.Config.input_TargetSurvName))
		end
		local function applyStandPilotNoclip(character)
			if not character then
				return
			end
			for _, part in ipairs(character:GetDescendants()) do
				if part:IsA("BasePart") then
					if standPilotCollisionState[part] == nil then
						standPilotCollisionState[part] = part.CanCollide
					end
					part.CanCollide = false
				end
			end
		end
		local function restoreStandPilotCollisions()
			for part, canCollide in pairs(standPilotCollisionState) do
				if part and part.Parent then
					pcall(function()
						part.CanCollide = canCollide
					end)
				end
			end
			standPilotCollisionState = setmetatable({}, { __mode = "k" })
		end
		function startStandPilot()
			if standPilotActive then
				stopStandPilot()
				return
			end
			if type(_G.TheBestClassicPilotSetEnabled) == "function" then
				pcall(_G.TheBestClassicPilotSetEnabled, false)
			end
			local char, _, root = getStandPilotCharacterParts()
			if not char or not root then
				return
			end
			local living = Workspace:FindFirstChild("Living")
			if not living then
				return
			end
			local stand = living:FindFirstChild(LocalPlayer.Name)
			if not stand then
				return
			end
			local standMorph = stand:FindFirstChild("StandMorph")
			if not standMorph then
				return
			end
			local standRoot = standMorph:FindFirstChild("HumanoidRootPart")
			if not standRoot then
				return
			end
			local owner = npcPilotOwned and "NpcFarm" or "Pilot"
			if not movementRuntime.Claim(owner, root, owner, 0.3) then return end
			standPilotActive = true
			standPilotCollisionState = setmetatable({}, { __mode = "k" })
			targetLastPos = nil
			targetVelocity = Vector3.new(0, 0, 0)
			local initialTarget=npcPilotOwned and getStandPilotTargetRoot()
			standPos = initialTarget and (initialTarget.Position+Vector3.new(0,_G.Config.standPilotYPos,0)) or root.Position + Vector3.new(0, _G.Config.standPilotUnderground, 0)
			standY = standPos.Y
			playerVelocityY = 0
			isJumping = false
			jumpCooldown = 0
			local cam = Workspace.CurrentCamera
			if cam then
				cameraAngleX = math.atan2(cam.CFrame.LookVector.Z, cam.CFrame.LookVector.X)
				cameraAngleY = math.asin(cam.CFrame.LookVector.Y)
			end
			previousMouseBehavior = UserInputService.MouseBehavior
			UserInputService.MouseBehavior = Enum.MouseBehavior.LockCenter
			mouseConn = UserInputService.InputChanged:Connect(function(input)
				if not standPilotActive then
					return
				end
				if input.UserInputType == Enum.UserInputType.MouseMovement then
					local delta = input.Delta
					cameraAngleX = cameraAngleX + delta.X * 0.003
					cameraAngleY = math.clamp(cameraAngleY - delta.Y * 0.003, -1.4, 1.4)
				end
			end)
			local initialLook = root.CFrame.LookVector * Vector3.new(1, 0, 1)
			if initialLook.Magnitude <= 0 then
				initialLook = Vector3.new(0, 0, -1)
			else
				initialLook = initialLook.Unit
			end
			standRoot.CFrame = CFrame.lookAt(standPos, standPos + initialLook)
			root.CFrame = CFrame.new(standPos.X, standY - _G.Config.standPilotUnderground, standPos.Z)
			applyStandPilotNoclip(char)
			noclipConn = RunService.Stepped:Connect(function()
				if not standPilotActive then
					return
				end
				applyStandPilotNoclip(char)
			end)
			local currentCamera = Workspace.CurrentCamera
			if currentCamera then
				previousCameraType = currentCamera.CameraType
				previousCameraSubject = currentCamera.CameraSubject
				currentCamera.CameraType = Enum.CameraType.Scriptable
			end
			camConn = RunService.RenderStepped:Connect(function()
				if not standPilotActive then
					return
				end
				local currentCam = Workspace.CurrentCamera
				if currentCam and standRoot and standRoot.Parent then
					local lookDir = Vector3.new(
						math.cos(cameraAngleY) * math.cos(cameraAngleX),
						math.sin(cameraAngleY),
						math.cos(cameraAngleY) * math.sin(cameraAngleX)
					)
					local cameraFocusPos = standRoot.Position
					local camPos = cameraFocusPos + Vector3.new(0, 4, 0) - lookDir * 12
					currentCam.CFrame = CFrame.lookAt(camPos, camPos + lookDir)
				end
			end)
			megaConn = RunService.RenderStepped:Connect(function(dt)
				local owner = npcPilotOwned and "NpcFarm" or "Pilot"
				if not movementRuntime.Claim(owner, root, owner, 0.3) then return end
				if not standPilotActive then
					return
				end
				local liveCharacter, liveHumanoid = getCharacterParts()
				if liveCharacter ~= char or not liveHumanoid or liveHumanoid.Health <= 0 then stopStandPilot(); return end
				if not standRoot or not standRoot.Parent then
					stopStandPilot()
					return
				end
				if not root or not root.Parent then
					stopStandPilot()
					return
				end
				local camLook = Vector3.new(math.cos(cameraAngleX), 0, math.sin(cameraAngleX))
				local camRight = Vector3.new(-camLook.Z, 0, camLook.X)
				if npcPilotOwned or _G.Config.pilotMode == "Target Lock" then
					local targetRoot = getStandPilotTargetRoot()
					if targetRoot then
						local targetPos = targetRoot.Position
						if targetLastPos then
							local rawVelocity = (targetPos - targetLastPos) / math.max(dt,1/240)
							targetVelocity = targetVelocity:Lerp(rawVelocity, targetSmoothFactor)
						end
						targetLastPos = targetPos
						local predictedPos = targetPos + targetVelocity * 0.5
						local predictOffset = predictedPos - targetPos
						if predictOffset.Magnitude > _G.Config.targetLockPredict then
							predictedPos = targetPos + predictOffset.Unit * _G.Config.targetLockPredict
						end
						standPos =
							Vector3.new(predictedPos.X, predictedPos.Y + _G.Config.standPilotYPos, predictedPos.Z)
						standY = standPos.Y
						standRoot.CFrame = CFrame.lookAt(standPos, standPos + camLook)
						root.CFrame = CFrame.new(standPos.X, standY - _G.Config.standPilotUnderground, standPos.Z)
					end
					return
				end
				local moveDir = Vector3.zero
				if UserInputService:IsKeyDown(Enum.KeyCode.W) then
					moveDir += camLook
				end
				if UserInputService:IsKeyDown(Enum.KeyCode.S) then
					moveDir -= camLook
				end
				if UserInputService:IsKeyDown(Enum.KeyCode.A) then
					moveDir -= camRight
				end
				if UserInputService:IsKeyDown(Enum.KeyCode.D) then
					moveDir += camRight
				end
				local speed = _G.Config.standPilotSpeed or 50
				if moveDir.Magnitude > 0 then
					moveDir = moveDir.Unit
					standPos = standPos + moveDir * speed * dt
				end
				local noclipMode = UserInputService:IsKeyDown(Enum.KeyCode.E)
				if not noclipMode then
					local groundY = getGroundHeight(standPos)
					local targetY = groundY + _G.Config.standPilotYPos
					if jumpCooldown > 0 then
						jumpCooldown = jumpCooldown - dt
					end
					local spaceHeld = UserInputService:IsKeyDown(Enum.KeyCode.Space)
					if spaceHeld and not isJumping and jumpCooldown <= 0 and standY <= targetY + 1 then
						playerVelocityY = 40
						isJumping = true
						jumpCooldown = 1
					end
					if isJumping then
						playerVelocityY = playerVelocityY - 100 * dt
						standY = standY + playerVelocityY * dt
						if standY <= targetY then
							standY = targetY
							playerVelocityY = 0
							isJumping = false
						end
					else
						if standY > targetY then
							standY = standY - 60 * dt
							if standY < targetY then
								standY = targetY
							end
						else
							standY = targetY
						end
					end
				end
				local finalPos = Vector3.new(standPos.X, standY, standPos.Z)
				standRoot.CFrame = CFrame.lookAt(finalPos, finalPos + camLook)
				root.CFrame = CFrame.new(standPos.X, standY - _G.Config.standPilotUnderground, standPos.Z)
			end)
		end
		function stopStandPilot()
			movementRuntime.Cancel(npcPilotOwned and "NpcFarm" or "Pilot")
			standPilotActive = false
			npcPilotOwned=false;npcPilotTarget=nil
			if previousMouseBehavior ~= nil then
				pcall(function()
					UserInputService.MouseBehavior = previousMouseBehavior
				end)
			end
			previousMouseBehavior = nil
			targetLastPos = nil
			targetVelocity = Vector3.new(0, 0, 0)
			if megaConn then
				megaConn:Disconnect()
				megaConn = nil
			end
			if noclipConn then
				noclipConn:Disconnect()
				noclipConn = nil
			end
			if camConn then
				camConn:Disconnect()
				camConn = nil
			end
			if mouseConn then
				mouseConn:Disconnect()
				mouseConn = nil
			end
			restoreStandPilotCollisions()
			local char = LocalPlayer.Character
			local cam = Workspace.CurrentCamera
			if cam and previousCameraType ~= nil then
				cam.CameraType = previousCameraType
				if previousCameraSubject then
					cam.CameraSubject = previousCameraSubject
				elseif char then
					local hum = char:FindFirstChildOfClass("Humanoid")
					if hum then
						cam.CameraSubject = hum
					end
				end
			end
			previousCameraType = nil
			previousCameraSubject = nil
		end
		_G.TheBestNpcPilotSetTarget=function(target)
			if not target then if npcPilotOwned then stopStandPilot() end;return false end
			if standPilotActive and not npcPilotOwned then stopStandPilot() end
			if npcPilotTarget~=target then targetLastPos=nil;targetVelocity=Vector3.zero end
			npcPilotTarget=target;npcPilotOwned=true
			if not standPilotActive then startStandPilot() end
			return standPilotActive
		end
