		if _G.TheBestOldMapTexturesCleanup then
			pcall(_G.TheBestOldMapTexturesCleanup)
			_G.TheBestOldMapTexturesCleanup = nil
		end
		local oldMapTextureStates = {}
		local oldMapTextureConnection = nil
		local oldMapTextureActive = false

		local function getOldMapTextureReplacement(part)
			local colorName = part.BrickColor.Name
			if colorName == "Fossil" or colorName == "Concrete" or colorName == "Cadet blue" then
				return "Color", Color3.fromRGB(185, 170, 142)
			elseif colorName == "Brick yellow" then
				return "BrickColor", BrickColor.new("Burlap")
			elseif colorName == "Earth blue" then
				return "BrickColor", BrickColor.new("Smoky grey")
			end
			return nil, nil
		end

		local function applyOldMapTextureToPart(part)
			if not oldMapTextureActive or not part:IsA("BasePart") or oldMapTextureStates[part] then
				return
			end
			local replacementKind, replacementValue = getOldMapTextureReplacement(part)
			if not replacementKind then
				return
			end
			oldMapTextureStates[part] = {
				Color = part.Color,
				BrickColor = part.BrickColor,
			}
			pcall(function()
				if replacementKind == "Color" then
					part.Color = replacementValue
				else
					part.BrickColor = replacementValue
				end
			end)
		end

		local function restoreOldMapTextures()
			oldMapTextureActive = false
			if oldMapTextureConnection then
				oldMapTextureConnection:Disconnect()
				oldMapTextureConnection = nil
			end
			for part, state in pairs(oldMapTextureStates) do
				pcall(function()
					part.BrickColor = state.BrickColor
					part.Color = state.Color
				end)
			end
			table.clear(oldMapTextureStates)
		end

		function updateMapTextures(enabled)
			if not enabled then
				restoreOldMapTextures()
				return
			end
			if oldMapTextureActive then
				return
			end
			local map = getMapRoot()
			if not map then
				return
			end
			oldMapTextureActive = true
			if map:IsA("BasePart") then
				applyOldMapTextureToPart(map)
			end
			for _, object in ipairs(map:GetDescendants()) do
				if object:IsA("BasePart") then
					applyOldMapTextureToPart(object)
				end
			end
			oldMapTextureConnection = map.DescendantAdded:Connect(function(object)
				if oldMapTextureActive and object:IsA("BasePart") then
					task.defer(function()
						if oldMapTextureActive and object.Parent then
							applyOldMapTextureToPart(object)
						end
					end)
				end
			end)
		end

		_G.TheBestOldMapTexturesCleanup = restoreOldMapTextures
		function getOcean()
			local map = workspace:FindFirstChild("Map")
			local important = map and map:FindFirstChild("IMPORTANT")
			return important and important:FindFirstChild("Ocean")
