			texture.Texture = "rbxassetid://5192458915"
			texture.StudsPerTileU = 37
			texture.StudsPerTileV = 63
			texture.Transparency = 0.9
			texture.Color3 = Color3.new(0, 0, 0)
			texture.Parent = ocean
		end
