		function Macro:GetFileName()
			local stats = LocalPlayer:FindFirstChild("PlayerStats")
			if not stats then
				return "rec1.json"
			end
			local stand = stats:FindFirstChild("Stand")
			local spec = stats:FindFirstChild("Spec")
			local standVal = stand and stand.Value or "0"
			local specVal = spec and spec.Value or "0"
			return standVal .. "_" .. specVal .. ".json"
		end
		function Macro:GetFileList()
			local files = {}
			local list = listfiles()
			for _, file in ipairs(list) do
				if file:match("^%d+_%d+%.json$") then
					table.insert(files, file)
				end
			end
			return files
		end
		function Macro:SimulateKeyDown(keyCode)
			VirtualInputManager:SendKeyEvent(true, keyCode, false, nil)
		end
		function Macro:SimulateKeyUp(keyCode)
			VirtualInputManager:SendKeyEvent(false, keyCode, false, nil)
		end
		function Macro:StartRecord()
			if self.Destroyed or self.Recording or self.Replaying then
				return
			end
			self.Events = {}
			self.StartTime = tick()
			self.Recording = true
			self.FirstInput = true
			self.KeyConnections = {}
			self.KeyConnections.InputBegan = UserInputService.InputBegan:Connect(function(input, gp)
				if gp or not self.Recording then
					return
				end
				if input.UserInputType == Enum.UserInputType.Keyboard then
					local key = input.KeyCode.Name
					if self.AllowedKeys[key] then
						local timestamp
						if self.FirstInput then
							self.FirstInput = false
							self.StartTime = tick()
							timestamp = 0
						else
							timestamp = tick() - self.StartTime
						end
						table.insert(self.Events, { Type = "KeyDown", Key = key, Time = timestamp })
					end
				end
			end)
			self.KeyConnections.InputEnded = UserInputService.InputEnded:Connect(function(input, gp)
				if gp or not self.Recording then
					return
				end
				if input.UserInputType == Enum.UserInputType.Keyboard then
					local key = input.KeyCode.Name
					if self.AllowedKeys[key] then
						table.insert(self.Events, { Type = "KeyUp", Key = key, Time = tick() - self.StartTime })
					end
				end
			end)
			print("Recording started! Press any allowed key to begin.")
			return true
		end
		function Macro:StopRecord()
			if not self.Recording then
				return
			end
			self.Recording = false
			for _, conn in pairs(self.KeyConnections) do
				conn:Disconnect()
			end
			self.KeyConnections = {}
			local filename = self:GetFileName()
			local data =
				{ RecordedAt = os.date("%Y-%m-%d %H:%M:%S"), TotalTime = tick() - self.StartTime, Events = self.Events }
			writefile(filename, HttpService:JSONEncode(data))
			print("Record saved to: " .. filename .. " (" .. #self.Events .. " events)")
			return filename
		end
		function Macro:ReplayFile(filename)
			if self.Destroyed or self.Replaying or self.Recording then
				return false
			end
			if not isfile(filename) then
				warn("File not found: " .. filename)
				return false
			end
			local data = HttpService:JSONDecode(readfile(filename))
			if not data or not data.Events then
				warn("Invalid macro file")
				return false
			end
			self.Replaying = true
			self.ReplayIndex = 1
			self.Events = data.Events
			self.CurrentFile = filename
			print("Replaying: " .. filename .. " (" .. #self.Events .. " events)")
			self:ProcessReplay()
			return true
		end
		function Macro:ProcessReplay()
			if self.Destroyed or not self.Replaying then
				return
			end
			if self.ReplayIndex > #self.Events then
				self:StopReplay()
				return
			end
			local event = self.Events[self.ReplayIndex]
			local delay = event.Time - (self.ReplayIndex > 1 and self.Events[self.ReplayIndex - 1].Time or 0)
			if delay < 0 then
				delay = 0
			end
			task.wait(delay)
			if self.Destroyed or not self.Replaying then
				return
			end
			if event.Type == "KeyDown" then
				local keyCode = Enum.KeyCode[event.Key]
				if keyCode then
					self:SimulateKeyDown(keyCode)
				end
			elseif event.Type == "KeyUp" then
				local keyCode = Enum.KeyCode[event.Key]
				if keyCode then
					self:SimulateKeyUp(keyCode)
				end
			end
			self.ReplayIndex = self.ReplayIndex + 1
			task.spawn(function()
				self:ProcessReplay()
			end)
		end
		function Macro:StopReplay()
			if not self.Replaying then
				return
			end
			self.Replaying = false
			self.ReplayIndex = 1
			for _, event in ipairs(self.Events) do
				if event.Type == "KeyDown" then
					local keyCode = Enum.KeyCode[event.Key]
					if keyCode then
						self:SimulateKeyUp(keyCode)
					end
				end
			end
			print("Replay stopped")
		end
		_G.TheBestMacroCleanup = function()
			if Macro.Destroyed then return end
			Macro.Destroyed = true
			pcall(Macro.StopRecord, Macro)
			Macro.Recording = false
			for _, connection in pairs(Macro.KeyConnections) do pcall(function() connection:Disconnect() end) end
			table.clear(Macro.KeyConnections)
			pcall(Macro.StopReplay, Macro)
			Macro.Replaying = false
			table.clear(Macro.Events)
			if Macro.HotkeyConnection then
				pcall(function() Macro.HotkeyConnection:Disconnect() end)
				if _G.zqqqq == Macro.HotkeyConnection then _G.zqqqq = nil end
				Macro.HotkeyConnection = nil
			end
		end
