			if inp.KeyCode == Enum.KeyCode.F2 then
				Macro:StopRecord()
			end
			if inp.KeyCode == Enum.KeyCode.F3 then
				local filename = Macro:GetFileName()
				Macro:ReplayFile(filename)
			end
		end)
