		local summonedConnection = nil
		local standChildAddedConnection = nil
		local currentStandMorph = nil
		local clearPose
		local function isStandSummoned(playerModel)
			local summoned = playerModel:FindFirstChild("SummonedStand")
			return summoned and summoned.Value == true
		end
		local function applyPose()
			if not _G.Config.oldSoundsAndAnimations then
				clearPose()
				return
			end
			if not currentStandMorph then
				return
			end
			if not humanoid then
				return
			end
			local living = workspace:FindFirstChild("Living")
			local playerModel = living and living:FindFirstChild(player.Name)
			if not playerModel then return end
			if not isStandSummoned(playerModel) then
				clearPose()
				return
			end
			local animationController=currentStandMorph:FindFirstChildOfClass("AnimationController") or currentStandMorph:FindFirstChildOfClass("Humanoid")
			local standAnimator=animationController and animationController:FindFirstChildOfClass("Animator")
			playerAnimator=humanoid:FindFirstChildOfClass("Animator")
			if not standAnimator or not playerAnimator or not _G.poseAssetStand or not _G.poseAssetPlayer then return end
			if runningConnection then
				runningConnection:Disconnect()
			end
			if standTrack then
				standTrack:Stop()
			end
			if playerTrack then
				playerTrack:Stop()
			end
			local standAnimation = Instance.new("Animation")
			standAnimation.AnimationId = "rbxassetid://" .. _G.poseAssetStand
			local idleAnimation = Instance.new("Animation")
			idleAnimation.AnimationId = "rbxassetid://" .. _G.poseAssetPlayer
			standTrack = standAnimator:LoadAnimation(standAnimation)
			playerTrack = playerAnimator:LoadAnimation(idleAnimation)
			standTrack.Looped = true
			playerTrack.Looped = true
			runningConnection = humanoid.Running:Connect(function(speed)
				if speed == 0 then
					if not playerTrack.IsPlaying then
						playerTrack:Play()
					end
				else
					if playerTrack.IsPlaying then
						playerTrack:Stop()
					end
				end
			end)
			standTrack:Play()
			if humanoid.MoveDirection.Magnitude == 0 then
				playerTrack:Play()
			end
		end
		clearPose = function()
			if runningConnection then
				runningConnection:Disconnect()
				runningConnection = nil
			end
			if standTrack then
				standTrack:Stop()
				standTrack = nil
			end
			if playerTrack then
				playerTrack:Stop()
				playerTrack = nil
			end
		end
		local function setupCharacter(character)
			clearPose()
			if summonedConnection then
				summonedConnection:Disconnect()
				summonedConnection = nil
			end
			if standChildAddedConnection then
				standChildAddedConnection:Disconnect()
				standChildAddedConnection = nil
			end
			currentStandMorph = nil
			humanoid = nil
			playerAnimator = nil
			if not _G.Config.oldSoundsAndAnimations then
				return
			end
			local stats = player:FindFirstChild("PlayerStats")
			local sss = stats and stats:FindFirstChild("Stand")
			if sss then
				local oldPoses={ ["Star Platinum"]="Old SP", ["King Crimson"]="Old KC", ["Gold Experience"]="GE", ["Chariot Requiem"]="SCR", ["Crazy Diamond"]="CD", ["The World"]="TW", ["The Hand"]="TH", ["King Crimson Requiem"]="KCR", ["Star Platinum: The World"]="SP:TW", ["The World Over Heaven"]="TWOH", ["The World Alternate Universe"]="TWAU" }
				if oldPoses[sss.Value] then setPose(oldPoses[sss.Value]) else _G.poseAssetStand=nil;_G.poseAssetPlayer=nil end
			end
			humanoid = character:WaitForChild("Humanoid")
			local living = workspace:FindFirstChild("Living")
			local playerModel = living and living:FindFirstChild(player.Name)
			if not playerModel then return end
			local summoned = playerModel:FindFirstChild("SummonedStand")
			if summoned then
				summonedConnection = summoned.Changed:Connect(function()
					if summoned.Value == true then
						applyPose()
					else
						clearPose()
					end
				end)
			end
			local existing = playerModel:FindFirstChild("StandMorph")
			if existing then
				currentStandMorph = existing
				task.wait(0.5)
				if not _G.Config.oldSoundsAndAnimations then
					currentStandMorph = nil
					return
				end
				applyPose()
			end
			if not _G.Config.oldSoundsAndAnimations then
				return
			end
			standChildAddedConnection = playerModel.ChildAdded:Connect(function(child)
				if child.Name == "StandMorph" then
					currentStandMorph = child
					task.wait(0.5)
					applyPose()
				end
			end)
		end
		_G.TheBestOldPoseCleanup = function()
			clearPose()
			if summonedConnection then
				pcall(function()
