				if obj.Name == player.Name then
					task.wait(1)
					setupDeathSoundCharacter()
				end
			end)
		end
		local succ, err = pcall(function()
			local Players = game:GetService("Players")
			local LocalPlayer = Players.LocalPlayer
			local UserInputService = game:GetService("UserInputService")
			local RunService = game:GetService("RunService")
			local Camera = workspace.CurrentCamera
			local jumping = false
			local canJump = true
			local lastJumpTime = 0
			local wasOnGround = true
			addFunctionConnection(LocalPlayer.CharacterAdded:Connect(function(character)
				local humanoid = character:WaitForChild("Humanoid")
				addFunctionConnection(humanoid.StateChanged:Connect(function(oldState, newState)
					if newState == Enum.HumanoidStateType.Landed then
						canJump = true
						wasOnGround = true
					elseif
						newState == Enum.HumanoidStateType.Freefall or newState == Enum.HumanoidStateType.Jumping
					then
						wasOnGround = false
					end
				end))
				if _G.Config.enableMobileExploit then
					mobileExploitState.Set(humanoid, false)
				end
			end))
			if LocalPlayer.Character then
				local humanoid = LocalPlayer.Character:FindFirstChild("Humanoid")
				if humanoid then
					addFunctionConnection(humanoid.StateChanged:Connect(function(oldState, newState)
						if newState == Enum.HumanoidStateType.Landed then
							canJump = true
							wasOnGround = true
						elseif
							newState == Enum.HumanoidStateType.Freefall
							or newState == Enum.HumanoidStateType.Jumping
						then
							wasOnGround = false
						end
					end))
					if _G.Config.enableMobileExploit then
						mobileExploitState.Set(humanoid, false)
					end
				end
			end
			addFunctionConnection(UserInputService.InputBegan:Connect(function(input, gameProcessed)
				if gameProcessed then
					return
				end
				if input.KeyCode == Enum.KeyCode.Space then
					jumping = true
				end
			end))
			addFunctionConnection(UserInputService.InputEnded:Connect(function(input)
				if input.KeyCode == Enum.KeyCode.Space then
					jumping = false
				end
			end))
			addFunctionConnection(RunService.RenderStepped:Connect(function()
				if not LocalPlayer.Character then
					return
				end
				if not _G.Config.enableMobileExploit then
					mobileExploitState.RestoreAll()
					return
				end
				local root = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
				local humanoid = LocalPlayer.Character:FindFirstChild("Humanoid")
				if not root or not humanoid or humanoid.Health <= 0 then
					return
				end
				if not movementRuntime.Claim("Mobile", root, "Mobile", 0.15) then mobileExploitState.RestoreAll(); return end
				mobileExploitState.Set(humanoid, false)
				Camera = workspace.CurrentCamera
				if not Camera then return end
				local state = humanoid:GetState()
				local onGround = (state == Enum.HumanoidStateType.Running or state == Enum.HumanoidStateType.Landed)
				if not onGround and wasOnGround == false then
					local rayOrigin = root.Position
					local rayDirection = Vector3.new(0, -5, 0)
					local params = RaycastParams.new()
					params.FilterType = Enum.RaycastFilterType.Blacklist
					params.FilterDescendantsInstances = { LocalPlayer.Character }
					local raycastResult = workspace:Raycast(rayOrigin, rayDirection, params)
					if raycastResult then
						onGround = true
					end
				end
				if jumping and canJump and onGround and tick() - lastJumpTime > 0.15 then
					root.Velocity = Vector3.new(root.Velocity.X, 50, root.Velocity.Z)
					canJump = false
					wasOnGround = false
					lastJumpTime = tick()
				end
				local shiftLock = UserInputService:IsKeyDown(Enum.KeyCode.LeftShift)
					or UserInputService:IsKeyDown(Enum.KeyCode.RightShift)
				if shiftLock then
					mobileExploitState.Set(humanoid, false)
					local camDirection = Camera.CFrame.LookVector * Vector3.new(1, 0, 1)
					if camDirection.Magnitude > 0.01 then
						root.CFrame = CFrame.new(root.Position, root.Position + camDirection.Unit)
					end
				else
					mobileExploitState.Set(humanoid, true)
				end
				if state == Enum.HumanoidStateType.Freefall or state == Enum.HumanoidStateType.Jumping then
					local moveDirection = Vector3.zero
					if UserInputService:IsKeyDown(Enum.KeyCode.W) then
						moveDirection += Camera.CFrame.LookVector * Vector3.new(1, 0, 1)
					end
					if UserInputService:IsKeyDown(Enum.KeyCode.S) then
						moveDirection -= Camera.CFrame.LookVector * Vector3.new(1, 0, 1)
					end
					if UserInputService:IsKeyDown(Enum.KeyCode.A) then
						moveDirection -= Camera.CFrame.RightVector
					end
					if UserInputService:IsKeyDown(Enum.KeyCode.D) then
						moveDirection += Camera.CFrame.RightVector
					end
					if moveDirection.Magnitude > 0 then
						moveDirection = moveDirection.Unit
						local currentVel = root.Velocity * Vector3.new(1, 0, 1)
						local speed = currentVel.Magnitude
						if speed < _G.Config.meStrafeSpeed then
							speed = _G.Config.meStrafeSpeed
						end
						local targetVel = moveDirection * speed
						root.Velocity = Vector3.new(
							currentVel.X + (targetVel.X - currentVel.X) * 0.15,
							root.Velocity.Y,
							currentVel.Z + (targetVel.Z - currentVel.Z) * 0.15
						)
					end
				end
			end))
		end)
		if not succ then
			warn("MOBILE EXPLOIT ERR: " .. err)
