				["Lime green"] = "White",
				["Really green"] = "Dark grey",
				["Forest green"] = "Dark grey",
				["Dark green"] = "Dark grey",
				["Green"] = "Light grey",
			}
			local function getWinterColor(greenColorName)
				return colorMap[greenColorName] or "White"
			end
			local function isTargetPart(part)
				if not part:IsA("BasePart") and not part:IsA("MeshPart") then
					return false
				end
				local name = part.Name:lower()
				return name:match("grass") or name:match("bush") or name:match("leaf") or name:match("leaves")
			end
			local function saveOriginalData()
				pcall(function()
					local function scanChildren(parent)
						for _, child in ipairs(parent:GetChildren()) do
							if isTargetPart(child) then
								table.insert(
									originalData.parts,
									{ part = child, originalColor = child.BrickColor.Name }
								)
							end
							scanChildren(child)
						end
					end
					scanChildren(workspace)
					local sky = Lighting:FindFirstChild("Sky")
					if sky then
						originalData.sky = sky
						originalData.skyProperties = {
							SkyboxBk = sky.SkyboxBk,
							SkyboxDn = sky.SkyboxDn,
							SkyboxFt = sky.SkyboxFt,
							SkyboxLf = sky.SkyboxLf,
							SkyboxRt = sky.SkyboxRt,
							SkyboxUp = sky.SkyboxUp,
							MoonAngularSize = sky.MoonAngularSize,
							MoonTextureId = sky.MoonTextureId,
							SunAngularSize = sky.SunAngularSize,
							SunTextureId = sky.SunTextureId,
							StarCount = sky.StarCount,
							SkyboxOrientation = sky.SkyboxOrientation,
							CelestialBodiesShown = sky.CelestialBodiesShown,
							Archivable = sky.Archivable,
						}
					end
					local ocean = workspace:FindFirstChild("Map")
					if ocean then
						ocean = ocean:FindFirstChild("IMPORTANT")
						if ocean then
							ocean = ocean:FindFirstChild("Ocean")
						end
					end
					if ocean then
						originalData.ocean = ocean
						originalData.oceanColor = ocean.Color
					end
				end)
			end
			local function applyWinterColors()
				pcall(function()
					local function scanChildren(parent)
						for _, child in ipairs(parent:GetChildren()) do
							if isTargetPart(child) then
								local currentColor = child.BrickColor.Name
								local newColor = getWinterColor(currentColor)
								child.BrickColor = BrickColor.new(newColor)
							end
							scanChildren(child)
						end
					end
					scanChildren(workspace)
				end)
			end
			local function doWinter()
				local ocean = workspace:FindFirstChild("Map")
				if ocean then
					ocean = ocean:FindFirstChild("IMPORTANT")
					if ocean then
						ocean = ocean:FindFirstChild("Ocean")
					end
				end
				local sky = Lighting:FindFirstChild("Sky")
				if not sky or not ocean then
					return
				end
				ocean.Color = Color3.new(0.8, 0.9, 1)
				local skyTexture = "http://www.roblox.com/asset/?id=401683862"
				local skyTextureUp = "http://www.roblox.com/asset/?id=401683877"
				local skyTextureDown = "http://www.roblox.com/asset/?id=401683843"
				sky.SkyboxBk = skyTexture
				sky.SkyboxFt = skyTexture
				sky.SkyboxLf = skyTexture
				sky.SkyboxRt = skyTexture
				sky.SkyboxUp = skyTextureUp
				sky.SkyboxDn = skyTextureDown
				sky.MoonAngularSize = 11
				sky.MoonTextureId = "rbxasset://sky/moon.jpg"
				sky.SunAngularSize = 21
				sky.SunTextureId = "rbxasset://sky/sun.jpg"
				sky.StarCount = 5000
				sky.SkyboxOrientation = Vector3.new(0, 0, 0)
				sky.CelestialBodiesShown = true
				sky.Archivable = false
				sky.Name = "Sky"
			end
			local function restore()
				pcall(function()
					for _, data in ipairs(originalData.parts) do
						if data.part and data.part.Parent then
							data.part.BrickColor = BrickColor.new(data.originalColor)
						end
					end
					if originalData.sky and originalData.sky.Parent then
						local sky = originalData.sky
						local props = originalData.skyProperties
						sky.SkyboxBk = props.SkyboxBk
						sky.SkyboxDn = props.SkyboxDn
						sky.SkyboxFt = props.SkyboxFt
						sky.SkyboxLf = props.SkyboxLf
						sky.SkyboxRt = props.SkyboxRt
						sky.SkyboxUp = props.SkyboxUp
						sky.MoonAngularSize = props.MoonAngularSize
						sky.MoonTextureId = props.MoonTextureId
						sky.SunAngularSize = props.SunAngularSize
						sky.SunTextureId = props.SunTextureId
						sky.StarCount = props.StarCount
						sky.SkyboxOrientation = props.SkyboxOrientation
						sky.CelestialBodiesShown = props.CelestialBodiesShown
						sky.Archivable = props.Archivable
					end
					if originalData.ocean and originalData.ocean.Parent then
						originalData.ocean.Color = originalData.oceanColor
					end
				end)
			end
			saveOriginalData()
			applyWinterColors()
			doWinter()
			return {
				apply = function()
					applyWinterColors()
					doWinter()
				end,
				restore = restore,
			}
		end
		local function deepMergeDefaults(target, defaults)
			target = type(target) == "table" and target or {}
			for key, defaultValue in pairs(defaults) do
				if type(defaultValue) == "table" then
					target[key] = deepMergeDefaults(target[key], defaultValue)
				elseif target[key] == nil then
					target[key] = defaultValue
				end
			end
			return target
		end
		local function getConfig()
			_G.Config = deepMergeDefaults(_G.Config, DEFAULT_CONFIG)
			return _G.Config
		end
		local function saveConfig()
			if type(SaveConfig) == "function" then
				task.spawn(SaveConfig)
			end
		end
		local function getRoot(model)
			if not model then
				return nil
			end
			return model:FindFirstChild("HumanoidRootPart")
				or model:FindFirstChild("UpperTorso")
				or model:FindFirstChild("Torso")
		end
		local function getPlayerPosition(player)
			if not player or not player.Character then
				return nil
			end
			local root = getRoot(player.Character)
			return root and root.Position or nil
		end
		local function findPlayerByModel(model)
			if not model or not model:IsA("Model") then
				return nil
			end
			local player = Players:GetPlayerFromCharacter(model)
			if player then
				return player
			end
			return Players:FindFirstChild(model.Name)
		end
		local function getPlayerFromOrigin(origin)
			if typeof(origin) ~= "Instance" then
				return nil
			end
			local current = origin
			local standMorph = nil
			while current do
				if current.Name == "StandMorph" then
					standMorph = current
				end
				if current:IsA("Model") then
					local player = findPlayerByModel(current)
					if player then
						return player
					end
				end
				current = current.Parent
			end
			if standMorph then
				current = standMorph.Parent
				while current do
					if current:IsA("Model") then
						local player = findPlayerByModel(current)
						if player then
							return player
						end
					end
					current = current.Parent
				end
			end
			return nil
		end
		local function isOwnOrigin(origin)
			local character = LocalPlayer.Character
			if not character then
				return false
			end
			if typeof(origin) ~= "Instance" then
				return false
			end
			if origin == character or origin:IsDescendantOf(character) then
				return true
			end
			local ownStand = character:FindFirstChild("StandMorph")
			if ownStand then
				if origin == ownStand or origin:IsDescendantOf(ownStand) then
					return true
				end
			end
			return false
		end
		local function getAttackSet()
			local result = {}
			local attacks = getConfig().autoParryAttacks
			if type(attacks) ~= "table" then
				return result
			end
			for key, value in pairs(attacks) do
				if type(value) == "string" then
					result[value] = true
				elseif type(key) == "string" and value == true then
					result[key] = true
				end
			end
			return result
		end
		local function getRemoteEvent()
			local character = LocalPlayer.Character
			if not character then
				return nil
			end
			local remote = character:FindFirstChild("RemoteEvent")
			if remote and remote:IsA("RemoteEvent") then
				return remote
			end
			return nil
		end
		local function performBlock()
			local remote = getRemoteEvent()
			if not remote then
				return false
			end
			local sequence = getConfig().autoParryBlockSequence
			if type(sequence) ~= "table" then
				sequence = DEFAULT_CONFIG.autoParryBlockSequence
			end
			if sequence.releaseAttack ~= false then
				remote:FireServer("HoldAttack", { Bool = false, Type = sequence.attackType or "m1" })
			end
			if sequence.releaseInput then
				local input = sequence.releaseInput
				if type(input) == "string" then
					input = Enum.KeyCode[input]
				end
				remote:FireServer("InputEnded", { Input = input })
			end
			remote:FireServer("StopBlocking", nil)
			task.wait(tonumber(sequence.beforeBlockDelay) or DEFAULT_CONFIG.autoParryBlockSequence.beforeBlockDelay)
			remote:FireServer("StartBlocking", nil)
			task.wait(tonumber(sequence.holdDuration) or DEFAULT_CONFIG.autoParryBlockSequence.holdDuration)
			remote:FireServer("StopBlocking", nil)
			return true
		end
		-- Anti Time Stop is handled by XenonIntegration's TimeStopping event controller.
		local RunService = game:GetService("RunService")
		function timerTick(seconds)
			local label = Instance.new("TextLabel")
			label.Size = UDim2.fromOffset(120, 30)
			label.Position = UDim2.fromScale(0.5, 0.8)
			label.AnchorPoint = Vector2.new(0.5, 0.5)
			label.BackgroundTransparency = 1
			label.TextScaled = true
			label.TextColor3 = Color3.new(1, 1, 1)
			label.Parent = game:GetService("Players").LocalPlayer.PlayerGui.HUD
			local start = time()
			local con
			con = RunService.RenderStepped:Connect(function()
				local remaining = math.max(0, seconds - (time() - start))
				label.Text = ("%.2f"):format(remaining)
				if remaining <= 0 then
					con:Disconnect()
					label:Destroy()
				end
			end)
		end
		function makethis()
			local lpchar = game:GetService("Players").LocalPlayer.Character
			local stand = lpchar:FindFirstChild("StandMorph")
			if stand then
				local target = getTargetCharacter(findTargetByName(_G.Config.input_TargetSurvName))
				if not target then
					warn("no target")
					return
				end
				timerTick(_G.Config.standOnlyTimeout)
				task.wait(_G.Config.standOnlyTimeout)
				local a = nil
				local standAttach = stand.HumanoidRootPart:FindFirstChild("StandAttach")
				if standAttach then
					standAttach = standAttach:Clone()
					stand.HumanoidRootPart.StandAttach:Destroy()
				end
				a = RunService.RenderStepped:Connect(function()
					local succ, err = pcall(function()
						stand.HumanoidRootPart.CFrame = target.HumanoidRootPart.CFrame * CFrame.new(0, 0, 2)
					end)
					if not succ then
						warn("runservice1: " .. err)
						if a ~= nil then
							a:Disconnect()
							a = nil
						end
					end
				end)
				task.wait(0.2)
				if a ~= nil then
					a:Disconnect()
					a = nil
				end
				a = RunService.RenderStepped:Connect(function()
					local succ, err = pcall(function()
						stand.HumanoidRootPart.CFrame = lpchar.HumanoidRootPart.CFrame * CFrame.new(0, 0, 0)
					end)
					if not succ then
						warn("runservice2: " .. err)
						if a ~= nil then
							a:Disconnect()
							a = nil
						end
					end
				end)
				task.wait(0.2)
				if a ~= nil then
					a:Disconnect()
					a = nil
				end
				if standAttach then
					standAttach.Parent = stand.HumanoidRootPart
				end
			end
		end
		if _G.AD_FunctionsCleanup then
			pcall(_G.AD_FunctionsCleanup)
		end
		addFunctionConnection(UserInputService.InputBegan:Connect(function(input, gp)
			if UserInputService:GetFocusedTextBox() or _G.TheBestCapturingKeybind then return end
			if input.KeyCode == getKey("aimbot") then
				-- Tab can be marked processed by Roblox's player list.
				if UserInputService:GetFocusedTextBox() or _G.TheBestCapturingKeybind
					or (gp and input.KeyCode ~= Enum.KeyCode.Tab) then
					return
				end
				if _G.Config.enableAimbot and aimbotPressedKey == nil then
					aimbotPressedKey = input.KeyCode
					if _G.Config.aimbotActivation == "Toggle" then
						holdingAimbot = not holdingAimbot
					else
						holdingAimbot = true
					end
				end
				return
			end
			if gp then
				return
			end
			if input.KeyCode == getKey("selectTarget") then
				local selectedTarget = findTargetInCircle()
				if selectedTarget then
					setLockedTarget(selectedTarget)
					SaveConfig()
				end
			elseif input.KeyCode == getKey("speedhack") then
				speedhackState.Begin(input.KeyCode, gp)
			elseif input.KeyCode == getKey("fly") then
				toggleFly()
			elseif input.KeyCode == getKey("standPilot") and (standPilotActive or _G.Config.standPilotEnabled) then
				if _G.Config.pilotMode == "Stand Only" then
					makethis()
				else
					startStandPilot()
				end
			elseif input.KeyCode == getKey("tpToTrgt") then
				tpToSelectedTarget()
			elseif input.KeyCode == getKey("tpToDioOverHeaven") then
				tpToDioOH()
			end
		end))
		addFunctionConnection(UserInputService.InputEnded:Connect(function(input)
			if input.KeyCode == aimbotPressedKey then
				aimbotPressedKey = nil
				if _G.Config.aimbotActivation ~= "Toggle" then
					holdingAimbot = false
				end
			end
			speedhackState.End(input.KeyCode)
		end))
		addFunctionConnection(LocalPlayer.CharacterRemoving:Connect(function()
			stopSpeedhack()
		end))
		addFunctionConnection(UserInputService.TextBoxFocused:Connect(function() stopSpeedhack() end))
		addFunctionConnection(UserInputService.WindowFocusReleased:Connect(function()
			stopSpeedhack()
			aimbotPressedKey = nil
			if _G.Config.aimbotActivation ~= "Toggle" then
				holdingAimbot = false
			end
		end))
		addFunctionConnection(RunService.RenderStepped:Connect(function()
			local cam = workspace.CurrentCamera
			local mouseLocation = UserInputService:GetMouseLocation()
			local inset = GuiService:GetGuiInset()
			if _G.q_circle then
				_G.q_circle.Position = Vector2.new(mouseLocation.X, mouseLocation.Y - inset.Y)
				_G.q_circle.Radius = _G.Config.circleRadius
				_G.q_circle.Visible = _G.Config.circle
			end
			if cam then
				Camera = cam
			end
			aimAtTarget()
		end))
		local ownedMacroCleanup = _G.TheBestMacroCleanup
		_G.AD_FunctionsCleanup = function()
			if type(ownedMacroCleanup) == "function" then pcall(ownedMacroCleanup) end
			if type(_G.TheBestSpeedExploitsCleanup) == "function" then pcall(_G.TheBestSpeedExploitsCleanup) end
			movementRuntime.Cleanup()
			mobileExploitState.Cleanup()
			if _G.TheBestMobileExploitRestore == mobileExploitState.RestoreAll then _G.TheBestMobileExploitRestore = nil end
			resetAimbotInput()
			_G.TheBestCapturingKeybind = nil
			for _, conn in ipairs(functionsConnections) do
				conn:Disconnect()
			end
			functionsConnections = {}
			stopSpeedhack()
			stopFly()
			stopStandPilot()
			uninstallSilentAimbot()
			if summonedConnection then
				summonedConnection:Disconnect()
				summonedConnection = nil
			end
			if standChildAddedConnection then
				standChildAddedConnection:Disconnect()
				standChildAddedConnection = nil
			end
			clearPose()
			if _G.q_circle then
				_G.q_circle:Remove()
				_G.q_circle = nil
			end
		end
	end
