				local api = {}

				local function isRussian()
					return _G.Config and _G.Config.interfaceLanguage == "Russian"
				end

				function api.Translate(value)
					local text = tostring(value or "")
					if not isRussian() then
						return text
					end
					local exact = russian[text]
					if exact then
						return exact
					end
					local selectedName = text:match("^(.-)%s+%(selected%)$")
					if selectedName then
						return selectedName .. " (\208\178\209\139\208\177\209\128\208\176\208\189)"
					end
					local equippedName = text:match("^(.-)%s+%(equipped%)$")
					if equippedName then
						return equippedName .. " (\209\141\208\186\208\184\208\191\208\184\209\128\208\190\208\178\208\176\208\189\208\190)"
					end
					if text:sub(1, 9) == "Enabled: " then
						return ("\208\146\208\186\208\187\209\142\209\135\208\181\208\189\208\190: " .. text:sub(10))
							:gsub(" | body ", " | \209\130\208\181\208\187\208\190 ")
							:gsub(" | acc ", " | \208\176\208\186\209\129\208\181\209\129\209\129\209\131\208\176\209\128\209\139 ")
							:gsub(" | joints ", " | \209\129\208\190\208\181\208\180\208\184\208\189\208\181\208\189\208\184\209\143 ")
					end
					for _, entry in ipairs(prefixes) do
						local englishPrefix = entry[1]
						if text:sub(1, #englishPrefix) == englishPrefix then
							local suffix = text:sub(#englishPrefix + 1)
							return entry[2] .. (russian[suffix] or suffix)
						end
					end
					return text
				end

				function api.SetText(object, englishText)
					if typeof(object) ~= "Instance" then
						return
					end
					local text = tostring(englishText or "")
					object:SetAttribute(TEXT_ATTRIBUTE, text)
					object.Text = api.Translate(text)
				end

				function api.SetPlaceholder(object, englishText)
					if typeof(object) ~= "Instance" or not object:IsA("TextBox") then
						return
					end
					local text = tostring(englishText or "")
					object:SetAttribute(PLACEHOLDER_ATTRIBUTE, text)
					object.PlaceholderText = api.Translate(text)
				end

				function api.Refresh(root)
					if typeof(root) ~= "Instance" then
						return
					end
					local objects = { root }
					for _, descendant in ipairs(root:GetDescendants()) do
						table.insert(objects, descendant)
					end
					for _, object in ipairs(objects) do
						if object:IsA("TextLabel") or object:IsA("TextButton") then
							local englishText = object:GetAttribute(TEXT_ATTRIBUTE)
							if type(englishText) == "string" then
								object.Text = api.Translate(englishText)
							end
						elseif object:IsA("TextBox") then
							local englishPlaceholder = object:GetAttribute(PLACEHOLDER_ATTRIBUTE)
							if type(englishPlaceholder) == "string" then
								object.PlaceholderText = api.Translate(englishPlaceholder)
							end
						end
					end
					for _, listener in ipairs(listeners) do
						pcall(listener)
					end
				end

				function api.Register(listener)
					if type(listener) == "function" then
						table.insert(listeners, listener)
					end
				end

				function api.SetLanguage(language, root)
					local normalized = language == "Russian" and "Russian" or "English"
					if _G.Config then
						_G.Config.interfaceLanguage = normalized
					end
					api.Refresh(root)
					return normalized
				end

				function api.GetLanguage()
					return isRussian() and "Russian" or "English"
				end

				return api
			end)()
