			for _, child in ipairs(element:GetDescendants()) do
				if child:IsA("TextLabel") or child:IsA("TextButton") or child:IsA("TextBox") then
					child.TextTransparency = 1
					table.insert(textObjects, child)
				end
			end
			task.delay(delayTime, function()
				if not element or not element.Parent then
					return
				end
				TweenService:Create(
					element,
					TweenInfo.new(ANIM_DURATION, ANIM_STYLE, ANIM_DIR),
					{ Position = originalPos, BackgroundTransparency = originalBackgroundTransparency }
				):Play()
				for _, obj in ipairs(textObjects) do
					if obj and obj.Parent then
						TweenService:Create(
							obj,
							TweenInfo.new(ANIM_DURATION * 0.85, ANIM_STYLE, ANIM_DIR),
							{ TextTransparency = 0 }
