		function Library:UpdateSubPositions()
			local yOffset = 35
			for i, subInfo in ipairs(subData) do
				subInfo.Frame.Position = UDim2.new(0, 10, 0, yOffset)
				yOffset = yOffset + subInfo.Height + 6
			end
		end
		function Library:LayoutFunctionTabs(classLabel)
			if not activeMainUI or not activeMainUI.WelcomeFrame then
				return
			end
			if layoutSuspended then
				if classLabel then
					pendingLayouts[classLabel] = true
				end
				return
			end
			local columnHeights = {}
			for i = 1, FUNCTION_TAB_COLUMNS do
				columnHeights[i] = 0
			end
			for _, tabData in ipairs(functionTabs) do
				if not tabData or not tabData.frame then
					continue
				end
				if (Library.OrbitSearchActive and Library.OrbitSearchMatches and Library.OrbitSearchMatches[tabData])
					or (not Library.OrbitSearchActive and tabData.classLabel == classLabel) then
					if tabData.fullWidth then
						local yOffset = math.max(columnHeights[1], columnHeights[2])
						tabData.frame.Position = UDim2.new(0, 0, 0, yOffset)
						local nextY = yOffset + tabData.frame.Size.Y.Offset + FUNCTION_TAB_GAP
						for i = 1, FUNCTION_TAB_COLUMNS do
							columnHeights[i] = nextY
						end
						continue
					end
					local shortestColumn = 1
					for i = 2, FUNCTION_TAB_COLUMNS do
						if columnHeights[i] < columnHeights[shortestColumn] then
							shortestColumn = i
						end
					end
					local xOffset = (shortestColumn - 1) * (FUNCTION_TAB_WIDTH + FUNCTION_TAB_GAP)
					local yOffset = columnHeights[shortestColumn]
					tabData.frame.Position = UDim2.new(0, xOffset, 0, yOffset)
					columnHeights[shortestColumn] = yOffset + tabData.frame.Size.Y.Offset + FUNCTION_TAB_GAP
				end
			end
			local maxHeight = 0
			for _, height in ipairs(columnHeights) do
				maxHeight = math.max(maxHeight, height)
			end
			activeMainUI.WelcomeFrame.CanvasSize =
				UDim2.new(0, 0, 0, math.max(maxHeight + 8, activeMainUI.WelcomeFrame.AbsoluteSize.Y))
		end
		function Library:FinishBuilding()
			loadingStage(98,"Restoring saved controls")
			if not activeMainUI then
				return
			end
			layoutSuspended = false
			local classLabels = {}
			for classLabel in pairs(pendingLayouts) do
				classLabels[classLabel] = true
			end
			for _, tabData in ipairs(functionTabs) do
				if tabData.classLabel then
					classLabels[tabData.classLabel] = true
				end
			end
			pendingLayouts = {}
			for classLabel in pairs(classLabels) do
				Library:LayoutFunctionTabs(classLabel)
			end
			if activeMainUI.BuildStatus then
				activeMainUI.BuildStatus:Destroy()
				activeMainUI.BuildStatus = nil
			end
			task.defer(function()
				for classLabel in pairs(classLabels) do
					Library:LayoutFunctionTabs(classLabel)
				end
			end)
		end
		function Library:CreateSub(text)
			if not activeMainUI then
