                line.AnchorPoint, line.Size = Vector2.new(.5,.5), UDim2.fromOffset(7,2)
                line.Position, line.Rotation = UDim2.fromOffset(index==1 and 4.5 or 9.5,7), index==1 and 45 or -45
                line.BorderSizePixel, line.ZIndex, line.Parent = 0, 2, arrow
            end
			local dropdownText = Instance.new("TextLabel")
			dropdownText.Size = UDim2.new(1, -34, 1, 0)
			dropdownText.Position = UDim2.new(0, 8, 0, 0)
			dropdownText.BackgroundTransparency = 1
			dropdownText.TextColor3 = T.text
