					return text
				end
				Library.Localization.SetText(dropdownText, formatDisplayText())
			local dropdownList = Instance.new("Frame")
			dropdownList.Size = UDim2.new(1, 0, 0, 0)
			dropdownList.Position = UDim2.new(0, 0, 1, 2)
			dropdownList.BackgroundColor3 = T.dropdownBg
			dropdownList.BackgroundTransparency = 0
			dropdownList.BorderSizePixel = 0
			dropdownList.ClipsDescendants = true
			dropdownList.ZIndex = 99
			dropdownList.Parent = dropdownMain
			local listCorner = Instance.new("UICorner")
			listCorner.CornerRadius = UDim.new(0, 4)
			listCorner.Parent = dropdownList
			local searchQuery = ""
			local searchBox = nil
			local searchHeight = prefixSearch and 24 or 0
			if prefixSearch then
				searchBox = Instance.new("TextBox")
