				searchBox.Size = UDim2.new(1, -6, 0, 20)
				searchBox.Position = UDim2.new(0, 3, 0, 2)
				searchBox.BackgroundColor3 = T.dropdownItem
				searchBox.BorderSizePixel = 0
				searchBox.ClearTextOnFocus = false
