			local listLayout = Instance.new("UIListLayout")
			listLayout.Padding = UDim.new(0, 1)
			listLayout.SortOrder = Enum.SortOrder.LayoutOrder
			listLayout.Parent = listScrolling
			local isOpen = false
            local controlHover, controlTween, borderTween, arrowTween = false, nil, nil, nil
            local function styleControl(animate)
                local fill = T.surface:Lerp(T.text, (controlHover or isOpen) and .11 or .065)
                local outline = isOpen and T.accent or T.stroke:Lerp(T.text,controlHover and .48 or .28)
                arrowLeft.BackgroundColor3, arrowRight.BackgroundColor3 = isOpen and T.accent or T.textDim, isOpen and T.accent or T.textDim
                if controlTween then controlTween:Cancel() end
                if borderTween then borderTween:Cancel() end
                if arrowTween then arrowTween:Cancel() end
                if animate then
                    local info = TweenInfo.new(.16,Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
                    controlTween = TweenService:Create(dropdownMain,info,{BackgroundColor3=fill})
                    borderTween = TweenService:Create(controlStroke,info,{Color=outline})
                    arrowTween = TweenService:Create(arrow,info,{Rotation=isOpen and 180 or 0})
                    controlTween:Play(); borderTween:Play(); arrowTween:Play()
                else
                    dropdownMain.BackgroundColor3, controlStroke.Color = fill, outline
                    arrow.Rotation = isOpen and 180 or 0
                end
            end
            dropdownMain.MouseEnter:Connect(function() controlHover=true; styleControl(true) end)
            dropdownMain.MouseLeave:Connect(function() controlHover=false; styleControl(true) end)
            styleControl(false)
            local listTween = nil
local function matchesSearch(value)
 local english = string.lower(tostring(value or ""))
 local translated = string.lower(tostring(Library.Localization.Translate(value) or ""))
 for word in searchQuery:gmatch("%S+") do
  if not string.find(english, word, 1, true) and not string.find(translated, word, 1, true) then return false end
 end
 return true
end

			local function getFilteredItems()
				local filtered = {}
				for _, item in ipairs(items) do
					if matchesSearch(item) then
						table.insert(filtered, item)
					end
				end
				return filtered
			end
			local updateListHeight
			updateListHeight = function(open)
                styleControl(true)
                arrow.ZIndex, arrowLeft.ZIndex, arrowRight.ZIndex = open and 101 or 2, open and 101 or 2, open and 101 or 2
                if open then
					local itemCount = #getFilteredItems()
					if not omitNoneOption and matchesSearch("None") then
						itemCount += 1
					end
					local totalHeight = itemCount * 20 + searchHeight + 4
					local maxHeight = 120
					local newHeight = math.min(totalHeight, maxHeight)
					if listTween then
						listTween:Cancel()
					end
					listTween = TweenService:Create(
						dropdownList,
						TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
						{ Size = UDim2.new(1, 0, 0, newHeight) }
					)
					listTween:Play()
					dropdownMain.ZIndex = 100
					dropdownList.ZIndex = 100
					frame.ZIndex = 100
					label.ZIndex = 100
					dropdownText.ZIndex = 100
				else
					if listTween then
						listTween:Cancel()
					end
					listTween = TweenService:Create(
						dropdownList,
						TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
						{ Size = UDim2.new(1, 0, 0, 0) }
					)
					listTween:Play()
					dropdownMain.ZIndex = 1
					dropdownList.ZIndex = 99
					frame.ZIndex = 1
					label.ZIndex = 1
					dropdownText.ZIndex = 1
				end
			end
			local function closeDropdown()
				isOpen = false
				if searchBox then
					if searchBox:IsFocused() then
						searchBox:ReleaseFocus()
					end
					if searchBox.Text ~= "" then
						searchBox.Text = ""
					end
				end
				updateListHeight(false)
			end
				local function updateDisplayText()
					Library.Localization.SetText(dropdownText, formatDisplayText())
					local displayText = dropdownText.Text
					local succeeded, characterCount = pcall(utf8.len, displayText)
					if succeeded and characterCount and characterCount > 18 then
						local byteIndex = utf8.offset(displayText, 19)
						if byteIndex then
							dropdownText.Text = string.sub(displayText, 1, byteIndex - 1) .. "..."
						end
					elseif not succeeded and #displayText > 18 then
						dropdownText.Text = string.sub(displayText, 1, 18) .. "..."
					end
					dropdownText.TextColor3 = T.text
				end
			local function toggleItem(itemText)
				local found = false
				for i, v in ipairs(selectedItems) do
					if v == itemText then
						table.remove(selectedItems, i)
						found = true
						break
					end
				end
				if not found and multiSelect then
					table.insert(selectedItems, itemText)
				elseif not found and not multiSelect then
					selectedItems = { itemText }
				end
				updateDisplayText()
				if callback then
					callback(multiSelect and selectedItems or selectedItems[1])
				end
			end
			local function populateList()
				for _, child in ipairs(listScrolling:GetChildren()) do
					if not child:IsA("UIListLayout") then
						child:Destroy()
					end
				end
				local function createItem(text)
					local isSelected = false
					for _, v in ipairs(selectedItems) do
						if v == text then
							isSelected = true
							break
						end
					end
					local item = Instance.new("TextButton")
					item.Size = UDim2.new(1, -4, 0, 20)
					item.BackgroundColor3 = T.dropdownItem
					item.BackgroundTransparency = 0
					item.BorderSizePixel = 0
						Library.Localization.SetText(item, text)
					item.TextColor3 = isSelected and T.accent or T.text
					item.TextSize = 11
					item.TextXAlignment = Enum.TextXAlignment.Left
					item.TextYAlignment = Enum.TextYAlignment.Center
					item.Font = Enum.Font.SourceSans
					item.ZIndex = 100
					item.Parent = listScrolling
					local itemCorner = Instance.new("UICorner")
					itemCorner.CornerRadius = UDim.new(0, 4)
					itemCorner.Parent = item
					item.MouseButton1Click:Connect(function()
						toggleItem(text)
						for _, childItem in ipairs(listScrolling:GetChildren()) do
							if childItem:IsA("TextButton") then
								local selected = false
								for _, v in ipairs(selectedItems) do
									if v == (childItem:GetAttribute("TheBestEnglishText") or childItem.Text) then
										selected = true
										break
									end
								end
								childItem.TextColor3 = selected and T.accent or T.text
							end
						end
				if not multiSelect then
							closeDropdown()
							_G.currentOpenDropdown = nil
						end
					end)
					return item
				end
				if not omitNoneOption and matchesSearch("None") then
					createItem("None")
				end
				for _, itemText in ipairs(getFilteredItems()) do
					createItem(itemText)
				end
				listScrolling.CanvasSize = UDim2.new(0, 0, 0, listLayout.AbsoluteContentSize.Y + 4)
			end
			if searchBox then
				searchBox:GetPropertyChangedSignal("Text"):Connect(function()
					searchQuery = string.lower(searchBox.Text:match("^%s*(.-)%s*$") or "")
					populateList()
					if isOpen then
						updateListHeight(true)
					end
				end)
			end
			populateList()
			updateDisplayText()
			local succ, err = pcall(function()
				if callback then
					callback(multiSelect and selectedItems or selectedItems[1])
				end
			end)
			if not succ then
				warn("[MENU API] Dropdown Error: " .. err)
			end
			dropdownMain.InputBegan:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1 then
					if _G.currentOpenDropdown and _G.currentOpenDropdown.main ~= dropdownMain then
						local oldDropdown = _G.currentOpenDropdown
						oldDropdown.close()
					end
					isOpen = not isOpen
					if isOpen then
						dropdownList.Size = UDim2.new(1, 0, 0, 0)
						populateList()
						updateListHeight(true)
						_G.currentOpenDropdown = { main = dropdownMain, close = closeDropdown }
						if searchBox then
							task.defer(function()
								if isOpen and searchBox.Parent then
									searchBox:CaptureFocus()
								end
							end)
						end
					else
						closeDropdown()
						_G.currentOpenDropdown = nil
					end
				end
			end)
			table.insert(tabData.elements, frame)
				registerThemeListener(function(theme)
				frame.BackgroundColor3 = theme.surface
				label.TextColor3 = theme.text
				styleControl(false)
				dropdownText.TextColor3 = theme.text
				dropdownList.BackgroundColor3 = theme.dropdownBg
					if searchBox then
						searchBox.BackgroundColor3 = theme.dropdownItem
						searchBox.TextColor3 = theme.text
						searchBox.PlaceholderColor3 = theme.textDim
                        local outline=searchBox:FindFirstChild("SearchOutline")
                        if outline then outline.Color=searchBox:IsFocused() and theme.accent or theme.stroke:Lerp(theme.text,.28) end
					end
					populateList()
				end)
				Library.Localization.Register(updateDisplayText)
			local function updateItems(newItems)
				items = newItems or {}
				local oldSelectedItems = selectedItems
				selectedItems = {}
				if multiSelect then
					for _, oldItem in ipairs(oldSelectedItems) do
						if hasItem(items, oldItem) then
							table.insert(selectedItems, oldItem)
						end
					end
				else
					local oldItem = oldSelectedItems[1]
					selectedItems = { hasItem(items, oldItem) and oldItem or getDefaultItem() }
				end
				populateList()
				updateDisplayText()
			end
			return {
				SetValue = function(newValue)
					if multiSelect then
						selectedItems = {}
						if type(newValue) == "table" then
							for _, v in ipairs(newValue) do
								if hasItem(items, v) then
									table.insert(selectedItems, v)
								end
							end
						else
							if hasItem(items, newValue) then
								table.insert(selectedItems, newValue)
							end
						end
					else
						if newValue and hasItem(items, newValue) then
							selectedItems = { newValue }
						else
							selectedItems = { getDefaultItem() }
						end
					end
					updateDisplayText()
					populateList()
					if callback then
						callback(multiSelect and selectedItems or selectedItems[1])
					end
				end,
				GetValue = function()
					return multiSelect and selectedItems or selectedItems[1]
				end,
				GetSelected = function()
					return selectedItems
				end,
				Update = updateItems,
				SetItems = updateItems,
			}
		end
		function Library:CreateSlider(tabData, labelText, currentValue, min, max, callback)
			if not tabData or not tabData.elementContainer then
				return nil
			end
			local function formatSliderValue(value)
				return string.format("%.2f", tonumber(value) or 0)
			end
			local frame = Instance.new("Frame")
			frame.Size = UDim2.new(1, 0, 0, 42)
			frame.BackgroundColor3 = T.surface
			frame.BackgroundTransparency = 0
			frame.BorderSizePixel = 0
			frame.Parent = tabData.elementContainer
			local label = Instance.new("TextLabel")
			label.Size = UDim2.new(0.72, -4, 0, 18)
			label.Position = UDim2.new(0, 4, 0, 0)
			label.BackgroundTransparency = 1
				Library.Localization.SetText(label, labelText)
			label.TextColor3 = T.text
			label.TextSize = 12
			label.TextXAlignment = Enum.TextXAlignment.Left
			label.TextYAlignment = Enum.TextYAlignment.Center
			label.Font = Enum.Font.SourceSans
			label.Parent = frame
			local valueLabel = Instance.new("TextLabel")
			valueLabel.Size = UDim2.new(0.28, -4, 0, 18)
			valueLabel.Position = UDim2.new(0.72, 0, 0, 0)
			valueLabel.BackgroundTransparency = 1
			valueLabel.Text = formatSliderValue(currentValue or min)
			valueLabel.TextColor3 = T.text
			valueLabel.TextSize = 12
			valueLabel.TextXAlignment = Enum.TextXAlignment.Right
			valueLabel.TextYAlignment = Enum.TextYAlignment.Center
			valueLabel.Font = Enum.Font.SourceSans
			valueLabel.Parent = frame
			local sliderHitbox = Instance.new("Frame")
			sliderHitbox.Name = "SliderHitbox"
			sliderHitbox.Size = UDim2.new(1, -8, 0, 20)
			sliderHitbox.Position = UDim2.new(0, 4, 0, 20)
			sliderHitbox.BackgroundTransparency = 1
			sliderHitbox.Active = true
			sliderHitbox.Parent = frame
			local sliderBack = Instance.new("Frame")
			sliderBack.Name = "SliderBack"
			sliderBack.Size = UDim2.new(1, 0, 0, 4)
			sliderBack.Position = UDim2.new(0, 0, 0.5, -2)
			sliderBack.BackgroundColor3 = T.sliderBack
			sliderBack.BackgroundTransparency = 0
			sliderBack.BorderSizePixel = 0
			sliderBack.Parent = sliderHitbox
			local sliderCorner = Instance.new("UICorner")
			sliderCorner.CornerRadius = UDim.new(0, 2)
			sliderCorner.Parent = sliderBack
			local targetScale = math.clamp(((currentValue or min) - min) / (max - min), 0, 1)
			local fill = Instance.new("Frame")
			fill.Name = "Fill"
			fill.Size = UDim2.new(0, 0, 1, 0)
			fill.BackgroundColor3 = T.accent
			fill.BackgroundTransparency = 0
			fill.BorderSizePixel = 0
			fill.Parent = sliderBack
			fill:SetAttribute("TargetScale", targetScale)
			local fillCorner = Instance.new("UICorner")
			fillCorner.CornerRadius = UDim.new(0, 2)
			fillCorner.Parent = fill
			local knob = Instance.new("Frame")
			knob.Size = UDim2.new(0, 12, 0, 12)
			knob.Position = UDim2.new(1, -6, 0.5, -6)
			knob.BackgroundColor3 = T.accent
			knob.BackgroundTransparency = 0
			knob.BorderSizePixel = 0
			knob.Parent = fill
			local knobCorner = Instance.new("UICorner")
			knobCorner.CornerRadius = UDim.new(0, 6)
			knobCorner.Parent = knob
			local handleMotion = nil
			local function animateHandle(size)
				if handleMotion then handleMotion:Cancel() end
				handleMotion = TweenService:Create(knob,TweenInfo.new(.16,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),
					{Size=UDim2.fromOffset(size,size),Position=UDim2.new(1,-size/2,.5,-size/2)})
				handleMotion:Play()
			end
			sliderHitbox.MouseEnter:Connect(function() animateHandle(16) end)
			sliderHitbox.MouseLeave:Connect(function() animateHandle(12) end)
			local dragging = false
			local ctrlPressed = false
			local function updateSlider(inputX)
				local rel = math.clamp((inputX - sliderHitbox.AbsolutePosition.X) / sliderHitbox.AbsoluteSize.X, 0, 1)
				local value = min + (max - min) * rel
				if ctrlPressed then
					value = math.floor(value + 0.5)
				end
				value = math.max(min, math.min(max, value))
				local newRel = (value - min) / (max - min)
				fill.Size = UDim2.new(newRel, 0, 1, 0)
				fill:SetAttribute("TargetScale", newRel)
				valueLabel.Text = formatSliderValue(value)
				if callback then
					callback(value)
				end
			end
			local succ, err = pcall(function()
				if callback then
					callback(currentValue or min)
				end
			end)
			if not succ then
				warn("[MENU API] Slider Error: " .. err)
			end
			sliderHitbox.InputBegan:Connect(function(input)
				if input.UserInputType == Enum.UserInputType.MouseButton1 then
					dragging = true
					_G.canDrag = false
					updateSlider(input.Position.X)
					input.Changed:Connect(function()
						if input.UserInputState == Enum.UserInputState.End then
							dragging = false
							_G.canDrag = true
						end
					end)
				end
			end)
			table.insert(Library.RuntimeConnections, UserInputService.InputChanged:Connect(function(input)
				if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then
					updateSlider(input.Position.X)
				end
			end))
			table.insert(Library.RuntimeConnections, UserInputService.InputBegan:Connect(function(input)
				if input.KeyCode == Enum.KeyCode.LeftControl or input.KeyCode == Enum.KeyCode.RightControl then
					ctrlPressed = true
				end
			end))
			table.insert(Library.RuntimeConnections, UserInputService.InputEnded:Connect(function(input)
				if input.KeyCode == Enum.KeyCode.LeftControl or input.KeyCode == Enum.KeyCode.RightControl then
					ctrlPressed = false
				end
			end))
			table.insert(tabData.elements, frame)
			registerThemeListener(function(theme)
				frame.BackgroundColor3 = theme.surface
				label.TextColor3 = theme.text
				valueLabel.TextColor3 = theme.text
				sliderBack.BackgroundColor3 = theme.sliderBack
				fill.BackgroundColor3 = theme.accent
				knob.BackgroundColor3 = theme.accent
			end)
			return {
				SetValue = function(newValue)
					local clamped = math.clamp(newValue, min, max)
					local rel = (clamped - min) / (max - min)
					fill.Size = UDim2.new(rel, 0, 1, 0)
					fill:SetAttribute("TargetScale", rel)
					valueLabel.Text = formatSliderValue(clamped)
					if callback then
						callback(clamped)
					end
				end,
				GetValue = function()
					local rel = fill.Size.X.Scale
					return min + (max - min) * rel
				end,
			}
		end
function Library:CreateToggle(tabData, text, currentValue, callback)
	if not tabData or not tabData.elementContainer then return nil end
	local palette, state, hovered, pressed, alive = T, currentValue == true, false, false, true
	local tweens, connections = {}, {}
	local function make(kind, props, parent)
		local object = Instance.new(kind)
		for key, value in pairs(props) do object[key] = value end
		object.Parent = parent
		return object
	end
	local frame = make("Frame", {Name="OrbitToggle", Size=UDim2.new(1,0,0,38),
		BackgroundColor3=palette.surface, BorderSizePixel=0}, tabData.elementContainer)
	local label = make("TextLabel", {Name="OrbitToggleLabel", Size=UDim2.new(1,-92,1,0), Position=UDim2.fromOffset(14,0),
		BackgroundTransparency=1, TextSize=14, Font=Enum.Font.Gotham, TextColor3=palette.text,
		TextXAlignment=Enum.TextXAlignment.Left, TextTruncate=Enum.TextTruncate.AtEnd}, frame)
	Library.Localization.SetText(label, text)
	local accent = make("Frame", {Name="StateAccent", AnchorPoint=Vector2.new(0,.5), Position=UDim2.new(0,3,.5,0),
		Size=UDim2.fromOffset(2,16), BackgroundColor3=palette.accent, BorderSizePixel=0}, frame)
	make("UICorner", {CornerRadius=UDim.new(1,0)}, accent)
	local chip = make("Frame", {Name="StateChip", AnchorPoint=Vector2.new(.5,.5), Position=UDim2.new(1,-39,.5,0),
		Size=UDim2.fromOffset(58,25), BackgroundColor3=palette.surface, BorderSizePixel=0}, frame)
	make("UICorner", {CornerRadius=UDim.new(0,6)}, chip)
	local outline = make("UIStroke", {ApplyStrokeMode=Enum.ApplyStrokeMode.Border, Color=palette.stroke,
		Thickness=1, Transparency=.6}, chip)
	local chipScale = make("UIScale", {Scale=1}, chip)
	local status = make("TextLabel", {Name="OrbitToggleStatus", Size=UDim2.new(1,0,1,-2),
		BackgroundTransparency=1, TextSize=11, Font=Enum.Font.GothamMedium, TextColor3=palette.textDim}, chip)
	local track = make("Frame", {Position=UDim2.new(0,7,1,-3), Size=UDim2.new(1,-14,0,2),
		BackgroundTransparency=1, BorderSizePixel=0}, chip)
	local progress = make("Frame", {Name="StateProgress", Size=UDim2.new(0,0,1,0),
		BackgroundColor3=palette.accent, BorderSizePixel=0}, track)
	make("UICorner", {CornerRadius=UDim.new(1,0)}, progress)
	local bottom = make("Frame", {Position=UDim2.new(0,12,1,-1), Size=UDim2.new(1,-24,0,1),
		BackgroundColor3=palette.stroke, BackgroundTransparency=.7, BorderSizePixel=0}, frame)
	local button = make("TextButton", {Name="ToggleInput", Size=UDim2.fromScale(1,1),
		BackgroundTransparency=1, Text="", AutoButtonColor=false}, frame)
	local function connect(signal, callback)
		local connection = signal:Connect(callback)
		table.insert(connections, connection)
	end
	local function move(object, goals, instant, spring)
		if tweens[object] then tweens[object]:Cancel(); tweens[object] = nil end
		if instant then
			for key, value in pairs(goals) do object[key] = value end
		else
			local tween = TweenService:Create(object, TweenInfo.new(spring and .24 or .17,
				spring and Enum.EasingStyle.Back or Enum.EasingStyle.Quart, Enum.EasingDirection.Out), goals)
			tweens[object] = tween
			tween:Play()
		end
	end
	local function refresh(instant)
		if not alive then return end
		frame:SetAttribute("OrbitToggleState", state)
		Library.Localization.SetText(status, state and "ON" or "OFF")
		move(frame, {BackgroundColor3=hovered and palette.hover or palette.surface}, instant)
		move(label, {TextColor3=state and palette.text or palette.textDim}, instant)
		move(accent, {BackgroundColor3=palette.accent, BackgroundTransparency=state and 0 or 1}, instant)
		move(chip, {BackgroundColor3=palette.surface:Lerp(palette.accent, state and .17 or (hovered and .06 or .025))}, instant)
		move(outline, {Color=state and palette.accent or palette.stroke, Transparency=state and .25 or (hovered and .25 or .65)}, instant)
		move(status, {TextColor3=state and palette.accent or palette.textDim}, instant)
		move(progress, {Size=UDim2.new(state and 1 or 0,0,1,0), BackgroundColor3=palette.accent}, instant)
		move(chipScale, {Scale=pressed and .92 or (hovered and 1.035 or 1)}, instant, true)
		bottom.BackgroundColor3 = palette.stroke
	end
	refresh(true)
	local ok, err = pcall(function() if callback then callback(state) end end)
	if not ok then warn("[MENU API] Toggle Error: " .. tostring(err)) end
	connect(button.MouseEnter, function() hovered = true; refresh(false) end)
	connect(button.MouseLeave, function() hovered, pressed = false, false; refresh(false) end)
	connect(button.MouseButton1Down, function() pressed = true; refresh(false) end)
	connect(button.MouseButton1Up, function() pressed = false; refresh(false) end)
	connect(button.Activated, function()
		state, pressed = not state, false
		chipScale.Scale = .9
		refresh(false)
		if callback then callback(state) end
	end)
	table.insert(tabData.elements, frame)
	registerThemeListener(function(theme)
		if not alive then return end
		palette = theme
		refresh(true)
	end)
	local control = {}
	control.SetState = function(newState, invokeCallback)
		state = newState == true
		refresh(false)
		if invokeCallback and callback then
			local succeeded, callbackError = pcall(callback, state)
			if not succeeded then warn("[MENU API] Toggle shutdown error: " .. tostring(callbackError)); return false end
		end
		return true
	end
	control.GetState = function() return state end
	table.insert(Library.ToggleControls, control)
	connect(frame.Destroying, function()
		alive = false
		for _, tween in pairs(tweens) do tween:Cancel() end
		table.clear(tweens)
		for _, connection in ipairs(connections) do connection:Disconnect() end
		table.clear(connections)
	end)
	return control
end

		function Library:DisableActiveToggles()
			local controls = table.clone(Library.ToggleControls)
			for index = #controls, 1, -1 do
				local control = controls[index]
				if control and control.GetState and control.GetState() then
					pcall(control.SetState, false, true)
				end
			end
		end

		function Library:CreateTwoWaySwitch(tabData, labelText, leftText, rightText, rightSelected, callback)
			if not tabData or not tabData.elementContainer then
				return nil
			end
			local frame = Instance.new("Frame")
