			label.TextColor3 = T.text
			label.TextSize = 12
			label.TextXAlignment = Enum.TextXAlignment.Left
			label.TextYAlignment = Enum.TextYAlignment.Center
			label.Font = Enum.Font.SourceSans
			label.Parent = frame

			local selector = Instance.new("Frame")
			selector.Name = "TwoWaySwitch"
			selector.Size = UDim2.new(0, 142, 0, 22)
			selector.Position = UDim2.new(1, -146, 0.5, -11)
			selector.BackgroundColor3 = T.sliderBack
			selector.BorderSizePixel = 0
			selector.ClipsDescendants = true
			selector.Parent = frame
			local selectorCorner = Instance.new("UICorner")
			selectorCorner.CornerRadius = UDim.new(0, 6)
			selectorCorner.Parent = selector
			local selectorStroke = Instance.new("UIStroke")
			selectorStroke.Color = T.stroke
			selectorStroke.Transparency = 0.35
			selectorStroke.Parent = selector

			local selectedFill = Instance.new("Frame")
			selectedFill.Name = "SelectedFill"
			selectedFill.Size = UDim2.new(0.5, -3, 1, -4)
			selectedFill.BackgroundColor3 = T.accent
			selectedFill.BorderSizePixel = 0
			selectedFill.ZIndex = 2
			selectedFill.Parent = selector
			local selectedCorner = Instance.new("UICorner")
			selectedCorner.CornerRadius = UDim.new(0, 5)
			selectedCorner.Parent = selectedFill

			local leftButton = Instance.new("TextButton")
			leftButton.Name = "Left"
			leftButton.Size = UDim2.new(0.5, 0, 1, 0)
			leftButton.Position = UDim2.new(0, 0, 0, 0)
			leftButton.BackgroundTransparency = 1
			leftButton.Text = tostring(leftText)
			leftButton.TextSize = 11
			leftButton.Font = Enum.Font.SourceSansBold
			leftButton.AutoButtonColor = false
			leftButton.ZIndex = 3
			leftButton.Parent = selector

			local rightButton = Instance.new("TextButton")
			rightButton.Name = "Right"
			rightButton.Size = UDim2.new(0.5, 0, 1, 0)
			rightButton.Position = UDim2.new(0.5, 0, 0, 0)
			rightButton.BackgroundTransparency = 1
			rightButton.Text = tostring(rightText)
			rightButton.TextSize = 11
			rightButton.Font = Enum.Font.SourceSansBold
			rightButton.AutoButtonColor = false
			rightButton.ZIndex = 3
			rightButton.Parent = selector

			local selectedRight = rightSelected == true
			local positionTween = nil
			local function updateSelection(animate)
				local targetPosition = selectedRight and UDim2.new(0.5, 1, 0, 2) or UDim2.new(0, 2, 0, 2)
				if animate then
					if positionTween then
						positionTween:Cancel()
					end
					positionTween = TweenService:Create(
						selectedFill,
						TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
						{ Position = targetPosition }
					)
					positionTween:Play()
				else
					selectedFill.Position = targetPosition
				end
				leftButton.TextColor3 = selectedRight and T.textDim or Color3.fromRGB(255, 255, 255)
				rightButton.TextColor3 = selectedRight and Color3.fromRGB(255, 255, 255) or T.textDim
			end

			local function setSelection(selectRight, triggerCallback)
				selectRight = selectRight == true
				if selectedRight == selectRight then
					return
				end
				selectedRight = selectRight
				updateSelection(true)
				if triggerCallback and callback then
					callback(selectedRight)
				end
			end

			updateSelection(false)
			local succ, err = pcall(function()
				if callback then
					callback(selectedRight)
				end
			end)
			if not succ then
				warn("[MENU API] Two Way Switch Error: " .. tostring(err))
			end

			leftButton.MouseButton1Click:Connect(function()
				setSelection(false, true)
			end)
			rightButton.MouseButton1Click:Connect(function()
				setSelection(true, true)
			end)

			table.insert(tabData.elements, frame)
			registerThemeListener(function(theme)
				frame.BackgroundColor3 = theme.surface
				label.TextColor3 = theme.text
				selector.BackgroundColor3 = theme.sliderBack
				selectorStroke.Color = theme.stroke
				selectedFill.BackgroundColor3 = theme.accent
				leftButton.TextColor3 = selectedRight and theme.textDim or Color3.fromRGB(255, 255, 255)
				rightButton.TextColor3 = selectedRight and Color3.fromRGB(255, 255, 255) or theme.textDim
			end)

			return {
				SetRightSelected = function(selectRight)
					setSelection(selectRight, false)
				end,
				IsRightSelected = function()
					return selectedRight
				end,
			}
		end

