			local inputPadding = Instance.new("UIPadding")
			inputPadding.PaddingLeft = UDim.new(0, 8)
			inputPadding.PaddingRight = UDim.new(0, 8)
			inputPadding.Parent = input
			local inputCorner = Instance.new("UICorner")
			inputCorner.CornerRadius = UDim.new(0, 4)
			inputCorner.Parent = input
            local inputStroke = Instance.new("UIStroke")
            inputStroke.Name, inputStroke.ApplyStrokeMode = "InputOutline", Enum.ApplyStrokeMode.Border
            inputStroke.Thickness, inputStroke.Parent = 1, input
            local focused, hover, fillMotion, strokeMotion = false, false, nil, nil
            local function styleInput(animate)
                local fill = T.surface:Lerp(T.text,hover and .1 or .065)
                local outline = focused and T.accent or T.stroke:Lerp(T.text,hover and .5 or .3)
                if fillMotion then fillMotion:Cancel() end
                if strokeMotion then strokeMotion:Cancel() end
                inputStroke.Thickness=focused and 1.5 or 1
                if animate then
                    local info=TweenInfo.new(.16,Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
                    fillMotion=TweenService:Create(input,info,{BackgroundColor3=fill})
                    strokeMotion=TweenService:Create(inputStroke,info,{Color=outline})
                    fillMotion:Play(); strokeMotion:Play()
                else input.BackgroundColor3,inputStroke.Color=fill,outline end
            end
            input.MouseEnter:Connect(function() hover=true; styleInput(true) end)
            input.MouseLeave:Connect(function() hover=false; styleInput(true) end)
            input.Focused:Connect(function() focused=true; styleInput(true) end)
            input.FocusLost:Connect(function() focused=false; styleInput(true) end)
            styleInput(false)
			local function setValue(value, invokeCallback)
				input.Text = tostring(value or "")
				if invokeCallback ~= false and callback then
					callback(input.Text)
				end
			end
			input.FocusLost:Connect(function()
				if callback then
					callback(input.Text)
				end
			end)
			table.insert(tabData.elements, frame)
			registerThemeListener(function(theme)
				frame.BackgroundColor3 = theme.surface
				label.TextColor3 = theme.text
				styleInput(false)
				input.TextColor3 = theme.text
				input.PlaceholderColor3 = theme.textDim
			end)
			return {
				SetValue = setValue,
				GetValue = function()
					return input.Text
				end,
				Focus = function()
					input:CaptureFocus()
				end,
				SetVisible = function(visible)
					frame.Visible = visible == true
					task.defer(function()
						Library:LayoutFunctionTabs(tabData.classLabel)
					end)
				end,
			}
		end
