				Library.Localization.SetText(button, text or "Button")
			button.TextColor3 = T.text
			button.TextSize = 12
			button.Font = Enum.Font.SourceSansBold
			button.Parent = frame
			local buttonCorner = Instance.new("UICorner")
			buttonCorner.CornerRadius = UDim.new(0, 5)
			buttonCorner.Parent = button
            button.TextXAlignment,button.TextTruncate = Enum.TextXAlignment.Left,Enum.TextTruncate.AtEnd
            local buttonPadding=Instance.new("UIPadding")
            buttonPadding.PaddingLeft,buttonPadding.PaddingRight=UDim.new(0,12),UDim.new(0,32)
            buttonPadding.Parent=button
            local actionStroke=Instance.new("UIStroke")
            actionStroke.Name,actionStroke.ApplyStrokeMode="ActionOutline",Enum.ApplyStrokeMode.Border
            actionStroke.Thickness,actionStroke.Parent=1,button
            local actionArms={}
            for index=1,2 do
                local line=Instance.new("Frame")
                line.AnchorPoint,line.Size=Vector2.new(.5,.5),UDim2.fromOffset(7,2)
                line.Position,line.Rotation=UDim2.new(1,-15,.5,index==1 and -2.5 or 2.5),index==1 and 45 or -45
                line.BorderSizePixel,line.Parent=0,button
                actionArms[index]=line
            end
            local actionHover,actionMotion,actionBorderMotion=false,nil,nil
            local function styleAction(animate)
                local fill=T.surface:Lerp(T.accent,actionHover and .18 or .08):Lerp(T.text,.035)
                local outline=actionHover and T.accent or T.stroke:Lerp(T.text,.28)
                for _,line in ipairs(actionArms) do line.BackgroundColor3=actionHover and T.accent or T.textDim end
                if actionMotion then actionMotion:Cancel() end
                if actionBorderMotion then actionBorderMotion:Cancel() end
                if animate then
                    local info=TweenInfo.new(.16,Enum.EasingStyle.Quart,Enum.EasingDirection.Out)
                    actionMotion=TweenService:Create(button,info,{BackgroundColor3=fill})
                    actionBorderMotion=TweenService:Create(actionStroke,info,{Color=outline})
                    actionMotion:Play(); actionBorderMotion:Play()
                else button.BackgroundColor3,actionStroke.Color=fill,outline end
            end
            styleAction(false)
			button.AnchorPoint,button.Position=Vector2.new(.5,.5),UDim2.new(.5,0,0,19)
			local pressScale=Instance.new("UIScale")
			pressScale.Parent=button
			local pressTween=nil
			local function pressFeedback(value)
				if pressTween then pressTween:Cancel() end
				pressTween=TweenService:Create(pressScale,TweenInfo.new(.16,Enum.EasingStyle.Quart,Enum.EasingDirection.Out),{Scale=value})
				pressTween:Play()
			end
			button.MouseButton1Down:Connect(function() pressFeedback(.975) end)
			button.MouseButton1Up:Connect(function() pressFeedback(1) end)
			button.MouseLeave:Connect(function() pressFeedback(1) end)
			button.MouseEnter:Connect(function()
				actionHover=true; styleAction(true)
			end)
			button.MouseLeave:Connect(function()
				actionHover=false; styleAction(true)
			end)
			button.MouseButton1Click:Connect(function()
				if callback then
					local succeeded, buttonError = pcall(callback)
					if not succeeded then
						warn("[MENU API] Button Error: " .. tostring(buttonError))
					end
				end
			end)
			table.insert(tabData.elements, frame)
			registerThemeListener(function(theme)
				frame.BackgroundColor3 = theme.surface
				styleAction(false)
				button.TextColor3 = theme.text
			end)
			return {
				SetText = function(newText)
					Library.Localization.SetText(button, newText)
				end,
				SetVisible = function(visible)
					frame.Visible = visible == true
					task.defer(function()
						Library:LayoutFunctionTabs(tabData.classLabel)
					end)
				end,
			}
		end
