local function createStandCardPreview(card, standName, skinName)
 if not standName or standName == "" then return end
 card.ClipsDescendants = true
 local preview = Instance.new("Frame")
 preview.Name = "StandPreview"
 preview.Size = UDim2.new(1,-8,1,-25)
 preview.Position = UDim2.fromOffset(4,2)
 preview.BackgroundColor3 = T.dropdownBg
 preview.BorderSizePixel = 0
 preview.ClipsDescendants = true
 preview.ZIndex = 1
 preview.Parent = card
 local corner = Instance.new("UICorner")
 corner.CornerRadius = UDim.new(0,6)
 corner.Parent = preview
 local picture = Instance.new("ImageLabel")
 picture.Name = "StandImage"
 picture.Size = UDim2.fromScale(1,1)
 picture.BackgroundTransparency = 1
 picture.ScaleType = Enum.ScaleType.Fit
 picture.Image = ""
 picture.ZIndex = 2
 picture.Parent = preview
 local function fallback()
  task.spawn(function()
   if not preview.Parent then return end
   local ok, template = pcall(function()
    return _G.TheBestStandPreviewProvider and _G.TheBestStandPreviewProvider(standName,skinName)
   end)
   if not preview.Parent then return end
   if ok and template then
    local success = pcall(function()
     local model = template:Clone()
     for _, object in ipairs(model:GetDescendants()) do
      if object:IsA("BaseScript") or object:IsA("ModuleScript") then object:Destroy()
      elseif object:IsA("BasePart") then object.Anchored=true; object.CanCollide=false end
     end
     local viewport = Instance.new("ViewportFrame")
     viewport.Size=UDim2.fromScale(1,1); viewport.BackgroundTransparency=1
     viewport.Ambient=Color3.fromRGB(195,195,210); viewport.LightColor=Color3.fromRGB(255,244,225)
     viewport.LightDirection=Vector3.new(-1,-0.5,-1); viewport.ZIndex=2; viewport.Parent=preview
     local world=Instance.new("WorldModel"); world.Parent=viewport; model.Parent=world
     local box, size=model:GetBoundingBox()
     local camera=Instance.new("Camera"); camera.FieldOfView=32
     local distance=math.max(size.X,size.Y,size.Z)*1.9
     camera.CFrame=CFrame.lookAt(box.Position+Vector3.new(distance*0.28,size.Y*0.08,-distance),box.Position)
     camera.Parent=viewport; viewport.CurrentCamera=camera
    end)
    if success then return end
   end
   local unavailable=Instance.new("TextLabel")
   unavailable.Size=UDim2.fromScale(1,1); unavailable.BackgroundTransparency=1
   unavailable.Text="Image unavailable"; unavailable.TextColor3=T.mutedText or T.text
   unavailable.TextSize=11; unavailable.Font=Enum.Font.Gotham; unavailable.ZIndex=3; unavailable.Parent=preview
  end)
 end
 if type(_G.TheBestRequestStandCardImage)=="function" then
  _G.TheBestRequestStandCardImage(standName,skinName,function(asset)
   if not preview.Parent then return end
   if asset then picture.Image=asset else fallback() end
  end)
 else fallback() end
 if skinName and skinName ~= "None" then
  local key=string.lower(tostring(standName):gsub("[^%w]", "")).."/"..string.lower(tostring(skinName):gsub("[^%w]", ""))
  if _G.TheBestCatalogSkinStates and _G.TheBestCatalogSkinStates[key]=="Preview only" then
   local status=Instance.new("TextLabel")
   status.Size=UDim2.new(1,0,0,19);status.Position=UDim2.new(0,0,1,-19)
   status.BackgroundColor3=T.background;status.BackgroundTransparency=.12;status.Text="Preview only"
   status.TextColor3=T.text;status.TextSize=10;status.Font=Enum.Font.Gotham;status.ZIndex=4;status.Parent=preview
  end
 end
end

