		function Library:ReleaseKeyboardFocus()
			if _G.currentOpenDropdown and _G.currentOpenDropdown.close then
				pcall(_G.currentOpenDropdown.close)
				_G.currentOpenDropdown = nil
			end
			if type(_G.TheBestCloseEmotePopup) == "function" then
				pcall(_G.TheBestCloseEmotePopup)
			end
			local focusedTextBox = UserInputService:GetFocusedTextBox()
			if focusedTextBox
				and activeMainUI
				and activeMainUI.ScreenGui
				and focusedTextBox:IsDescendantOf(activeMainUI.ScreenGui)
			then
				pcall(function()
					focusedTextBox:ReleaseFocus()
				end)
			end
		end
		function Library:DestroyUI()
			Library:ReleaseKeyboardFocus()
			for _, connection in ipairs(Library.RuntimeConnections) do
				pcall(function()
					connection:Disconnect()
				end)
			end
			table.clear(Library.RuntimeConnections)
			if activeMainUI then
				activeMainUI.ScreenGui:Destroy()
				activeMainUI = nil
				subData = {}
				functionTabs = {}
			end
			table.clear(Library.ToggleControls)
		end
		table.insert(Library.RuntimeConnections, UserInputService.InputBegan:Connect(function(input, gameProcessed)
			if gameProcessed then
				return
			end
			if not activeMainUI or not activeMainUI.Frame then
				return
			end
			if input.UserInputType ~= Enum.UserInputType.Keyboard then
				return
			end
			local openMenuKey = getKey and getKey("OpenMenu") or Enum.KeyCode.Delete
			if input.KeyCode == openMenuKey then
				if _G.TheBestBuildingUI then return end
				if type(Library.ToggleMenu) == "function" then
					Library.ToggleMenu()
					return
				end
				local visible = not activeMainUI.Frame.Visible
				if not visible then
					Library:ReleaseKeyboardFocus()
				end
				activeMainUI.Frame.Visible = visible
			end
		end))
