			local function serializeCFrame(value)
				if typeof(value) ~= "CFrame" then
					return false
				end
				return { value:GetComponents() }
			end

			local function deserializeCFrame(value)
				if type(value) ~= "table" then
					return nil
				end
				local components = {}
				for index = 1, 12 do
					local component = tonumber(value[index])
					if component == nil then
						return nil
					end
					components[index] = component
				end
				local succeeded, result = pcall(CFrame.new, table.unpack(components, 1, 12))
				return succeeded and result or nil
			end

			local function getCharacter()
				local character = XLocalPlayer.Character
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")
				local root = character and (character.PrimaryPart or character:FindFirstChild("HumanoidRootPart"))
				return character, humanoid, root
			end
			controller.GetCharacter = getCharacter

			local function getRemote()
				local character = XLocalPlayer.Character
				local remote = character and character:FindFirstChild("RemoteEvent", true)
				return remote and remote:IsA("RemoteEvent") and remote or nil
			end
			local function getRemoteFunction()
				local character = XLocalPlayer.Character
				return character and character:FindFirstChild("RemoteFunction")
			end

			local function contains(list, value)
				if type(list) ~= "table" then
					return false
				end
				for _, item in ipairs(list) do
					if item == value then
						return true
					end
				end
				return false
			end

			local function sortedKeys(dictionary)
				local result = {}
				for key in pairs(dictionary or {}) do
					table.insert(result, key)
				end
				table.sort(result)
				return result
			end
			controller.SortedKeys = sortedKeys

			local function startLoop(name, callback, interval)
				local generation = (controller.Loops[name] or 0) + 1
				controller.Loops[name] = generation
				task.spawn(function()
					while controller.Loops[name] == generation do
						local succeeded, loopError = pcall(callback, generation)
						if not succeeded then
							warn("[THEBEST/XENON " .. name .. "] " .. tostring(loopError))
						end
						task.wait(interval or 0.1)
					end
				end)
				return generation
			end
			local function stopLoop(name)
				controller.Loops[name] = (controller.Loops[name] or 0) + 1
				local transaction = controller.ItemCollectTransaction
				if transaction and transaction.Loop == name then transaction.Cancel() end
				if not controller.FarmReturnCFrames[name] then movement.Cancel("farm:" .. name) end
			end
			local function loopCurrent(name, generation)
				return controller.Loops[name] == generation
			end

			local function waitCurrent(name, generation, seconds)
				local finish = os.clock() + math.max(tonumber(seconds) or 0, 0)
				repeat
					if not loopCurrent(name, generation) or (name == "AutoSBR" and not movement.Renew(controller.AutoSbrLease, 1)) then
						return false
					end
					task.wait(math.min(0.05, math.max(finish - os.clock(), 0)))
				until os.clock() >= finish
				return loopCurrent(name, generation)
			end

			function controller:Teleport(value, offset, owner)
				local _, humanoid, root = getCharacter()
				if not root or not humanoid or humanoid.Health <= 0 then
					return false
				end
				local target = typeof(value) == "Vector3" and CFrame.new(value) or value
				if typeof(target) ~= "CFrame" then
					return false
				end
				local lease = movement.Claim(owner or "Manual", root, owner and "Shop" or "Manual", owner and 65 or 0.4)
				if not lease or not movement.Write(lease, target + (offset or Vector3.zero)) then return false end
				root.AssemblyLinearVelocity = Vector3.zero
				root.AssemblyAngularVelocity = Vector3.zero
				return true
			end

			function controller:SetWaypoint()
				local _, humanoid, root = getCharacter()
				if not root or not humanoid or humanoid.Health <= 0 then
					return false
				end
				_G.Config.xenonWaypoint = serializeCFrame(root.CFrame)
				save()
				return _G.Config.xenonWaypoint ~= false
			end

			function controller:GoToWaypoint()
				local waypoint = deserializeCFrame(_G.Config.xenonWaypoint)
				return waypoint ~= nil and self:Teleport(waypoint) or false
			end

			function controller:SetSpawnpoint()
				local _, humanoid, root = getCharacter()
				if not root or not humanoid or humanoid.Health <= 0 then
					return false
