			function controller:GetPlayerNames()
				local names = {}
				for _, player in ipairs(XPlayers:GetPlayers()) do
					if player ~= XLocalPlayer then
						table.insert(names, player.Name)
					end
				end
				table.sort(names)
				return names
			end

			function controller:GetNpcNames()
				local names, seen = {}, {}
				local living = workspace:FindFirstChild("Living")
				if living then
					for _, model in ipairs(living:GetChildren()) do
						if model:IsA("Model") and model:FindFirstChild("Spawn") and not seen[model.Name] then
							seen[model.Name] = true
							table.insert(names, model.Name)
						end
					end
				end
				table.sort(names)
				return names
			end

			function controller:TeleportToPlayer(name)
				local player = XPlayers:FindFirstChild(tostring(name or ""))
				local targetRoot = player and player.Character and player.Character:FindFirstChild("HumanoidRootPart")
				return targetRoot and self:Teleport(targetRoot.CFrame * CFrame.new(0, 0, 3)) or false
			end

			function controller:TeleportToNpc(name)
				local living = workspace:FindFirstChild("Living")
				local target = living and living:FindFirstChild(tostring(name or ""))
				local targetRoot = target and (target.PrimaryPart or target:FindFirstChild("HumanoidRootPart"))
				return targetRoot and self:Teleport(targetRoot.CFrame * CFrame.new(0, 0, 3)) or false
			end

			controller.ItemEspTypes = table.clone(controller.AllItems)
			if not contains(controller.ItemEspTypes, "Lucky Arrow") then table.insert(controller.ItemEspTypes, "Lucky Arrow") end
			table.sort(controller.ItemEspTypes)
			local itemNameAliases = {}
			for _, name in ipairs(controller.ItemEspTypes) do
				itemNameAliases[string.lower(name):gsub("[^%w]", "")] = name
			end
			local function canonicalItemName(value)
				if type(value) ~= "string" then return nil end
				local text = value:gsub("<[^>]->", "")
				return itemNameAliases[string.lower(text):gsub("[^%w]", "")]
			end
			local function itemMetadataName(object)
				for _, key in ipairs({ "ItemName", "Item" }) do
					local named = canonicalItemName(object:GetAttribute(key))
					if named then return named end
					local value = object:FindFirstChild(key)
					if value and value:IsA("StringValue") then
						named = canonicalItemName(value.Value)
						if named then return named end
					end
				end
			end
			local function identifyItemPrompt(prompt)
				if not prompt or not prompt:IsA("ProximityPrompt") then return nil end
				local current = prompt.Parent
				local metadataName, ownerName = itemMetadataName(prompt), nil
				local promptName = canonicalItemName(prompt.ObjectText)
				while current and current ~= workspace do
					local dialogue = current:FindFirstChild("Dialogue")
					if current:FindFirstChildOfClass("Humanoid") or (dialogue and dialogue:IsA("StringValue")) then return nil end
					if not metadataName then metadataName = itemMetadataName(current) end
					if not ownerName then ownerName = canonicalItemName(current.Name) end
					current = current.Parent
				end
				return metadataName or ownerName or promptName
			end

			local function getPromptModel(prompt)
				local current = prompt and prompt.Parent
				while current and current ~= workspace do
					if current:IsA("Model") then return current end
					current = current.Parent
				end
				return prompt and prompt.Parent or nil
			end

			local function validItemPosition(position)
				return position and position.X == position.X and position.Y == position.Y and position.Z == position.Z
					and math.abs(position.X) < math.huge and math.abs(position.Y) < math.huge and math.abs(position.Z) < math.huge
					and position.Magnitude > 0.05
			end
			local function getAdornee(prompt)
				local parent = prompt and prompt.Parent
				if not parent then return nil end
				if parent:IsA("Attachment") then
					local part = parent:FindFirstAncestorWhichIsA("BasePart")
					if part and validItemPosition(parent.WorldPosition) then return part, parent end
					return nil
				end
				if parent:IsA("BasePart") then
					return validItemPosition(parent.Position) and parent or nil
				end
				-- A direct model prompt needs a real item part, never the pivot of an outer spawn container.
