				if not name then return end
				local adornee, displayAdornee = getAdornee(prompt)
				if not adornee then return end
				local model = getPromptModel(prompt)
				local entry = { Name = name, Model = model, Adornee = adornee, DisplayAdornee = displayAdornee, Prompt = prompt }
				controller.ItemEntries[prompt] = entry
				ensureItemEsp(entry)
