			function controller:CollectOne(names)
				scanItemPrompts()
				local prompt = findNearestPrompt(names)
				if prompt then
					task.spawn(function()
						self:CollectPrompt(prompt)
					end)
					return true
				end
				return false
			end

			function controller:SetItemFarm(enabled)
				_G.Config.xenonItemFarm = enabled == true
				stopLoop("ItemFarm")
				if enabled then
					scanItemPrompts()
					startLoop("ItemFarm", function(generation)
						local selected = _G.Config.xenonSelectedItems
						if type(selected) ~= "table" or #selected == 0 then
							return
						end
						local prompt = findNearestPrompt(selected)
						if prompt then
							self:CollectPrompt(prompt, "ItemFarm", generation)
						end
					end, 0.1)
				elseif not _G.Config.xenonNoClip then
					local character = XLocalPlayer.Character
					setCharacterNoclip(character, false)
