					return
				end
				local sourceModel = descendant.Parent
				local sourceRoot = sourceModel and sourceModel:FindFirstChild("HumanoidRootPart")
				local _, humanoid, root = getCharacter()
				if not sourceRoot or not root or not humanoid or humanoid.Health <= 0 then
					return
				end
				if (sourceRoot.Position - root.Position).Magnitude >= 25 then
					return
				end
