			local function clickGuiButton(button, scope) return genericGuiClick.Click(button, scope) end

			local function findTool(names)
				if type(names) == "string" then
					names = { names }
				end
				for _, container in ipairs({ XLocalPlayer:FindFirstChild("Backpack"), XLocalPlayer.Character }) do
					if container then
						for _, name in ipairs(names or {}) do
							local tool = container:FindFirstChild(name)
							if tool and tool:IsA("Tool") then
								return tool
							end
						end
					end
				end
				return nil
			end

			local function equipTool(names)
				local _, humanoid = getCharacter()
				local tool = findTool(names)
				if humanoid and tool then
					pcall(function()
						humanoid:UnequipTools()
					end)
					humanoid:EquipTool(tool)
					local deadline = os.clock() + 0.45
					repeat
						if tool.Parent == XLocalPlayer.Character then
							return tool
						end
						task.wait(0.05)
					until os.clock() >= deadline or not tool.Parent
					return tool.Parent and tool or nil
				end
				return nil
			end

			local function learnSkills(extraWorthiness)
				local remoteFunction = getRemoteFunction()
				if not remoteFunction then
					return
				end
				local skills = { "Agility I", "Agility II", "Agility III", "Worthiness" }
				for _ = 1, tonumber(extraWorthiness) or 0 do
					table.insert(skills, "Worthiness")
				end
				for _, skill in ipairs(skills) do
					pcall(function()
						remoteFunction:InvokeServer("LearnSkill", { Skill = skill, SkillTreeType = "Character" })
					end)
				end
			end
			controller.LearnSkills = learnSkills

			local function getCurrentStandValue()
				local playerStats = XLocalPlayer:FindFirstChild("PlayerStats")
				local standValue = playerStats and playerStats:FindFirstChild("Stand")
				return standValue and tostring(standValue.Value) or "None"
			end

			local function findDialogueGui(playerGui)
				if not playerGui then
					return nil
				end
				local exact = playerGui:FindFirstChild("DialogueGui", true)
				if exact then
					return exact
				end
				for _, object in ipairs(playerGui:GetDescendants()) do
					if string.find(string.lower(object.Name), "dialogue", 1, true)
						and (object:IsA("LayerCollector") or object:IsA("GuiObject"))
					then
						return object
					end
				end
				return nil
			end

			local function findDialogueOption(dialogue)
				if not dialogue then
					return nil
				end
				local option = dialogue:FindFirstChild("Option1", true)
				if option then
					if option:IsA("GuiButton") then
						return option
					end
					local nested = option:FindFirstChildWhichIsA("GuiButton", true)
					if nested then
						return nested
					end
				end
				for _, object in ipairs(dialogue:GetDescendants()) do
					if object:IsA("GuiButton") and object.Visible and object.Active then
						local text = object:IsA("TextButton") and string.lower(object.Text or "") or ""
						if text ~= "no" and text ~= "cancel" and text ~= "\208\189\208\181\209\130" then
							return object
						end
					end
				end
				return nil
			end

			local function activateDialogueTool(tool)
				local activated = pcall(function()
					tool:Activate()
				end)
				if activated then
					return true
				end
				local camera = workspace.CurrentCamera
				local viewport = camera and camera.ViewportSize or Vector2.new(1280, 720)
				pcall(function()
					XVirtualInputManager:SendMouseButtonEvent(viewport.X * 0.5, viewport.Y * 0.5, 0, true, game, 1)
					XVirtualInputManager:SendMouseButtonEvent(viewport.X * 0.5, viewport.Y * 0.5, 0, false, game, 1)
				end)
				return false
			end

			local function useDialogueTool(names, requireStand)
				local playerStats = XLocalPlayer:FindFirstChild("PlayerStats")
				local standValue = playerStats and playerStats:FindFirstChild("Stand")
				if requireStand == true and (not standValue or standValue.Value == "None") then
					return false
				elseif requireStand == false and standValue and standValue.Value ~= "None" then
					return false
				end
				local tool = equipTool(names)
				if not tool then
					return false
				end
				genericGuiClick.Reset()
				local playerGui = XLocalPlayer:FindFirstChildOfClass("PlayerGui")
				local startingStand = getCurrentStandValue()
				local toolName = tostring(tool.Name):gsub("^Redeemed%s+", "")
				local remote = getRemote()
				local function completed()
					local currentStand = getCurrentStandValue()
					if requireStand then
						return currentStand == "None"
					end
					return currentStand ~= "None"
				end
				local function confirmDialogue()
					if not remote then
						return false
					end
					return pcall(function()
						remote:FireServer("EndDialogue", {
							NPC = toolName,
							Option = "Option1",
							Dialogue = "Dialogue2",
						})
					end)
				end

				activateDialogueTool(tool)
				confirmDialogue()
				local deadline = os.clock() + 0.65
				repeat
					if completed() then
						return true
					end
					local dialogue = findDialogueGui(playerGui)
					local button = findDialogueOption(dialogue)
					if button then
						clickGuiButton(button, dialogue)
					end
					task.wait(0.04)
				until os.clock() >= deadline or not tool.Parent

				if tool.Parent then
					activateDialogueTool(tool)
					confirmDialogue()
				end
				deadline = os.clock() + 1.75
				repeat
					if completed() then
						return true
					elseif not tool.Parent and getCurrentStandValue() ~= startingStand then
						return true
					end
					local dialogue = findDialogueGui(playerGui)
					local button = findDialogueOption(dialogue)
					if button then
						clickGuiButton(button, dialogue)
					end
					task.wait(0.08)
				until os.clock() >= deadline
				return getCurrentStandValue() ~= startingStand
			end

			function controller:UseArrow()
				learnSkills(0)
				local names = _G.Config.xenonUseRedeemedItems
					and { "Redeemed Mysterious Arrow", "Mysterious Arrow" }
					or { "Mysterious Arrow" }
				return useDialogueTool(names, false)
			end
			function controller:UseRokakaka()
				local names = _G.Config.xenonUseRedeemedItems
					and { "Redeemed Rokakaka", "Rokakaka" }
					or { "Rokakaka" }
				return useDialogueTool(names, true)
			end
