			function controller:UseRib()
				learnSkills(4)
				if getCurrentStandValue() ~= "None" or farmRuntime.DialogueBusy then return false end
				local names = _G.Config.xenonUseRedeemedItems
					and { "Redeemed Rib Cage of The Saint's Corpse", "Redeemed Rib Cage of the Saint's Corpse", "Rib Cage of The Saint's Corpse", "Rib Cage of the Saint's Corpse" }
					or { "Rib Cage of The Saint's Corpse", "Rib Cage of the Saint's Corpse" }
				local tool = equipTool(names)
				local character, humanoid = getCharacter()
				if not tool or not character or not humanoid then return false end
