					return farmRuntime:WaitForConfirmation(function()
						return getCurrentStandValue() ~= "None"
					end, function()
						return XLocalPlayer.Character == character and humanoid.Health > 0
							and (not farmWasEnabled or _G.Config.xenonRibFarm or _G.Config.xenonRibShinyFarm)
					end, 8)
				end)
				farmRuntime.DialogueBusy = false
				return ok and result == true
			end

			local function getStandName()
				local stats = XLocalPlayer:FindFirstChild("PlayerStats")
				local stand = stats and stats:FindFirstChild("Stand")
				return stand and tostring(stand.Value) or "None"
			end
			local function getPity()
				local stats = XLocalPlayer:FindFirstChild("PlayerStats")
				local pity = stats and (stats:FindFirstChild("Pity") or stats:FindFirstChild("PityCount"))
				return pity and tonumber(pity.Value) or 0
			end
			local function getShinyName()
				local remoteFunction = getRemoteFunction()
				if not remoteFunction then
					return "None"
				end
				local succeeded, result = pcall(function()
					return remoteFunction:InvokeServer("ReturnStandSkin", "Stand")
				end)
				return succeeded and tostring(result or "None") or "None"
			end
			controller.GetStandName = getStandName
			controller.GetPity = getPity
			controller.GetShinyName = getShinyName

			local function swapToEmptyStandSlot()
				local playerGui = XLocalPlayer:FindFirstChildOfClass("PlayerGui")
				local remote = getRemote()
				if not playerGui or not remote then
					return false
				end
				local standsFrame = playerGui:FindFirstChild("Stands", true)
				local scrollingFrame = standsFrame and standsFrame:FindFirstChildWhichIsA("ScrollingFrame", true)
				if not scrollingFrame then
					return false
				end
				for _, slot in ipairs(scrollingFrame:GetChildren()) do
					local label = slot:FindFirstChildWhichIsA("TextLabel", true)
					if label and string.find(string.lower(label.Text), "none", 1, true) then
						remote:FireServer("SwapStand", tostring(slot.Name))
						return true
					end
				end
				return false
			end

			local function sendConfiguredWebhook(title, message)
				if not _G.Config.xenonWebhookEnabled then
					return
				end
				local url = tostring(_G.Config.xenonWebhookUrl or "")
				if not string.match(url, "^https://") then
					return
				end
				local requestFunction = http_request or request or (type(syn) == "table" and syn.request)
				if type(requestFunction) ~= "function" then
					return
				end
				local body = XHttpService:JSONEncode({ embeds = { {
					title = title, description = message, type = "rich", color = 0xD9A62E,
				} } })
				pcall(requestFunction, {
					Url = url, Method = "POST", Body = body, Headers = { ["Content-Type"] = "application/json" },
				})
			end

			local function farmSelectedWorldItem(names, loopName, generation)
				if not loopCurrent(loopName, generation) then return false end
				scanItemPrompts()
				local prompt = findNearestPrompt(names)
				if prompt then
					return controller:CollectPrompt(prompt, loopName, generation)
				end
				return false
			end

local function prepareSafeFarm(loopName)
				local character, humanoid, root = getCharacter()
				if not root or not humanoid or humanoid.Health <= 0 then return false end
				local lease = movement.Claim("farm:" .. loopName, root, "StandFarm", 10)
				if not lease then return false end
				local snapshot = controller.FarmReturnCFrames[loopName]
				if type(snapshot) ~= "table" or snapshot.Root ~= root or snapshot.Lease ~= lease then
					snapshot = { Root = root, Character = character, Frame = root.CFrame, Lease = lease }
					controller.FarmReturnCFrames[loopName] = snapshot
				end
				movement.Write(lease, SAFE_FARM_CFRAME)
				root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
				humanoid.PlatformStand = false
				return true
			end
			local function restoreSafeFarm(loopName)
				local snapshot = controller.FarmReturnCFrames[loopName]
				controller.FarmReturnCFrames[loopName] = nil
				if type(snapshot) == "table" and XLocalPlayer.Character == snapshot.Character
					and snapshot.Root.Parent and movement.Write(snapshot.Lease, snapshot.Frame) then
					snapshot.Root.AssemblyLinearVelocity, snapshot.Root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
				end
				movement.Cancel("farm:" .. loopName)
			end

			local function standFarmStep(mode, generation)
				if not loopCurrent(mode, generation) then return end
				local standName = getStandName()
				local hasStand = standName ~= "None"
				local shinyName = getShinyName()
				local hasShiny = shinyName ~= "None" and shinyName ~= "nil"
				local isRib = mode == "RibFarm" or mode == "RibShinyFarm"
				local isShinyFarm = mode == "ShinyFarm" or mode == "RibShinyFarm"
				local selected = isShinyFarm and _G.Config.xenonSelectedShinies or _G.Config.xenonSelectedStands

				if isShinyFarm and hasShiny and contains(selected, shinyName) then
					if desiredShinyNotified ~= shinyName then
						desiredShinyNotified = shinyName
						notify("Wanted shiny obtained", shinyName, 6)
						sendConfiguredWebhook("TheBest - Shiny obtained", "Username: `" .. XLocalPlayer.Name
							.. "`\nShiny: `" .. shinyName .. "`\nPity: `" .. tostring(getPity()) .. "`")
						swapToEmptyStandSlot()
					end
					return
				end
				if not isShinyFarm and hasStand and (contains(selected, standName) or (_G.Config.xenonKeepAnyShiny and hasShiny)) then
					return
				end
				local pityMode = isRib and _G.Config.xenonRibPityFarm or _G.Config.xenonArrowPityFarm
				if pityMode and getPity() >= math.clamp(tonumber(_G.Config.xenonPityAmount) or 20, 20, 125) then
					notify("Pity farm", "Target pity reached: " .. tostring(getPity()), 6)
					return
				end
				if hasStand then
					if isRib then
						if not controller:UseRokakaka() then
							farmSelectedWorldItem({ "Rokakaka" }, mode, generation)
						end
					elseif not controller:UseRokakaka() then
						farmSelectedWorldItem({ "Rokakaka" }, mode, generation)
					end
				else
					if isRib then
						if not controller:UseRib() then
							-- A stopped Rib loop must not collect a replacement after a pending dialogue.
							local modeConfigKey = mode == "RibFarm" and "xenonRibFarm" or "xenonRibShinyFarm"
							if _G.Config[modeConfigKey] ~= true then return end
							farmSelectedWorldItem({ "Rib Cage of The Saint's Corpse" }, mode, generation)
						end
					elseif not controller:UseArrow() then
						farmSelectedWorldItem({ "Mysterious Arrow" }, mode, generation)
					end
				end
			end

			function controller:SetStandFarm(kind, enabled)
				local configKey = ({ StandFarm = "xenonStandFarm", RibFarm = "xenonRibFarm",
					ShinyFarm = "xenonShinyFarm", RibShinyFarm = "xenonRibShinyFarm" })[kind]
				if not configKey then
					return
				end
				_G.Config[configKey] = enabled == true
				stopLoop(kind)
				if enabled then
					desiredShinyNotified = nil
					startLoop(kind, function(generation)
						if not prepareSafeFarm(kind) then return end
						standFarmStep(kind, generation)
					end, 0.35)
				else
					restoreSafeFarm(kind)
				end
				save()
			end

			local function findLivingTarget(name)
				local livingFolder = workspace:FindFirstChild("Living")
				if not livingFolder then
					return nil
				end
				for _, model in ipairs(livingFolder:GetChildren()) do
					local humanoid = model:FindFirstChildOfClass("Humanoid")
					local health = model:FindFirstChild("Health")
					if model.Name == name and humanoid and humanoid.Health > 0 and (not health or health.Value > 0) then
						return model
					end
				end
				return nil
			end

			local function attackNpcStep(target, loopName)
				local character, humanoid, root = getCharacter()
