				local targetRoot = target and (target.PrimaryPart or target:FindFirstChild("HumanoidRootPart"))
				if not character or not humanoid or humanoid.Health <= 0 or not root or not targetRoot or not targetHumanoid then
					return
				end
				if not controller.FarmReturnCFrames[loopName] then
					controller.FarmReturnCFrames[loopName] = { Root = root, Character = character, Frame = root.CFrame,
