					farmRuntime.CameraSuppressed = false
				end
				_G.Config.xenonNpcFarm = enabled == true
				stopLoop("NpcFarm")
				if enabled then
					startLoop("NpcFarm", function()
						local succeeded, farmError = pcall(function()
							local target = findLivingTarget(_G.Config.xenonNpcFarmTarget)
							if target then
								local _, _, root = getCharacter()
								if root and movement.Claim("NpcFarm", root, "NpcFarm", 0.3) then attackNpcStep(target, "NpcFarm") end
							else
								_G.TheBestNpcPilotSetTarget(nil)
							end
						end)
						if not succeeded then _G.TheBestNpcPilotSetTarget(nil); error(farmError, 0) end
					end, 0.1)
				else
					restoreCombatFarm("NpcFarm")
				end
				save()
			end

			function controller:TraceItemSale(state, detail)
                self.ItemSellTrace = self.ItemSellTrace or {}
                local text = tostring(detail or ""):gsub("[\r\n]", " "):sub(1, 1000)
                local line = string.format("%.2f %s %s", os.clock(), tostring(state), text)
                table.insert(self.ItemSellTrace, line)
                if #self.ItemSellTrace > 48 then table.remove(self.ItemSellTrace, 1) end
                self.ItemSellStatus = tostring(state) .. ": " .. text:sub(1, 150)
                if self.OnItemSellStatus then pcall(self.OnItemSellStatus, self.ItemSellStatus) end
            end
            function controller:GetItemSellLog()
                return "TheBest Item Sell diagnostics\n" .. table.concat(self.ItemSellTrace or {}, "\n")
            end
            function controller:SellSelectedOnce(automatic, generation)
