	local character, humanoid, root = getCharacter()
	local remote = getRemote()
	local backpack = XLocalPlayer:FindFirstChild("Backpack")
	if not character or not humanoid or humanoid.Health <= 0 or not remote or not backpack then return false end
	if self:GetItemSellGui() then self:TraceItemSale("foreign_dialogue", "Close the current dialogue before starting a sale.") return false end
	local saleLease = root and movement.Claim("Sale", root, "Sale", 1)
	if not saleLease then return false end
	self.ItemSellBusy = true
	self.ItemSellCancel = false
	self:TraceItemSale("starting", automatic and "Automatic sale" or "Selected sale")
	self.ItemSellFailures = self.ItemSellFailures or {}
	local sold, rejected, attempted = 0, 0, 0
	local function active()
		return movement.Renew(saleLease, 1) and not self.ItemSellCancel and XLocalPlayer.Character == character and humanoid.Parent ~= nil and humanoid.Health > 0
			and (not automatic or loopCurrent("AutoSell", generation))
	end
	local ok, reason = pcall(function()
		for _, name in ipairs(_G.Config.xenonSelectedSellItems or {}) do
			if not active() then break end
			local before = self:CountItem(name)
			local priorFailure = self.ItemSellFailures[name]
			local tool = backpack:FindFirstChild(name) or character:FindFirstChild(name)
			local library = self.ItemLimitLibrary
			local sellable = not library or not library.SellableItems or library.SellableItems[name] ~= nil
			if tool and tool:IsA("Tool") and sellable and before > 0 and (not automatic or not priorFailure
				or priorFailure.Count ~= before or os.clock() >= priorFailure.Until) then
				attempted += 1
				self:TraceItemSale("equip", name .. "; before=" .. tostring(before))
				humanoid:UnequipTools()
				humanoid:EquipTool(tool)
				local deadline = os.clock() + 1.5
				repeat task.wait(0.05) until tool.Parent == character or not active() or os.clock() >= deadline
				if tool.Parent == character and active() then
					local decreasedAt, lastCount
					local function confirmed()
						if not active() then return false end
						local count = self:CountItem(name)
						if count < before then
							if count ~= lastCount then decreasedAt, lastCount = os.clock(), count end
							return decreasedAt ~= nil and os.clock() - decreasedAt >= 0.6
						end
						decreasedAt, lastCount = nil, count
						return false
					end
					-- Exact readable Xenon V3 sell request. Current builds can open a quantity UI.
					if self:GetItemSellGui() then self:TraceItemSale("foreign_dialogue", "A dialogue opened before the sell request; leaving it untouched.") return end
					self:TraceItemSale("direct", "Xenon Merchant/Dialogue5/Option1")
					remote:FireServer("EndDialogue", { NPC = "Merchant", Option = "Option1", Dialogue = "Dialogue5" })
					deadline = os.clock() + 1.2
					repeat task.wait(0.05) until confirmed() or not active() or os.clock() >= deadline
					local responseGui = self:GetItemSellGui()
					if active() and (not confirmed() or responseGui) then
						self:CompleteMerchantSale(before, confirmed, active, responseGui)
					end
					if active() and confirmed() then
						-- The count, not GUI closure or a disappearing/replaced Tool, is the receipt.
						sold += math.max(before - self:CountItem(name), 0)
						self:TraceItemSale("confirmed", name .. "; before=" .. before .. "; after=" .. self:CountItem(name))
						self.ItemSellFailures[name] = nil
					elseif active() then
						rejected += 1
						self:TraceItemSale("unconfirmed", name .. "; before=" .. before .. "; after=" .. self:CountItem(name))
						self.ItemSellFailures[name] = { Count = self:CountItem(name), Until = os.clock() + 30 }
					end
				elseif active() then
					rejected += 1
					self.ItemSellFailures[name] = { Count = self:CountItem(name), Until = os.clock() + 30 }
				end
			end
		end
	end)
	self.ItemSellBusy = false
	if not ok then self:TraceItemSale("error", reason) warn("[TheBest/ItemSell] " .. tostring(reason)) end
	if not active() then self:TraceItemSale("cancelled", "Character changed, died, or Auto Sell was disabled.") end
	if attempted == 0 then self:TraceItemSale("idle", "No selected sellable items, or automatic retry cooldown.") end
	if not automatic and active() then
		if sold > 0 then notify("Item Sell", "Confirmed sold: " .. sold .. (rejected > 0 and "; refused: " .. rejected or "") .. ".", 4)
		elseif rejected > 0 or not ok then notify("Item Sell", "Sale not confirmed: the inventory did not decrease.", 5)
		elseif attempted == 0 then notify("Item Sell", "No selected sellable tools are currently in your inventory.", 4) end
	end
	local completed = ok and active() and sold > 0
	movement.Release(saleLease)
	return completed
end

