				for _, connection in ipairs(connections) do
					local succeeded = pcall(function()
						if type(connection.Fire) == "function" then connection:Fire(); fired = true
						elseif type(connection.Function) == "function" then connection.Function(); fired = true end
					end)
					if not succeeded then fired = false end
