				if fired then return true end
			end
		end
		return false
	end
	function runtime:ResolveDialogue(name)
		local wanted = normalize(name)
		local modules = replicatedStorage:FindFirstChild("Dialogue")
		if wanted == "" or not modules then return nil end
		for _, parent in ipairs({ workspace, replicatedStorage }) do
			local folder = parent:FindFirstChild("Dialogues")
			if folder then
				for _, npc in ipairs(folder:GetChildren()) do
					local value = npc:FindFirstChild("Dialogue")
					local id = value and value:IsA("StringValue") and value.Value
