			local function queueAutoPrestigeResume()
				local environment = type(getgenv) == "function" and getgenv() or _G
				if environment.TheBestAutoPrestigeQueued then
					return true
				end
				local queue = rawget(environment, "queue_on_teleport")
					or rawget(environment, "queueonteleport")
				local synApi = rawget(environment, "syn")
				local fluxusApi = rawget(environment, "fluxus")
				if type(queue) ~= "function" and type(synApi) == "table" then
					queue = synApi.queue_on_teleport
				end
				if type(queue) ~= "function" and type(fluxusApi) == "table" then
					queue = fluxusApi.queue_on_teleport
				end
				if type(queue) ~= "function" then
					return false
				end
				local succeeded = pcall(queue, AUTO_PRESTIGE_RESUME_SOURCE)
				if succeeded then
					environment.TheBestAutoPrestigeQueued = true
				end
				return succeeded
			end

			function controller:SetAutoPrestige(enabled)
