                local merchantClick = (function(button, attempt)
    if not button or not button.Parent then return false, "missing button" end
    local signalName = attempt == 3 and "Activated" or "MouseButton1Click"
    local signal = button[signalName]
    if not signal then return false, signalName .. " unavailable" end
    local function connections()
        if type(getconnections) ~= "function" then return false end
        local read, list = pcall(getconnections, signal)
        if not read or type(list) ~= "table" then return false end
        local count = 0
        for _, connection in ipairs(list) do
            local sent = false
            pcall(function()
                if connection.Enabled ~= false and connection.Connected ~= false then
                    if type(connection.Fire) == "function" then sent = pcall(function() connection:Fire() end)
                    elseif type(connection.Function) == "function" then sent = pcall(connection.Function) end
                end
            end)
            if sent then count += 1 end
        end
        return count > 0
    end
    if attempt ~= 2 and connections() then return true, signalName .. "/callbacks" end
    if type(firesignal) == "function" then
        local sent = pcall(firesignal, signal)
        if sent then return true, signalName .. "/firesignal; awaiting transition" end
    end
    if attempt == 2 and connections() then return true, signalName .. "/callbacks" end
    return false, signalName .. "/no callable handler"
