            if object:IsA("GuiButton") and adapter.Visible(object, gui) then
                local text, name = normalized(textOf(object)), normalized(object.Name)
                if rejected(text) or name == "cancel" or name == "close" or name == "exit" then
                    exit = exit or object
                elseif text ~= "" then
                    local quantity = tonumber(text:match("%((%d+)%)") or text:match("^%s*(%d+)%s*$")
                        or text:match("sell%s+(%d+)") or text:match("(%d+)%s+items?"))
                    if text:find("sell all", 1, true) or text:find("all of these", 1, true) then all = all or object
                    elseif quantity then
                        if quantity > 0 and quantity <= available and (not numeric or quantity > numeric.Quantity) then
                            numeric = { Button = object, Quantity = quantity }
                        end
                    elseif text == "deal" or text:match("^deal[%s%p]*$") or text == "yes" or text:match("^yes[%s%p]") or text == "confirm" or text == "sell"
                        or (text:find("sell", 1, true) and not text:find("buy", 1, true)) then
