				local horse = self:GetHorse()
				local horseRoot = horse and (horse.PrimaryPart or horse:FindFirstChild("HumanoidRootPart"))
				local seat = horse and horse:FindFirstChild("Seat", true)
				if not targetHumanoid or not targetRoot or not horseRoot or not seat or not seat:IsA("Seat") then
					return false
				end
				for _ = 1, 10 do
					task.wait(0.1)
					if not targetRoot.Parent or not horseRoot.Parent then return false end
					horseRoot.CFrame = targetRoot.CFrame
				end
				if seat.Occupant ~= targetHumanoid then
					return false
				end
				task.wait(0.5)
				horseRoot.CFrame += Vector3.new(0, -155, 0)
				task.wait(2)
				if seat.Parent then seat:Destroy() end
				return true
			end

			local function waitForMissing(loopName, generation, parent, childName)
				while loopCurrent(loopName, generation) do
					if loopName == "AutoSBR" and not movement.Renew(controller.AutoSbrLease, 1) then return false end
					if not parent or not parent:FindFirstChild(childName) then
						return true
					end
					task.wait(0.1)
				end
				return false
			end
			function controller:SetSbrAuto(enabled)
				_G.Config.xenonSbrAuto = enabled == true
				stopLoop("AutoSBR")
				movement.Cancel("AutoSBR")
				self.AutoSbrLease = nil
				if enabled and game.PlaceId == 4643697430 then
					local generation = (self.Loops.AutoSBR or 0) + 1
					self.Loops.AutoSBR = generation
					task.spawn(function()
						local teleports = self:GetSbrTeleports()
						local _, _, playerRoot = getCharacter()
						local horse = self:GetHorse()
						local root = _G.Config.xenonSbrUseHorse and horse
							and (horse.PrimaryPart or horse:FindFirstChild("HumanoidRootPart")) or playerRoot
						if not root or not teleports["Normal Hide"] then return end
						local lease
						repeat
							if not loopCurrent("AutoSBR", generation) or not root.Parent then return end
							lease = movement.Claim("AutoSBR", root, "AutoSBR", 1)
							if not lease then task.wait(0.1) end
						until lease
						self.AutoSbrLease = lease
						if not movement.Write(lease, teleports["Normal Hide"]) then return end
						local barrier = workspace:FindFirstChild("Barrier")
						if not waitForMissing("AutoSBR", generation, barrier, "StartBarrier") then return end
						for stage = 1, 3 do
							if not waitCurrent("AutoSBR", generation, _G.Config["xenonSbrDelay" .. stage]) then return end
							if not movement.Write(lease, teleports["Stage " .. stage .. " Barrier"]) then return end
							if not waitCurrent("AutoSBR", generation, _G.Config.xenonSbrHideDelay) then return end
							if not movement.Write(lease, teleports["Normal Hide"]) then return end
							if not waitForMissing("AutoSBR", generation, workspace:FindFirstChild("Barriers"), tostring(stage)) then return end
						end
						if not waitCurrent("AutoSBR", generation, _G.Config.xenonSbrDelay4) then return end
						if not movement.Write(lease, teleports["Stage 4 Barrier"]) then return end
						if not waitCurrent("AutoSBR", generation, _G.Config.xenonSbrHideDelay) then return end
						local barriers = workspace:FindFirstChild("Barriers")
						while loopCurrent("AutoSBR", generation) and movement.Renew(lease, 1) and barriers and barriers:FindFirstChild("4") do
							if not movement.Write(lease, teleports["Finish Hide"]) then return end
							task.wait(0.1)
						end
						if not waitCurrent("AutoSBR", generation, _G.Config.xenonSbrDelay5) then return end
						if not movement.Write(lease, teleports["Stage 4 Barrier"]) then return end
						if not waitCurrent("AutoSBR", generation, _G.Config.xenonSbrHideDelay) then return end
						if not movement.Write(lease, teleports["Finish Hide"]) then return end
					end)
				end
				save()
			end

			local barrierState = setmetatable({}, { __mode = "k" })
			function controller:SetSbrBarrierNoclip(enabled)
				_G.Config.xenonSbrBarrierNoclip = enabled == true
				for _, folderName in ipairs({ "Barrier", "Barriers" }) do
					local folder = workspace:FindFirstChild(folderName)
					if folder then
						for _, part in ipairs(folder:GetDescendants()) do
							if part:IsA("BasePart") then
								if enabled then
									if barrierState[part] == nil then barrierState[part] = part.CanCollide end
									part.CanCollide = false
								elseif barrierState[part] ~= nil then
									part.CanCollide = barrierState[part]
									barrierState[part] = nil
								end
							end
						end
					end
				end
				save()
			end

			table.insert(controller.Connections, workspace.DescendantAdded:Connect(function(object)
				if object:IsA("ProximityPrompt") then
					task.defer(function()
						if object.Parent and (_G.Config.xenonItemEsp or _G.Config.xenonItemFarm) then
							addItemPrompt(object)
						end
					end)
				end
			end))
			table.insert(controller.Connections, workspace.DescendantRemoving:Connect(function(object)
				if object:IsA("ProximityPrompt") and controller.ItemEntries[object] then
					destroyItemEntry(object)
				end
			end))
			table.insert(controller.Connections, XPlayers.PlayerAdded:Connect(function()
				task.defer(function()
					if controller.RefreshDynamicDropdowns then controller.RefreshDynamicDropdowns() end
				end)
			end))
			table.insert(controller.Connections, XPlayers.PlayerRemoving:Connect(function()
				task.defer(function()
					if controller.RefreshDynamicDropdowns then controller.RefreshDynamicDropdowns() end
				end)
			end))
			table.insert(controller.Connections, XLocalPlayer.OnTeleport:Connect(function(state)
				if state == Enum.TeleportState.Started or state == Enum.TeleportState.InProgress then
					_G.Config.xenonSpawnpoint, _G.Config.xenonSpawnpointName = false, false
					save()
				end
			end))
			table.insert(controller.Connections, XLocalPlayer.CharacterAdded:Connect(function(character)
				local savedSpawnpoint = deserializeCFrame(_G.Config.xenonSpawnpoint)
				if not savedSpawnpoint then
					return
				end
				task.spawn(function()
					local humanoid = character:FindFirstChildOfClass("Humanoid")
						or character:WaitForChild("Humanoid", 8)
					local root = character:FindFirstChild("HumanoidRootPart")
						or character:WaitForChild("HumanoidRootPart", 8)
					task.wait(0.15)
					if character ~= XLocalPlayer.Character
						or not humanoid
						or humanoid.Health <= 0
						or not root
						or not root.Parent
					then
						return
					end
					local currentSpawnpoint = deserializeCFrame(_G.Config.xenonSpawnpoint)
					if currentSpawnpoint then
						local lease = movement.Claim("Manual", root, "Manual", 0.4)
						if not lease or not movement.Write(lease, currentSpawnpoint) then return end
						root.AssemblyLinearVelocity = Vector3.zero
						root.AssemblyAngularVelocity = Vector3.zero
					end
				end)
			end))
			table.insert(controller.Connections, living.ChildAdded:Connect(function()
				task.defer(function()
					if controller.RefreshDynamicDropdowns then controller.RefreshDynamicDropdowns() end
				end)
			end))
			table.insert(controller.Connections, living.ChildRemoved:Connect(function()
				task.defer(function()
					if controller.RefreshDynamicDropdowns then controller.RefreshDynamicDropdowns() end
				end)
			end))
			local heartbeatElapsed = 0
			table.insert(controller.Connections, XRunService.Heartbeat:Connect(function(deltaTime)
				heartbeatElapsed += deltaTime
				if heartbeatElapsed < 0.1 then
					return
				end
				heartbeatElapsed = 0
				updateItemEspDistances()
				if _G.Config.xenonNoFog then
					XLighting.FogStart = 1000000
					XLighting.FogEnd = 1000000
				end
				if not lightingGuard then
					lightingGuard = true
					if _G.Config.xenonAlwaysNight then
						XLighting.ClockTime = 0
					elseif _G.Config.xenonAlwaysDay then
						XLighting.ClockTime = 12
					end
					lightingGuard = false
				end
				local character, humanoid, root = getCharacter()
				if _G.Config.xenonNoClip and character then
					setCharacterNoclip(character, true)
				end
				if _G.Config.xenonStealMoney and root then
					for _, object in ipairs(workspace:GetChildren()) do
						if object:IsA("BasePart") and object.Name == "Money" then
							object.CFrame = root.CFrame
						end
					end
				end
				if _G.Config.xenonHideOwnName or _G.Config.xenonHideAllNames then
					applyHiddenNames()
				end
				if _G.Config.xenonStandAttach and character and root then
					local target = living:FindFirstChild(tostring(_G.Config.xenonStandAttachTarget or ""))
					local targetRoot = target and (target.PrimaryPart or target:FindFirstChild("HumanoidRootPart"))
					local stand = character:FindFirstChild("StandMorph")
					local standRoot = stand and (stand.PrimaryPart or stand:FindFirstChild("HumanoidRootPart"))
					if targetRoot and standRoot and movement.Claim("StandAttach", root, "StandAttach", 0.25) then
						local prediction = targetRoot.AssemblyLinearVelocity * math.clamp(tonumber(_G.Config.xenonPredictionStrength) or 0.5, 0, 0.5)
						local targetPosition
						if prediction.Magnitude > 0.01 then
							targetPosition = targetRoot.Position + prediction
						else
							targetPosition = (targetRoot.CFrame + targetRoot.CFrame.LookVector
								* math.clamp(tonumber(_G.Config.xenonStandAttachDistance) or 2.5, 0, 3.5)).Position
						end
						standRoot.CFrame = CFrame.lookAt(targetPosition, targetRoot.Position)
						if _G.Config.xenonFollowStand then
							root.CFrame = standRoot.CFrame - Vector3.new(0, 25, 0)
						end
						if _G.Config.xenonViewStand then
							local focus = character:FindFirstChild("FocusCam")
							if not focus then
								focus = Instance.new("ObjectValue")
								focus.Name = "FocusCam"
								focus:SetAttribute("TheBestCreated", true)
								focus.Parent = character
							end
							if focus:IsA("ObjectValue") then focus.Value = targetRoot end
						end
					end
				end
				if game.PlaceId == 4643697430 then
					local horse = controller:GetHorse()
					local horseHumanoid = horse and horse:FindFirstChildOfClass("Humanoid")
					if horseHumanoid then
						horseHumanoid.WalkSpeed = tonumber(_G.Config.xenonHorseWalkSpeed) or horseHumanoid.WalkSpeed
						horseHumanoid.JumpPower = tonumber(_G.Config.xenonHorseJumpPower) or horseHumanoid.JumpPower
					end
				end
			end))

			local function cleanup()
				farmRuntime:Cleanup()
				local destroyMapDesired = _G.Config.xenonDestroyMap
				local barrierNoclipDesired = _G.Config.xenonSbrBarrierNoclip
				for name in pairs(controller.Loops) do
					stopLoop(name)
				end
				for _, connection in ipairs(controller.Connections) do
					pcall(function() connection:Disconnect() end)
				end
				table.clear(controller.Connections)
				clearItemEsp()
				setCharacterNoclip(XLocalPlayer.Character, false)
				restoreHiddenNames()
				restoreStandAttachFocus()
				controller:SetDestroyMap(false)
				controller:SetSbrBarrierNoclip(false)
				_G.Config.xenonDestroyMap = destroyMapDesired
				_G.Config.xenonSbrBarrierNoclip = barrierNoclipDesired
				save()
				controller:StopAnimation()
				destroyCoinCounter()
				if fogSnapshot then
					XLighting.FogStart = fogSnapshot.Start
					XLighting.FogEnd = fogSnapshot.Finish
					fogSnapshot = nil
				end
			end
			_G.TheBestNpcFarmCameraStop = function() farmRuntime:ReleaseNpcCamera(true) end
			controller.Cleanup = cleanup
			_G.TheBestXenonIntegrationCleanup = cleanup
			clearItemEsp()
			if _G.Config.xenonItemEsp or _G.Config.xenonItemFarm then
				scanItemPrompts()
			end
			return controller
		end)()
