			local infoElapsed = 0
			table.insert(xenon.Connections, game:GetService("RunService").Heartbeat:Connect(function(deltaTime)
				infoElapsed += deltaTime
				if infoElapsed < 1 then return end
				infoElapsed = 0
				standInfoLabel.SetText("Stand: " .. xenon.GetStandName())
				pityInfoLabel.SetText("Pity: " .. tostring(xenon.GetPity()))
				shinyInfoLabel.SetText("Shiny: " .. xenon.GetShinyName())
			end))
		end
		do
			local HitboxPlayers = game:GetService("Players")
			local HitboxRunService = game:GetService("RunService")
			local hitboxLocalPlayer = HitboxPlayers.LocalPlayer
			local function normalizeHitboxSize(value)
				local number = tonumber(value)
				if not number or number ~= number or number == math.huge or number == -math.huge then
					return nil
				end
				number = math.clamp(number, 1, 1000000)
				return math.floor(number * 100 + 0.5) / 100
			end
			local hitboxSize = normalizeHitboxSize(_G.Config.hitboxSize) or 1000000
			local hitboxVisible = _G.Config.showHitbox == true
			_G.Config.hitboxSize = hitboxSize
			local selectedPlayerName = nil
			local selectedHitboxEnabled = _G.Config.selectedPlayerHitboxEnabled == true
			local allHitboxesEnabled = _G.Config.allPlayersHitboxEnabled == true
			local touchedPlayers = setmetatable({}, { __mode = "k" })
			local rootSnapshots = setmetatable({}, { __mode = "k" })
			local activeHitboxSizes = setmetatable({}, { __mode = "k" })
			local desiredHitboxPlayers = setmetatable({}, { __mode = "k" })
			local hitboxDropdown = nil
			local hitboxWhitelistDropdown = nil
			local whitelistedPlayerNames = {}
			local currentPlayerNames = {}
			local currentPlayerListKey = ""
			local hitboxConnections = {}
			if type(_G.Config.hitboxWhitelist) == "table" then
				for _, name in ipairs(_G.Config.hitboxWhitelist) do
					if type(name) == "string" and name ~= "" then
						whitelistedPlayerNames[name] = true
					end
				end
			end

			if _G.TheBestHitboxManagerCleanup then
				pcall(_G.TheBestHitboxManagerCleanup)
			end

			local function collectPlayerNames()
				local names = {}
				for _, player in ipairs(HitboxPlayers:GetPlayers()) do
					if player ~= hitboxLocalPlayer then
						table.insert(names, player.Name)
					end
				end
				table.sort(names, function(left, right)
					return string.lower(left) < string.lower(right)
				end)
				return names
			end

			local function containsName(names, targetName)
				if not targetName then
					return false
				end
				for _, name in ipairs(names) do
					if name == targetName then
						return true
					end
				end
				return false
			end

			local function getPlayerRoot(player)
				if not player or player == hitboxLocalPlayer then
					return nil
				end

				local character = player.Character
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")
				local root = humanoid and humanoid.RootPart
				if root and root:IsA("BasePart") then
					return root
				end
				return nil
			end

			local function removeLegacyHitboxProxies(character)
				if not character then
					return
				end
				for _, child in ipairs(character:GetChildren()) do
					if child:IsA("BasePart") and child:GetAttribute("TheBestHitboxProxy") == true then
						child:Destroy()
					end
				end
			end

			local function restoreRoot(root)
				local snapshot = rootSnapshots[root]
				rootSnapshots[root] = nil
				activeHitboxSizes[root] = nil
				if not snapshot or not root or not root.Parent then
					return
				end
				pcall(function()
					root.Size = snapshot.Size
					root.Transparency = snapshot.Transparency
					root.CanCollide = snapshot.CanCollide
				end)
			end

			local function destroyPlayerHitbox(player)
				local root = touchedPlayers[player]
				touchedPlayers[player] = nil
				if root then
					restoreRoot(root)
				end
				removeLegacyHitboxProxies(player and player.Character)
			end

			local function captureRoot(root)
				if not rootSnapshots[root] then
					rootSnapshots[root] = {
						Size = root.Size,
						Transparency = root.Transparency,
						CanCollide = root.CanCollide,
					}
				end
				return rootSnapshots[root]
			end

			local function pointIsInsideHitbox(root, worldPoint, size)
				local offset = root.CFrame:PointToObjectSpace(worldPoint)
				local halfSize = size * 0.5
				return math.abs(offset.X) <= halfSize
					and math.abs(offset.Y) <= halfSize
					and math.abs(offset.Z) <= halfSize
			end

			local function localPlayerIsInsideHitbox(root, size)
				local character = hitboxLocalPlayer.Character
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")
				local localRoot = humanoid and humanoid.RootPart
				if localRoot and pointIsInsideHitbox(root, localRoot.Position, size) then
					return true
				end

				local camera = workspace.CurrentCamera
				return camera ~= nil and pointIsInsideHitbox(root, camera.CFrame.Position, size)
			end

			local function getActiveHitboxSize(root)
				if hitboxSize > 100 then
					return hitboxSize
				end
				local nearSize = math.min(7, hitboxSize)
				local innerSize = math.min(3, hitboxSize)
				if localPlayerIsInsideHitbox(root, nearSize) then
					return innerSize
				end
				if localPlayerIsInsideHitbox(root, hitboxSize) then
					return nearSize
				end
				return hitboxSize
			end

			local function updateRootState(root, force)
				local activeSize = getActiveHitboxSize(root)
				if not force and activeHitboxSizes[root] == activeSize then
					return
				end
				captureRoot(root)
				activeHitboxSizes[root] = activeSize
				pcall(function()
					-- Infinite Yield's hitbox mechanic changes the real HumanoidRootPart.
					root.CanCollide = false
					root.Size = Vector3.new(activeSize, activeSize, activeSize)
					root.Transparency = hitboxVisible and 0.4 or 1
				end)
			end

			local function setPlayerHitbox(player, enabled, force)
				if not enabled then
					destroyPlayerHitbox(player)
					return
				end

				local root = getPlayerRoot(player)
				if not root then
					return
				end
				local previousRoot = touchedPlayers[player]
				if previousRoot and previousRoot ~= root then
					restoreRoot(previousRoot)
				end
				removeLegacyHitboxProxies(player.Character)
				touchedPlayers[player] = root
				updateRootState(root, force == true or previousRoot ~= root)
			end

			local function applyCurrentHitboxes()
				local desiredPlayers = setmetatable({}, { __mode = "k" })
				if allHitboxesEnabled then
					for _, player in ipairs(HitboxPlayers:GetPlayers()) do
						if player ~= hitboxLocalPlayer and not whitelistedPlayerNames[player.Name] then
							desiredPlayers[player] = true
						end
					end
				end
				if selectedHitboxEnabled and selectedPlayerName then
					local selectedPlayer = HitboxPlayers:FindFirstChild(selectedPlayerName)
					if selectedPlayer and selectedPlayer ~= hitboxLocalPlayer then
						desiredPlayers[selectedPlayer] = true
					end
				end

				local playersToRestore = {}
				for player in pairs(touchedPlayers) do
					if not desiredPlayers[player] then
						table.insert(playersToRestore, player)
					end
				end
				for _, player in ipairs(playersToRestore) do
					setPlayerHitbox(player, false)
				end

				for player in pairs(desiredPlayers) do
					setPlayerHitbox(player, true, true)
				end
				desiredHitboxPlayers = desiredPlayers
			end

			local function getVisibleWhitelist(playerNames)
				local visibleNames = {}
				for _, name in ipairs(playerNames) do
					if whitelistedPlayerNames[name] then
						table.insert(visibleNames, name)
					end
				end
				return visibleNames
			end

			local function setHitboxWhitelist(values)
				local newWhitelist = {}
				if type(values) ~= "table" then
					values = { values }
				end
				for _, name in ipairs(values) do
					if type(name) == "string" and name ~= "" and name ~= "None" then
						newWhitelist[name] = true
					end
				end
				whitelistedPlayerNames = newWhitelist

				local savedNames = {}
				for name in pairs(whitelistedPlayerNames) do
					table.insert(savedNames, name)
				end
				table.sort(savedNames, function(left, right)
					return string.lower(left) < string.lower(right)
				end)
				_G.Config.hitboxWhitelist = savedNames
				applyCurrentHitboxes()
				SaveConfig()
			end

			currentPlayerNames = collectPlayerNames()
			currentPlayerListKey = table.concat(currentPlayerNames, "\0")
			selectedPlayerName = currentPlayerNames[1]

			local hitboxSection = _G.TheBestFunctionSections.hitboxes
			local hitboxPresetValues = {
				["35"] = true,
				["40"] = true,
				["45"] = true,
				["50"] = true,
				["1000000"] = true,
			}
			local hitboxPresetDropdown = nil
			local customHitboxInput = nil
			local syncingHitboxControls = false
			local function applyHitboxSize(newSize)
				hitboxSize = newSize
				_G.Config.hitboxSize = newSize
				applyCurrentHitboxes()
				SaveConfig()
			end
			local initialPreset = tostring(hitboxSize)
			if not hitboxPresetValues[initialPreset] then
				initialPreset = "Custom"
			end
			hitboxPresetDropdown = Library:CreateDropdown(
				hitboxSection,
				"Hitbox Size Preset",
				{ "35", "40", "45", "50", "1000000", "Custom" },
				initialPreset,
				false,
				function(value)
					if syncingHitboxControls or value == "Custom" then
						return
					end
					local newSize = normalizeHitboxSize(value)
					if not newSize then
						return
					end
					applyHitboxSize(newSize)
					if customHitboxInput then
						customHitboxInput.SetValue(tostring(newSize), false)
					end
				end,
				true,
				true
			)
			customHitboxInput = Library:CreateTextInput(
