		do
			if type(_G.TheBestAutoParryRadiusCleanup) == "function" then
				pcall(_G.TheBestAutoParryRadiusCleanup)
			end
			local radiusPlayers = game:GetService("Players")
			local radiusRunService = game:GetService("RunService")
			local radiusPlayer = radiusPlayers.LocalPlayer
			local holder, lastRadius
			local arcs = {}
			local radiusConnections = {}
			local stopped = false
			local quarterHandle = 0.5522847498307936
			local domeColor = ColorSequence.new(Color3.fromRGB(255, 58, 70))
			local function clearDome()
				if holder then holder:Destroy() end
				holder, lastRadius = nil, nil
				table.clear(arcs)
			end
			local function addArc(center, axisU, axisV, circleRadius, startAngle, endAngle, base)
				local normal = axisU:Cross(axisV).Unit
				local function frameAt(angle)
					local point = center + (axisU * math.cos(angle) + axisV * math.sin(angle)) * circleRadius
					local tangent = -axisU * math.sin(angle) + axisV * math.cos(angle)
					return CFrame.fromMatrix(point, tangent, normal:Cross(tangent))
				end
				local first = Instance.new("Attachment")
				first.Name = "RadiusArcStart"
				first.Parent = holder
				local last = Instance.new("Attachment")
				last.Name = "RadiusArcEnd"
				last.Parent = holder
				local beam = Instance.new("Beam")
				beam.Name = base and "RadiusRim" or "RadiusDomeArc"
				beam.Attachment0, beam.Attachment1 = first, last
				beam.Color = domeColor
				beam.Transparency = NumberSequence.new(base and 0.15 or 0.45)
				beam.Width0, beam.Width1 = base and 0.10 or 0.055, base and 0.10 or 0.055
				beam.FaceCamera = true
				beam.LightEmission = 1
				beam.LightInfluence = 0
				beam.Segments = 16
				beam.Parent = holder
				table.insert(arcs, {
					first = first, last = last, beam = beam,
					firstFrame = frameAt(startAngle), lastFrame = frameAt(endAngle),
					handle = circleRadius * quarterHandle,
				})
			end
			local function createDome()
				holder = Instance.new("Part")
				holder.Name = "TheBestAutoParryRadius"
				holder:SetAttribute("TheBestOwned", true)
				holder.Anchored = true
				holder.CanCollide = false
				holder.CanTouch = false
				holder.CanQuery = false
				holder.CastShadow = false
				holder.Transparency = 1
				holder.Size = Vector3.new(0.05, 0.05, 0.05)
				holder.Parent = workspace
				-- Seven latitude rings span both hemispheres, including the brighter equator.
				for level = -3, 3 do
					local elevation = level * math.pi / 8
					local center = Vector3.new(0, math.sin(elevation), 0)
					local ringRadius = math.cos(elevation)
					for quadrant = 0, 3 do
						addArc(center, Vector3.xAxis, Vector3.zAxis, ringRadius,
							quadrant * math.pi / 2, (quadrant + 1) * math.pi / 2, level == 0)
					end
				end
				-- Four complete meridians span the full sphere.
				for meridian = 0, 3 do
					local angle = meridian * math.pi / 4
					local horizontal = Vector3.new(math.cos(angle), 0, math.sin(angle))
					for quarter = 0, 3 do
						addArc(Vector3.zero, horizontal, Vector3.yAxis, 1,
							quarter * math.pi / 2, (quarter + 1) * math.pi / 2, false)
					end
				end
			end
			local function scaleDome(radius)
				for _, arc in ipairs(arcs) do
					local firstFrame, lastFrame = arc.firstFrame, arc.lastFrame
					arc.first.CFrame = CFrame.new(firstFrame.Position * radius) * firstFrame.Rotation
					arc.last.CFrame = CFrame.new(lastFrame.Position * radius) * lastFrame.Rotation
					arc.beam.CurveSize0 = arc.handle * radius
					arc.beam.CurveSize1 = arc.handle * radius
				end
				lastRadius = radius
			end
			local function updateDome()
				if stopped then return end
				local config = _G.Config
				local character = radiusPlayer.Character
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")
				local root = character and (character:FindFirstChild("HumanoidRootPart")
					or character:FindFirstChild("UpperTorso") or character:FindFirstChild("Torso"))
				if not config or config.autoParryShowRadius ~= true or not root
					or (humanoid and humanoid.Health <= 0) then
					if holder then clearDome() end
					return
				end
				local radius = math.clamp(tonumber(config.autoParryRadius) or 20, 1, 50)
				if holder and not holder.Parent then clearDome() end
				if not holder then createDome() end
				if radius ~= lastRadius then scaleDome(radius) end
				-- Parry measures root-to-root distance, so retain that exact center and world-up orientation.
				holder.CFrame = CFrame.new(root.Position)
			end
			local cleanup
			cleanup = function()
				if stopped then return end
				stopped = true
				for _, connection in ipairs(radiusConnections) do connection:Disconnect() end
				table.clear(radiusConnections)
				clearDome()
				if _G.TheBestAutoParryRadiusCleanup == cleanup then
					_G.TheBestAutoParryRadiusCleanup = nil
				end
			end
			_G.TheBestAutoParryRadiusCleanup = cleanup
			table.insert(radiusConnections, radiusRunService.RenderStepped:Connect(updateDome))
			local radiusGui = activeMainUI and activeMainUI.ScreenGui
			if radiusGui then
				table.insert(radiusConnections, radiusGui.Destroying:Connect(cleanup))
			end
			updateDome()
		end
		local Players = game:GetService("Players")
		local LocalPlayer = Players.LocalPlayer
		function events()
