			end

			teleportPlayerNames = collectTeleportPlayerNames()
			teleportPlayerListKey = table.concat(teleportPlayerNames, "\0")
			if containsTeleportPlayerName(teleportPlayerNames, _G.Config.input_TargetSurvName) then
