						for _, npc in ipairs(living:GetChildren()) do
							if npc:IsA("Model") and Players:GetPlayerFromCharacter(npc) == nil and isValidTarget(npc) then
								duplicateCounts[npc.Name] = (duplicateCounts[npc.Name] or 0) + 1
								local suffix = duplicateCounts[npc.Name] > 1 and (" #" .. duplicateCounts[npc.Name]) or ""
								table.insert(entries, { display = npc.Name .. " [NPC]" .. suffix, target = npc })
							end
						end
					end
				end
				table.sort(entries, function(left, right)
					return string.lower(left.display) < string.lower(right.display)
				end)
				return entries
			end

			local function displayForTarget(target)
