		do
			if type(_G.TheBestAutoPlayerCleanup) == "function" then
				pcall(_G.TheBestAutoPlayerCleanup)
			end
			local input = game:GetService("VirtualInputManager")
			local userInput = game:GetService("UserInputService")
			local enabled = false
			local pendingKey, prepareAt = nil, 0
			local resumeMouseAt = 0
			local held = {}
			local connections = {}
			local nextClick, nextR, nextE = 0, 0, 0
			local control
			local menuFrame = activeMainUI and activeMainUI.Frame
			local menuGui = activeMainUI and activeMainUI.ScreenGui
			local function menuIsOpen()
				return menuFrame and menuFrame.Parent and menuGui and menuGui.Parent
					and menuFrame.Visible and menuGui.Enabled
			end
			local function send(key, down)
				if key == "Mouse" then
					local camera = workspace.CurrentCamera
					local point = camera and camera.ViewportSize or Vector2.new(800, 600)
					input:SendMouseButtonEvent(point.X / 2, point.Y / 2, 0, down, game, 1)
				else
					input:SendKeyEvent(down, Enum.KeyCode[key], false, game)
				end
			end
			local function release()
				for key in pairs(held) do
					if pcall(send, key, false) then held[key] = nil end
				end
			end
			local function resetTimers()
				local now = os.clock()
				nextClick, nextR, nextE = now, now + 7, now + 12
				pendingKey, prepareAt, resumeMouseAt = nil, 0, 0
			end
			local function setEnabled(value)
				enabled = value == true
				release()
				resetTimers()
			end
			control = Library:CreateToggle(pilotSection, "AutoPlayer", false, setEnabled)
			Library.StopAutoPlayerForMenu = function()
				setEnabled(false)
				control.SetState(false)
			end
			-- Arming with the menu open sends no input. Reopening cancels the run.
			local function menuVisibilityChanged()
				if menuIsOpen() then
					setEnabled(false)
					control.SetState(false)
				else
					resetTimers()
				end
			end
			if menuFrame then
				table.insert(connections, menuFrame:GetPropertyChangedSignal("Visible"):Connect(menuVisibilityChanged))
			end
			if menuGui then
				table.insert(connections, menuGui:GetPropertyChangedSignal("Enabled"):Connect(menuVisibilityChanged))
			end
			-- Focus changes do not stop automation; input stays inside Roblox.
			table.insert(connections, game:GetService("RunService").Heartbeat:Connect(function()
				if not enabled or menuIsOpen() or userInput:GetFocusedTextBox() then
					release()
					resetTimers()
					return
				end
				local ok, err = pcall(function()
					local now = os.clock()
					for key, deadline in pairs(held) do
						if now >= deadline then
							send(key, false)
							held[key] = nil
							if key ~= "Mouse" then resumeMouseAt = now + 0.4 end
						end
					end
					-- Skills are serialized, with a quiet gap before and after each.
					if held.R or held.E then return end
					if now < resumeMouseAt then return end
					if pendingKey then
						if now < prepareAt then return end
						local key = pendingKey
						pendingKey = nil
						local duration = key == "E" and 3 or 0.15
						held[key] = now + duration
						send(key, true)
						resumeMouseAt = now + duration + 0.4
						if key == "E" then nextE = now + 12 else nextR = now + 7 end
						return
					end
					if now >= nextR or now >= nextE then
						if held.Mouse then
							send("Mouse", false)
							held.Mouse = nil
						end
						pendingKey = nextE <= nextR and "E" or "R"
						prepareAt = now + 0.6
						return
					end
					if now >= nextClick and not held.Mouse then
						held.Mouse = now + 0.03
						send("Mouse", true)
						nextClick = now + 0.1
					end
				end)
				if not ok then
					setEnabled(false)
					control.SetState(false)
					warn("[AutoPlayer] Input stopped: " .. tostring(err))
				end
			end))
			local function cleanup()
				setEnabled(false)
				for _, connection in ipairs(connections) do connection:Disconnect() end
				table.clear(connections)
				control.SetState(false)
			end
			_G.TheBestAutoPlayerCleanup = cleanup
			if menuGui then
				table.insert(connections, menuGui.Destroying:Connect(cleanup))
			end
		end
		local characterToolsSection = Library:CreateFunctionTab(tab_functions, "Character Tools")
		do
			local CharacterPlayers = game:GetService("Players")
			local CharacterRunService = game:GetService("RunService")
			local CharacterInputService = game:GetService("UserInputService")
			local CharacterReplicatedStorage = game:GetService("ReplicatedStorage")
			local CharacterPhysicsService = game:GetService("PhysicsService")
			local characterLocalPlayer = CharacterPlayers.LocalPlayer

			if _G.TheBestCharacterToolsCleanup then
				pcall(_G.TheBestCharacterToolsCleanup)
			end
			-- A surviving v6 cleanup may have cleared the shared v3 flags. Reapply policy without installing a hook.
			bypassRuntime.ApplyConfig(_G.Config)

			local managerConnections = {}
			local characterConnections = {}
			local invisibilityActive = false
			local invisibilityCharacter = nil
			local invisibilityHighlight = nil
			local internalCharacterSwap = false
			local internalCharacterSwapUntil = 0
			local classicPilotDesired = _G.Config.classicPilotEnabled == true
			local classicPilotActive = false
			local classicPilotRuntime = nil
			local classicPilotGeneration = 0
			local invisibilityToggleControl = nil
			local classicPilotToggleControl = nil
			local setInvisibilityEnabled
			local setClassicPilotEnabled

			local function disconnectConnections(connections)
				for _, connection in ipairs(connections) do
					pcall(function()
						connection:Disconnect()
					end)
				end
				table.clear(connections)
			end

			local function playFrozenInvisibilityAnimation(character)
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")
				if not humanoid then
					return nil
				end
				local animator = humanoid:FindFirstChildOfClass("Animator")
				if not animator then
					animator = Instance.new("Animator")
					animator.Parent = humanoid
				end
				local animation = Instance.new("Animation")
				animation.AnimationId = "rbxassetid://7189062263"
				local succeeded, track = pcall(function()
					return animator:LoadAnimation(animation)
				end)
				animation:Destroy()
				if not succeeded or not track then
					return nil
				end
				pcall(function()
					track.Priority = Enum.AnimationPriority.Action4
					track:Play(0)
					track:AdjustSpeed(0)
					track.TimePosition = 5
				end)
				return track
			end

			local function stopAndDestroyTrack(track)
				if not track then
					return
				end
				pcall(function()
					track:Stop(0)
					track:Destroy()
				end)
			end

			local function protectPlayerGui(playerGui)
				local state = {
					Vault = nil,
					Objects = {},
				}
				if not playerGui then
					return state
				end

				local coreGui = game:GetService("CoreGui")
				for _, oldVault in ipairs(coreGui:GetChildren()) do
					if oldVault:IsA("Folder") and oldVault.Name == "TheBestInvisibilityGuiVault" then
						for _, object in ipairs(oldVault:GetChildren()) do
							pcall(function()
								object.Parent = playerGui
							end)
						end
						if #oldVault:GetChildren() == 0 then
							oldVault:Destroy()
						end
					end
				end
				local vault = Instance.new("Folder")
				vault.Name = "TheBestInvisibilityGuiVault"
				vault.Parent = coreGui
				state.Vault = vault
				for _, object in ipairs(playerGui:GetChildren()) do
					local objectState = {
						Object = object,
						Parent = playerGui,
					}
					if object:IsA("LayerCollector") then
						objectState.Enabled = object.Enabled
					end
					if object:IsA("ScreenGui") then
						objectState.ResetOnSpawn = object.ResetOnSpawn
						object.ResetOnSpawn = false
					end
					table.insert(state.Objects, objectState)
					pcall(function()
						object.Parent = vault
					end)
				end
				return state
			end

			local function restoreProtectedPlayerGui(state)
				for _, objectState in ipairs(state and state.Objects or {}) do
					local object = objectState.Object
					if object then
						pcall(function()
							object.Parent = objectState.Parent
							if objectState.ResetOnSpawn ~= nil and object:IsA("ScreenGui") then
								object.ResetOnSpawn = objectState.ResetOnSpawn
							end
							if objectState.Enabled ~= nil and object:IsA("LayerCollector") then
								object.Enabled = objectState.Enabled
							end
						end)
					end
				end
				if state and state.Vault then
					if #state.Vault:GetChildren() == 0 then
						pcall(function()
							state.Vault:Destroy()
						end)
					end
				end
			end

			local function suspendCharacterSignals()
				local suspended = {}
				if type(getconnections) ~= "function" then
					return suspended
				end
				local signals = {
					characterLocalPlayer.CharacterAdded,
					characterLocalPlayer.CharacterRemoving,
					characterLocalPlayer:GetPropertyChangedSignal("Character"),
				}
				for _, signal in ipairs(signals) do
					local succeeded, connections = pcall(getconnections, signal)
					if succeeded and type(connections) == "table" then
						for _, connection in ipairs(connections) do
							local canDisable = type(connection.Disable) == "function"
							local canEnable = type(connection.Enable) == "function"
							if canDisable and canEnable and connection.Enabled ~= false then
								local disabled = pcall(function()
									connection:Disable()
								end)
								if disabled then
									table.insert(suspended, connection)
								end
							end
						end
					end
				end
				return suspended
			end

			local function resumeCharacterSignals(suspended)
				for _, connection in ipairs(suspended or {}) do
					pcall(function()
						connection:Enable()
					end)
				end
			end

			local function disableInvisibilityRuntime()
				local character = invisibilityCharacter or characterLocalPlayer.Character
				if invisibilityActive and character and character.Parent then
					local track = playFrozenInvisibilityAnimation(character)
					stopAndDestroyTrack(track)
				end
				if invisibilityHighlight then
					pcall(function()
						invisibilityHighlight:Destroy()
					end)
					invisibilityHighlight = nil
				end
				invisibilityActive = false
				invisibilityCharacter = nil
			end

			local function enableInvisibilityRuntime()
				local character = characterLocalPlayer.Character
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")
				if not character or not humanoid or humanoid.Health <= 0 then
					return false, "Character is not ready"
				end
				if invisibilityActive and invisibilityCharacter == character then
					return true
				end
				disableInvisibilityRuntime()

				local playerGui = characterLocalPlayer:FindFirstChildOfClass("PlayerGui")
				local protectedGui = protectPlayerGui(playerGui)
				local suspendedSignals = suspendCharacterSignals()
				local track = nil
				invisibilityCharacter = character
				internalCharacterSwap = true
				internalCharacterSwapUntil = os.clock() + 0.75
				local succeeded, invisibilityError = xpcall(function()
					track = playFrozenInvisibilityAnimation(character)
					if not track then
						error("Unable to load invisibility animation")
					end
					characterLocalPlayer.Character = nil
					stopAndDestroyTrack(track)
					track = nil
					characterLocalPlayer.Character = character
				end, function(err)
					return tostring(err)
				end)
				pcall(function()
					if characterLocalPlayer.Character ~= character and character.Parent then
						characterLocalPlayer.Character = character
					end
				end)
				restoreProtectedPlayerGui(protectedGui)
				resumeCharacterSignals(suspendedSignals)
				stopAndDestroyTrack(track)
				internalCharacterSwap = false
				if not succeeded or not character.Parent then
					invisibilityCharacter = nil
					return false, invisibilityError
				end

				invisibilityHighlight = Instance.new("Highlight")
				invisibilityHighlight.Name = "TheBestInvisibilityHighlight"
				invisibilityHighlight.Enabled = true
				invisibilityHighlight.Parent = character
				invisibilityActive = true
				return true
			end

			local function getClassicPilotParts()
				local character = characterLocalPlayer.Character
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")
				local root = character and (character.PrimaryPart or character:FindFirstChild("HumanoidRootPart"))
				local standMorph = character and character:FindFirstChild("StandMorph")
				local standHumanoid = standMorph and standMorph:FindFirstChildOfClass("Humanoid")
				local standRoot = standMorph
					and (standMorph.PrimaryPart or standMorph:FindFirstChild("HumanoidRootPart") or standMorph:FindFirstChildWhichIsA("BasePart", true))
				if not character
					or not humanoid
					or humanoid.Health <= 0
					or not root
					or not standMorph
					or not standHumanoid
					or not standRoot
				then
					return nil
				end
				return character, humanoid, root, standMorph, standHumanoid, standRoot
			end

			local function restoreOrphanedPilotStorage()
				local storage = CharacterReplicatedStorage:FindFirstChild("TheBestPilotStorage")
				if not storage then
					return
				end
				local locations = workspace:FindFirstChild("Locations")
				if locations then
					for _, object in ipairs(storage:GetChildren()) do
						if object.Name == "Naples' Sewers" then
							object.Parent = locations
						end
					end
				end
				if #storage:GetChildren() == 0 then
					pcall(function()
						storage:Destroy()
					end)
				end
			end

			restoreOrphanedPilotStorage()

			local function cleanupClassicPilotRuntime(returnBody)
				local runtime = classicPilotRuntime
				classicPilotRuntime = nil
				classicPilotActive = false
				classicPilotGeneration += 1
				if not runtime then
					return
				end
				disconnectConnections(runtime.Connections)

				if runtime.StandHumanoid and runtime.StandHumanoid.Parent then
					pcall(function()
						runtime.StandHumanoid:Move(Vector3.zero, true)
						runtime.StandHumanoid.WalkSpeed = runtime.StandWalkSpeed
						runtime.StandHumanoid.JumpPower = runtime.StandJumpPower
					end)
				end
				for part, canCollide in pairs(runtime.CharacterCollisionState) do
					if part.Parent then
						pcall(function()
							part.CanCollide = canCollide
						end)
					end
				end
				for constraint, enabled in pairs(runtime.ConstraintState) do
					if constraint.Parent then
						pcall(function()
							constraint.Enabled = enabled
						end)
					end
				end
				for part, collisionGroup in pairs(runtime.StandCollisionState) do
					if part.Parent then
						pcall(function()
							part.CollisionGroup = collisionGroup
						end)
					end
				end
				if runtime.FocusCam then
					if runtime.CreatedFocusCam then
						pcall(function()
							runtime.FocusCam:Destroy()
						end)
					elseif runtime.FocusCam.Parent then
						pcall(function()
							runtime.FocusCam.Value = runtime.FocusCamValue
						end)
					end
				end
				local locations = workspace:FindFirstChild("Locations")
				if locations then
					for _, sewer in ipairs(runtime.StoredLocations) do
						if sewer.Parent then
							pcall(function()
								sewer.Parent = locations
							end)
						end
					end
				end
				if runtime.Storage and #runtime.Storage:GetChildren() == 0 then
					pcall(function()
						runtime.Storage:Destroy()
					end)
				end
				local root = runtime.Root
				if root and root.Parent then
					pcall(function()
						root.Anchored = runtime.RootAnchored
						if returnBody and runtime.Humanoid and runtime.Humanoid.Health > 0
							and _G.TheBestMovementRuntime.Current(runtime.MovementLease) then
							root.AssemblyLinearVelocity = Vector3.zero
							root.AssemblyAngularVelocity = Vector3.zero
							if _G.Config.classicPilotReturnToStand and runtime.StandRoot and runtime.StandRoot.Parent then
								root.CFrame = runtime.StandRoot.CFrame
							else
								root.CFrame = runtime.OriginalCFrame
							end
						end
					end)
				end
			end

			local function startClassicPilotRuntime()
				if classicPilotActive and classicPilotRuntime then
					return true
				end
				local character, humanoid, root, standMorph, standHumanoid, standRoot = getClassicPilotParts()
				if not character then
					return false
				end
				stopStandPilot()
				local lease = _G.TheBestMovementRuntime.Claim("ClassicPilot", root, "ClassicPilot", 0.25)
				if not lease then return false end
				classicPilotGeneration += 1
				local generation = classicPilotGeneration
				local runtime = {
					Character = character,
					Humanoid = humanoid,
					Root = root,
					StandMorph = standMorph,
					StandHumanoid = standHumanoid,
					StandRoot = standRoot,
					OriginalCFrame = root.CFrame,
					MovementLease = lease,
					RootAnchored = root.Anchored,
					StandWalkSpeed = standHumanoid.WalkSpeed,
					StandJumpPower = standHumanoid.JumpPower,
					CharacterCollisionState = setmetatable({}, { __mode = "k" }),
					StandCollisionState = setmetatable({}, { __mode = "k" }),
					ConstraintState = setmetatable({}, { __mode = "k" }),
					StoredLocations = {},
					Connections = {},
				}
				classicPilotRuntime = runtime
				classicPilotActive = true

				local storage = Instance.new("Folder")
				storage.Name = "TheBestPilotStorage"
				storage.Parent = CharacterReplicatedStorage
				runtime.Storage = storage
				local locations = workspace:FindFirstChild("Locations")
				if locations then
					for _, location in ipairs(locations:GetChildren()) do
						if location.Name == "Naples' Sewers" then
							table.insert(runtime.StoredLocations, location)
							location.Parent = storage
						end
					end
				end

				local focusCam = character:FindFirstChild("FocusCam")
				if focusCam and not focusCam:IsA("ObjectValue") then
					focusCam = nil
				end
				if focusCam then
					runtime.FocusCamValue = focusCam.Value
				else
					focusCam = Instance.new("ObjectValue")
					focusCam.Name = "FocusCam"
					focusCam.Parent = standMorph.Parent
					runtime.CreatedFocusCam = true
				end
				focusCam.Value = standHumanoid
				runtime.FocusCam = focusCam

				local function applyCharacterPart(part)
					if not part:IsA("BasePart") then
						return
					end
					if part:IsDescendantOf(standMorph) then
						return
					end
					if runtime.CharacterCollisionState[part] == nil then
						runtime.CharacterCollisionState[part] = part.CanCollide
					end
					part.CanCollide = false
				end

				local function applyStandObject(object)
					if object:IsA("AlignOrientation") or object:IsA("AlignPosition") then
						if runtime.ConstraintState[object] == nil then
							runtime.ConstraintState[object] = object.Enabled
						end
						object.Enabled = false
					elseif object:IsA("BasePart") then
						if runtime.StandCollisionState[object] == nil then
							runtime.StandCollisionState[object] = object.CollisionGroup
						end
						local changed = pcall(function()
							object.CollisionGroup = "Players"
						end)
						if not changed then
							pcall(function()
								CharacterPhysicsService:SetPartCollisionGroup(object, "Players")
							end)
						end
					end
				end

				for _, object in ipairs(character:GetDescendants()) do
					applyCharacterPart(object)
				end
				for _, object in ipairs(standMorph:GetDescendants()) do
					applyStandObject(object)
				end

				local function applyPilotSettings()
					if classicPilotRuntime ~= runtime then
						return
					end
					standHumanoid.WalkSpeed = humanoid.WalkSpeed * (tonumber(_G.Config.classicPilotSpeed) or 1.5)
					standHumanoid.JumpPower = humanoid.JumpPower * (tonumber(_G.Config.classicPilotJumpPower) or 1.5)
					root.Anchored = _G.Config.classicPilotHideBody == false
				end
				runtime.ApplySettings = applyPilotSettings
				applyPilotSettings()

				table.insert(runtime.Connections, character.DescendantAdded:Connect(function(object)
					if classicPilotRuntime == runtime then
						applyCharacterPart(object)
					end
				end))
				table.insert(runtime.Connections, standMorph.DescendantAdded:Connect(function(object)
					if classicPilotRuntime == runtime then
						applyStandObject(object)
					end
				end))
				table.insert(runtime.Connections, humanoid:GetPropertyChangedSignal("Jump"):Connect(function()
					if classicPilotRuntime == runtime and humanoid.Jump then
						standHumanoid.Jump = true
					end
				end))
				table.insert(runtime.Connections, humanoid:GetPropertyChangedSignal("WalkSpeed"):Connect(applyPilotSettings))
				table.insert(runtime.Connections, humanoid:GetPropertyChangedSignal("JumpPower"):Connect(applyPilotSettings))
				local summonedStand = character:FindFirstChild("SummonedStand")
				if summonedStand and summonedStand:IsA("BoolValue") then
					table.insert(runtime.Connections, summonedStand:GetPropertyChangedSignal("Value"):Connect(function()
						if not summonedStand.Value and setClassicPilotEnabled then
							task.defer(setClassicPilotEnabled, false, true, true)
						end
					end))
				end
				table.insert(runtime.Connections, CharacterRunService.Heartbeat:Connect(function()
					if generation ~= classicPilotGeneration or classicPilotRuntime ~= runtime then
						return
					end
					if not classicPilotDesired
						or not character.Parent
						or humanoid.Health <= 0
						or not root.Parent
						or not standMorph.Parent
						or not standHumanoid.Parent
						or not standRoot.Parent
					then
						task.defer(setClassicPilotEnabled, false, true, true)
						return
					end
					local currentLease = _G.TheBestMovementRuntime.Claim("ClassicPilot", root, "ClassicPilot", 0.25)
					if not currentLease then standHumanoid:Move(Vector3.zero, true); return end
					runtime.MovementLease = currentLease
					local camera = workspace.CurrentCamera
					if camera then
						local moveDirection = camera.CFrame:VectorToObjectSpace(humanoid.MoveDirection)
						standHumanoid:Move(moveDirection, true)
					end
					if _G.Config.classicPilotHideBody ~= false then
						root.CFrame = standRoot.CFrame
							+ Vector3.new(0, -(tonumber(_G.Config.classicPilotBodyDistance) or 37), 0)
					end
				end))
				return true
			end

			setInvisibilityEnabled = function(enabled, syncControl, persist)
				enabled = enabled == true
				local succeeded, enableError = true, nil
				if enabled then
					succeeded, enableError = enableInvisibilityRuntime()
				else
					disableInvisibilityRuntime()
				end
				if not succeeded then
					enabled = false
					disableInvisibilityRuntime()
					warn("[INVISIBILITY] " .. tostring(enableError))
				end
				_G.Config.invisibilityEnabled = enabled
				if syncControl ~= false and invisibilityToggleControl then
					invisibilityToggleControl.SetState(enabled)
				end
				if persist ~= false then
					SaveConfig()
				end
				return succeeded
			end

			setClassicPilotEnabled = function(enabled, syncControl, persist)
				enabled = enabled == true
				classicPilotDesired = enabled
				_G.Config.classicPilotEnabled = enabled
				local started = true
				if enabled then
					started = startClassicPilotRuntime()
				else
					cleanupClassicPilotRuntime(true)
				end
				if syncControl ~= false and classicPilotToggleControl then
					classicPilotToggleControl.SetState(enabled)
				end
				if persist ~= false then
					SaveConfig()
				end
				return started
			end

			_G.TheBestClassicPilotSetEnabled = setClassicPilotEnabled
			_G.TheBestInvisibilitySetEnabled = setInvisibilityEnabled

			-- TP/Fly protection lives in the persistent bypass runtime; no UI ownership.

			local function bindCharacter(character)
				disconnectConnections(characterConnections)
				if not character then
					return
				end
				local humanoid = character:FindFirstChildOfClass("Humanoid") or character:WaitForChild("Humanoid", 5)
				if humanoid then
					table.insert(characterConnections, humanoid.Died:Connect(function()
						task.defer(function()
							setInvisibilityEnabled(false, true, false)
							setClassicPilotEnabled(false, true, false)
							SaveConfig()
						end)
					end))
					table.insert(characterConnections, humanoid.StateChanged:Connect(function(_, newState)
						if newState ~= Enum.HumanoidStateType.FallingDown
							and newState ~= Enum.HumanoidStateType.Ragdoll
							and newState ~= Enum.HumanoidStateType.PlatformStanding
						then
							return
						end
						task.delay(0.12, function()
							if not humanoid.Parent or humanoid.Health <= 0 or classicPilotActive or _G.Config.enableFly then
								return
							end
							local currentState = humanoid:GetState()
							if currentState ~= Enum.HumanoidStateType.FallingDown
								and currentState ~= Enum.HumanoidStateType.Ragdoll
								and currentState ~= Enum.HumanoidStateType.PlatformStanding
							then
								return
							end
							local root = character:FindFirstChild("HumanoidRootPart")
							if root and root.AssemblyLinearVelocity.Magnitude > 90 then
								return
							end
							humanoid.PlatformStand = false
							pcall(function()
								humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
							end)
						end)
					end))
				end
				table.insert(characterConnections, character.DescendantAdded:Connect(function(object)
					local standMorph = character:FindFirstChild("StandMorph")
					if classicPilotDesired
						and (object.Name == "StandMorph" or (standMorph and object:IsDescendantOf(standMorph)))
					then
						task.defer(startClassicPilotRuntime)
					end
				end))
			end

			invisibilityToggleControl = Library:CreateToggle(
				characterToolsSection,
				"Invisibility",
				_G.Config.invisibilityEnabled,
				function(state)
					setInvisibilityEnabled(state, true, true)
				end
			)
			classicPilotToggleControl = Library:CreateToggle(
				characterToolsSection,
				"Classic Pilot",
				_G.Config.classicPilotEnabled,
				function(state)
					setClassicPilotEnabled(state, true, true)
				end
			)
			Library:CreateSlider(
				characterToolsSection,
				"Classic Pilot Speed",
				_G.Config.classicPilotSpeed,
				0.5,
				5,
				function(value)
					_G.Config.classicPilotSpeed = value
					if classicPilotRuntime and classicPilotRuntime.ApplySettings then
						classicPilotRuntime.ApplySettings()
					end
					SaveConfig()
				end
			)
			Library:CreateSlider(
				characterToolsSection,
				"Classic Pilot Jump",
				_G.Config.classicPilotJumpPower,
				0.5,
				5,
				function(value)
					_G.Config.classicPilotJumpPower = value
					if classicPilotRuntime and classicPilotRuntime.ApplySettings then
						classicPilotRuntime.ApplySettings()
					end
					SaveConfig()
				end
			)
			Library:CreateSlider(
				characterToolsSection,
				"Classic Pilot Body Distance",
				_G.Config.classicPilotBodyDistance,
				1,
				100,
				function(value)
					_G.Config.classicPilotBodyDistance = value
					SaveConfig()
				end
			)
			Library:CreateToggle(characterToolsSection, "Hide Body Underground", _G.Config.classicPilotHideBody, function(state)
				_G.Config.classicPilotHideBody = state
				if classicPilotRuntime and classicPilotRuntime.ApplySettings then
					classicPilotRuntime.ApplySettings()
				end
				SaveConfig()
			end)
			Library:CreateToggle(
				characterToolsSection,
				"Return Body To Stand",
				_G.Config.classicPilotReturnToStand,
				function(state)
					_G.Config.classicPilotReturnToStand = state
					SaveConfig()
				end
			)
			invisibilityToggleControl.SetState(_G.Config.invisibilityEnabled == true)
			classicPilotToggleControl.SetState(_G.Config.classicPilotEnabled == true)

			bindCharacter(characterLocalPlayer.Character)
			table.insert(managerConnections, characterLocalPlayer.CharacterAdded:Connect(function(character)
				if internalCharacterSwap
					or (character == invisibilityCharacter and os.clock() <= internalCharacterSwapUntil)
				then
					return
				end
				setInvisibilityEnabled(false, true, false)
				setClassicPilotEnabled(false, true, false)
				SaveConfig()
				bindCharacter(character)
			end))
			table.insert(managerConnections, CharacterInputService.InputBegan:Connect(function(input, gameProcessed)
				if gameProcessed or CharacterInputService:GetFocusedTextBox() then
					return
				end
				if input.KeyCode == getKey("invisibility") then
					setInvisibilityEnabled(not invisibilityActive, true, true)
				elseif input.KeyCode == getKey("classicPilot") then
					setClassicPilotEnabled(not classicPilotDesired, true, true)
				end
			end))

			_G.TheBestCharacterToolsCleanup = function()
				disconnectConnections(managerConnections)
				disconnectConnections(characterConnections)
				disableInvisibilityRuntime()
				cleanupClassicPilotRuntime(true)
				-- Shared TP/Fly protection survives character-tool UI cleanup.
				if _G.TheBestClassicPilotSetEnabled == setClassicPilotEnabled then
					_G.TheBestClassicPilotSetEnabled = nil
				end
				if _G.TheBestInvisibilitySetEnabled == setInvisibilityEnabled then
					_G.TheBestInvisibilitySetEnabled = nil
				end
			end
		end
		local tab_outfits = Library:CreateClass("Outfits")

		local playerOutfitSection = Library:CreateFunctionTab(tab_outfits, "PLAYER OUTFIT")
		local outfitPlayersService = game:GetService("Players")
		local outfitRunService = game:GetService("RunService")
		local outfitLocalPlayer = outfitPlayersService.LocalPlayer
		local outfitStatusControl = nil
		local outfitUsernameControl = nil
		local favoriteOutfitDropdown = nil
		local selectedFavoriteUsername = nil
		local outfitCharacterConnection = nil
		local outfitRequestVersion = 0
		local outfitVisualModel = nil
		local outfitRenderConnection = nil
		local outfitHiddenParts = {}
		local NO_FAVORITES_TEXT = "No favorites"
		local function trimUsername(value)
			return tostring(value or ""):match("^%s*(.-)%s*$") or ""
		end
		local function setOutfitStatus(text)
			if outfitStatusControl then
				outfitStatusControl.SetText(text)
			end
		end
		local function normalizeFavoriteUsernames()
			local sourceFavorites = type(_G.Config.playerOutfitFavorites) == "table" and _G.Config.playerOutfitFavorites
				or {}
			local normalized = {}
			local seen = {}
			for _, username in pairs(sourceFavorites) do
				username = trimUsername(username)
				local key = string.lower(username)
				if username ~= "" and not seen[key] then
					seen[key] = true
					table.insert(normalized, username)
				end
			end
			table.sort(normalized, function(left, right)
				return string.lower(left) < string.lower(right)
			end)
			_G.Config.playerOutfitFavorites = normalized
			return normalized
		end
		local function getFavoriteDropdownItems()
			local favorites = normalizeFavoriteUsernames()
			if #favorites == 0 then
				return { NO_FAVORITES_TEXT }
			end
			local copy = {}
			for _, username in ipairs(favorites) do
				table.insert(copy, username)
			end
			return copy
		end
		local function refreshFavoriteDropdown(preferredUsername)
			local items = getFavoriteDropdownItems()
			if favoriteOutfitDropdown then
				favoriteOutfitDropdown.Update(items)
			end
			local preferredKey = string.lower(trimUsername(preferredUsername))
			selectedFavoriteUsername = nil
			for _, username in ipairs(items) do
				if username ~= NO_FAVORITES_TEXT and string.lower(username) == preferredKey then
					selectedFavoriteUsername = username
					break
				end
			end
			if not selectedFavoriteUsername and items[1] ~= NO_FAVORITES_TEXT then
				selectedFavoriteUsername = items[1]
			end
			if favoriteOutfitDropdown and selectedFavoriteUsername then
				favoriteOutfitDropdown.SetValue(selectedFavoriteUsername)
			end
		end
		local function resolveOutfitUsername(rawUsername)
			local username = trimUsername(rawUsername)
			if username == "" then
				return nil, nil, "Enter a Roblox username."
			end
			local lowerUsername = string.lower(username)
			for _, serverPlayer in ipairs(outfitPlayersService:GetPlayers()) do
				if
					string.lower(serverPlayer.Name) == lowerUsername
					or string.lower(serverPlayer.DisplayName) == lowerUsername
				then
					return serverPlayer.UserId, serverPlayer.Name, nil
				end
			end
			local idSucceeded, userId = pcall(function()
				return outfitPlayersService:GetUserIdFromNameAsync(username)
			end)
			if not idSucceeded or type(userId) ~= "number" or userId <= 0 then
				return nil, nil, "Player not found."
			end
			local nameSucceeded, canonicalUsername = pcall(function()
				return outfitPlayersService:GetNameFromUserIdAsync(userId)
			end)
			if not nameSucceeded or type(canonicalUsername) ~= "string" then
				canonicalUsername = username
			end
			return userId, canonicalUsername, nil
		end
		local function fetchOutfitModel(userId, targetRigType)
			local appearanceInfoSucceeded, appearanceInfo = pcall(function()
				return outfitPlayersService:GetCharacterAppearanceInfoAsync(userId)
			end)
			local sourceRigType = Enum.HumanoidRigType.R15
			if
				appearanceInfoSucceeded
				and type(appearanceInfo) == "table"
				and tostring(appearanceInfo.playerAvatarType) == "R6"
			then
				sourceRigType = Enum.HumanoidRigType.R6
			end
			local rigType = targetRigType == Enum.HumanoidRigType.R6 and Enum.HumanoidRigType.R6
				or targetRigType == Enum.HumanoidRigType.R15 and Enum.HumanoidRigType.R15
				or sourceRigType
			local descriptionSucceeded, description = pcall(function()
				return outfitPlayersService:GetHumanoidDescriptionFromUserIdAsync(userId)
			end)
			if not descriptionSucceeded then
				descriptionSucceeded, description = pcall(function()
					return outfitPlayersService:GetHumanoidDescriptionFromUserId(userId)
				end)
			end
			local succeeded = false
			local appearanceModel = nil
			if descriptionSucceeded and description then
				succeeded, appearanceModel = pcall(function()
					return outfitPlayersService:CreateHumanoidModelFromDescriptionAsync(description, rigType)
				end)
			end
			if not succeeded or not appearanceModel then
				succeeded, appearanceModel = pcall(function()
					return outfitPlayersService:CreateHumanoidModelFromUserIdAsync(userId)
				end)
			end
			if not succeeded or not appearanceModel then
				succeeded, appearanceModel = pcall(function()
					return outfitPlayersService:GetCharacterAppearanceAsync(userId)
				end)
			end
			if not succeeded or not appearanceModel then
				return nil, "Could not download this player's complete outfit."
			end
			local createdHumanoid = appearanceModel:FindFirstChildOfClass("Humanoid")
			local createdRigType = createdHumanoid and createdHumanoid.RigType or rigType
			appearanceModel:SetAttribute("TheBestAvatarRig", createdRigType.Name)
			return appearanceModel, nil
		end
		local OUTFIT_BODY_PART_NAMES = {
			Head = true,
			Torso = true,
			["Left Arm"] = true,
			["Right Arm"] = true,
			["Left Leg"] = true,
			["Right Leg"] = true,
			UpperTorso = true,
			LowerTorso = true,
			LeftUpperArm = true,
			LeftLowerArm = true,
			LeftHand = true,
			RightUpperArm = true,
			RightLowerArm = true,
			RightHand = true,
			LeftUpperLeg = true,
			LeftLowerLeg = true,
			LeftFoot = true,
			RightUpperLeg = true,
			RightLowerLeg = true,
			RightFoot = true,
		}
		local OUTFIT_RIG_ANCHORS = {
			"LowerTorso",
			"Torso",
			"UpperTorso",
		}
		local function purgeStaleOutfitVisuals(character, forceCharacterRecovery)
			local roots = { workspace, workspace.CurrentCamera, character }
			local checkedRoots = {}
			local removedOutfitArtifact = false
			for _, root in ipairs(roots) do
				if root and not checkedRoots[root] then
					checkedRoots[root] = true
					for _, child in ipairs(root:GetChildren()) do
						if
							child ~= outfitVisualModel
							and child:IsA("Model")
							and (child.Name == "TheBestOutfitVisual" or child:GetAttribute("TheBestOutfitVisual"))
						then
							removedOutfitArtifact = true
							child:Destroy()
						end
					end
				end
			end
			if character then
				for _, descendant in ipairs(character:GetDescendants()) do
					if descendant:IsA("JointInstance") and descendant.Name == "TheBestOutfitWeld" then
						removedOutfitArtifact = true
						descendant:Destroy()
					elseif descendant:IsA("BasePart") then
						local accessory = descendant:FindFirstAncestorOfClass("Accessory")
						local isBodyPart = descendant.Parent == character and OUTFIT_BODY_PART_NAMES[descendant.Name]
						if (accessory or isBodyPart) and descendant.LocalTransparencyModifier >= 0.99 then
							descendant.LocalTransparencyModifier = 0
						end
					end
				end
				if removedOutfitArtifact or forceCharacterRecovery then
					local rootPart = character:FindFirstChild("HumanoidRootPart")
					if rootPart and rootPart:IsA("BasePart") then
						rootPart.Anchored = false
						rootPart.AssemblyLinearVelocity = Vector3.zero
						rootPart.AssemblyAngularVelocity = Vector3.zero
					end
					local humanoid = character:FindFirstChildOfClass("Humanoid")
					if humanoid then
						humanoid.PlatformStand = false
						humanoid.AutoRotate = true
						pcall(function()
							humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
						end)
						if workspace.CurrentCamera then
							workspace.CurrentCamera.CameraSubject = humanoid
						end
					end
				end
			end
		end
		local function restoreOriginalCharacterVisuals(character, forceCharacterRecovery)
			if outfitRenderConnection then
				outfitRenderConnection:Disconnect()
				outfitRenderConnection = nil
			end
			for part, previousModifier in pairs(outfitHiddenParts) do
				if part and part.Parent then
					pcall(function()
						part.LocalTransparencyModifier = previousModifier
					end)
				end
			end
			outfitHiddenParts = {}
			if outfitVisualModel then
				outfitVisualModel:Destroy()
				outfitVisualModel = nil
			end
			purgeStaleOutfitVisuals(character or outfitLocalPlayer.Character, forceCharacterRecovery)
		end
		local function hideOriginalCharacterVisuals(character)
			for _, descendant in ipairs(character:GetDescendants()) do
				if descendant:IsA("BasePart") and not descendant:IsDescendantOf(outfitVisualModel) then
					local accessory = descendant:FindFirstAncestorOfClass("Accessory")
					local isBodyPart = descendant.Parent == character and OUTFIT_BODY_PART_NAMES[descendant.Name]
					if accessory or isBodyPart then
						if outfitHiddenParts[descendant] == nil then
							outfitHiddenParts[descendant] = descendant.LocalTransparencyModifier
						end
						descendant.LocalTransparencyModifier = 1
					end
				end
			end
		end
		local function findOutfitRigAnchor(model)
			for _, partName in ipairs(OUTFIT_RIG_ANCHORS) do
				local part = model:FindFirstChild(partName)
				if part and part:IsA("BasePart") then
					return part
				end
			end
			return nil
		end
		local function isDirectOutfitRigMotor(motor, model)
			if not motor:IsA("Motor6D") or not motor.Part0 or not motor.Part1 then
				return false
			end
