			local attachment1 = nil
			local attachmentName = OUTFIT_RIG_ATTACHMENT_BY_MOTOR[motor.Name]
			if attachmentName then
				attachment0 = part0:FindFirstChild(attachmentName)
				attachment1 = part1:FindFirstChild(attachmentName)
			end
			if not attachment0 or not attachment1 then
				for _, candidate in ipairs(part0:GetChildren()) do
					if candidate:IsA("Attachment") and candidate.Name:find("RigAttachment$") then
						local matchingAttachment = part1:FindFirstChild(candidate.Name)
						if matchingAttachment and matchingAttachment:IsA("Attachment") then
