		local function enablePlayerOutfit(rawUsername, silent, character)
			outfitRequestVersion += 1
			local requestVersion = outfitRequestVersion
			if not silent then
				setOutfitStatus("Loading player outfit...")
			end
			local userId, canonicalUsername, resolveError = resolveOutfitUsername(rawUsername)
			if requestVersion ~= outfitRequestVersion then
				return false
			end
			if not userId then
				if not silent then
					setOutfitStatus(resolveError)
				end
				return false
			end
			local targetCharacter = character or outfitLocalPlayer.Character
			local targetHumanoid = targetCharacter and targetCharacter:FindFirstChildOfClass("Humanoid")
			local targetRigType = targetHumanoid and targetHumanoid.RigType or nil
			local appearanceModel, downloadError = fetchOutfitModel(userId, targetRigType)
			if requestVersion ~= outfitRequestVersion then
				if appearanceModel then
					appearanceModel:Destroy()
				end
				return false
			end
			if not appearanceModel then
				if not silent then
					setOutfitStatus(downloadError)
				end
				return false
			end
			local applied, applyError, applyStats = applyOutfitModelLocally(appearanceModel, targetCharacter)
			if requestVersion ~= outfitRequestVersion then
				restoreOriginalCharacterVisuals()
				return false
			end
			if not applied then
				if appearanceModel and appearanceModel.Parent then
					appearanceModel:Destroy()
				end
				restoreOriginalCharacterVisuals()
				if not silent then
					setOutfitStatus(applyError)
				end
				return false
			end
			_G.Config.playerOutfitUsername = canonicalUsername
			_G.Config.playerOutfitEnabled = true
			_G.Config.playerStandOutfitEnabled = false
			_G.Config.playerStandOutfitSkin = ""
			_G.Config.playerStandOutfitStand = ""
			_G.Config.playerNpcOutfitEnabled = false
			_G.Config.playerNpcOutfitName = ""
			SaveConfig()
			if outfitUsernameControl then
				outfitUsernameControl.SetValue(canonicalUsername, false)
			end
			applyStats = applyStats or {}
			setOutfitStatus(
				("Enabled: %s | %s | body %d | acc %d | joints %d"):format(
					canonicalUsername,
					tostring(applyStats.rig or "avatar"),
					tonumber(applyStats.bodyParts) or 0,
					tonumber(applyStats.accessories) or 0,
					tonumber(applyStats.joints) or 0
				)
			)
			return true
		end
		local function disablePlayerOutfit()
