				table.sort(labels, function(left, right)
					return string.lower(left) < string.lower(right)
				end)
				local blue = blueJack:Select({ workspace, replicatedStorage }, isUsableNpcModel)
				sources[blueJack.Label] = blue or blueJack.Fallback
				table.insert(labels, blueJack.Label)
				table.sort(labels, function(left, right) return string.lower(left) < string.lower(right) end)
