					if not source or not source.Parent then
						refreshNpcList()
						source = npcSources[label]
					end
					visualModel = cloneNpcModel(source, label)
				end
				if not visualModel then
					if not silent then
						setStatus("NPC model is not available in this server.")
					end
					return false
				end
				local templateCopy = visualModel:Clone()
				local targetCharacter = character or playersService.LocalPlayer.Character
				local applied, applyError = applyVisualModel(visualModel, targetCharacter, true, {
					clearSourcePose = _G.Config.npcOutfitKeepPose ~= true,
				})
				if requestVersion ~= getRequestVersion() then
					if templateCopy then
						templateCopy:Destroy()
					end
					restoreVisuals(targetCharacter)
					return false
				end
				if not applied then
					pcall(function()
						visualModel:Destroy()
					end)
					templateCopy:Destroy()
					restoreVisuals(targetCharacter)
					if not silent then
						setStatus(applyError)
					end
					return false
				end
				if cachedNpcTemplate then
					cachedNpcTemplate:Destroy()
				end
				cachedNpcTemplate = templateCopy
				blueJack:Animate(visualModel)
				_G.Config.playerOutfitEnabled = false
				_G.Config.playerStandOutfitEnabled = false
				_G.Config.playerStandOutfitSkin = ""
				_G.Config.playerStandOutfitStand = ""
				_G.Config.playerNpcOutfitEnabled = true
				_G.Config.playerNpcOutfitName = label
