		local function saveFavoriteUsername()
			local rawUsername = outfitUsernameControl and outfitUsernameControl.GetValue()
				or _G.Config.playerOutfitUsername
			setOutfitStatus("Checking username...")
			local _, canonicalUsername, resolveError = resolveOutfitUsername(rawUsername)
			if not canonicalUsername then
				setOutfitStatus(resolveError)
				return false
			end
			local favorites = normalizeFavoriteUsernames()
			for _, username in ipairs(favorites) do
				if string.lower(username) == string.lower(canonicalUsername) then
					selectedFavoriteUsername = username
					setOutfitStatus("Favorite already saved: " .. username)
					return false
				end
			end
			table.insert(favorites, canonicalUsername)
			_G.Config.playerOutfitFavorites = favorites
			_G.Config.playerOutfitUsername = canonicalUsername
			SaveConfig()
			refreshFavoriteDropdown(canonicalUsername)
			if outfitUsernameControl then
				outfitUsernameControl.SetValue(canonicalUsername, false)
			end
			setOutfitStatus("Saved favorite: " .. canonicalUsername)
			return true
		end
		local function deleteFavoriteUsername()
			local targetUsername = trimUsername(selectedFavoriteUsername)
			if targetUsername == "" and outfitUsernameControl then
				targetUsername = trimUsername(outfitUsernameControl.GetValue())
			end
			if targetUsername == "" then
				setOutfitStatus("Select a favorite to delete.")
				return false
			end
			local favorites = normalizeFavoriteUsernames()
			local removed = false
			for index = #favorites, 1, -1 do
				if string.lower(favorites[index]) == string.lower(targetUsername) then
					table.remove(favorites, index)
					removed = true
				end
			end
			if not removed then
				setOutfitStatus("Favorite not found.")
				return false
			end
			_G.Config.playerOutfitFavorites = favorites
			SaveConfig()
			selectedFavoriteUsername = nil
			refreshFavoriteDropdown(nil)
			setOutfitStatus("Deleted favorite: " .. targetUsername)
			return true
		end
