		-- Vanta Safe Zone: recovered f24 from the 2026-04-11 reference.
		-- Keep the original 150x1x150 pad, +200 local-Y / +6 stand offset,
		-- void-height recovery and 15-second lifetime. Only lifecycle/UI are adapted.
		;(function()
			local players = game:GetService("Players")
			local player = players.LocalPlayer
			local pads = {}
			local active = true
			local characterConnection, safeZoneInputConnection = nil, nil
			if type(_G.TheBestVantaSafeZoneCleanup) == "function" then
				pcall(_G.TheBestVantaSafeZoneCleanup)
			end
			local section = Library:CreateFunctionTab(tab_misc, "Quick Actions")
			local status = Library:CreateStatusLabel(section, "Safe zone platform lasts 15 seconds.")
			local function setStatus(message)
				if active and status then
					status.SetText(message)
				end
			end
			local function removePad(pad, cancelTimer)
				local timer = pads[pad]
				pads[pad] = nil
				if cancelTimer and timer and type(task.cancel) == "function" then
					pcall(task.cancel, timer)
				end
				pcall(function()
					pad:Destroy()
				end)
			end
			local function clearPads()
				for pad in pairs(pads) do
					removePad(pad, true)
				end
			end
			local function teleportToSafeZone()
				if not active then
					return
				end
				local character = player and player.Character
				local root = character and character:FindFirstChild("HumanoidRootPart")
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")
				if not root or not root:IsA("BasePart") or not root.Parent or not humanoid or humanoid.Health <= 0 then
					setStatus("Character is not ready.")
					return
				end
				local lease = _G.TheBestMovementRuntime.Claim("Manual", root, "Manual", 0.4)
				if not lease then setStatus("Another movement operation is active."); return end
				local wasAnchored = root.Anchored
				local pad = nil
				local ok, teleportError = pcall(function()
					local minimumHeight = workspace.FallenPartsDestroyHeight
					local position = root.Position
					if position.Y < minimumHeight + 100 then
						root.Position = Vector3.new(position.X, minimumHeight + 180, position.Z)
					end
					root.Anchored = true
					root.AssemblyLinearVelocity = Vector3.zero
					root.AssemblyAngularVelocity = Vector3.zero
					pad = Instance.new("Part")
					pad.Name = "TheBestVantaSafeZone"
					pad.Anchored = true
					pad.CanCollide = true
					pad.Size = Vector3.new(150, 1, 150)
					pad.Transparency = 1
					pad.CFrame = root.CFrame * CFrame.new(0, 200, 0)
					pad.Parent = workspace
					root.CFrame = pad.CFrame * CFrame.new(0, 6, 0)
					root.Anchored = false
					pads[pad] = task.delay(15, function()
						removePad(pad, false)
					end)
				end)
				if not ok then
					pcall(function()
						root.Anchored = wasAnchored
					end)
					if pad then
						removePad(pad, true)
					end
					setStatus("Safe zone teleport failed.")
					warn("[TheBest / Vanta Safe Zone] " .. tostring(teleportError))
					return
				end
				setStatus("Teleported to safe zone.")
			end
			Library:CreateButton(section, "Teleport to Safe Zone", teleportToSafeZone)
			safeZoneInputConnection = game:GetService("UserInputService").InputBegan:Connect(function(input, processed)
				if processed or not active or game:GetService("UserInputService"):GetFocusedTextBox() then return end
				if input.KeyCode == getKey("safeZone") then teleportToSafeZone() end
			end)
			if player then
				characterConnection = player.CharacterRemoving:Connect(clearPads)
			end
			_G.TheBestVantaSafeZoneCleanup = function()
				if safeZoneInputConnection then safeZoneInputConnection:Disconnect(); safeZoneInputConnection = nil end
				active = false
				clearPads()
				if characterConnection then
					characterConnection:Disconnect()
					characterConnection = nil
				end
			end
		end)()
		do
			local xenon = XenonIntegration
			;(function()
