					end
				end

				local function addEmote(name, id)
					local numericId = tonumber(id)
					local baseName = tostring(name or "")
					if baseName == "" or not numericId or controller.IdsSeen[numericId] then
						return
					end
					controller.IdsSeen[numericId] = true
					local displayName = baseName
					if controller.IdsByName[displayName] then
						displayName = string.format("%s [%d]", baseName, numericId)
					end
					controller.IdsByName[displayName] = numericId
					table.insert(controller.Names, displayName)
				end

				for _, emote in ipairs({
					{ "Arm Wave", 5915773155 },
					{ "Head Banging", 5915779725 },
					{ "Face Calisthenics", 9830731012 },
					{ "Metro Man arm swings", 136271269847411 },
					{ "Jason Vorhees Dance Goofy", 127633235542889 },
