				}) do
					addEmote(emote[1], emote[2])
				end

				local function getSortedNames()
					local result = {}
					for _, name in ipairs(controller.Names) do
						table.insert(result, name)
					end
					table.sort(result, function(left, right)
						return string.lower(left) < string.lower(right)
					end)
					return result
				end

				function controller:Stop()
					if self.Track then
						pcall(function() self.Track:Stop(0.1) end)
						pcall(function() self.Track:Destroy() end)
						self.Track = nil
					end
				end

				function controller:Play(name)
					local id = self.IdsByName[name]
					if not id then
						setStatus("Select an emote first.")
						return false
					end
					local character = localPlayer and localPlayer.Character
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")
					if not humanoid then
						setStatus("Character is not ready for emotes.")
						return false
					end
					if humanoid.RigType == Enum.HumanoidRigType.R6 then
						setStatus("Emotes require an R15 character.")
						return false
					end
					self:Stop()
					local succeeded, track = pcall(function()
						return humanoid:PlayEmoteAndGetAnimTrackById(id)
					end)
					if not succeeded or not track then
						local animation = Instance.new("Animation")
						animation.AnimationId = "rbxassetid://" .. tostring(id)
						local animator = humanoid:FindFirstChildOfClass("Animator") or humanoid
						succeeded, track = pcall(function()
							local loadedTrack = animator:LoadAnimation(animation)
							loadedTrack:Play(0.1)
							return loadedTrack
						end)
						animation:Destroy()
					end
					if not succeeded or not track then
						setStatus("Could not play this emote.")
						return false
					end
					self.Track = track
					setStatus("Current emote: " .. name)
					return true
				end

				function controller:Load(force)
					if self.Loading or (self.Loaded and not force) then
						return
					end
					self.LoadToken += 1
					local token = self.LoadToken
					self.Loading = true
					setStatus("Loading Roblox emotes...")
					task.spawn(function()
						local params = CatalogSearchParams.new()
						params.AssetTypes = { Enum.AvatarAssetType.EmoteAnimation }
						params.SortType = Enum.CatalogSortType.RecentlyCreated
						params.SortAggregation = Enum.CatalogSortAggregation.AllTime
						params.IncludeOffSale = true
						params.CreatorName = "Roblox"
						params.Limit = 120
						local catalogPages = nil
						for attempt = 1, 3 do
							local ok, result = pcall(function()
								return AvatarEditorService:SearchCatalog(params)
							end)
							if ok and result then
								catalogPages = result
								break
							end
							if attempt < 3 then
								task.wait(attempt)
							end
						end
						if token ~= self.LoadToken then
							return
						end
						if not catalogPages then
							self.Loading = false
							setStatus("Roblox emote catalog is unavailable; custom emotes remain available.")
							return
						end
						local completed = true
						while token == self.LoadToken do
							local page = catalogPages:GetCurrentPage()
							for _, emote in ipairs(page) do
								addEmote(emote.Name, emote.Id)
							end
							if catalogPages.IsFinished then
								break
							end
							local advanced = false
							for attempt = 1, 3 do
								advanced = pcall(function() catalogPages:AdvanceToNextPageAsync() end)
								if advanced then
									break
								end
								if attempt < 3 then
									task.wait(attempt)
								end
							end
							if not advanced then
								completed = false
								break
							end
						end
						if token ~= self.LoadToken then
							return
						end
						self.Loading = false
						self.Loaded = completed
						local names = getSortedNames()
						if popupController then
							popupController.Refresh()
						end
						setStatus("Loaded emotes: " .. tostring(#names))
					end)
				end

				if type(_G.TheBestAllEmotesCleanup) == "function" then
