						end
						panel.Visible = false
						shade.Visible = false
					end
					local function openPopup()
						if _G.currentOpenDropdown and _G.currentOpenDropdown.close then
							pcall(_G.currentOpenDropdown.close)
							_G.currentOpenDropdown = nil
						end
						refresh()
						shade.Visible = true
						panel.Visible = true
					end

					searchBox:GetPropertyChangedSignal("Text"):Connect(function()
						query = string.lower(searchBox.Text:match("^%s*(.-)%s*$") or "")
						refresh()
					end)
					shade.MouseButton1Click:Connect(closePopup)
					closeButton.MouseButton1Click:Connect(closePopup)
					registerThemeListener(function(theme)
						panel.BackgroundColor3 = theme.surface
						panelStroke.Color = theme.stroke
						title.TextColor3 = theme.text
						countLabel.TextColor3 = theme.textDim
						closeButton.BackgroundColor3 = theme.dropdownBg
						closeButton.TextColor3 = theme.text
						searchBox.BackgroundColor3 = theme.dropdownBg
						searchBox.TextColor3 = theme.text
						searchBox.PlaceholderColor3 = theme.textDim
						list.BackgroundColor3 = theme.background
						list.ScrollBarImageColor3 = theme.scrollBar
						paintButtons()
					end)
					_G.TheBestCloseEmotePopup = closePopup
					refresh()
					return {
						Open = openPopup,
						Close = closePopup,
						Refresh = refresh,
						Select = function(name)
							selectedName = name
							paintButtons()
						end,
						Destroy = function()
							closePopup()
							if _G.TheBestCloseEmotePopup == closePopup then
								_G.TheBestCloseEmotePopup = nil
							end
							shade:Destroy()
							panel:Destroy()
						end,
					}
				end

