local coordinateCells, coordinateLabels = {}, {}
for index, axis in ipairs({"X", "Y", "Z"}) do
	local cell = Instance.new("Frame")
	cell.Size, cell.Position = UDim2.fromOffset(80, 52), UDim2.fromOffset(13 + (index - 1) * 89, 40)
	cell.BorderSizePixel, cell.Parent = 0, panel
	local rounding = Instance.new("UICorner")
	rounding.CornerRadius, rounding.Parent = UDim.new(0, 6), cell
	local caption = Instance.new("TextLabel")
	caption.BackgroundTransparency, caption.Font, caption.TextSize = 1, Enum.Font.GothamMedium, 10
	caption.Position, caption.Size = UDim2.fromOffset(8, 5), UDim2.new(1, -16, 0, 14)
	caption.TextXAlignment, caption.Text, caption.Parent = Enum.TextXAlignment.Left, axis, cell
	local amount = Instance.new("TextLabel")
	amount.BackgroundTransparency, amount.Font, amount.TextSize = 1, Enum.Font.Code, 15
	amount.Position, amount.Size = UDim2.fromOffset(8, 22), UDim2.new(1, -16, 0, 23)
	amount.TextXAlignment, amount.TextTruncate, amount.Text, amount.Parent = Enum.TextXAlignment.Left, Enum.TextTruncate.AtEnd, "--", cell
	coordinateCells[index], coordinateLabels[index] = {cell, caption}, amount
end
local function setCoordinateValues(position)
	for index, axis in ipairs({"X", "Y", "Z"}) do
		coordinateLabels[index].Text = position and string.format("%.1f", position[axis]) or "--"
	end
end
local function applyCoordinateTheme(theme)
	if not panel.Parent then return end
	panel.BackgroundColor3, panelStroke.Color, pin.BackgroundColor3 = theme.surface, theme.accent, theme.accent
	title.TextColor3 = theme.text
	for index, entry in ipairs(coordinateCells) do
		entry[1].BackgroundColor3, entry[2].TextColor3 = theme.dropdownBg or theme.background, theme.accent
		coordinateLabels[index].TextColor3 = theme.text
	end
end
applyCoordinateTheme(T)
registerThemeListener(applyCoordinateTheme)

