		local OLD_YBA_MAP_ASSET = "rbxassetid://18867175349"
		local OLD_YBA_MAP_NAME = "TheBest_OldYBAMap"
		local oldYbaMapInstance = nil
		local oldYbaCurrentMap = nil
		local oldYbaMapObjectStates = {}
		local oldYbaMapDescendantConnection = nil
		local oldYbaMapActive = false
		local oldYbaMapStatusControl = nil
		local oldYbaMapToggleControl = nil
		local oldYbaMapOperationId = 0

		local function setOldYbaMapStatus(text)
			if oldYbaMapStatusControl then
				oldYbaMapStatusControl.SetText(text)
			end
		end

		local function saveOldYbaMapObjectState(object)
			if not object or oldYbaMapObjectStates[object] then
				return
			end
			if object:IsA("BasePart") then
				oldYbaMapObjectStates[object] = {
					kind = "BasePart",
					Transparency = object.Transparency,
					LocalTransparencyModifier = object.LocalTransparencyModifier,
					CanCollide = object.CanCollide,
					CanTouch = object.CanTouch,
					CanQuery = object.CanQuery,
					CastShadow = object.CastShadow,
				}
			elseif object:IsA("Decal") or object:IsA("Texture") then
				oldYbaMapObjectStates[object] = { kind = "Transparency", Transparency = object.Transparency }
			elseif
				object:IsA("ParticleEmitter")
				or object:IsA("Beam")
				or object:IsA("Trail")
				or object:IsA("Smoke")
				or object:IsA("Fire")
				or object:IsA("Sparkles")
				or object:IsA("PointLight")
				or object:IsA("SpotLight")
				or object:IsA("SurfaceLight")
				or object:IsA("ProximityPrompt")
			then
				oldYbaMapObjectStates[object] = { kind = "Enabled", Enabled = object.Enabled }
			end
		end

		local function hideOldYbaCurrentMapObject(object)
			saveOldYbaMapObjectState(object)
			local state = oldYbaMapObjectStates[object]
			if not state then
				return
			end
			pcall(function()
				if state.kind == "BasePart" then
					object.Transparency = 1
					object.LocalTransparencyModifier = 1
					object.CanCollide = false
					object.CanTouch = false
					object.CanQuery = false
					object.CastShadow = false
				elseif state.kind == "Transparency" then
					object.Transparency = 1
				elseif state.kind == "Enabled" then
					object.Enabled = false
				end
			end)
		end

		local function hideOldYbaCurrentMap(map)
			if not map then
				return
			end
			hideOldYbaCurrentMapObject(map)
			for _, object in ipairs(map:GetDescendants()) do
				hideOldYbaCurrentMapObject(object)
			end
			if oldYbaMapDescendantConnection then
				oldYbaMapDescendantConnection:Disconnect()
			end
			oldYbaMapDescendantConnection = map.DescendantAdded:Connect(function(object)
				if oldYbaMapActive then
					task.defer(function()
						if oldYbaMapActive and object:IsDescendantOf(map) then
							hideOldYbaCurrentMapObject(object)
						end
					end)
				end
			end)
		end

		local function restoreOldYbaCurrentMap()
			if oldYbaMapDescendantConnection then
				pcall(function()
					oldYbaMapDescendantConnection:Disconnect()
				end)
				oldYbaMapDescendantConnection = nil
			end
			local statesToRestore = oldYbaMapObjectStates
			oldYbaMapObjectStates = {}
			local function restoreStates()
				for object, state in pairs(statesToRestore) do
					pcall(function()
						if state.kind == "BasePart" then
							object.Transparency = state.Transparency
							object.LocalTransparencyModifier = state.LocalTransparencyModifier
							object.CanCollide = state.CanCollide
							object.CanTouch = state.CanTouch
							object.CanQuery = state.CanQuery
							object.CastShadow = state.CastShadow
						elseif state.kind == "Transparency" then
							object.Transparency = state.Transparency
						elseif state.kind == "Enabled" then
							object.Enabled = state.Enabled
						end
					end)
				end
			end
			restoreStates()
			oldYbaCurrentMap = nil
		end

		local function removeOldYbaMapInstance()
			if oldYbaMapInstance then
				pcall(function()
					oldYbaMapInstance:Destroy()
				end)
				oldYbaMapInstance = nil
			end
			for _, object in ipairs(workspace:GetChildren()) do
				if
					object.Name == OLD_YBA_MAP_NAME
					or object:GetAttribute("TheBestOldYbaMap") == true
				then
					pcall(function()
						object:Destroy()
					end)
				end
			end
		end

		local function disableOldYbaMap(silent)
			oldYbaMapActive = false
			restoreOldYbaCurrentMap()
			removeOldYbaMapInstance()
			if not silent then
				setOldYbaMapStatus("Current YBA map restored.")
			end
			return true
		end

		local function enableOldYbaMap(operationId)
			if operationId ~= oldYbaMapOperationId then
				return false, nil, true
			end
			if oldYbaMapActive and oldYbaMapInstance and oldYbaMapInstance.Parent then
				setOldYbaMapStatus("Old YBA map is already enabled.")
				return true
			end
			disableOldYbaMap(true)
			setOldYbaMapStatus("Loading old YBA map...")
			local character = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
			local root = character and (character:FindFirstChild("HumanoidRootPart") or character:WaitForChild("HumanoidRootPart", 10))
			if operationId ~= oldYbaMapOperationId then
				return false, nil, true
			end
			if not root then
				return false, "Character root was not found."
			end
			local currentMap = workspace:FindFirstChild("Map")
			if not currentMap then
				return false, "workspace.Map was not found."
			end
			local loadedOk, loadedObjects = pcall(function()
				return game:GetObjects(OLD_YBA_MAP_ASSET)
			end)
			if not loadedOk or type(loadedObjects) ~= "table" or not loadedObjects[1] then
				return false, "Could not load asset " .. OLD_YBA_MAP_ASSET .. "."
			end
			local loadedMap = loadedObjects[1]
			for index = 2, #loadedObjects do
				pcall(function()
					loadedObjects[index]:Destroy()
				end)
			end
			if operationId ~= oldYbaMapOperationId then
				loadedMap:Destroy()
				return false, nil, true
			end
			if not (loadedMap:IsA("Model") or loadedMap:IsA("BasePart")) then
				loadedMap:Destroy()
				return false, "The loaded asset is not a Model or BasePart."
			end
			loadedMap.Name = OLD_YBA_MAP_NAME
			loadedMap:SetAttribute("TheBestOldYbaMap", true)
			for _, object in ipairs(loadedMap:GetDescendants()) do
				if object:IsA("BaseScript") then
					pcall(function()
						object.Disabled = true
					end)
				end
			end
			local positioned, positionError = pcall(function()
				loadedMap:PivotTo(CFrame.new(root.Position) * CFrame.new(250, 0, 950))
			end)
			if not positioned then
				loadedMap:Destroy()
				return false, "Could not position old YBA map: " .. tostring(positionError)
			end
			oldYbaMapInstance = loadedMap
			if operationId ~= oldYbaMapOperationId then
				loadedMap:Destroy()
				oldYbaMapInstance = nil
				return false, nil, true
			end
			loadedMap.Parent = workspace
			if operationId ~= oldYbaMapOperationId then
				loadedMap:Destroy()
				oldYbaMapInstance = nil
				return false, nil, true
			end
			oldYbaCurrentMap = currentMap
			oldYbaMapActive = true
			local hiddenOk, hiddenError = pcall(hideOldYbaCurrentMap, currentMap)
			if not hiddenOk then
				disableOldYbaMap(true)
				return false, "Could not hide current map: " .. tostring(hiddenError)
			end
			if operationId ~= oldYbaMapOperationId then
				disableOldYbaMap(true)
				return false, nil, true
			end
			setOldYbaMapStatus("Old YBA map enabled. Toggle off to restore current map.")
			return true
		end

		if _G.TheBestOldYbaMapCleanup then
			pcall(_G.TheBestOldYbaMapCleanup)
		end
		_G.TheBestOldYbaMapCleanup = function()
			oldYbaMapOperationId += 1
			disableOldYbaMap(true)
		end

		local legacyFovConnection = _G.fov_value_conn
		if _G.TheBestFovCleanup then
			pcall(_G.TheBestFovCleanup)
			_G.TheBestFovCleanup = nil
		elseif legacyFovConnection then
			pcall(function()
				legacyFovConnection:Disconnect()
			end)
			local legacyCamera = workspace.CurrentCamera
			if legacyCamera then
				pcall(function()
					legacyCamera.FieldOfView = 70
				end)
			end
		end
		_G.fov_value_conn = nil

		local fovState = {
			originals = {},
			applying = false,
			cameraConnection = nil,
		}

		local function rememberFov(camera)
			if camera and fovState.originals[camera] == nil then
				fovState.originals[camera] = camera.FieldOfView
			end
		end

		local function disconnectFovConnections()
			if _G.fov_value_conn then
				pcall(function()
					_G.fov_value_conn:Disconnect()
				end)
				_G.fov_value_conn = nil
			end
			if fovState.cameraConnection then
				pcall(function()
					fovState.cameraConnection:Disconnect()
				end)
				fovState.cameraConnection = nil
			end
		end

		local function restoreFov()
			disconnectFovConnections()
			fovState.applying = true
			for camera, originalFov in pairs(fovState.originals) do
				pcall(function()
					camera.FieldOfView = originalFov
				end)
			end
			fovState.applying = false
			table.clear(fovState.originals)
		end

		local function applyFov()
			if not _G.Config.enableFovChanger then
				return
			end
			local camera = workspace.CurrentCamera
			if not camera then
				return
			end
			rememberFov(camera)
			fovState.applying = true
			pcall(function()
				camera.FieldOfView = _G.Config.fovValue
			end)
			fovState.applying = false
		end

		local function attachFovCamera()
			if _G.fov_value_conn then
				pcall(function()
					_G.fov_value_conn:Disconnect()
				end)
				_G.fov_value_conn = nil
			end
			if not _G.Config.enableFovChanger then
				return
			end
			local camera = workspace.CurrentCamera
			if not camera then
				return
			end
			rememberFov(camera)
			_G.fov_value_conn = camera:GetPropertyChangedSignal("FieldOfView"):Connect(function()
				if _G.Config.enableFovChanger and not fovState.applying then
					applyFov()
				end
			end)
			applyFov()
		end

		local function enableFovChanger()
			if fovState.cameraConnection then
				fovState.cameraConnection:Disconnect()
			end
			fovState.cameraConnection = workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
				task.defer(attachFovCamera)
			end)
			attachFovCamera()
		end

		_G.TheBestFovCleanup = restoreFov
		Library:CreateToggle(visualsSection, "Enable FOV Changer", _G.Config.enableFovChanger, function(val)
			_G.Config.enableFovChanger = val
			if not val then
				restoreFov()
			else
				enableFovChanger()
			end
			SaveConfig()
		end)
		Library:CreateSlider(visualsSection, "FOV Value", _G.Config.fovValue, 60, 120, function(v)
			_G.Config.fovValue = v
			if _G.Config.enableFovChanger then
				applyFov()
			end
			SaveConfig()
		end)
