local skyCache = {}
local skyRequestVersion = 0
local function prepareCatalogSky(name)
 if skyCache[name] then return skyCache[name] end
 local raw = SKYBOX_PRESETS[name]
 if not raw then return nil end
 local loader = getcustomasset or getsynasset
 assert(type(loader)=="function" and writefile and isfile, "Local skybox image API unavailable")
 ensureConfigFolder()
 local folder="thebest/skyboxes-v016-seam5"
 if makefolder and (not isfolder or not isfolder(folder)) then pcall(makefolder,folder) end
 local result = {CelestialBodiesShown=false,StarCount=0}
 for property, record in pairs(raw) do
  local file=folder.."/"..record.hash..".jpg"
  if not isfile(file) then writefile(file,decodeBase64(record.data)) end
  result[property]=loader(file)
  task.wait()
 end
 skyCache[name]=result
 return result
end

		if _G.Config.skyboxPreset=="Magenta Cloudscape" then _G.Config.skyboxPreset="Sunset Clouds HD" end
local function getCurrentSky()
			return Lighting:FindFirstChildOfClass("Sky")
		end

		local function captureOriginalSky()
			if skyboxState.original then
				return true
			end

			local sky = getCurrentSky()
			if not sky then
				sky = Instance.new("Sky")
				sky.Name = "TheBestSkybox"
				sky.Parent = Lighting
				skyboxState.original = {
					sky = sky,
					properties = {},
					created = true,
				}
				return true
			end

			local properties = {}
			for _, property in ipairs(SkyboxProperties) do
				properties[property] = sky[property]
			end

			skyboxState.original = {
				sky = sky,
				properties = properties,
				created = false,
			}
			return true
		end

		local function restoreOriginalSky()
			local data = skyboxState.original
			if not data or not data.sky then
				return
			end

			pcall(function()
				if data.created and data.sky.Parent then
					data.sky:Destroy()
					return
				end

				if data.sky.Parent then
					for _, property in ipairs(SkyboxProperties) do
						data.sky[property] = data.properties[property]
					end
				end
			end)
		end

		local SKYBOX_ALIASES = {}
		local function applySkyboxPreset(name)
			name = SKYBOX_ALIASES[name] or name
			if not skyboxActive then return false, "Skybox stopped" end
