		local function rememberAndSet(instance, property, value)
			if typeof(instance) ~= "Instance" then
				return
			end
			local propertyState = oldSoundsState.properties[instance]
			if not propertyState then
				propertyState = {}
				oldSoundsState.properties[instance] = propertyState
			end
			if propertyState[property] == nil then
				local readOk, originalValue = pcall(function()
					return instance[property]
				end)
				if not readOk then
					return
				end
				propertyState[property] = { value = originalValue }
			end
			pcall(function()
				instance[property] = value
			end)
		end
		local function snapshotAndClear(container)
			if typeof(container) ~= "Instance" then
				return
			end
			if not oldSoundsState.snapshots[container] then
				local cloned = nil
				local wasArchivable = container.Archivable
				pcall(function()
					container.Archivable = true
				end)
				local cloneOk, cloneResult = pcall(function()
					return container:Clone()
				end)
				pcall(function()
					container.Archivable = wasArchivable
				end)
				if cloneOk and cloneResult then
					cloned = cloneResult
					cloned.Parent = nil
				end
				if cloned then
					oldSoundsState.snapshots[container] = cloned
				else
					warn("[OLD SOUNDS AND ANIMATIONS] Could not back up " .. container:GetFullName())
					return
				end
			end
			for _, child in ipairs(container:GetChildren()) do
				child:Destroy()
			end
		end
		local function restoreOldSoundsAssets()
			for instance, propertyState in pairs(oldSoundsState.properties) do
				if typeof(instance) == "Instance" and instance.Parent then
					for property, stored in pairs(propertyState) do
						pcall(function()
							instance[property] = stored.value
						end)
					end
				end
			end
			for container, snapshot in pairs(oldSoundsState.snapshots) do
				if typeof(container) == "Instance" and container.Parent and snapshot then
					pcall(function()
						for _, child in ipairs(container:GetChildren()) do
							child:Destroy()
						end
						local restored = snapshot:Clone()
						for _, child in ipairs(restored:GetChildren()) do
							child.Parent = container
						end
						restored:Destroy()
					end)
				end
				pcall(function()
					snapshot:Destroy()
				end)
			end
			oldSoundsState.properties = {}
			oldSoundsState.snapshots = {}
		end
