					if not bestObject then
						return
					end
					target = bestObject
					targetRestoreImage = bestObject.Image
					if targetRestoreImage ~= "" then
						_G.TheBestGodLightningOriginalImage = targetRestoreImage
					end
					connections[#connections + 1] = target:GetPropertyChangedSignal("Image"):Connect(function()
						if active and not changingImage and target and target.Parent and target.Image ~= asset then
							if target.Image ~= "" then
								targetRestoreImage = target.Image
								_G.TheBestGodLightningOriginalImage = target.Image
							end
							applyTargetImage()
						end
					end)
					applyTargetImage()
				end

				connections[#connections + 1] = playerGui.DescendantAdded:Connect(function(object)
					if not isImageObject(object) then
						return
					end
					task.defer(function()
						if active and object.Parent then
							remember(object, true)
							chooseTarget()
						end
					end)
				end)

				local function cleanup()
					if not active then
						return
					end
					active = false
					for _, connection in ipairs(connections) do
						pcall(function()
							connection:Disconnect()
						end)
					end
					for object, properties in pairs(effectOriginalState) do
						if object.Parent then
							for property, state in pairs(properties) do
								pcall(function()
									object[property] = state.Value
								end)
							end
						end
					end
					if target and target.Parent then
						pcall(function()
							target.Image = targetRestoreImage
						end)
					end
					if _G.TheBestHomelanderFinisherCleanup == cleanup then
						_G.TheBestHomelanderFinisherCleanup = nil
					end
				end

				_G.TheBestHomelanderFinisherCleanup = cleanup
				for _, delayTime in ipairs({ 0, 0.04, 0.12, 0.35, 0.8, 1.5 }) do
					task.delay(delayTime, chooseTarget)
				end
				local duration = math.clamp(getFinisherLockDuration(data) + 0.25, 1, 6)
				task.delay(duration, cleanup)
				return cleanup
			end

			-- Golda uses its own visual and sound without invoking another finisher.
			local function beginGolda(data)
				if _G.TheBestHomelanderFinisherCleanup then
					pcall(_G.TheBestHomelanderFinisherCleanup)
					_G.TheBestHomelanderFinisherCleanup = nil
				end
				if _G.TheBestGoldaFinisherCleanup then
