				local soundAsset = assets.Sound
				if not imageAsset and not soundAsset then
					warn("[GOLDA] Image and sound assets are unavailable.")
					return nil
				end

				local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui") or LocalPlayer:WaitForChild("PlayerGui")
				local tweenService = game:GetService("TweenService")
				local soundService = game:GetService("SoundService")
				local active = true
				local anchorPart = nil
				local visualRoot = nil
				local imageObject = nil
				local customSound = nil

				local function resolveAdornee(value)
					if typeof(value) ~= "Instance" then
						return nil
					end
					if value:IsA("BasePart") or value:IsA("Attachment") then
						return value
					elseif value:IsA("Model") then
						return value.PrimaryPart
							or value:FindFirstChild("HumanoidRootPart")
							or value:FindFirstChild("Head")
							or value:FindFirstChildWhichIsA("BasePart", true)
					end
					return value:FindFirstAncestorWhichIsA("BasePart")
						or value:FindFirstChildWhichIsA("BasePart", true)
				end

				local function resolvePosition(value)
					if typeof(value) == "CFrame" then
						return value.Position
					elseif typeof(value) == "Vector3" then
						return value
					end
					local adornee = resolveAdornee(value)
					if adornee and adornee:IsA("Attachment") then
						return adornee.WorldPosition
					elseif adornee and adornee:IsA("BasePart") then
						return adornee.Position
					end
					return nil
				end

				if imageAsset then
					local adornee = resolveAdornee(data and data.Origin)
					if not adornee then
						local position = resolvePosition(data and data.Origin)
							or resolvePosition(data and data.User)
						if position then
							anchorPart = Instance.new("Part")
							anchorPart.Name = "TheBestGoldaFinisherAnchor"
							anchorPart.Anchored = true
							anchorPart.CanCollide = false
							anchorPart.CanTouch = false
							anchorPart.CanQuery = false
							anchorPart.CastShadow = false
							anchorPart.Transparency = 1
							anchorPart.Size = Vector3.new(0.2, 0.2, 0.2)
