						billboard.AlwaysOnTop = true
						billboard.LightInfluence = 0
						billboard.MaxDistance = 1000
						-- Scale components are measured in studs, so the visual keeps a fixed
						-- world size and becomes smaller with distance instead of appearing larger.
						billboard.Size = UDim2.fromScale(4.6, 3.5)
						billboard.StudsOffsetWorldSpace = Vector3.new(0, 4.6, 0)
						billboard.Parent = playerGui
						visualRoot = billboard

						local image = Instance.new("ImageLabel")
						image.Name = "Golda"
						image.Size = UDim2.fromScale(1, 1)
						image.BackgroundTransparency = 1
						image.Image = imageAsset
						image.ImageTransparency = 1
						image.ScaleType = Enum.ScaleType.Fit
						image.Parent = billboard
						imageObject = image
					else
						local screenGui = Instance.new("ScreenGui")
						screenGui.Name = "TheBestGoldaFinisherVisual"
						screenGui.IgnoreGuiInset = true
						screenGui.ResetOnSpawn = false
						screenGui.DisplayOrder = 900
						screenGui.Parent = playerGui
						visualRoot = screenGui

						local image = Instance.new("ImageLabel")
						image.Name = "Golda"
						image.AnchorPoint = Vector2.new(0.5, 0.5)
						image.Position = UDim2.fromScale(0.5, 0.24)
						image.Size = UDim2.fromOffset(92, 70)
						image.BackgroundTransparency = 1
						image.Image = imageAsset
						image.ImageTransparency = 1
						image.ScaleType = Enum.ScaleType.Fit
						image.Parent = screenGui
						imageObject = image
					end

					if imageObject then
						tweenService:Create(
							imageObject,
							TweenInfo.new(0.08, Enum.EasingStyle.Linear),
							{ ImageTransparency = 0 }
						):Play()
					end
				end

				if soundAsset then
					customSound = Instance.new("Sound")
					customSound.Name = "TheBestGoldaFinisherSound"
					customSound:SetAttribute("TheBestGoldaSound", true)
					customSound.SoundId = soundAsset
					customSound.Volume = 1
					customSound.Looped = false
					customSound.Parent = soundService
					customSound.Ended:Connect(function()
						if customSound then
							customSound:Destroy()
							customSound = nil
						end
					end)
					local played = pcall(function()
						customSound:Play()
					end)
					if not played then
						customSound:Destroy()
						customSound = nil
					end
				end

				local function cleanup()
					if not active then
						return
					end
					active = false
					if imageObject and imageObject.Parent then
						tweenService:Create(imageObject, TweenInfo.new(0.16), { ImageTransparency = 1 }):Play()
					end
					task.delay(0.17, function()
