function Xenon.Utils:IsMax(Item) 
    local Max = {
        ["Zeppeli's Hat"] = 25,
        ["Caesar's Headband"] = 25,
        ["Clackers"] = 25,
        ["Diamond"] = 30,
        ["Red Candy"] = 25,
        ["Yellow Candy"] = 25,
        ["Blue Candy"] = 25,
        ["Green Candy"] = 25,
        ["Gold Coin"] = 45,
        ["Mysterious Arrow"] = 25,
        ["Pure Rokakaka"] = 10,
        ["Rokakaka"] = 25,
        ["Stone Mask"] = 10,
        ["Rib Cage of The Saint's Corpse"] = 10,
        ["Steel Ball"] = 10,
        ["Ancient Scroll"] = 10,
        ["Dio's Diary"] = 10,
        ["Caesar's Headband"] = 10,
        ["Christmas Present"] = 45,
        ["Quinton's Glove"] = 10,
        ["Lucky Arrow"] = 10
    }
    if self:Has2X() then
