Misc_Arcade:Toggle("Auto Arcade", false, function(State)
    if State then
        -- ПЕРВЫЙ СКРИПТ: Отключение RollingItem
        local function DisableRollingItem()
            local GuiName = "RollingItem"
            local PlayerGui = game:GetService("Players").LocalPlayer.PlayerGui
            
            local function DisableScreenGui()
                local screenGui = PlayerGui:FindFirstChild(GuiName)
                if screenGui and screenGui:IsA("ScreenGui") then
                    screenGui.Enabled = false
                end
            end
            
            -- Запускаем отключение RollingItem
            Util:AddTask("DisableRollingItem", Util:GetService("RunService").RenderStepped:Connect(function()
                DisableScreenGui()
            end))
        end

        -- ВТОРОЙ СКРИПТ: Счетчик Gold Coin
        local function StartCoinCounter()
            local Players = game:GetService("Players")
            local UserInputService = game:GetService("UserInputService")
            local RunService = game:GetService("RunService")
            local LocalPlayer = Players.LocalPlayer

            local ItemName = "Gold Coin"
            local InventoryFolderName = "Backpack" 
            local ToggleKey = Enum.KeyCode.L

            local function FormatNumber(n)
                local s = tostring(math.floor(n))
                local formatted = s:reverse():gsub("...", "%0,"):reverse() 
                if formatted:sub(1, 1) == "," then
                    return formatted:sub(2)
                else
                    return formatted
                end
            end

            local InventoryPath = LocalPlayer:WaitForChild(InventoryFolderName, 10)
            if not InventoryPath then
                warn("Ошибка: Папка инвентаря '" .. InventoryFolderName .. "' не найдена.")
                return
            end

            local PlayerGui = LocalPlayer:WaitForChild("PlayerGui")
            
            -- Удаляем старый GUI если есть
            local oldGui = PlayerGui:FindFirstChild("CoinCounterGui")
            if oldGui then
                oldGui:Destroy()
            end

            local ScreenGui = Instance.new("ScreenGui")
            ScreenGui.Name = "CoinCounterGui"
            ScreenGui.Parent = PlayerGui
            ScreenGui.ResetOnSpawn = false
            ScreenGui.Enabled = true

            local TextLabel = Instance.new("TextLabel")
            TextLabel.Name = "CoinCountLabel"
            TextLabel.Size = UDim2.new(0.2, 0, 0.05, 0)
            TextLabel.Position = UDim2.new(0.8, 0, 0, 0)
            TextLabel.BackgroundTransparency = 0.7
            TextLabel.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
            TextLabel.TextColor3 = Color3.fromRGB(255, 223, 0)
            TextLabel.Font = Enum.Font.SourceSansBold
            TextLabel.TextSize = 20
            TextLabel.ZIndex = 2
            TextLabel.Parent = ScreenGui

            local function GetItemCount()
                local count = 0
                for _, item in ipairs(InventoryPath:GetChildren()) do
                    if item.Name == ItemName then
                        if item:IsA("IntValue") or item:IsA("NumberValue") then
                            count = count + item.Value
                        else
                            count = count + 1
                        end
                    end
                end
                return count
            end

            local function UpdateDisplay()
                local currentCount = GetItemCount()
                TextLabel.Text = ItemName .. ": " .. FormatNumber(currentCount) 
            end

            InventoryPath.ChildAdded:Connect(UpdateDisplay)
            InventoryPath.ChildRemoved:Connect(UpdateDisplay)

            Util:AddTask("CoinCounterUpdate", RunService.Heartbeat:Connect(function()
                if ScreenGui.Enabled then
                    UpdateDisplay()
                end
            end))

            UpdateDisplay()

            Util:AddTask("CoinCounterToggle", UserInputService.InputBegan:Connect(function(input, gameProcessedEvent)
                if gameProcessedEvent then return end
                if input.KeyCode == ToggleKey then
                    ScreenGui.Enabled = not ScreenGui.Enabled
                    print("Coin Counter " .. (ScreenGui.Enabled and "включен" or "выключен"))
                end
            end))
        end

        -- Запускаем оба скрипта
        DisableRollingItem()
        StartCoinCounter()

        -- Оригинальная функция Auto Arcade
        Util:AddTask("AutoArcade", Util:GetService("RunService").RenderStepped:Connect(function()
            if Util:GetPlayer().PlayerGui:FindFirstChild("RollingItem") == nil then
                Util:GetCharacter().RemoteEvent:FireServer("EndDialogue", {["NPC"] = "Item Machine", ["Option"] = "Option1", ["Dialogue"] = "Dialogue1"})
            end
            task.wait(1)
        end))

        Library:Notification("Auto Arcade", "Функция включена! Счетчик монет активирован (L для скрытия)", 5)

    else
        -- Очистка при выключении
        Util:DisconnectTask("AutoArcade")
        Util:DisconnectTask("DisableRollingItem")
        Util:DisconnectTask("CoinCounterUpdate")
        Util:DisconnectTask("CoinCounterToggle")
        
        -- Удаляем GUI счетчика
        local PlayerGui = game:GetService("Players").LocalPlayer.PlayerGui
        local coinCounter = PlayerGui:FindFirstChild("CoinCounterGui")
        if coinCounter then
            coinCounter:Destroy()
        end
        
        Library:Notification("Auto Arcade", "Функция выключена", 3)
    end     
end)

