		local function getLocalCameraSubject()
			local character = spectateLocalPlayer and spectateLocalPlayer.Character
			if not character then
				return nil
			end
			return character:FindFirstChildOfClass("Humanoid")
				or character:FindFirstChild("HumanoidRootPart")
				or character
		end

		local function restoreLocalCamera()
			local camera = spectateWorkspace.CurrentCamera
			local subject = getLocalCameraSubject()
			if camera and subject then
				pcall(function()
					camera.CameraType = Enum.CameraType.Custom
					camera.CameraSubject = subject
				end)
			end
		end

		local function getSpectateSubject(player)
			local character = player and player.Character
			if not character then
				return nil
			end
			return character:FindFirstChildOfClass("Humanoid")
				or character:FindFirstChild("HumanoidRootPart")
				or character:FindFirstChild("Head")
		end

		local applySpectateCamera
		local function bindSpectateCameraSubject()
			if spectateCameraSubjectConnection then
				spectateCameraSubjectConnection:Disconnect()
				spectateCameraSubjectConnection = nil
			end
			local camera = spectateWorkspace.CurrentCamera
			if not camera then
				return
			end
			spectateCameraSubjectConnection = camera:GetPropertyChangedSignal("CameraSubject"):Connect(function()
				if spectateEnabled then
					task.defer(applySpectateCamera)
				end
			end)
		end

		applySpectateCamera = function()
			if not spectateEnabled or not spectateTarget or spectateTarget.Parent ~= spectatePlayers then
				return false
			end
			local camera = spectateWorkspace.CurrentCamera
			local subject = getSpectateSubject(spectateTarget)
			if not camera or not subject then
				return false
			end
			pcall(function()
				camera.CameraType = Enum.CameraType.Custom
				if camera.CameraSubject ~= subject then
					camera.CameraSubject = subject
				end
			end)
			return true
		end

		local function disconnectSpectateTarget()
			if spectateTargetCharacterConnection then
				spectateTargetCharacterConnection:Disconnect()
				spectateTargetCharacterConnection = nil
			end
		end

		local function waitForSpectateCharacter(player, character)
			task.spawn(function()
				character = character or player.Character
				if not character then
					return
				end
				character:WaitForChild("Humanoid", 10)
				if spectateEnabled and spectateTarget == player and player.Character == character then
					applySpectateCamera()
				end
			end)
		end

		local function stopSpectating(restoreCamera)
			spectateEnabled = false
			spectateTarget = nil
			disconnectSpectateTarget()
			if spectateCameraSubjectConnection then
				spectateCameraSubjectConnection:Disconnect()
				spectateCameraSubjectConnection = nil
			end
			if spectateCurrentCameraConnection then
				spectateCurrentCameraConnection:Disconnect()
				spectateCurrentCameraConnection = nil
			end
			if restoreCamera ~= false then
				restoreLocalCamera()
			end
		end

		local function startSpectating(playerName)
			if type(_G.TheBestNpcFarmCameraStop) == "function" then _G.TheBestNpcFarmCameraStop() end
			local player = playerName and spectatePlayers:FindFirstChild(playerName) or nil
			if not player or player == spectateLocalPlayer then
				return false
			end

			disconnectSpectateTarget()
			spectateEnabled = true
			spectateTarget = player
			spectateTargetCharacterConnection = player.CharacterAdded:Connect(function(character)
				waitForSpectateCharacter(player, character)
			end)
			bindSpectateCameraSubject()
			if not spectateCurrentCameraConnection then
				spectateCurrentCameraConnection = spectateWorkspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
					if spectateEnabled then
						bindSpectateCameraSubject()
						task.defer(applySpectateCamera)
					end
				end)
			end
			if not applySpectateCamera() then
				waitForSpectateCharacter(player, player.Character)
			end
			return true
		end

		spectatePlayerRemovingConnection = spectatePlayers.PlayerRemoving:Connect(function(player)
			if spectateEnabled and player == spectateTarget then
				stopSpectating(true)
			end
		end)

		_G.TheBestSpectateCleanup = function()
			stopSpectating(true)
			if spectatePlayerRemovingConnection then
				spectatePlayerRemovingConnection:Disconnect()
				spectatePlayerRemovingConnection = nil
			end
		end
		_G.TheBestSpectateStart = function(playerName)
			return startSpectating(playerName)
		end
		_G.TheBestSpectateStop = function()
			if type(_G.TheBestNpcFarmCameraStop) == "function" then _G.TheBestNpcFarmCameraStop() end
			stopSpectating(true)
		end
