		task.spawn(function()
			local function getPlayerStatText(playerStats, statName)
				local stat = playerStats:FindFirstChild(statName)
				return stat and tostring(stat.Value) or "None"
			end
			local function buildEquipmentList(playerStats, equippedStatName, styleSlots)
				local equippedValue = getPlayerStatText(playerStats, equippedStatName)
				local equippedLabel = equippedValue .. " (equipped)"
				local list = { equippedLabel }
				local seen = { [string.lower(equippedValue)] = true }
				local slots = {}
				for _, item in ipairs(playerStats:GetChildren()) do
					local isStyleSlot = item.Name:match("StyleSlot") ~= nil
					if item.Name:match("Slot") and isStyleSlot == styleSlots then
						local succeeded, rawValue = pcall(function()
							return item.Value
						end)
						local value = succeeded and tostring(rawValue or "") or ""
						local normalized = string.lower(value)
						if value ~= "" and normalized ~= "none" and not seen[normalized] then
							seen[normalized] = true
							table.insert(slots, { Name = item.Name, Value = value })
						end
					end
				end
				table.sort(slots, function(left, right)
					return left.Name < right.Name
				end)
				for _, slot in ipairs(slots) do
					table.insert(list, slot.Value)
				end
				return list, equippedLabel
			end
			local displayedPlayerName = nil
			local displayedStand = nil
			local displayedSpec = nil
			while true do
				local succ, err = pcall(function()
					local infoPlayerName = playerlist_player
					local equippedStandLabel = "None (equipped)"
					local equippedSpecLabel = "None (equipped)"
					playerStandsList = { equippedStandLabel }
					playerSpecsList = { equippedSpecLabel }
					local player = infoPlayerName and game:GetService("Players"):FindFirstChild(infoPlayerName)
						or nil
					if player then
						local playerStats = player:FindFirstChild("PlayerStats")
						if playerStats then
							playerPrestigeList = { getPlayerStatText(playerStats, "Prestige") }
							playerLvlList = { getPlayerStatText(playerStats, "Level") }
							playerGangList = { getPlayerStatText(playerStats, "Gang") }
							playerMoneyList = { getPlayerStatText(playerStats, "Money") }
							playerStandsList, equippedStandLabel = buildEquipmentList(playerStats, "Stand", false)
							playerSpecsList, equippedSpecLabel = buildEquipmentList(playerStats, "Spec", true)
						end
					end
					local plr = playerlist_player and game:GetService("Players"):FindFirstChild(playerlist_player)
						or nil
					if plr then
						local backpack = plr:FindFirstChild("Backpack")
						if backpack then
							local counts = {}
							playerBackpackList = {}
							for _, item in ipairs(backpack:GetChildren()) do
								local name = item.Name
								counts[name] = (counts[name] or 0) + 1
							end
							for name, count in pairs(counts) do
								table.insert(playerBackpackList, name .. " x" .. count)
							end
						end
					end
					updateDropdownItems(playerMoney, playerMoneyList)
					updateDropdownItems(playerPrestige, playerPrestigeList)
					updateDropdownItems(playerLvl, playerLvlList)
					updateDropdownItems(playerGang, playerGangList)
					updateDropdownItems(playerStands, playerStandsList)
					updateDropdownItems(playerSpecs, playerSpecsList)
					if infoPlayerName ~= displayedPlayerName or equippedStandLabel ~= displayedStand then
						playerStands.SetValue(equippedStandLabel)
					end
					if infoPlayerName ~= displayedPlayerName or equippedSpecLabel ~= displayedSpec then
						playerSpecs.SetValue(equippedSpecLabel)
					end
					displayedPlayerName = infoPlayerName
					displayedStand = equippedStandLabel
					displayedSpec = equippedSpecLabel
					updateDropdownItems(playerBackpack, playerBackpackList)
					playersOnServer = {}
					for _, player in ipairs(game:GetService("Players"):GetPlayers()) do
						if player.Name == _G.Config.input_TargetSurvName then
							if #playersOnServer >= 1 then
								table.insert(playersOnServer, 2, player.Name .. " (selected)")
							else
								table.insert(playersOnServer, player.Name .. " (selected)")
							end
							if _G.Config.playersInfo_selectedOnly then
								playerlist_player = player.Name
							end
						else
							table.insert(playersOnServer, player.Name)
						end
					end
					if
						(not playerlist_player or not game:GetService("Players"):FindFirstChild(playerlist_player))
						and #playersOnServer > 0
					then
						playerlist_player = playersOnServer[1]:gsub("%s*%(selected%)%s*", ""):match("^%s*(.-)%s*$")
					end
					updateDropdownItems(playerList, playersOnServer)
				end)
				if not succ then
					warn("[player list] " .. err)
				end
				task.wait(1)
			end
		end)
