					if value ~= "English" and value ~= "Russian" then
						task.defer(function()
							if languageDropdown then
								languageDropdown.SetValue(Library:GetLanguage())
							end
						end)
						return
					end
					Library:SetLanguage(value)
					SaveConfig()
					if languageStatus then
						languageStatus.SetText(
							value == "Russian"
								and "Russian localization is active."
								or "English is the original interface language."
						)
					end
				end,
				true,
				true
			)
			languageStatus = Library:CreateStatusLabel(
				languageSection,
				currentLanguage == "Russian"
					and "Russian localization is active."
					or "English is the original interface language."
			)
			Library:CreateStatusLabel(
				languageSection,
				"Language changes are applied immediately and saved in the config."
			)
		end
