		function SaveModel()
			local stand = getStandMorph1()
			if not stand then
				warn("StandMorph not found")
				return
			end
			for _, obj in ipairs(stand:GetDescendants()) do
				if obj:IsA("Attachment") then
					obj:SetAttribute("SaveID", nil)
				end
			end
			local usedAttachments = {}
			for _, obj in ipairs(stand:GetDescendants()) do
				if obj:IsA("Beam") or obj:IsA("Trail") then
					if obj.Attachment0 then
						usedAttachments[obj.Attachment0] = true
					end
					if obj.Attachment1 then
						usedAttachments[obj.Attachment1] = true
					end
				end
			end
			local modelData = {}
			pcall(function()
				local upperTorso = stand:FindFirstChild("UpperTorso")
				local gearModel = stand:FindFirstChild("Gear")
				if gearModel and upperTorso then
					local gearMesh = nil
					if gearModel:IsA("Model") then
						gearMesh = gearModel:FindFirstChildWhichIsA("MeshPart")
					elseif gearModel:IsA("MeshPart") then
						gearMesh = gearModel
					end
					if gearMesh then
						if not modelData["_Gear"] then
							modelData["_Gear"] = { Children = {} }
						end
						table.insert(modelData["_Gear"].Children, saveInstance(gearMesh, upperTorso))
					end
				end
			end)
			for _, partName in ipairs(allSaveParts) do
				local part = stand:FindFirstChild(partName)
				if part then
					local partData = { Children = {} }
					for _, child in ipairs(part:GetChildren()) do
						if visualClasses[child.ClassName] then
							if child:IsA("Attachment") then
								if hasParticleEmitterInside(child) or usedAttachments[child] then
									table.insert(partData.Children, saveInstance(child, part))
								end
							elseif child:IsA("Model") then
							else
								table.insert(partData.Children, saveInstance(child, part))
							end
						end
					end
					modelData[partName] = partData
				end
			end
			for _, obj in ipairs(stand:GetDescendants()) do
				if obj:IsA("Folder") and obj.Name:find("_Extra_Parts$") then
					local targetPartName = obj.Name:gsub("_Extra_Parts$", "")
					if not modelData[targetPartName] then
						modelData[targetPartName] = { Children = {} }
					end
					for _, child in ipairs(obj:GetChildren()) do
						if visualClasses[child.ClassName] then
							table.insert(
								modelData[targetPartName].Children,
								saveInstance(child, stand:FindFirstChild(targetPartName))
							)
						end
					end
				end
			end
			local highlightsData = {}
			for _, obj in ipairs(stand:GetDescendants()) do
				if obj:IsA("Highlight") then
					table.insert(highlightsData, saveInstance(obj, stand))
				end
			end
			if #highlightsData > 0 then
				modelData["_Highlights"] = { Children = highlightsData }
			end
			local targetPlayer = nil
			for _, player in ipairs(Players:GetPlayers()) do
				if player.Name:lower():find(_G.ADMINDEBUG_name:lower(), 1, true) then
					targetPlayer = player
					break
				end
			end
			if targetPlayer and targetPlayer.Character then
				local playerAuras = {}
				for _, part in ipairs(targetPlayer.Character:GetChildren()) do
					if part:IsA("BasePart") then
						for _, child in ipairs(part:GetChildren()) do
							if
								(child:IsA("Attachment") or child:IsA("ParticleEmitter"))
								and (child.Name:find("StandAura") or child.Name:find("Aura"))
							then
								local auraData = saveInstance(child, part)
								auraData.Properties.ParentPartName = part.Name
								table.insert(playerAuras, auraData)
								break
							end
						end
					end
				end
				if #playerAuras > 0 then
					modelData["_PlayerAuras"] = { Children = playerAuras }
					print("Saved " .. #playerAuras .. " StandAura attachments from " .. _G.ADMINDEBUG_name)
				end
			end
			if not isfolder("ssoc_skins") then
				makefolder("ssoc_skins")
			end
			local json = HttpService:JSONEncode(modelData)
			local encoded = encodeData(json)
			writefile("ssoc_skins/model.ssoc", encoded)
			print("Saved! (encrypted .ssoc + StandAura)")
		end
		local BASE_STAND_NAME_ALIASES = {
			magicansred = { "magiciansred" },
			chillipepperalternateuniverse = {
				"chilipepperalternateuniverse",
				"redhotchilipepper",
				"redhotchilipepperalternateuniverse",
			},
		}
		local function normalizeBaseStandName(value)
			return string.lower(tostring(value or ""):gsub("[^%w]", ""))
		end
		local function getBaseStandSearchNames(targetName)
			local normalized = normalizeBaseStandName(targetName)
			local names = { [normalized] = true }
			for _, alias in ipairs(BASE_STAND_NAME_ALIASES[normalized] or {}) do
				names[alias] = true
			end
			return names
		end
		local function baseStandNameMatches(value, searchNames)
			return searchNames[normalizeBaseStandName(value)] == true
		end
		local function scoreBaseStandTemplate(model, searchNames, standsFolder)
			if not model:IsA("Model") then
				return nil
			end
			local torso = model:FindFirstChild("UpperTorso") or model:FindFirstChild("Torso")
			if not torso or not torso:IsA("BasePart") then
				return nil
			end
			local bodyPartCount = 0
			for _, child in ipairs(model:GetChildren()) do
				if child:IsA("BasePart") then
					bodyPartCount += 1
				end
			end
			if bodyPartCount < 6 then
				return nil
			end
			local matched = false
			local score = bodyPartCount * 2
			if baseStandNameMatches(model.Name, searchNames) then
				matched = true
				score += 500
			end
			local standValue = model:FindFirstChild("Stand Name", true)
			if standValue and standValue:IsA("StringValue") and baseStandNameMatches(standValue.Value, searchNames) then
				matched = true
				score += 800
			end
			local ancestor = model.Parent
			while ancestor and ancestor ~= game do
				if baseStandNameMatches(ancestor.Name, searchNames) then
					matched = true
					score += 350
					break
				end
				ancestor = ancestor.Parent
			end
			if not matched then
				return nil
			end
			if standsFolder and model:IsDescendantOf(standsFolder) then
				score += 150
			end
			return score
		end
local function findBaseStandTemplate(targetName)
 local replicatedStorage = game:GetService("ReplicatedStorage")
 local standsFolder = replicatedStorage:FindFirstChild("Stands")
 local searchNames = getBaseStandSearchNames(targetName)
 local bestModel, bestScore = nil, -math.huge
 local roots = {replicatedStorage}
 local world = game:GetService("Workspace")
 local living = world:FindFirstChild("Living")
 if living then table.insert(roots, living) end
 local ignored = world:FindFirstChild("IgnoreInstances")
 local morphs = ignored and ignored:FindFirstChild("StandMorphs")
 if morphs then table.insert(roots, morphs) end
 local visited, count = {}, 0
 for _, root in ipairs(roots) do
  for _, object in ipairs(root:GetDescendants()) do
   count += 1
   if object:IsA("Model") and not visited[object] then
    visited[object] = true
    local ancestor, custom = object, false
    while ancestor and ancestor ~= root.Parent do
     if ancestor:GetAttribute("TheBestSkinCustom") or ancestor.Name:match("_Custom$") then custom=true; break end
     ancestor = ancestor.Parent
    end
    if not custom then
     local score = scoreBaseStandTemplate(object, searchNames, standsFolder)
     -- The game keeps the skin identity on StandMorph.StandSkin, not its generic model name.
     local skinValue = object:FindFirstChild("StandSkin") or object:FindFirstChild("Skin")
     local skinName = skinValue and skinValue:IsA("StringValue") and skinValue.Value
     local exactSkin = skinName and skinName ~= "None" and baseStandNameMatches(skinName, searchNames)
     local attributeSkin = object:GetAttribute("StandSkin") or object:GetAttribute("Skin")
     if attributeSkin and baseStandNameMatches(attributeSkin, searchNames) then exactSkin = true end
     if exactSkin then
      -- Reuse the same compatible-body check before serializing a living stand.
      local names = {[normalizeBaseStandName(object.Name)]=true}
      local compatibleScore = scoreBaseStandTemplate(object, names, standsFolder)
      if compatibleScore then score=compatibleScore+1600 end
     elseif root ~= replicatedStorage then
      -- A living base stand with a different skin must never impersonate the requested skin.
      score = nil
     end
     if score and score > bestScore then bestModel,bestScore=object,score end
    end
   end
   if count % 600 == 0 then game:GetService("RunService").Heartbeat:Wait() end
  end
 end
 return bestModel
end

		local function isExistingCustomStandObject(object)
			local current = object
			while current do
				if current:GetAttribute("TheBestSkinCustom") or current.Name:find("_Custom$") then
					return true
				end
				current = current.Parent
			end
			return false
		end
		local function markBaseStandPartData(data)
			if type(data) ~= "table" then
				return
			end
			if data.ClassName == "MeshPart" or data.ClassName == "Part" then
				data.Properties = data.Properties or {}
				data.Properties.PreserveSize = true
			end
			for _, childData in ipairs(data.Children or {}) do
				markBaseStandPartData(childData)
			end
		end
		local function isVisibleTemplatePart(part)
			if part.Transparency < 0.999 then
				return true
			end
			if part:IsA("MeshPart") and tostring(part.MeshId or "") ~= "" then
				return true
			end
			for _, object in ipairs(part:GetDescendants()) do
				if
					object:IsA("SpecialMesh")
					or object:IsA("Decal")
					or object:IsA("Texture")
					or object:IsA("SurfaceAppearance")
					or object:IsA("ParticleEmitter")
					or object:IsA("Beam")
					or object:IsA("Trail")
				then
					return true
				end
			end
			return false
		end
		local function buildBaseStandModelData(standTemplate)
			local usedAttachments = {}
			for _, object in ipairs(standTemplate:GetDescendants()) do
				if object:IsA("Beam") or object:IsA("Trail") then
					if object.Attachment0 then
						usedAttachments[object.Attachment0] = true
					end
					if object.Attachment1 then
						usedAttachments[object.Attachment1] = true
					end
				end
			end
			local modelData = {}
			local directBodyParts = {}
			for _, partName in ipairs(allSaveParts) do
				local part = standTemplate:FindFirstChild(partName)
				if part and part:IsA("BasePart") then
					directBodyParts[part] = partName
					local partData = { Children = {} }
					if partName ~= "HumanoidRootPart" and isVisibleTemplatePart(part) then
						local bodyData = saveInstance(part, part)
						bodyData.Children = {}
						markBaseStandPartData(bodyData)
						for _, child in ipairs(part:GetChildren()) do
							if
								visualClasses[child.ClassName]
								and not child:IsA("BasePart")
								and not child:IsA("Model")
								and not child:IsA("Weld")
								and not child:IsA("WeldConstraint")
								and not isExistingCustomStandObject(child)
							then
								if not child:IsA("Attachment")
									or hasParticleEmitterInside(child)
									or usedAttachments[child]
								then
									table.insert(bodyData.Children, saveInstance(child, part))
								end
							end
						end
						table.insert(partData.Children, bodyData)
					end
					for _, descendant in ipairs(part:GetDescendants()) do
						if descendant:IsA("BasePart") and not isExistingCustomStandObject(descendant) then
							local nearestBasePart = descendant.Parent
							while nearestBasePart and nearestBasePart ~= part and not nearestBasePart:IsA("BasePart") do
								nearestBasePart = nearestBasePart.Parent
							end
							if nearestBasePart == part and isVisibleTemplatePart(descendant) then
								local extraData = saveInstance(descendant, part)
								markBaseStandPartData(extraData)
								table.insert(partData.Children, extraData)
							end
						end
					end
					modelData[partName] = partData
				end
			end
			local bodyPartList = {}
			for bodyPart in pairs(directBodyParts) do
				table.insert(bodyPartList, bodyPart)
			end
			for _, descendant in ipairs(standTemplate:GetDescendants()) do
				if
					descendant:IsA("BasePart")
					and not directBodyParts[descendant]
					and not isExistingCustomStandObject(descendant)
					and isVisibleTemplatePart(descendant)
				then
					local insideKnownBody = false
					for bodyPart in pairs(directBodyParts) do
						if descendant:IsDescendantOf(bodyPart) then
							insideKnownBody = true
							break
						end
					end
					local parentBasePart = descendant.Parent
					while parentBasePart and parentBasePart ~= standTemplate and not parentBasePart:IsA("BasePart") do
						parentBasePart = parentBasePart.Parent
					end
					if not insideKnownBody and (not parentBasePart or parentBasePart == standTemplate) then
						local closestPart = nil
						local closestDistance = math.huge
						for _, bodyPart in ipairs(bodyPartList) do
							local distance = (bodyPart.Position - descendant.Position).Magnitude
							if distance < closestDistance then
								closestPart = bodyPart
								closestDistance = distance
							end
						end
						if closestPart then
							local targetName = directBodyParts[closestPart]
							modelData[targetName] = modelData[targetName] or { Children = {} }
							local extraData = saveInstance(descendant, closestPart)
							markBaseStandPartData(extraData)
							table.insert(modelData[targetName].Children, extraData)
						end
					end
				end
			end
			local highlightsData = {}
			for _, object in ipairs(standTemplate:GetDescendants()) do
				if object:IsA("Highlight") and not isExistingCustomStandObject(object) then
					table.insert(highlightsData, saveInstance(object, standTemplate))
				end
			end
			if #highlightsData > 0 then
				modelData._Highlights = { Children = highlightsData }
			end
			return modelData
		end
		_G.TheBestBaseStandModelDataCache = type(_G.TheBestBaseStandModelDataCache) == "table"
			and _G.TheBestBaseStandModelDataCache
			or {}
		local function getBaseStandModelData(targetName)
			local cacheKey = normalizeBaseStandName(targetName)
			local cached = _G.TheBestBaseStandModelDataCache[cacheKey]
			if type(cached) == "table" then
				return cached
			end
			local template = findBaseStandTemplate(targetName)
			if not template then
				return nil, "Base model for " .. tostring(targetName) .. " was not found in ReplicatedStorage."
			end
			local modelData = buildBaseStandModelData(template)
			_G.TheBestBaseStandModelDataCache[cacheKey] = modelData
			return modelData
		end
		local function loadProp(data)
			if type(data) == "table" and data.__t then
				local t = data.__t
				local v = data.v
				if t == "Vector3" then
					return Vector3.new(v[1], v[2], v[3])
				elseif t == "Vector2" then
					return Vector2.new(v[1], v[2])
				elseif t == "Color3" then
					return Color3.new(v[1], v[2], v[3])
				elseif t == "CFrame" then
					return CFrame.new(table.unpack(v))
				elseif t == "NumberRange" then
					return NumberRange.new(v[1], v[2])
				elseif t == "NumberSequence" then
					local keys = {}
					for _, p in ipairs(v) do
						table.insert(keys, NumberSequenceKeypoint.new(p.Time, p.Value, p.Envelope or 0))
					end
					return NumberSequence.new(keys)
				elseif t == "ColorSequence" then
					local keys = {}
					for _, p in ipairs(v) do
						table.insert(
							keys,
							ColorSequenceKeypoint.new(p.Time, Color3.new(p.Color[1], p.Color[2], p.Color[3]))
						)
					end
					return ColorSequence.new(keys)
				elseif t == "BrickColor" then
					return BrickColor.new(v)
				elseif t == "Enum" then
					local parts = {}
					for part in string.gmatch(v, "[^%.]+") do
						table.insert(parts, part)
					end
					if #parts >= 3 then
						local enumName = parts[2]
						local valueName = parts[3]
						local success, result = pcall(function()
							return Enum[enumName][valueName]
						end)
						if success then
							return result
						end
					end
				end
			end
			return data
		end
		local function applyProps(inst, props, children)
			local function decodeStandProperty(propertyName, value)
				local decoded = loadProp(value)
				if type(decoded) ~= "string" then
					return decoded
				end
				if
					propertyName ~= "MeshId"
					and propertyName ~= "TextureID"
					and propertyName ~= "TextureId"
					and propertyName ~= "Texture"
					and propertyName ~= "ColorMap"
					and propertyName ~= "MetalnessMap"
					and propertyName ~= "NormalMap"
					and propertyName ~= "RoughnessMap"
					and propertyName ~= "ShirtTemplate"
					and propertyName ~= "PantsTemplate"
					and propertyName ~= "Graphic"
				then
					return decoded
				end
				local trimmed = decoded:match("^%s*(.-)%s*$")
				local assetId = trimmed:match("^(%d+)$")
					or trimmed:match("rbxassetid://(%d+)")
					or trimmed:match("[?&]id=(%d+)")
				if assetId then
					return "rbxassetid://" .. assetId
				end
				return trimmed
			end
			if inst:IsA("MeshPart") or inst:IsA("Part") then
				if inst:IsA("MeshPart") and props.MeshId then
					pcall(function()
						inst.MeshId = decodeStandProperty("MeshId", props.MeshId)
					end)
				end
				if inst:IsA("MeshPart") and props.TextureID then
					pcall(function()
						inst.TextureID = decodeStandProperty("TextureID", props.TextureID)
					end)
				end
				for prop, value in pairs(props) do
					if
						prop ~= "RelativeCFrame"
						and prop ~= "MeshId"
						and prop ~= "TextureID"
						and prop ~= "SizeOrig"
						and prop ~= "HasDecalChild"
						and prop ~= "Attachment0CF"
						and prop ~= "Attachment1CF"
						and prop ~= "Attachment0ID"
						and prop ~= "Attachment1ID"
						and prop ~= "AttachmentID"
						and prop ~= "RelativeToStand"
						and prop ~= "Position"
						and prop ~= "Orientation"
						and prop ~= "Transform"
						and prop ~= "PreserveSize"
					then
						local decoded = decodeStandProperty(prop, value)
						if decoded ~= nil then
							pcall(function()
								inst[prop] = decoded
							end)
						end
					end
				end
				local hasDecalChild = false
				if children then
					for _, child in ipairs(children) do
						if child.ClassName == "Decal" then
							hasDecalChild = true
							break
						end
					end
				end
				if props.PreserveSize and props.SizeOrig then
					pcall(function()
						inst.Size = loadProp(props.SizeOrig)
					end)
				elseif hasDecalChild then
					pcall(function()
						inst.Size = Vector3.new(1.1, 1.1, 1.1)
					end)
				else
					pcall(function()
						inst.Size = Vector3.new(1, 1, 1)
					end)
				end
			elseif inst:IsA("SpecialMesh") then
				for prop, value in pairs(props) do
					local decoded = decodeStandProperty(prop, value)
					if decoded ~= nil then
						pcall(function()
							inst[prop] = decoded
						end)
					end
				end
			elseif inst:IsA("Bone") then
				if props.Transform then
					pcall(function()
						inst.Transform = loadProp(props.Transform)
					end)
				end
			elseif inst:IsA("Weld") or inst:IsA("WeldConstraint") then
				if props.Part0Name then
					inst:SetAttribute("WeldPart0", props.Part0Name)
				end
				if props.Part1Name then
					inst:SetAttribute("WeldPart1", props.Part1Name)
				end
				for prop, value in pairs(props) do
					if prop ~= "Part0Name" and prop ~= "Part1Name" then
						local decoded = loadProp(value)
						if decoded ~= nil then
							pcall(function()
								inst[prop] = decoded
							end)
						end
					end
				end
			elseif inst:IsA("Highlight") then
				for prop, value in pairs(props) do
					local decoded = loadProp(value)
					if decoded ~= nil then
						pcall(function()
							inst[prop] = decoded
						end)
					end
				end
			elseif inst:IsA("PointLight") then
				for prop, value in pairs(props) do
					if prop ~= "RelativeCFrame" then
						local decoded = loadProp(value)
						if decoded ~= nil then
							pcall(function()
								inst[prop] = decoded
							end)
						end
					end
				end
			elseif inst:IsA("Attachment") then
				if props.Position then
					pcall(function()
						inst.Position = loadProp(props.Position)
					end)
				end
				if props.Orientation then
					pcall(function()
						inst.Orientation = loadProp(props.Orientation)
					end)
				end
			elseif inst:IsA("Decal") then
				for prop, value in pairs(props) do
					if prop ~= "RelativeCFrame" then
						local decoded = decodeStandProperty(prop, value)
						if decoded ~= nil then
							pcall(function()
								inst[prop] = decoded
							end)
						end
					end
				end
			elseif inst:IsA("Texture") then
				for prop, value in pairs(props) do
					local decoded = decodeStandProperty(prop, value)
					if decoded ~= nil then
						pcall(function()
							inst[prop] = decoded
						end)
					end
				end
			elseif inst:IsA("SurfaceAppearance") then
				for prop, value in pairs(props) do
					local decoded = decodeStandProperty(prop, value)
					if decoded ~= nil then
						pcall(function()
							inst[prop] = decoded
						end)
					end
				end
			elseif inst:IsA("Beam") then
				for prop, value in pairs(props) do
					if
						prop ~= "Attachment0CF"
						and prop ~= "Attachment1CF"
						and prop ~= "Attachment0ID"
						and prop ~= "Attachment1ID"
					then
						local decoded = decodeStandProperty(prop, value)
						if decoded ~= nil then
							pcall(function()
								inst[prop] = decoded
							end)
						end
					end
				end
			elseif inst:IsA("Trail") then
				for prop, value in pairs(props) do
					if
						prop ~= "Attachment0CF"
						and prop ~= "Attachment1CF"
						and prop ~= "Attachment0ID"
						and prop ~= "Attachment1ID"
					then
						local decoded = decodeStandProperty(prop, value)
						if decoded ~= nil then
							pcall(function()
								inst[prop] = decoded
							end)
						end
					end
				end
			elseif inst:IsA("ParticleEmitter") then
				for prop, value in pairs(props) do
					local decoded = decodeStandProperty(prop, value)
					if decoded ~= nil then
						pcall(function()
							inst[prop] = decoded
						end)
					end
				end
			end
		end
		local function createFromData(parent, childData)
			if childData.ClassName == "Model" then
				for _, subData in ipairs(childData.Children or {}) do
					if subData.ClassName == "Attachment" then
						createFromData(parent, subData)
					end
				end
				for _, subData in ipairs(childData.Children or {}) do
					if subData.ClassName == "Beam" or subData.ClassName == "Trail" then
						createFromData(parent, subData)
					end
				end
				for _, subData in ipairs(childData.Children or {}) do
					if
						subData.ClassName ~= "Attachment"
						and subData.ClassName ~= "Beam"
						and subData.ClassName ~= "Trail"
					then
						createFromData(parent, subData)
					end
				end
			elseif childData.ClassName == "Attachment" then
				local attachment = Instance.new("Attachment")
				attachment.Name = (childData.Name or "Attachment") .. "_Custom"
				attachment:SetAttribute("TheBestSkinCustom", true)
				attachment.Parent = parent
				if childData.Properties and childData.Properties.AttachmentID then
					attachmentCache[childData.Properties.AttachmentID] = attachment
				end
				if childData.Properties and childData.Properties.RelativeCFrame then
					local parentCF = parent:IsA("Model") and parent:GetPivot() or parent.CFrame
					local relCF = loadProp(childData.Properties.RelativeCFrame)
					attachment.CFrame = relCF
				end
				if childData.Properties then
					applyProps(attachment, childData.Properties)
				end
				for _, subData in ipairs(childData.Children or {}) do
					createFromData(attachment, subData)
				end
			elseif childData.ClassName == "Beam" then
				local beam = Instance.new("Beam")
				beam.Name = (childData.Name or "Beam") .. "_Custom"
				beam:SetAttribute("TheBestSkinCustom", true)
				beam.Parent = parent
				if childData.Properties then
					if childData.Properties.Attachment0ID then
						beam:SetAttribute("A0", childData.Properties.Attachment0ID)
					end
					if childData.Properties.Attachment1ID then
						beam:SetAttribute("A1", childData.Properties.Attachment1ID)
					end
					applyProps(beam, childData.Properties)
				end
			elseif childData.ClassName == "Trail" then
				local trail = Instance.new("Trail")
				trail.Name = (childData.Name or "Trail") .. "_Custom"
				trail:SetAttribute("TheBestSkinCustom", true)
				trail.Parent = parent
				if childData.Properties then
					if childData.Properties.Attachment0ID then
						trail:SetAttribute("A0", childData.Properties.Attachment0ID)
					end
					if childData.Properties.Attachment1ID then
						trail:SetAttribute("A1", childData.Properties.Attachment1ID)
					end
					applyProps(trail, childData.Properties)
				end
			elseif childData.ClassName == "Bone" then
				local bone = Instance.new("Bone")
				bone.Name = (childData.Name or "Bone") .. "_Custom"
				bone:SetAttribute("TheBestSkinCustom", true)
				bone.Parent = parent
				applyProps(bone, childData.Properties or {})
				for _, subData in ipairs(childData.Children or {}) do
					createFromData(bone, subData)
				end
			elseif childData.ClassName == "Highlight" then
				local highlight = Instance.new("Highlight")
				highlight.Name = (childData.Name or "Highlight") .. "_Custom"
				highlight:SetAttribute("TheBestSkinCustom", true)
				highlight.Parent = parent
				applyProps(highlight, childData.Properties or {})
			elseif childData.ClassName == "Weld" or childData.ClassName == "WeldConstraint" then
				local weld = Instance.new(childData.ClassName)
				weld.Name = (childData.Name or childData.ClassName) .. "_Custom"
				weld:SetAttribute("TheBestSkinCustom", true)
				weld.Parent = parent
				applyProps(weld, childData.Properties or {})
			elseif childData.ClassName == "PointLight" then
				local light = Instance.new("PointLight")
				light.Name = (childData.Name or "PointLight") .. "_Custom"
				light:SetAttribute("TheBestSkinCustom", true)
				light.Parent = parent
				applyProps(light, childData.Properties or {})
				if childData.Properties and childData.Properties.RelativeCFrame then
					local parentCF = parent:IsA("Model") and parent:GetPivot() or parent.CFrame
					local relCF = loadProp(childData.Properties.RelativeCFrame)
					light.CFrame = parentCF * relCF
				end
			elseif childData.ClassName == "MeshPart" or childData.ClassName == "Part" then
				local child = Instance.new(childData.ClassName)
				child.Name = (childData.Name or childData.ClassName) .. "_Custom"
				child:SetAttribute("TheBestSkinCustom", true)
				child.Parent = parent
				applyProps(child, childData.Properties or {}, childData.Children or {})
				child.Anchored = false
				child.CanCollide = false
				child.CanTouch = false
				child.CanQuery = false
				child.Massless = true
				for _, subData in ipairs(childData.Children or {}) do
					if subData.ClassName == "Attachment" then
						createFromData(child, subData)
					end
				end
				for _, subData in ipairs(childData.Children or {}) do
					if subData.ClassName == "Beam" or subData.ClassName == "Trail" then
						createFromData(child, subData)
					end
				end
				for _, subData in ipairs(childData.Children or {}) do
					if
						subData.ClassName ~= "Attachment"
						and subData.ClassName ~= "Beam"
						and subData.ClassName ~= "Trail"
					then
						createFromData(child, subData)
					end
				end
				if childData.Properties and childData.Properties.RelativeCFrame then
					local parentCF = parent:IsA("Model") and parent:GetPivot()
						or (parent:IsA("Attachment") and parent.WorldCFrame or parent.CFrame)
					local relCF = loadProp(childData.Properties.RelativeCFrame)
					child.CFrame = parentCF * relCF
				end
				if parent:IsA("BasePart") then
					local weld = Instance.new("Weld")
					weld.Part0 = parent
					weld.Part1 = child
					local relative = parent.CFrame:ToObjectSpace(child.CFrame)
					weld.C0 = relative
					weld.C1 = CFrame.new()
					weld.Parent = child
				end
			elseif childData.ClassName == "Decal" then
				local decal = Instance.new("Decal")
				decal.Name = (childData.Name or "Decal") .. "_Custom"
				decal:SetAttribute("TheBestSkinCustom", true)
				decal.Parent = parent
				applyProps(decal, childData.Properties or {})
			else
				local child = Instance.new(childData.ClassName)
				child.Name = (childData.Name or childData.ClassName) .. "_Custom"
				child:SetAttribute("TheBestSkinCustom", true)
				child.Parent = parent
				applyProps(child, childData.Properties or {})
