		local skinAuraData, auraCharacter, appliedAura, auraVersion, appliedVersion = nil,nil,nil,0,-1
		local auraRoots={}
		local standEffectEnabled=setmetatable({}, {__mode="k"})
		local function clearAllPlayerAuras()
			for _,root in ipairs(auraRoots) do pcall(function() root:Destroy() end) end
			table.clear(auraRoots);appliedAura=nil;appliedVersion=-1
			local char=LocalPlayer.Character
			if not char then return end
			-- Only earlier TheBest imports, never the game's original character effects.
			for _,part in ipairs(char:GetChildren()) do
				if part:IsA("BasePart") then
					for _,child in ipairs(part:GetChildren()) do
						if child.Name:match("_Custom$") and (child.Name:find("Aura") or child:GetAttribute("TheBestSkinAura")) then child:Destroy() end
					end
				end
			end
		end
		local function updateSkinAura()
			local char=LocalPlayer.Character
			local hum=char and char:FindFirstChildOfClass("Humanoid")
			local summoned=char and char:FindFirstChild("SummonedStand")
			local living=workspace:FindFirstChild("Living")
			local playerModel=living and living:FindFirstChild(LocalPlayer.Name)
			summoned=summoned or (playerModel and playerModel:FindFirstChild("SummonedStand"))
			local stand=(char and char:FindFirstChild("StandMorph")) or (playerModel and playerModel:FindFirstChild("StandMorph"))
			local visible=summoned and summoned.Value==true and hum and hum.Health>0
			if stand then
				for _,effect in ipairs(stand:GetDescendants()) do
					if effect.Name:match("_Custom$") and (effect:IsA("ParticleEmitter") or effect:IsA("Beam") or effect:IsA("Trail") or effect:IsA("Light")) then
						if standEffectEnabled[effect]==nil then standEffectEnabled[effect]=effect.Enabled end
						effect.Enabled=visible and standEffectEnabled[effect] or false
					end
				end
			end
			local preset=_G.Config.standSkinAuraPreset or "Skin Default"
			local data=preset=="Skin Default" and skinAuraData or auraCatalog[preset]
			local auraAllowed=_G.Config.showAuraWithoutStand==true or (summoned and summoned.Value==true and stand~=nil)
			if not char or not hum or hum.Health<=0 or not auraAllowed or not data then
				if #auraRoots>0 then clearAllPlayerAuras() end
				auraCharacter=char;return
			end
			if auraCharacter==char and appliedAura==data and appliedVersion==auraVersion then return end
