		function LoadModel(val, standName, standOverride, previewMode, requestCurrent, preserveBaseGear)
			local selectedVersion = skinSelectionVersion
			local function stillCurrent() return selectedVersion == skinSelectionVersion and (not requestCurrent or requestCurrent()) end
			if not stillCurrent() then return false end
			local stand = standOverride or getStandMorph2()
			if not stand then
				warn("StandMorph not found")
				return false
			end
			local inlineModelData = type(val) == "table"
			local sourceName = inlineModelData and "__thebest_base_stand" or tostring(val)
			local standNameParsed = tostring(standName or ""):gsub(":", ""):match("^%s*(.-)%s*$")
			local filePath = inlineModelData and nil or ("ssoc_skins/" .. sourceName)
			if not inlineModelData and not isfile(filePath) then
				warn("'" .. filePath .. "' not found, trying to download...")
				if DownloadSkin(sourceName) then
					print("Downloaded '" .. sourceName .. "' successfully. Continue loading...")
				else
					warn("Failed to download '" .. sourceName .. "'.")
					return false
				end
			end
			if not stillCurrent() then return false end
			attachmentCache = {}
			local modelData = inlineModelData and val or _G.TheBestStandModelDataCache[sourceName]
			if not inlineModelData and type(modelData) ~= "table" then
				local decoded, result = pcall(function() return HttpService:JSONDecode(decodeData(readfile(filePath))) end)
				if not stillCurrent() then return false end
				if not decoded or type(result) ~= "table" then warn("[SkinChanger] Invalid model: " .. sourceName); return false end
				modelData = result
				_G.TheBestStandModelDataCache[sourceName] = modelData
			end
			if not stillCurrent() or type(modelData) ~= "table" then return false end
			clearStandSkinCustom(stand, preserveBaseGear == true and not modelData["_Gear"])
			local upperTorso = stand:FindFirstChild("UpperTorso")
			local hrp = stand:FindFirstChild("HumanoidRootPart")
			if not previewMode then
				clearAllPlayerAuras()
				skinAuraData=modelData["_PlayerAuras"];auraVersion+=1
			end
			if modelData["Horse"] and upperTorso and not upperTorso:FindFirstChild("Horse") then
				local horse = Instance.new("MeshPart")
				horse.Name = "Horse"
				horse:SetAttribute("TheBestSkinCustom", true)
				horse.Anchored = false
				horse.CanCollide = false
				horse.Massless = true
				horse.Parent = upperTorso
				local weld = Instance.new("Weld")
				weld.Part0 = upperTorso
				weld.Part1 = horse
				weld.C0 = upperTorso.CFrame:ToObjectSpace(horse.CFrame)
				weld.C1 = CFrame.new()
				weld.Parent = horse
				print("Created Horse MeshPart in UpperTorso")
			end
			if modelData["_Gear"] then
				local gearData = modelData["_Gear"].Children[1]
				if gearData and gearData.ClassName == "MeshPart" then
					local gear = Instance.new("MeshPart")
					gear.Name = "Gear"
					gear:SetAttribute("TheBestSkinCustom", true)
					gear.Anchored = false
					gear.CanCollide = false
					gear.Massless = true
					if gearData.Properties then
						applyProps(gear, gearData.Properties, nil)
					end
					if upperTorso and gearData.Properties and gearData.Properties.RelativeCFrame then
						local relCF = loadProp(gearData.Properties.RelativeCFrame)
						gear.CFrame = upperTorso.CFrame * relCF
					end
					gear.Parent = upperTorso or stand
					if stand:FindFirstChild("HumanoidRootPart") then
						local weld = Instance.new("Weld")
						weld.Part0 = stand:FindFirstChild("HumanoidRootPart")
						weld.Part1 = gear
						weld.C0 = CFrame.new()
						weld.C1 = CFrame.new(0, -2, -2)
						weld.Parent = gear
					end
				end
			end
			local bodyLookup = {}
			for _, name in ipairs(bodyParts) do
				bodyLookup[name] = false
			end
			bodyLookup["HumanoidRootPart"] = false
			bodyLookup["Head"] = false
			bodyLookup["Gear"] = false
			bodyLookup["Horse"] = false
			for _, obj in ipairs(stand:GetDescendants()) do
				if obj:IsA("MeshPart") or obj:IsA("Part") then
					if not bodyLookup[obj.Name] then
						obj.Transparency = 1
						obj.LocalTransparencyModifier = 1
						obj.CanCollide = false
						obj.CastShadow = false
					end
				elseif obj:IsA("Decal") then
					obj.Transparency = 1
				elseif obj:IsA("Beam") then
					obj.Enabled = false
				elseif obj:IsA("Trail") then
					obj.Enabled = false
				elseif obj:IsA("ParticleEmitter") then
					obj.Enabled = false
				elseif obj:IsA("PointLight") then
					obj.Enabled = false
				end
			end
			local partNames = {}
			for name in pairs(modelData) do
				table.insert(partNames, name)
			end
			table.sort(partNames)
			for _, partName in ipairs(partNames) do
				if partName ~= "_Gear" and partName ~= "_Highlights" and partName ~= "_PlayerAuras" then
					local part = stand:FindFirstChild(partName)
					local partData = modelData[partName]
					if part and partData then
						for _, childData in ipairs(partData.Children or {}) do
							if childData.ClassName == "Attachment" then
								createFromData(part, childData)
							end
						end
					end
				end
			end
			for _, partName in ipairs(partNames) do
				if partName ~= "_Gear" and partName ~= "_Highlights" and partName ~= "_PlayerAuras" then
					local part = stand:FindFirstChild(partName)
					local partData = modelData[partName]
					if part and partData then
						for _, childData in ipairs(partData.Children or {}) do
							if childData.ClassName == "Beam" or childData.ClassName == "Trail" then
								createFromData(part, childData)
							end
						end
					end
				end
			end
			for _, partName in ipairs(partNames) do
				if partName == "_Highlights" then
					local highlightsData = modelData["_Highlights"]
					if highlightsData then
						for _, childData in ipairs(highlightsData.Children or {}) do
							createFromData(stand, childData)
						end
					end
				elseif partName == "_Gear" then
				elseif partName == "_PlayerAuras" then
					if not previewMode then
						loadPlayerAuras(modelData)
					end
				else
					local part = stand:FindFirstChild(partName)
					local partData = modelData[partName]
					if part and partData then
						for _, childData in ipairs(partData.Children or {}) do
							if
								childData.ClassName ~= "Attachment"
								and childData.ClassName ~= "Beam"
								and childData.ClassName ~= "Trail"
							then
								createFromData(part, childData)
							end
						end
					end
				end
			end
			for _, obj in ipairs(stand:GetDescendants()) do
				if obj:IsA("Beam") or obj:IsA("Trail") then
					local a0ID = obj:GetAttribute("A0")
					local a1ID = obj:GetAttribute("A1")
					if a0ID and attachmentCache[a0ID] then
						obj.Attachment0 = attachmentCache[a0ID]
					end
					if a1ID and attachmentCache[a1ID] then
						obj.Attachment1 = attachmentCache[a1ID]
					end
				end
			end
			for _, obj in ipairs(stand:GetDescendants()) do
				if obj:IsA("Weld") or obj:IsA("WeldConstraint") then
					local p0Name = obj:GetAttribute("WeldPart0")
					local p1Name = obj:GetAttribute("WeldPart1")
					if p0Name then
						local p0 = obj.Parent:FindFirstChild(p0Name .. "_Custom") or obj.Parent:FindFirstChild(p0Name)
						if p0 then
							obj.Part0 = p0
						end
					end
					if p1Name then
						local p1 = obj.Parent:FindFirstChild(p1Name .. "_Custom") or obj.Parent:FindFirstChild(p1Name)
						if p1 then
							obj.Part1 = p1
						end
					end
				end
			end

			local count = 0
			for _, obj in ipairs(stand:GetDescendants()) do
				if obj.Name:find("_Custom$") then
					count = count + 1
				end
			end
			local lowerSourceName = string.lower(sourceName)
			if
				lowerSourceName:match("retrotheworld")
				or (lowerSourceName:match("old") and not lowerSourceName:match("controldevil"))
				or lowerSourceName:match("theworldgreatest")
				or lowerSourceName:match("ovatheworld")
			then
				stand.Name = ""
				for _, bodyPartName in ipairs({
					"Head",
					"LeftFoot",
					"UpperTorso",
					"RightUpperLeg",
					"RightUpperArm",
					"RightLowerLeg",
					"RightLowerArm",
					"RightHand",
					"RightFoot",
					"LowerTorso",
					"LeftUpperLeg",
					"LeftUpperArm",
					"LeftLowerLeg",
					"LeftLowerArm",
					"LeftHand",
				}) do
					local bodyPart = stand:FindFirstChild(bodyPartName, true)
					if bodyPart and bodyPart:IsA("BasePart") then
						bodyPart.Transparency = 0
						bodyPart.LocalTransparencyModifier = 0
						bodyPart.Color = Color3.new(1, 1, 1)
					end
				end
			end
			task.spawn(function()
				local contentToPreload = {}
				for _, object in ipairs(stand:GetDescendants()) do
					if
						object:IsA("MeshPart")
						or object:IsA("Decal")
						or object:IsA("Texture")
						or object:IsA("SurfaceAppearance")
						or object:IsA("ParticleEmitter")
						or object:IsA("Beam")
						or object:IsA("Trail")
					then
						table.insert(contentToPreload, object)
					end
				end
				if #contentToPreload > 0 then
					pcall(function()
						game:GetService("ContentProvider"):PreloadAsync(contentToPreload)
					end)
				end
			end)
			print("Loaded! " .. count .. " custom parts created")
			return true
		end
		local function LoadBaseStand(targetStandName, standOverride, previewMode, requestCurrent)
			local modelData, modelError = getBaseStandModelData(targetStandName)
			if type(modelData) ~= "table" or next(modelData) == nil then
				warn("[SkinChanger] " .. tostring(modelError or ("Base model for " .. tostring(targetStandName) .. " is empty.")))
