		function loadRtwoh(val, standName, standOverride, previewMode, requestCurrent)
			local baseLoaded = LoadModel("thenooboverheaven.ssoc", standName, standOverride, previewMode, requestCurrent)
			if baseLoaded == false then return false end
			local skinLoaded = LoadModel(val, standName, standOverride, previewMode, requestCurrent, true)
			if skinLoaded == false then return false end
			local targetStand = standOverride or getStandMorph2()
			local upperTorso = targetStand and targetStand:FindFirstChild("UpperTorso")
			local gear = upperTorso and upperTorso:FindFirstChild("Gear")
			if gear then
				gear.Transparency = 0
				print("[debug]: loaded rtwoh gear")
			end
			return baseLoaded ~= false and skinLoaded ~= false
		end
		_G.TheBestApplyStandSkinAsOutfit = function(skin, standName, character, silent, selectionCurrent)
			if selectionCurrent and not selectionCurrent() then return false end
			if type(skin) ~= "string" or skin == "" then
				return false
			end
			character = character or outfitLocalPlayer.Character
			if not character then
				if not silent then
					setOutfitStatus("Your character is not ready.")
				end
				return false
			end
			outfitRequestVersion += 1
			local requestVersion = outfitRequestVersion
			if not silent then
				setOutfitStatus("Loading stand skin for your body...")
			end
			local description = Instance.new("HumanoidDescription")
			local created, visualModel = pcall(function()
				return outfitPlayersService:CreateHumanoidModelFromDescriptionAsync(
					description,
					Enum.HumanoidRigType.R15
				)
			end)
			description:Destroy()
			if (selectionCurrent and not selectionCurrent()) or requestVersion ~= outfitRequestVersion then
				if visualModel then visualModel:Destroy() end
				return false
			end
			if not created or not visualModel then
				if not silent then
					setOutfitStatus("Could not create the stand body rig.")
				end
				return false
			end
			visualModel:SetAttribute("TheBestAvatarRig", "R15 Stand")
			local lowerSkin = string.lower(skin)
			local specialSkin = lowerSkin:match("retrotheworld")
				or (lowerSkin:match("old") and not lowerSkin:match("controldevil"))
				or lowerSkin:match("theworldgreatest")
				or lowerSkin:match("ovatheworld")
			local loaded, loadResult = pcall(function()
				if specialSkin then
					return loadRtwoh(skin, standName, visualModel, true, selectionCurrent)
				end
				return LoadModel(skin, standName, visualModel, true, selectionCurrent)
			end)
			if requestVersion ~= outfitRequestVersion or (selectionCurrent and not selectionCurrent()) then visualModel:Destroy(); return false end
			if not loaded or loadResult == false then
				visualModel:Destroy()
				if not silent then
					setOutfitStatus("Could not apply the selected stand skin.")
				end
				return false
			end
			local applied, applyError = applyOutfitModelLocally(visualModel, character, true, {requestCurrent=function() return requestVersion == outfitRequestVersion and (not selectionCurrent or selectionCurrent()) end})
			if requestVersion ~= outfitRequestVersion or (selectionCurrent and not selectionCurrent()) then
				visualModel:Destroy()
				return false
			end
			if not applied then
				if visualModel.Parent then
					visualModel:Destroy()
				end
				restoreOriginalCharacterVisuals(character)
				if not silent then
					setOutfitStatus(applyError)
				end
				return false
			end
			_G.Config.playerOutfitEnabled = false
			_G.Config.playerStandOutfitEnabled = true
			_G.Config.playerStandOutfitSkin = skin
			_G.Config.playerStandOutfitStand = standName
			_G.Config.playerNpcOutfitEnabled = false
			_G.Config.playerNpcOutfitName = ""
			SaveConfig()
			setOutfitStatus("Stand skin applied to your body.")
			return true
		end
