function DownloadSkin(fileName)
 local endpoint=tostring(_G.nga_link or "")
 if _G.TheBestSkinDownloadBlockedFor==endpoint then return false,"Authorization required" end
 local separator=endpoint:find("?",1,true) and "&" or "?"
 local success,raw=pcall(function()return game:HttpGet(endpoint..separator.."s="..HttpService:UrlEncode(fileName))end)
 if not success or type(raw)~="string" then return false,"Model server unavailable" end
 -- A successful HTTP status can contain the service's JSON authorization error.
 if raw:match("^%s*{") then
  local ok,response=pcall(function()return HttpService:JSONDecode(raw)end)
  if ok and type(response)=="table" and response.error then
   local errorText=string.lower(tostring(response.error))
   if errorText:find("key",1,true) or errorText:find("auth",1,true) then
    _G.TheBestSkinDownloadBlockedFor=endpoint
    return false,"Authorization required"
   end
   return false,"Model unavailable"
  end
 end
 local ok,decoded=pcall(function()return HttpService:JSONDecode(decodeData(raw))end)
 if not ok or type(decoded)~="table" or not (type(decoded.Head)=="table" or type(decoded.UpperTorso)=="table" or type(decoded.Torso)=="table") then return false,"Invalid model response" end
 local written=pcall(writefile,"ssoc_skins/"..fileName,raw)
 if not written then return false,"Could not save model" end
 _G.TheBestStandModelDataCache[fileName]=decoded
 if not table.find(ssocskins,fileName) then table.insert(ssocskins,fileName) end
 return true
end

