 local cache, jobs, queue, running = {}, {}, {}, 0
 local folder = "thebest/catalog-v014"
 local function normalized(value)
  return string.lower(tostring(value or ""):gsub("[^%w]", ""))
 end
 local function callbackAll(job, asset)
  jobs[job.key] = nil
  for _, callback in ipairs(job.callbacks) do pcall(callback, asset) end
 end
 local function pump()
  while running < 3 and #queue > 0 do
   local job = table.remove(queue, 1)
   running += 1
   task.spawn(function()
    local asset
    local ok, err = pcall(function()
     local loader = getcustomasset or getsynasset
     assert(type(loader) == "function" and type(writefile) == "function" and type(isfile) == "function", "Local image API unavailable")
     ensureConfigFolder()
     if makefolder and (not isfolder or not isfolder(folder)) then pcall(makefolder, folder) end
     local path = folder .. "/" .. job.key:gsub("[^%w]", "-") .. (job.record.extension or ".png")
     if not isfile(path) then
      local bytes = embedded[job.key] and decodeBase64(embedded[job.key]) or game:HttpGet(job.record.url)
      local png = bytes:sub(1,4) == "\137PNG"
      local jpg = bytes:sub(1,3) == "\255\216\255"
      local webp = bytes:sub(1,4) == "RIFF" and bytes:sub(9,12) == "WEBP"
      assert(png or jpg or webp, "Image response is not PNG, JPEG, or WebP")
      writefile(path, bytes)
     end
     asset = loader(path)
     assert(type(asset) == "string" and asset ~= "", "Could not register image")
     cache[job.key] = asset
    end)
    if not ok then warn("[StandCatalog] " .. tostring(err)) end
    callbackAll(job, asset)
    task.wait()
    running -= 1
    pump()
   end)
  end
 end
 _G.TheBestStandCatalogEntries = data.entries
 _G.TheBestCatalogNewSkinModels = data.newModels
 _G.TheBestRequestStandCardImage = function(stand, skin, callback)
  if skin == "None" then skin = nil end
  local key = normalized(stand) .. "/" .. normalized(skin)
  local record = data.images[key]
  if not record then callback(nil); return end
  if cache[key] then callback(cache[key]); return end
  if jobs[key] then table.insert(jobs[key].callbacks, callback); return end
  local job = {key=key, record=record, callbacks={callback}}
  jobs[key] = job
  table.insert(queue, job)
  pump()
 end
 _G.TheBestStandPreviewProvider = function(stand, skin)
  return findBaseStandTemplate(skin and skin ~= "None" and skin or stand)
 end
 _G.TheBestPrepareCatalogSkin = function(stand, skin)
  local succeeded, modelData = pcall(getBaseStandModelData, skin)
  if not succeeded or type(modelData) ~= "table" or not (modelData.Head or modelData.UpperTorso or modelData.Torso) then return nil end
  local file = "catalog-v014-" .. normalized(stand) .. "-" .. normalized(skin) .. ".ssoc"
  local written, err = pcall(function()
   writefile("ssoc_skins/" .. file, encodeData(HttpService:JSONEncode(modelData)))
  end)
  if not written then warn("[StandCatalog] " .. tostring(err)); return nil end
  _G.TheBestStandModelDataCache[file] = modelData
  return file
 end
