local skinStates = {}
_G.TheBestCatalogSkinStates = skinStates
local function selectionKey(stand, skin) return normalized(stand).."/"..normalized(skin) end
local function validModel(raw)
 local ok, decoded=pcall(function()return HttpService:JSONDecode(decodeData(raw))end)
 if not ok or type(decoded)~="table" or not (type(decoded.Head)=="table" or type(decoded.UpperTorso)=="table" or type(decoded.Torso)=="table") then return nil end
 return decoded
end
local function acceptedFile(file)
 local cached = _G.TheBestStandModelDataCache[file]
 if type(cached)=="table" and (cached.Head or cached.UpperTorso or cached.Torso) then return file end
 local ok, raw=pcall(readfile,"ssoc_skins/"..file)
 local decoded=ok and validModel(raw)
 if not decoded then return nil end
 _G.TheBestStandModelDataCache[file]=decoded
 return file
end
local function matchesFile(file, stand, skin)
 local base=tostring(file):match("([^/\\]+)$") or tostring(file)
 base=base:gsub("%.[sS][sS][oO][cC]$", "")
 local wanted=normalized(skin)
 local candidate=normalized(base)
 if candidate==wanted or candidate=="catalogv014"..normalized(stand)..wanted or candidate=="catalogv015"..normalized(stand)..wanted then return true end
 -- This is the actual filename spelling used by the old local model pack.
 return wanted=="mrjukesangels" and candidate=="mrjukesangles"
end
_G.TheBestCatalogSkinUnconfirmed = function(stand, skin)
 if not skin or skin=="None" or skin=="" then return false end
 local state=skinStates[selectionKey(stand,skin)]
 if state=="Preview only" then return true end
 if state=="3D ready" then return false end
 for file in pairs(bundled) do
  if matchesFile(file,stand,skin) then return false end
 end
 -- Only already validated model data counts as ready. Do not read/decode models,
 -- scan the world, or request the model server while rendering a card.
 for file,cached in pairs(_G.TheBestStandModelDataCache or {}) do
  if type(cached)=="table" and (cached.Head or cached.UpperTorso or cached.Torso) and matchesFile(file,stand,skin) then return false end
 end
 return true
end

_G.TheBestResolveCatalogSkin = function(stand, skin)
 local key=selectionKey(stand,skin)
 if _G.TheBestCatalogAvailableSkinFiles and not _G.TheBestCatalogAvailableSkinFiles[key] then return nil,"Model unavailable" end
 -- Local models must be checked before trying the optional remote server.
 for _, file in ipairs(ssocskins) do
  if matchesFile(file,stand,skin) and acceptedFile(file) then skinStates[key]="3D ready";return file end
 end
 for file, encoded in pairs(bundled) do
  if matchesFile(file,stand,skin) then
   local ok,result=pcall(function()
    local raw=decodeBase64(encoded)
    local decoded=validModel(raw)
    if not decoded then return nil end
    writefile("ssoc_skins/"..file,raw)
    _G.TheBestStandModelDataCache[file]=decoded
    table.insert(ssocskins,file)
    return file
   end)
   if ok and result then skinStates[key]="3D ready";return result end
  end
 end
 local prepared=_G.TheBestPrepareCatalogSkin(stand,skin)
 if prepared then skinStates[key]="3D ready";return prepared end
 local fileName=string.lower(tostring(skin):gsub("%s+", ""))..".ssoc"
 local downloaded,reason=DownloadSkin(fileName)
 if downloaded then skinStates[key]="3D ready";return fileName end
 skinStates[key]="Preview only"
 return nil,reason or "Model unavailable"
end
_G.TheBestCatalogModelMissing = function(stand, skin, reason)
 skinStates[selectionKey(stand,skin)]="Preview only"
 local message=tostring(skin)..": picture preview only; the 3D model is not available."
 if reason=="Authorization required" then message=tostring(skin)..": 3D model is not cached; the optional model server requires its owner's key." end
 warn("[StandCatalog] "..message)
 pcall(function()game:GetService("StarterGui"):SetCore("SendNotification",{Title="Stand Skins",Text=message,Duration=7})end)
end

-- v016 available-model catalog: images alone are never selectable skins.
local availableFiles = {}
for file in pairs(bundled) do availableFiles[file]=true end
for _,file in ipairs(ssocskins) do
 if not availableFiles[file] and acceptedFile(file) then availableFiles[file]=true end
end
local entries,selections,stats=(function(entries, files)
 local function normalized(value) return string.lower(tostring(value or ""):gsub("[^%w]", "")) end
 local indexed = {}
 for file, ready in pairs(files or {}) do
  if ready then
   local base = tostring(file):match("([^/\\]+)$") or tostring(file)
   base = base:gsub("%.[sS][sS][oO][cC]$", "")
   indexed[normalized(base)] = file
  end
 end
 local filtered, selections = {}, {}
 local stats = {OriginalStands=0, OriginalSkins=0, Stands=0, Skins=0}
 for _, entry in ipairs(entries or {}) do
  stats.OriginalStands += 1
  local kept, seen = {"None"}, {}
  local standKey = normalized(entry.Name)
  for _, skin in ipairs(entry.Skins or {}) do
   if type(skin)=="string" and skin~="" and skin~="None" then
    stats.OriginalSkins += 1
    local skinKey = normalized(skin)
    local file = indexed[skinKey] or indexed["catalogv014"..standKey..skinKey] or indexed["catalogv015"..standKey..skinKey]
    if not file and skinKey=="mrjukesangels" then file=indexed.mrjukesangles end
    if file and not seen[skinKey] then
     seen[skinKey]=true
     table.insert(kept,skin)
     selections[standKey.."/"..skinKey]=file
     stats.Skins += 1
    end
   end
  end
  if #kept>1 then
   local copy=table.clone(entry)
   copy.Skins=kept
   table.insert(filtered,copy)
   stats.Stands += 1
  end
 end
 stats.RemovedStands=stats.OriginalStands-stats.Stands
 stats.RemovedSkins=stats.OriginalSkins-stats.Skins
 return filtered,selections,stats
end)(data.entries,availableFiles)
_G.TheBestStandCatalogEntries=entries
_G.TheBestCatalogAvailableSkinFiles=selections
_G.TheBestCatalogAvailabilityStats=stats
_G.TheBestCatalogSkinUnconfirmed=function(stand,skin)
 return skin~=nil and skin~="" and skin~="None" and selections[selectionKey(stand,skin)]==nil
end
_G.TheBestCatalogIsAvailableFile=function(file)
 return type(file)=="string" and file~="" and (availableFiles[file]==true or acceptedFile(file)~=nil)
end
end)()

		local DB_FILE = "ssoc_skins/stands_dat.json"
		local ANY_STAND_SKIN_DB_KEY = "__TheBestAnyStandSkin"
		local BASE_STAND_DB_KEY = "__TheBestBaseStand"
		_G.skinChanger_stands = {}
local skinDbNeedsBackup = false
local skinDbPreservedRaw = nil
local function validSkinDatabase(data)
 if type(data) ~= "table" then return false end
 for key, value in pairs(data) do
  if type(key) ~= "string" or key == "" or type(value) ~= "string" then return false end
 end
 return true
end
function SaveSkinDB(explicitSelection)
 if not validSkinDatabase(_G.skinChanger_stands) then return false end
 if skinDbNeedsBackup and explicitSelection ~= true then return false end
 local ok, reason = pcall(function()
  if not isfolder("ssoc_skins") then makefolder("ssoc_skins") end
  if skinDbNeedsBackup then
   -- Never replace the damaged source until an exact, readable backup exists.
   if type(skinDbPreservedRaw) ~= "string" then error("Original skin database could not be read") end
   local backup = DB_FILE .. ".corrupt-" .. HttpService:GenerateGUID(false) .. ".bak"
   writefile(backup, skinDbPreservedRaw)
   if readfile(backup) ~= skinDbPreservedRaw then error("Skin database backup verification failed") end
  end
  local encoded = HttpService:JSONEncode(_G.skinChanger_stands)
  writefile(DB_FILE, encoded)
 end)
 if not ok then warn("[Skin DB] Save failed: " .. tostring(reason)); return false end
 skinDbNeedsBackup, skinDbPreservedRaw = false, nil
 return true
end
function LoadSkinDB()
 local ok, exists = pcall(isfile, DB_FILE)
 if ok and not exists then
  _G.skinChanger_stands = {}
  skinDbNeedsBackup, skinDbPreservedRaw = false, nil
  return true
 end
 local readOK, raw = pcall(readfile, DB_FILE)
 local decodedOK, data = false, nil
 if readOK and type(raw) == "string" then
  decodedOK, data = pcall(function() return HttpService:JSONDecode(raw) end)
 end
 if not decodedOK or not validSkinDatabase(data) then
  _G.skinChanger_stands = {}
  skinDbNeedsBackup = true
  skinDbPreservedRaw = readOK and type(raw) == "string" and raw or nil
  warn("[Skin DB] Invalid database preserved; saved skins are disabled until you choose a skin again.")
  return false
 end
 _G.skinChanger_stands = data
 skinDbNeedsBackup, skinDbPreservedRaw = false, nil
 return true
end

