		_G.TheBestStandConcealConnections = {}
		local standSkinOperations = setmetatable({}, { __mode = "k" })
		local standSkinBodyParts = {
			Head = true,
			Torso = true,
			["Left Arm"] = true,
			["Right Arm"] = true,
			["Left Leg"] = true,
			["Right Leg"] = true,
