		local function ApplyStandSkinFromMorph(standMorph)
			local selectedVersion = skinSelectionVersion
			if not standMorph or not standMorph:IsA("Model") then
				return
			end
			local concealRegistry = _G.TheBestStandConcealConnections
			local previousConceal = concealRegistry[standMorph]
			if previousConceal and type(previousConceal.restore) == "function" then
				pcall(previousConceal.restore)
			end
			local operationToken = {}
			standSkinOperations[standMorph] = operationToken
			standMorph:SetAttribute("TheBestSkinApplying", true)
			local originalStandName = standMorph.Name
			local hiddenState = setmetatable({}, { __mode = "k" })
			local concealedObjects = setmetatable({}, { __mode = "k" })
			local concealConnection = nil
			local ancestryConnection = nil
			local concealRemovingConnection = nil
			local concealing = false
			local preserveCustomObjects = false
			local preserveSpecialBody = false
			local function isCurrentOperation()
				return standSkinOperations[standMorph] == operationToken and selectedVersion == skinSelectionVersion
			end
			local function isCustomSkinObject(object)
				local current = object
				while current and current ~= standMorph do
					if current:GetAttribute("TheBestSkinCustom") or current.Name:find("_Custom$") then
						return true
					end
					current = current.Parent
				end
				return false
			end
			local function isConcealableEffect(object)
				return object:IsA("Beam")
					or object:IsA("Trail")
					or object:IsA("ParticleEmitter")
					or object:IsA("Smoke")
					or object:IsA("Fire")
					or object:IsA("Sparkles")
					or object:IsA("Highlight")
					or object:IsA("PointLight")
					or object:IsA("SpotLight")
					or object:IsA("SurfaceLight")
			end
			local function forgetConcealedObject(object)
				local connections = concealedObjects[object]
				concealedObjects[object] = nil
				for _, connection in ipairs(connections or {}) do connection:Disconnect() end
			end
			local function enforceConcealedObject(object)
				if not object.Parent then
					forgetConcealedObject(object)
					return
				end
				pcall(function()
					if object:IsA("BasePart") then
						if object.LocalTransparencyModifier ~= 1 then object.LocalTransparencyModifier = 1 end
						if object.Transparency ~= 1 then object.Transparency = 1 end
						if object.CanCollide then object.CanCollide = false end
						if object.CastShadow then object.CastShadow = false end
					elseif object:IsA("Decal") or object:IsA("Texture") then
						if object.Transparency ~= 1 then object.Transparency = 1 end
					elseif isConcealableEffect(object) then
						if object.Enabled then object.Enabled = false end
					end
				end)
			end
			local function concealObject(object)
				if not object.Parent then
					return
				end
				if preserveCustomObjects and isCustomSkinObject(object) then
					concealedObjects[object] = nil
					return
				end
				if
					preserveSpecialBody
					and object:IsA("BasePart")
					and object.Parent == standMorph
					and standSkinBodyParts[object.Name]
				then
					concealedObjects[object] = nil
					return
				end
				if object:IsA("BasePart") then
					if not hiddenState[object] then
						hiddenState[object] = {
							LocalTransparencyModifier = object.LocalTransparencyModifier,
							Transparency = object.Transparency,
							CanCollide = object.CanCollide,
							CastShadow = object.CastShadow,
							Color = object.Color,
						}
					end
				elseif object:IsA("Decal") or object:IsA("Texture") then
					if not hiddenState[object] then
						hiddenState[object] = { Transparency = object.Transparency }
					end
				elseif isConcealableEffect(object) then
					if not hiddenState[object] then
						hiddenState[object] = { Enabled = object.Enabled }
					end
				else
					return
				end
				enforceConcealedObject(object)
				if not concealedObjects[object] then
					local connections = {}
					concealedObjects[object] = connections
					local properties = object:IsA("BasePart")
						and { "Transparency", "LocalTransparencyModifier", "CanCollide", "CastShadow" }
						or ((object:IsA("Decal") or object:IsA("Texture")) and { "Transparency" } or { "Enabled" })
					for _, property in ipairs(properties) do
						connections[#connections + 1] = object:GetPropertyChangedSignal(property):Connect(function()
							if isCurrentOperation() and concealedObjects[object] then enforceConcealedObject(object) end
						end)
					end
				end
			end
			local function disconnectConceal()
				if concealConnection then
					concealConnection:Disconnect()
					concealConnection = nil
				end
				if concealRemovingConnection then
					concealRemovingConnection:Disconnect()
					concealRemovingConnection = nil
				end
				for object in pairs(concealedObjects) do forgetConcealedObject(object) end
				if ancestryConnection then
					ancestryConnection:Disconnect()
					ancestryConnection = nil
				end
				if isCurrentOperation() then
					concealRegistry[standMorph] = nil
				end
			end
			local function removeCustomSkinObjects()
				local customRoots = {}
				for _, object in ipairs(standMorph:GetDescendants()) do
					if isCustomSkinObject(object) and not isCustomSkinObject(object.Parent) then
						table.insert(customRoots, object)
					end
				end
				for _, object in ipairs(customRoots) do
					if object.Parent then
						object:Destroy()
					end
				end
			end
			local function restoreOriginal(removeCustom)
				if isCurrentOperation() then standMorph:SetAttribute("TheBestSkinApplying", false) end
				disconnectConceal()
				for object, state in pairs(hiddenState) do
					if object.Parent then
						pcall(function()
							for propertyName, propertyValue in pairs(state) do
								object[propertyName] = propertyValue
							end
						end)
					end
				end
				table.clear(concealedObjects)
				if removeCustom ~= false then
					removeCustomSkinObjects()
				end
				if standMorph.Parent and standMorph.Name == "" then
					standMorph.Name = originalStandName ~= "" and originalStandName or "StandMorph"
				end
				if isCurrentOperation() then
					standSkinOperations[standMorph] = nil
				end
			end
			local function connectConcealWatcher()
				concealConnection = standMorph.DescendantAdded:Connect(function(object)
					if isCurrentOperation() and standMorph.Parent then concealObject(object) end
				end)
				concealRemovingConnection = standMorph.DescendantRemoving:Connect(function(object)
					forgetConcealedObject(object)
					local saved = hiddenState[object]
					hiddenState[object] = nil
					if saved then pcall(function()
						for property, value in pairs(saved) do object[property] = value end
					end) end
				end)
				ancestryConnection = standMorph.AncestryChanged:Connect(function(_, parent)
					if parent == nil and isCurrentOperation() then
						disconnectConceal()
						standSkinOperations[standMorph] = nil
					end
				end)
				concealRegistry[standMorph] = {
					connection = concealConnection,
					removingConnection = concealRemovingConnection,
					ancestryConnection = ancestryConnection,
					restore = restoreOriginal,
				}
			end
			local function beginConceal()
				if concealing or not standMorph.Parent or not isCurrentOperation() then
					return
				end
				concealing = true
				for _, object in ipairs(standMorph:GetDescendants()) do
					concealObject(object)
				end
				connectConcealWatcher()
			end
			local function beginPersistentConceal(specialSkin)
				if not standMorph.Parent or not isCurrentOperation() then
					return
				end
				preserveCustomObjects = true
				preserveSpecialBody = specialSkin == true
				for _, object in ipairs(standMorph:GetDescendants()) do
					concealObject(object)
				end
				connectConcealWatcher()
			end

			local savedUniversalSkin = _G.skinChanger_stands
				and _G.skinChanger_stands[ANY_STAND_SKIN_DB_KEY]
			local savedBaseStand = _G.skinChanger_stands
				and _G.skinChanger_stands[BASE_STAND_DB_KEY]
			if
				(savedUniversalSkin and savedUniversalSkin ~= "")
				or (savedBaseStand and savedBaseStand ~= "")
			then
				beginConceal()
			end
			task.spawn(function()
				local standName = standMorph:WaitForChild("Stand Name", 5)
				if not isCurrentOperation() then
					return
				end
				if not standName then
					restoreOriginal()
					return
				end
				local baseStandTarget = _G.skinChanger_stands[BASE_STAND_DB_KEY]
				local useBaseStand = type(baseStandTarget) == "string" and baseStandTarget ~= ""
				local skin = useBaseStand and nil or _G.skinChanger_stands[ANY_STAND_SKIN_DB_KEY]
				if not useBaseStand and skin == nil then
					skin = _G.skinChanger_stands[standName.Value]
				end
				if not useBaseStand and (skin == "" or not skin) then
					restoreOriginal()
					return
				end
				beginConceal()
				local specialSkin = false
				if not useBaseStand then
					local lowerSkin = string.lower(skin)
					specialSkin = lowerSkin:match("retrotheworld")
						or (lowerSkin:match("old") and not lowerSkin:match("controldevil"))
						or lowerSkin:match("theworldgreatest")
						or lowerSkin:match("ovatheworld")
					local requiredFiles = specialSkin and { "thenooboverheaven.ssoc", skin } or { skin }
					for _, fileName in ipairs(requiredFiles) do
						local prepared = isfile("ssoc_skins/" .. fileName)
						if not prepared then prepared = DownloadSkin(fileName) end
						if not isCurrentOperation() then return end
						if not prepared then
							restoreOriginal()
							warn("[SkinChanger] Failed to prepare " .. tostring(fileName))
							return
						end
						if not isCurrentOperation() then
							return
						end
					end
				end
				local readyDeadline = os.clock() + 1
				repeat
					local bodyPartCount = 0
					for _, object in ipairs(standMorph:GetChildren()) do
						if object:IsA("BasePart") then
							bodyPartCount += 1
						end
					end
					if
						standMorph:FindFirstChild("HumanoidRootPart")
						and (standMorph:FindFirstChild("UpperTorso") or standMorph:FindFirstChild("Torso"))
						and bodyPartCount >= 6
					then
						break
					end
					game:GetService("RunService").Heartbeat:Wait()
				until os.clock() >= readyDeadline or not standMorph.Parent
				if not isCurrentOperation() or not standMorph.Parent then
					return
				end
				disconnectConceal()
				local ok, loadedOrError = pcall(function()
					if useBaseStand then
						return LoadBaseStand(baseStandTarget, standMorph, false, isCurrentOperation)
					end
					if specialSkin then
						return loadRtwoh(skin, standName.Value, standMorph, false, isCurrentOperation)
					end
					return LoadModel(skin, standName.Value, standMorph, false, isCurrentOperation)
				end)
				if not isCurrentOperation() then return end
				if not ok or loadedOrError == false then
					restoreOriginal()
					warn("[SkinChanger] Stand visual load failed: " .. tostring(loadedOrError))
					return
				end
				beginPersistentConceal(specialSkin and true or false)
				standMorph:SetAttribute("TheBestSkinApplying", false)
				standMorph:SetAttribute("TheBestSkinRevision", (standMorph:GetAttribute("TheBestSkinRevision") or 0) + 1)
				task.defer(function()
					if isCurrentOperation() and type(_G.TheBestRefreshBarrageContext) == "function" then
						_G.TheBestRefreshBarrageContext()
					end
				end)
			end)
		end
		_G.TheBestApplyStandSkinFromMorph = ApplyStandSkinFromMorph
		local barrageReplicatedStorage = game:GetService("ReplicatedStorage")
		local barrageUserInputService = game:GetService("UserInputService")
		local barrageConnections = {}
		local barrageHeld = barrageUserInputService:IsKeyDown(Enum.KeyCode.E)
		-- Barrage models are spawned hundreds of times per second. Keep one lightweight
		-- visual on one anchor per model instead of cloning a complete stand limb rig.
		local MAX_BARRAGE_VISUAL_ROOTS = 1
		local MAX_BARRAGE_SKINNED_PARTS_PER_MODEL = 1
		local barrageContextCache = nil
		local barrageModelWatchers = setmetatable({}, { __mode = "k" })
		local barrageBodyPartOrder = {
			"RightHand",
			"LeftHand",
			"RightLowerArm",
			"LeftLowerArm",
			"RightUpperArm",
			"LeftUpperArm",
			"Right Arm",
			"Left Arm",
		}
		local barrageBodyAliases = {
			righthand = "RightHand",
			rightfist = "RightHand",
			lefthand = "LeftHand",
			leftfist = "LeftHand",
			rightlowerarm = "RightLowerArm",
			leftlowerarm = "LeftLowerArm",
			rightupperarm = "RightUpperArm",
			leftupperarm = "LeftUpperArm",
			rightarm = "RightUpperArm",
			leftarm = "LeftUpperArm",
		}
		local barrageBodyFallbacks = {
			RightHand = { "RightHand", "RightLowerArm", "RightUpperArm", "Right Arm" },
			LeftHand = { "LeftHand", "LeftLowerArm", "LeftUpperArm", "Left Arm" },
			RightLowerArm = { "RightLowerArm", "RightUpperArm", "Right Arm", "RightHand" },
			LeftLowerArm = { "LeftLowerArm", "LeftUpperArm", "Left Arm", "LeftHand" },
			RightUpperArm = { "RightUpperArm", "Right Arm", "RightLowerArm", "RightHand" },
			LeftUpperArm = { "LeftUpperArm", "Left Arm", "LeftLowerArm", "LeftHand" },
