		local function hasActiveStandReplacement()
			local database = _G.skinChanger_stands
			if type(database) ~= "table" then
				return false
			end
			local skin = database[ANY_STAND_SKIN_DB_KEY]
			local baseStand = database[BASE_STAND_DB_KEY]
			return (type(skin) == "string" and skin ~= "")
				or (type(baseStand) == "string" and baseStand ~= "")
		end
		local function normalizeBarrageName(value)
			return string.lower(tostring(value or ""):gsub("[^%w]", ""))
		end
		local function getBarrageMeshKey(part)
			local meshValue = nil
			if part:IsA("MeshPart") then
				meshValue = part.MeshId
			else
				local specialMesh = part:FindFirstChildOfClass("SpecialMesh")
				meshValue = specialMesh and specialMesh.MeshId
			end
			local textValue = tostring(meshValue or "")
			return textValue:match("(%d+)") or (textValue ~= "" and textValue or nil)
		end
		local function isBarrageSkinVisual(object)
			local current = object
			while current do
				if current:GetAttribute("TheBestBarrageVisual") then
					return true
				end
				current = current.Parent
			end
			return false
		end
		local function originalBarrageDescendants(root)
			local result = {}
			local queue = root:GetChildren()
			local index = 1
			while index <= #queue do
				local object = queue[index]
				index += 1
				if not object:GetAttribute("TheBestBarrageVisual") then
					result[#result + 1] = object
					for _, child in ipairs(object:GetChildren()) do queue[#queue + 1] = child end
				end
			end
			return result
		end
		local function isStandSkinVisual(object, stopAt)
			local current = object
			while current and current ~= stopAt do
				if current:GetAttribute("TheBestSkinCustom") or current.Name:find("_Custom$") then
					return true
				end
				current = current.Parent
			end
			return false
		end
		local function getStandSkinVisualRoots(bodyPart)
			local roots = {}
			for _, child in ipairs(bodyPart:GetChildren()) do
				if isStandSkinVisual(child, bodyPart) and child:IsA("BasePart") then
					table.insert(roots, child)
				end
			end
			table.sort(roots, function(left, right)
				local function visualPriority(object)
					local priority = object:IsA("MeshPart") and tostring(object.MeshId or "") ~= "" and 100 or 0
					local size = object.Size
					return priority + math.clamp(size.X * size.Y * size.Z, 0, 50)
				end
				return visualPriority(left) > visualPriority(right)
			end)
			while #roots > MAX_BARRAGE_VISUAL_ROOTS do
				table.remove(roots)
			end
			return roots
		end
		local barrageEffectNameTokens = {
			"effect",
			"trail",
			"beam",
			"wave",
			"wind",
			"blur",
			"slash",
			"rush",
			"speed",
			"afterimage",
			"aura",
			"glow",
			"spark",
		}
		local function isBarrageEffectInstance(object)
			return object:IsA("ParticleEmitter")
				or object:IsA("Beam")
				or object:IsA("Trail")
				or object:IsA("PointLight")
				or object:IsA("SpotLight")
				or object:IsA("SurfaceLight")
				or object:IsA("Smoke")
				or object:IsA("Fire")
				or object:IsA("Sparkles")
				or object:IsA("Highlight")
		end
		local function findBarrageAncestorBasePart(object)
			local current = object and object.Parent
			while current do
				if current:IsA("BasePart") then
					return current
				end
				current = current.Parent
			end
			return nil
		end
		local function isBarrageEffectGeometry(part)
			if not part or not part:IsA("BasePart") or isBarrageSkinVisual(part) then
				return false
			end
			local normalizedName = normalizeBarrageName(part.Name)
			for _, token in ipairs(barrageEffectNameTokens) do
				if normalizedName:find(token, 1, true) then
					return true
				end
			end
			if part.Material == Enum.Material.Neon and part.Transparency > 0.05 then
				return true
			end
			return false
		end
		local function readBarrageProperty(object, propertyName)
			local ok, value = pcall(function()
				return object[propertyName]
			end)
			return ok and value or nil
		end
		local function scoreBarrageColor(color)
			if typeof(color) ~= "Color3" then
				return -math.huge
			end
			local hue, saturation, value = color:ToHSV()
			local yellowDistance = math.min(math.abs(hue - 0.14), 1 - math.abs(hue - 0.14))
			local baseYellowPenalty = saturation > 0.45 and yellowDistance < 0.09 and 0.35 or 0
			return saturation * 3 + value * 0.25 - baseYellowPenalty
		end
		local function considerBarrageColor(profile, color, weight)
			local score = scoreBarrageColor(color) + (weight or 0)
			if score > profile.accentScore then
				profile.accentScore = score
				profile.accentColor = color
			end
			return score
		end
		local function considerBarrageGeometryColor(profile, color, weight)
			local score = scoreBarrageColor(color) + (weight or 0)
			if score > profile.geometryAccentScore then
				profile.geometryAccentScore = score
				profile.geometryAccentColor = color
			end
			considerBarrageColor(profile, color, weight)
		end
		local function considerBarrageColorSequence(profile, colorSequence, weight)
			if typeof(colorSequence) ~= "ColorSequence" then
				return -math.huge
			end
			local bestScore = -math.huge
			local bestColor = nil
			local bestSaturation = 0
			for _, keypoint in ipairs(colorSequence.Keypoints) do
				local candidateScore = considerBarrageColor(profile, keypoint.Value, weight)
				if candidateScore > bestScore then
					bestScore = candidateScore
					bestColor = keypoint.Value
					local _, saturation = keypoint.Value:ToHSV()
					bestSaturation = saturation
				end
			end
			if bestScore > profile.sequenceScore then
				profile.sequenceScore = bestScore
				profile.accentSequence = colorSequence
				profile.sequenceAccentColor = bestColor
				profile.sequenceSaturation = bestSaturation
			end
			return bestScore
		end
		local function considerBarrageEffectStyle(profile, object, weight)
			local style = nil
			local styleScore = -math.huge
			if object:IsA("ParticleEmitter") or object:IsA("Beam") or object:IsA("Trail") then
				local color = readBarrageProperty(object, "Color")
				styleScore = considerBarrageColorSequence(profile, color, weight)
				style = {
					Color = color,
					Texture = readBarrageProperty(object, "Texture"),
					LightEmission = readBarrageProperty(object, "LightEmission"),
					LightInfluence = readBarrageProperty(object, "LightInfluence"),
					Brightness = readBarrageProperty(object, "Brightness"),
				}
			elseif object:IsA("PointLight") or object:IsA("SpotLight") or object:IsA("SurfaceLight") then
				local color = readBarrageProperty(object, "Color")
				styleScore = considerBarrageColor(profile, color, weight)
				style = { Color = color }
			elseif object:IsA("Smoke") then
				local color = readBarrageProperty(object, "Color")
				styleScore = considerBarrageColor(profile, color, weight)
				style = { Color = color }
			elseif object:IsA("Fire") then
				local color = readBarrageProperty(object, "Color")
				local secondaryColor = readBarrageProperty(object, "SecondaryColor")
				styleScore = math.max(
					considerBarrageColor(profile, color, weight),
					considerBarrageColor(profile, secondaryColor, weight)
				)
				style = { Color = color, SecondaryColor = secondaryColor }
			elseif object:IsA("Sparkles") then
				local color = readBarrageProperty(object, "SparkleColor")
				styleScore = considerBarrageColor(profile, color, weight)
				style = { SparkleColor = color }
			elseif object:IsA("Highlight") then
				local fillColor = readBarrageProperty(object, "FillColor")
				local outlineColor = readBarrageProperty(object, "OutlineColor")
				styleScore = math.max(
					considerBarrageColor(profile, fillColor, weight),
					considerBarrageColor(profile, outlineColor, weight)
				)
				style = { FillColor = fillColor, OutlineColor = outlineColor }
			end
			if not style then
				return
			end
			if readBarrageProperty(object, "Enabled") == true then
				styleScore += 0.2
			end
			local previous = profile.effectStyles[object.ClassName]
			if not previous or styleScore > previous.score then
				style.score = styleScore
				profile.effectStyles[object.ClassName] = style
			end
		end
		local function inspectBarrageProfileObject(profile, object, weight, seen)
			if seen[object] and seen[object] >= weight then
				return
			end
			seen[object] = weight
			if object:IsA("BasePart") then
				considerBarrageGeometryColor(profile, object.Color, weight)
			elseif object:IsA("Decal") or object:IsA("Texture") then
				considerBarrageGeometryColor(profile, object.Color3, weight + 0.1)
			elseif isBarrageEffectInstance(object) then
				considerBarrageEffectStyle(profile, object, weight + 3)
			end
		end
		local function buildBarrageEffectProfile(stand, visualRootsByPart)
			local profile = {
				accentColor = Color3.new(1, 1, 1),
				accentScore = -math.huge,
				accentSequence = nil,
				sequenceScore = -math.huge,
				sequenceAccentColor = nil,
				sequenceSaturation = 0,
				geometryAccentColor = nil,
				geometryAccentScore = -math.huge,
				effectStyles = {},
			}
			local seen = {}
			for bodyPart, roots in pairs(visualRootsByPart) do
				for _, root in ipairs(roots) do
					inspectBarrageProfileObject(profile, root, 1, seen)
					for _, descendant in ipairs(root:GetDescendants()) do
						inspectBarrageProfileObject(profile, descendant, 1, seen)
					end
				end
				for _, descendant in ipairs(bodyPart:GetDescendants()) do
					if isStandSkinVisual(descendant, bodyPart) then
						inspectBarrageProfileObject(profile, descendant, 0.8, seen)
					end
				end
			end
			for _, object in ipairs(stand:GetDescendants()) do
				if isStandSkinVisual(object, stand) and isBarrageEffectInstance(object) then
					inspectBarrageProfileObject(profile, object, 2, seen)
				end
			end
			local character = LocalPlayer.Character
			if character then
				for _, object in ipairs(character:GetDescendants()) do
					if isBarrageEffectInstance(object) and isStandSkinVisual(object, character) then
						local current = object
						local auraMarked = false
						while current and current ~= character do
							if normalizeBarrageName(current.Name):find("aura", 1, true) then
								auraMarked = true
								break
							end
							current = current.Parent
						end
						if auraMarked then
							inspectBarrageProfileObject(profile, object, 3, seen)
						end
					end
				end
			end
			if profile.accentScore == -math.huge then
				profile.accentColor = Color3.new(1, 1, 1)
			end
			if profile.accentSequence and profile.sequenceSaturation >= 0.15 then
				profile.accentColor = profile.sequenceAccentColor or profile.accentColor
			elseif profile.geometryAccentColor then
				profile.accentColor = profile.geometryAccentColor
				profile.accentSequence = ColorSequence.new(profile.geometryAccentColor)
			elseif not profile.accentSequence then
				profile.accentSequence = ColorSequence.new(profile.accentColor)
			end
			return profile
		end
		local function sanitizeBarrageVisualTemplate(clone)
			clone:SetAttribute("TheBestBarrageVisual", true)
			if clone:IsA("BasePart") then
				clone.Anchored = false
				clone.CanCollide = false
				clone.CanTouch = false
				clone.CanQuery = false
				clone.Massless = true
				clone.CastShadow = false
			end
			for _, descendant in ipairs(clone:GetDescendants()) do
				if descendant.Parent == nil then
					continue
				end
				if descendant:IsA("Script") or descendant:IsA("LocalScript") then
					descendant:Destroy()
				elseif
					descendant:IsA("ParticleEmitter")
					or descendant:IsA("Beam")
					or descendant:IsA("Trail")
					or descendant:IsA("PointLight")
					or descendant:IsA("SpotLight")
					or descendant:IsA("SurfaceLight")
					or descendant:IsA("Sound")
					or descendant:IsA("Highlight")
					or descendant:IsA("Attachment")
				then
					descendant:Destroy()
				elseif descendant:IsA("Motor6D")
					or descendant:IsA("Weld")
					or descendant:IsA("WeldConstraint")
				then
					-- Internal joints were the main multiplier in the diagnostic report.
					descendant:Destroy()
				elseif descendant:IsA("BasePart") then
					-- The selected root already contains the visible mesh/texture. Nested
					-- rig parts caused 20k+ Welds during a five-second barrage.
					descendant:Destroy()
				end
			end
			return clone
		end
		local function clearBarrageContextCache()
			local oldContext = barrageContextCache
			barrageContextCache = nil
			if not oldContext then
				return
			end
			for _, templates in pairs(oldContext.visualTemplatesByPart or {}) do
				for _, templateData in ipairs(templates) do
					if templateData.template then
						pcall(function()
							templateData.template:Destroy()
						end)
					end
				end
			end
		end
		local function findVisualBodyPart(context, requestedName)
			for _, partName in ipairs(barrageBodyFallbacks[requestedName] or { requestedName }) do
				local bodyPart = context.stand:FindFirstChild(partName)
				if bodyPart and context.visualRootsByPart[bodyPart] then
					return bodyPart
				end
			end
			return nil
		end
		local function makeBarrageSkinContext()
			if not hasActiveStandReplacement() then
				clearBarrageContextCache()
				return nil
			end
			local stand = getStandMorph2()
			if not stand or not stand.Parent then
				clearBarrageContextCache()
				return nil
			end
			if stand:GetAttribute("TheBestSkinApplying") then return nil end
			local database = _G.skinChanger_stands
			local signature = tostring(database[ANY_STAND_SKIN_DB_KEY] or "")
				.. "|"
				.. tostring(database[BASE_STAND_DB_KEY] or "")
				.. "|" .. tostring(stand:GetAttribute("TheBestSkinRevision") or 0)
			if barrageContextCache
				and barrageContextCache.stand == stand
				and barrageContextCache.signature == signature
			then
				local cacheValid = barrageContextCache.root and barrageContextCache.root.Parent ~= nil
				if cacheValid then
					for _, roots in pairs(barrageContextCache.visualRootsByPart) do
						for _, root in ipairs(roots) do
							if not root.Parent then
								cacheValid = false
								break
							end
						end
						if not cacheValid then
							break
						end
					end
				end
				if cacheValid then
					return barrageContextCache
				end
			end
			clearBarrageContextCache()
			local meshSources = {}
			local visualRootsByPart = {}
			local visualTemplatesByPart = {}
			local visualRootCount = 0
			for _, partName in ipairs(barrageBodyPartOrder) do
				local bodyPart = stand:FindFirstChild(partName)
				local visualRoots = bodyPart and bodyPart:IsA("BasePart") and getStandSkinVisualRoots(bodyPart) or {}
				if bodyPart and #visualRoots > 0 then
					visualRootsByPart[bodyPart] = visualRoots
					visualTemplatesByPart[bodyPart] = {}
					for _, visualRoot in ipairs(visualRoots) do
						local template = sanitizeBarrageVisualTemplate(visualRoot:Clone())
						table.insert(visualTemplatesByPart[bodyPart], {
							template = template,
							relativeCFrame = bodyPart.CFrame:ToObjectSpace(visualRoot.CFrame),
						})
					end
					visualRootCount += #visualRoots
					local meshKey = getBarrageMeshKey(bodyPart)
					if meshKey then
						meshSources[meshKey] = meshSources[meshKey] or {}
						table.insert(meshSources[meshKey], bodyPart)
					end
				end
			end
			if visualRootCount == 0 then
				clearBarrageContextCache()
				return nil
			end
			local effectProfile = buildBarrageEffectProfile(stand, visualRootsByPart)
			barrageContextCache = {
				stand = stand,
				signature = signature,
				meshSources = meshSources,
				visualRootsByPart = visualRootsByPart,
				visualTemplatesByPart = visualTemplatesByPart,
				effectProfile = effectProfile,
				root = stand:FindFirstChild("HumanoidRootPart")
					or stand:FindFirstChild("UpperTorso")
					or stand:FindFirstChild("Torso"),
			}
			return barrageContextCache
		end
		_G.TheBestRefreshBarrageContext = makeBarrageSkinContext
		local function getNamedBarrageBodyPart(effectPart, context)
			local current = effectPart
			for _ = 1, 4 do
				if not current then
					break
				end
				local normalizedName = normalizeBarrageName(current.Name)
				local requestedName = barrageBodyAliases[normalizedName]
				if not requestedName then
					local side = normalizedName:find("left", 1, true) and "Left"
						or (normalizedName:find("right", 1, true) and "Right" or nil)
					if side and (normalizedName:find("hand", 1, true) or normalizedName:find("fist", 1, true)) then
						requestedName = side .. "Hand"
					elseif side and normalizedName:find("arm", 1, true) then
						requestedName = side .. "UpperArm"
					end
				end
				if requestedName then
					local bodyPart = findVisualBodyPart(context, requestedName)
					if bodyPart then
						return bodyPart
					end
				end
				current = current.Parent
			end
			return nil
		end
		local function chooseBarrageVisualSource(effectPart, context)
			local namedSource = getNamedBarrageBodyPart(effectPart, context)
			if namedSource then
				return namedSource
			end
			local meshKey = getBarrageMeshKey(effectPart)
			local candidates = meshKey and context.meshSources[meshKey]
			if not candidates or #candidates == 0 then
				return nil
			end
			local normalizedName = normalizeBarrageName(effectPart.Name)
			local wantedSide = normalizedName:find("left", 1, true) and "left"
				or (normalizedName:find("right", 1, true) and "right" or nil)
			if wantedSide then
				for _, candidate in ipairs(candidates) do
					if string.lower(candidate.Name):find(wantedSide, 1, true) then
						return candidate
					end
				end
			end
			return candidates[1]
		end
		local function applyBarrageStyleProperty(object, propertyName, value)
			if value == nil then
				return
			end
			pcall(function()
				object[propertyName] = value
			end)
		end
		local function applyBarrageEffectStyle(object, context)
			if not object or not object.Parent or isBarrageSkinVisual(object) then
				return false
			end
			if object:GetAttribute("TheBestBarrageEffectSignature") == context.signature then
				return false
			end
			local profile = context.effectProfile
			if not profile then
				return false
			end
			local changed = false
			local style = profile.effectStyles[object.ClassName]
			if object:IsA("ParticleEmitter") or object:IsA("Beam") or object:IsA("Trail") then
				local color = style and style.Color or profile.accentSequence
				if typeof(color) ~= "ColorSequence" then
					color = profile.accentSequence
				end
				applyBarrageStyleProperty(object, "Color", color)
				if style then
					if type(style.Texture) == "string" and style.Texture ~= "" then
						applyBarrageStyleProperty(object, "Texture", style.Texture)
					end
					applyBarrageStyleProperty(object, "LightEmission", style.LightEmission)
					applyBarrageStyleProperty(object, "LightInfluence", style.LightInfluence)
					applyBarrageStyleProperty(object, "Brightness", style.Brightness)
				end
				changed = true
			elseif object:IsA("PointLight") or object:IsA("SpotLight") or object:IsA("SurfaceLight") then
				applyBarrageStyleProperty(object, "Color", style and style.Color or profile.accentColor)
				changed = true
			elseif object:IsA("Smoke") then
				applyBarrageStyleProperty(object, "Color", style and style.Color or profile.accentColor)
				changed = true
			elseif object:IsA("Fire") then
				applyBarrageStyleProperty(object, "Color", style and style.Color or profile.accentColor)
				applyBarrageStyleProperty(
					object,
					"SecondaryColor",
					style and style.SecondaryColor or profile.accentColor
				)
				changed = true
			elseif object:IsA("Sparkles") then
				applyBarrageStyleProperty(
					object,
					"SparkleColor",
					style and style.SparkleColor or profile.accentColor
				)
				changed = true
			elseif object:IsA("Highlight") then
				applyBarrageStyleProperty(object, "FillColor", style and style.FillColor or profile.accentColor)
				applyBarrageStyleProperty(object, "OutlineColor", style and style.OutlineColor or profile.accentColor)
				changed = true
			elseif object:IsA("BasePart") and isBarrageEffectGeometry(object) then
				applyBarrageStyleProperty(object, "Color", profile.accentColor)
				changed = true
			elseif object:IsA("Decal") or object:IsA("Texture") then
				local parentPart = findBarrageAncestorBasePart(object)
				if parentPart and isBarrageEffectGeometry(parentPart) then
					applyBarrageStyleProperty(object, "Color3", profile.accentColor)
					changed = true
				end
			elseif object:IsA("SpecialMesh") then
				local parentPart = findBarrageAncestorBasePart(object)
				if parentPart and isBarrageEffectGeometry(parentPart) then
					applyBarrageStyleProperty(
						object,
						"VertexColor",
						Vector3.new(profile.accentColor.R, profile.accentColor.G, profile.accentColor.B)
					)
					changed = true
				end
			end
			if changed then
				pcall(function()
					object:SetAttribute("TheBestBarrageEffectSignature", context.signature)
				end)
			end
			return changed
		end
		local function getBarragePartPriority(part, context)
			if isBarrageEffectGeometry(part) then
				return -math.huge
			end
			local score = math.clamp(part.Size.X * part.Size.Y * part.Size.Z, 0, 100)
			local normalizedName = normalizeBarrageName(part.Name)
			if barrageBodyAliases[normalizedName]
				or normalizedName:find("hand", 1, true)
				or normalizedName:find("fist", 1, true)
				or normalizedName:find("arm", 1, true)
			then
				score += 10000
			end
			local meshKey = getBarrageMeshKey(part)
			if meshKey and context.meshSources[meshKey] then
				score += 5000
			end
			if chooseBarrageVisualSource(part, context) then
				score += 1000
			end
			return score
		end
		local function cloneBarrageVisualTemplate(templateData, effectPart)
			local clone = templateData.template:Clone()
			clone:SetAttribute("TheBestBarrageVisual", true)
			if clone:IsA("BasePart") then
				local relativeCFrame = templateData.relativeCFrame
				clone.CFrame = effectPart.CFrame * relativeCFrame
				clone.Anchored = false
				clone.CanCollide = false
				clone.CanTouch = false
				clone.CanQuery = false
				clone.Massless = true
				clone.LocalTransparencyModifier = 0
				local weld = Instance.new("Weld")
				weld.Name = "TheBestBarrageWeld"
				weld.Part0 = effectPart
				weld.Part1 = clone
				weld.C0 = relativeCFrame
				weld.C1 = CFrame.new()
				weld.Parent = clone
				clone.Parent = effectPart
				return true
			end
			clone.Parent = effectPart
			return false
		end
		local function hideOriginalBarrageVisual(effectPart, context, container)
			local originalParts = { effectPart }
			local seenParts = { [effectPart] = true }
			for _, descendant in ipairs(originalBarrageDescendants(effectPart)) do
				if descendant:IsA("BasePart") and not seenParts[descendant] then
					seenParts[descendant] = true
					table.insert(originalParts, descendant)
				end
			end
			local connectedOk, connectedParts = pcall(function()
				return effectPart:GetConnectedParts(true)
			end)
			if connectedOk then
				for _, connectedPart in ipairs(connectedParts) do
					local insideContainer = connectedPart == container or connectedPart:IsDescendantOf(container)
					if insideContainer and not seenParts[connectedPart] then
						seenParts[connectedPart] = true
						table.insert(originalParts, connectedPart)
					end
				end
			end
			for _, originalPart in ipairs(originalParts) do
				if not isBarrageSkinVisual(originalPart) then
					if originalPart == effectPart or not isBarrageEffectGeometry(originalPart) then
						pcall(function()
							originalPart:SetAttribute("TheBestBarrageOriginalHidden", true)
							originalPart.Transparency = 1
							originalPart.LocalTransparencyModifier = 1
							originalPart.CastShadow = false
							originalPart.CanCollide = false
							originalPart.CanTouch = false
							originalPart.CanQuery = false
						end)
						for _, descendant in ipairs(originalBarrageDescendants(originalPart)) do
							if not isBarrageSkinVisual(descendant) then
								if descendant:IsA("Decal") or descendant:IsA("Texture") then
									pcall(function()
										descendant.Transparency = 1
									end)
								elseif isBarrageEffectInstance(descendant) then
									applyBarrageEffectStyle(descendant, context)
								end
							end
						end
					else
						applyBarrageEffectStyle(originalPart, context)
					end
				end
			end
		end
		local function skinBarragePart(effectPart, context, requireProximity, container)
			if
				not effectPart:IsA("BasePart")
				or effectPart:GetAttribute("TheBestBarrageSkinned")
				or effectPart:GetAttribute("TheBestBarrageOriginalHidden")
				or isBarrageSkinVisual(effectPart)
				or isBarrageEffectGeometry(effectPart)
				or effectPart:IsDescendantOf(context.stand)
			then
				return false
			end
			if requireProximity then
				if not context.root or (effectPart.Position - context.root.Position).Magnitude > 45 then
					return false
				end
				local meshKey = getBarrageMeshKey(effectPart)
				local matchingMesh = meshKey and context.meshSources[meshKey]
				local ancestorModel = effectPart:FindFirstAncestorOfClass("Model")
				if not matchingMesh and (not ancestorModel or ancestorModel.Name ~= "Model") then
					return false
				end
			end
			local sourceBodyPart = chooseBarrageVisualSource(effectPart, context)
			if not sourceBodyPart then
				return false
			end
			effectPart:SetAttribute("TheBestBarrageSkinned", true)
			local createdPartVisual = false
			for _, templateData in ipairs(context.visualTemplatesByPart[sourceBodyPart] or {}) do
				createdPartVisual = cloneBarrageVisualTemplate(templateData, effectPart)
					or createdPartVisual
			end
			if not createdPartVisual then
				effectPart:SetAttribute("TheBestBarrageSkinned", nil)
				return false
			end
			effectPart:SetAttribute("TheBestBarrageSkinned", true)
			hideOriginalBarrageVisual(effectPart, context, container)
			return true
		end
		local function skinBarrageContainer(container, requireProximity)
			if not barrageHeld or not container or not container.Parent then
				return false
			end
			local context = makeBarrageSkinContext()
			if not context then
				return false
			end
			local changed = false
			local barrageParts = {}
			local skinnedAnchors = {}
			local insideWorkspace = container:IsDescendantOf(workspace)
			local enforceConnectedOriginals = insideWorkspace
				and (
					container:GetAttribute("TheBestBarrageConnectedHiddenSignature") ~= context.signature
					or container:GetAttribute("TheBestBarrageConnectionsDirty") == true
				)
			if container:IsA("BasePart") then
				applyBarrageEffectStyle(container, context)
				if container:GetAttribute("TheBestBarrageSkinned") then
					table.insert(skinnedAnchors, container)
				end
				if
					not isBarrageSkinVisual(container)
					and not container:GetAttribute("TheBestBarrageSkinned")
					and not container:GetAttribute("TheBestBarrageOriginalHidden")
				then
					table.insert(barrageParts, container)
				end
			end
			for _, descendant in ipairs(originalBarrageDescendants(container)) do
				if descendant:IsA("BasePart") then
					applyBarrageEffectStyle(descendant, context)
					if descendant:GetAttribute("TheBestBarrageSkinned") then
						table.insert(skinnedAnchors, descendant)
					end
				elseif
					isBarrageEffectInstance(descendant)
					or descendant:IsA("Decal")
					or descendant:IsA("Texture")
					or descendant:IsA("SpecialMesh")
				then
					applyBarrageEffectStyle(descendant, context)
				end
				if
					descendant:IsA("BasePart")
					and not isBarrageSkinVisual(descendant)
					and not descendant:GetAttribute("TheBestBarrageSkinned")
					and not descendant:GetAttribute("TheBestBarrageOriginalHidden")
				then
					table.insert(barrageParts, descendant)
				end
			end
			local priorities = {}
			for _, barragePart in ipairs(barrageParts) do
				priorities[barragePart] = getBarragePartPriority(barragePart, context)
			end
			table.sort(barrageParts, function(left, right)
				return priorities[left] > priorities[right]
			end)
			local totalSkinnedParts = #skinnedAnchors
			for _, barragePart in ipairs(barrageParts) do
				if totalSkinnedParts >= MAX_BARRAGE_SKINNED_PARTS_PER_MODEL then
					break
				end
				if priorities[barragePart] > -math.huge
					and skinBarragePart(barragePart, context, requireProximity, container)
				then
					changed = true
					totalSkinnedParts += 1
				end
			end
			if enforceConnectedOriginals then
				for _, skinnedAnchor in ipairs(skinnedAnchors) do
					if skinnedAnchor.Parent then
						hideOriginalBarrageVisual(skinnedAnchor, context, container)
					end
				end
				pcall(function()
					container:SetAttribute("TheBestBarrageConnectedHiddenSignature", context.signature)
					container:SetAttribute("TheBestBarrageConnectionsDirty", false)
				end)
			end
			if changed then
				pcall(function()
					container:SetAttribute("TheBestBarrageModelSkinSignature", context.signature)
				end)
			end
			return changed
		end
		local function disconnectBarrageModelWatcher(model)
			local watcher = barrageModelWatchers[model]
			if not watcher then
				return
			end
			if watcher.descendantConnection then
				watcher.descendantConnection:Disconnect()
			end
			if watcher.ancestryConnection then
				watcher.ancestryConnection:Disconnect()
			end
			barrageModelWatchers[model] = nil
		end
		local function disconnectAllBarrageModelWatchers()
			local models = {}
			for model in pairs(barrageModelWatchers) do
				table.insert(models, model)
			end
			for _, model in ipairs(models) do
				disconnectBarrageModelWatcher(model)
			end
		end
		local function watchBarrageModel(model, requireProximity)
			if
				not barrageHeld
				or not model
				or not model.Parent
				or not model:IsA("Model")
				or model.Name ~= "Model"
			then
				return
			end
			if barrageModelWatchers[model] then
				return
			end
			local watcher = { pendingScan = false, scanCount = 0 }
			barrageModelWatchers[model] = watcher
			local function scheduleModelScan()
				if watcher.pendingScan or watcher.scanCount >= 2 then
					return
				end
				watcher.pendingScan = true
				task.delay(0.035, function()
					watcher.pendingScan = false
					if barrageHeld and model.Parent and barrageModelWatchers[model] == watcher then
						watcher.scanCount += 1
						skinBarrageContainer(model, requireProximity)
					end
				end)
			end
			watcher.descendantConnection = model.DescendantAdded:Connect(function(object)
				if not barrageHeld then
					return
				end
				local scanTrigger = object:IsA("BasePart")
					or object:IsA("Motor6D")
					or object:IsA("Weld")
					or object:IsA("WeldConstraint")
				local styleCandidate = object:IsA("BasePart")
					or isBarrageEffectInstance(object)
					or object:IsA("Decal")
					or object:IsA("Texture")
					or object:IsA("SpecialMesh")
				if (not scanTrigger and not styleCandidate) or isBarrageSkinVisual(object) then
					return
				end
				if styleCandidate then
					local context = makeBarrageSkinContext()
					if context then
						applyBarrageEffectStyle(object, context)
					end
				end
				if scanTrigger then
					pcall(function()
						model:SetAttribute("TheBestBarrageConnectionsDirty", true)
					end)
					scheduleModelScan()
				end
			end)
			watcher.ancestryConnection = model.AncestryChanged:Connect(function(_, parent)
				if parent == nil then
					disconnectBarrageModelWatcher(model)
				end
			end)
			-- Let the game finish inserting the short-lived barrage model before the
			-- first scan. DescendantAdded can schedule at most one follow-up scan.
			scheduleModelScan()
		end
		table.insert(barrageConnections, barrageUserInputService.InputBegan:Connect(function(input, gameProcessed)
			if not gameProcessed and input.KeyCode == Enum.KeyCode.E then
				barrageHeld = true
				for _, child in ipairs(barrageReplicatedStorage:GetChildren()) do
					if child:IsA("Model") and child.Name == "Model" then
						watchBarrageModel(child, false)
					end
				end
			end
		end))
		table.insert(barrageConnections, barrageUserInputService.InputEnded:Connect(function(input)
			if input.KeyCode == Enum.KeyCode.E then
				barrageHeld = false
				disconnectAllBarrageModelWatchers()
			end
		end))
		table.insert(barrageConnections, barrageReplicatedStorage.ChildAdded:Connect(function(child)
			if barrageHeld and child:IsA("Model") and child.Name == "Model" then
				watchBarrageModel(child, false)
			end
		end))
		table.insert(barrageConnections, workspace.DescendantAdded:Connect(function(object)
			if
				not barrageHeld
				or not object:IsA("Model")
				or object.Name ~= "Model"
				or not hasActiveStandReplacement()
			then
				return
			end
			if not isBarrageSkinVisual(object) then watchBarrageModel(object, true) end
		end))
		_G.TheBestBarrageSkinCleanup = function()
			if _G.TheBestRefreshBarrageContext == makeBarrageSkinContext then _G.TheBestRefreshBarrageContext = nil end
			disconnectAllBarrageModelWatchers()
			clearBarrageContextCache()
			for _, connection in ipairs(barrageConnections) do
				connection:Disconnect()
			end
			table.clear(barrageConnections)
			if _G.TheBestBarrageSkinCleanup then
				_G.TheBestBarrageSkinCleanup = nil
			end
		end
		local function ApplyGloveSkinWhenReady()
			if not workspace:FindFirstChild("Living") then return end
			task.spawn(function()
				repeat
					task.wait(0.15)
				until #getAllGloves() > 0
				skinChanger(_G.Config.itemSkinGloves)
			end)
		end
		local function SetupCharacter()
			local living = workspace:FindFirstChild("Living")
			local workspacePlayer = living and living:FindFirstChild(player.Name) or player.Character
			if not workspacePlayer then return end
			if _G.qweqwe then
				_G.qweqwe:Disconnect()
			end
			local currentStand = workspacePlayer:FindFirstChild("StandMorph")
			if currentStand then
				ApplyStandSkinFromMorph(currentStand)
			end
			_G.qweqwe = workspacePlayer.ChildAdded:Connect(function(child)
				if child.Name == "StandMorph" then
					ApplyStandSkinFromMorph(child)
				end
			end)
		end
		local skinChangerCharacterConnection
