					local goldaCounter = _G.TheBestGoldaCounterController
					if type(goldaCounter) == "table" and type(goldaCounter.Destroy) == "function" then
						pcall(goldaCounter.Destroy)
					end
					_G.TheBestGoldaCounterController = nil

					local connectionNames = {
						"TheBestFinisherConnection", "TheBestLoadingScreenCaptureConnection",
						"TheBestSkillTreeCaptureConnection", "TheBestOldSoundsCharacterConnection",
						"miscVisualConn", "zqqqq", "ggwpqqq", "conn4", "conn5", "qwe", "ezzz",
						"fov_value_conn", "z", "qweqwe", "ttpConn",
					}
					for _, name in ipairs(connectionNames) do
