						if connection then
							pcall(function()
								connection:Disconnect()
							end)
						end
						_G[name] = nil
					end
					if type(_G.TheBestLoadingScreenCaptureConnections) == "table" then
						for _, connection in ipairs(_G.TheBestLoadingScreenCaptureConnections) do
							pcall(function()
								connection:Disconnect()
							end)
						end
					end
					_G.TheBestLoadingScreenCaptureConnections = nil

					pcall(function()
						game:GetService("RunService"):UnbindFromRenderStep("DrawingESP_Update")
					end)
					if _G.q_circle then
						pcall(function()
							_G.q_circle:Remove()
						end)
						_G.q_circle = nil
					end

					local localPlayer = game:GetService("Players").LocalPlayer
					local function removeOwnedGui(root)
						if not root then
							return
						end
						for _, gui in ipairs(root:GetChildren()) do
							if gui.Name == "MainFrameGUI"
								or gui.Name:sub(1, 7) == "TheBest"
								or gui:GetAttribute("TheBestOwned") == true
							then
								pcall(function()
									gui:Destroy()
								end)
							end
						end
					end
					removeOwnedGui(game:GetService("CoreGui"))
					removeOwnedGui(localPlayer and localPlayer:FindFirstChildOfClass("PlayerGui"))

					_G.TheBestBuildingUI = false
					_G.TheBestConfigSavePending = nil
					_G.TheBestKeybindSavePending = nil
					SaveConfig()
					Library:DestroyUI()
					_G.TheBestUiBuildToken = nil
					_G.TheBestEmergencyShutdown = nil
					_G.TheBestEmergencyShutdownActive = nil
					return true
				end
