				local avatarTextObjects = setmetatable({}, { __mode = "k" })
				local avatarPlaceholderObjects = setmetatable({}, { __mode = "k" })
				local function translateAvatarText(value)
					local text = tostring(value or "")
					if not (_G.Config and _G.Config.interfaceLanguage == "Russian") then return text end
					if avatarRussian[text] then return avatarRussian[text] end
					for _, pair in ipairs(avatarPrefixes) do
						if text:sub(1, #pair[1]) == pair[1] then return pair[2] .. text:sub(#pair[1] + 1) end
					end
					return text
				end
				local function setAvatarText(object, english)
					avatarTextObjects[object] = tostring(english or "")
					object.Text = translateAvatarText(english)
				end
				local function setAvatarPlaceholder(object, english)
					avatarPlaceholderObjects[object] = tostring(english or "")
					object.PlaceholderText = translateAvatarText(english)
				end
				Library.Localization.Register(function()
					for object, english in pairs(avatarTextObjects) do
						if object.Parent then object.Text = translateAvatarText(english) end
					end
					for object, english in pairs(avatarPlaceholderObjects) do
						if object.Parent then object.PlaceholderText = translateAvatarText(english) end
					end
				end)
				if not localPlayer then
					error("LocalPlayer is unavailable")
				end

				-- ---------- Safe enum helpers ----------
				local function enumItem(enumObject, name)
					local success, value = pcall(function()
						return enumObject[name]
					end)
					if success then
						return value
					end
					return nil
				end

				local function tryEnum(enumName, valueName)
					local success, result = pcall(function()
						local enumObject = Enum[enumName]
						return enumObject and enumObject[valueName]
					end)
					return success and result or nil
				end

				-- ---------- Create a full-width Avatar section ----------
				-- Category is registered before asynchronous catalog work.
				local avatarTab = avatarClass and Library:CreateFunctionTab(avatarClass, "Roblox Catalog")
				if not avatarTab or not avatarTab.elementContainer then
					error("Avatar tab container was not created")
				end

				avatarTab.fullWidth = true
				avatarTab.frame.Size = UDim2.fromOffset(500, 548)
				avatarTab.contentFrame.Size = UDim2.new(1, -24, 0, 524)
				avatarTab.elementContainer.Size = UDim2.fromOffset(480, 500)
				avatarTab.elementContainer.Position = UDim2.fromOffset(10, 25)

				local root = avatarTab.elementContainer

				local panel = Instance.new("Frame")
				panel.Name = "TheBestAvatarCatalog"
				panel.Size = UDim2.fromOffset(480, 500)
				panel.BackgroundColor3 = T.surface
				panel.BorderSizePixel = 0
				panel.LayoutOrder = 1
				panel.Parent = root

				local panelCorner = Instance.new("UICorner")
				panelCorner.CornerRadius = UDim.new(0, 10)
				panelCorner.Parent = panel

				local panelStroke = Instance.new("UIStroke")
				panelStroke.Color = T.stroke
				panelStroke.Transparency = 0.25
				panelStroke.Parent = panel

				local function addCorner(instance, radius)
					local c = Instance.new("UICorner")
					c.CornerRadius = UDim.new(0, radius or 6)
					c.Parent = instance
					return c
				end

				local function addStroke(instance, color, transparency)
					local s = Instance.new("UIStroke")
					s.Color = color or T.stroke
					s.Transparency = transparency == nil and 0.45 or transparency
					s.Parent = instance
					return s
				end

				local title = Instance.new("TextLabel")
				title.Size = UDim2.new(1, -24, 0, 25)
				title.Position = UDim2.fromOffset(12, 8)
				title.BackgroundTransparency = 1
				setAvatarText(title, "Avatar Catalog")
				title.TextColor3 = T.text
				title.TextSize = 16
				title.Font = Enum.Font.GothamBold
				title.TextXAlignment = Enum.TextXAlignment.Left
				title.Parent = panel

				local subtitle = Instance.new("TextLabel")
				subtitle.Size = UDim2.new(1, -24, 0, 17)
				subtitle.Position = UDim2.fromOffset(12, 32)
				subtitle.BackgroundTransparency = 1
				setAvatarText(subtitle, "Browse Roblox items \194\183 local try-on \194\183 visible only to you")
				subtitle.TextColor3 = T.textDim
				subtitle.TextSize = 9
				subtitle.Font = Enum.Font.Gotham
				subtitle.TextXAlignment = Enum.TextXAlignment.Left
				subtitle.Parent = panel

				local searchBox = Instance.new("TextBox")
				searchBox.Size = UDim2.fromOffset(250, 31)
				searchBox.Position = UDim2.fromOffset(12, 56)
				searchBox.BackgroundColor3 = T.dropdownBg
				searchBox.BorderSizePixel = 0
