				local function setStatus(text, bad)
					setAvatarText(status, tostring(text))
					status.TextColor3 = bad and Color3.fromRGB(255, 105, 105) or T.textDim
				end

				local function getCharacterHumanoid()
					local character = localPlayer.Character
					local humanoid = character and character:FindFirstChildOfClass("Humanoid")
					return character, humanoid
				end

				local function rememberOriginal()
					local character, humanoid = getCharacterHumanoid()
					if not humanoid then
						return nil
					end
					if originalCharacter ~= character or not originalDescription then
						local success, desc = pcall(function()
							return humanoid:GetAppliedDescription()
						end)
						if success and desc then
							originalCharacter = character
							originalDescription = desc:Clone()
						end
					end
					return originalDescription
				end

				local function clearPreview()
					for _, child in ipairs(worldModel:GetChildren()) do
						child:Destroy()
					end
					previewModel = nil
				end

				local function fitCamera(model)
					local success, boxCFrame, boxSize = pcall(function()
						return model:GetBoundingBox()
					end)
					if not success then
						camera.CFrame = CFrame.new(0, 2.5, 9) * CFrame.Angles(0, math.pi, 0)
						return
					end
					local height = math.max(boxSize.Y, 2)
					local width = math.max(boxSize.X, 2)
					local depth = math.max(boxSize.Z, 2)
					local distance = math.max(height * 0.90, width * 1.65, depth * 2.0, 4.8)
					local focus = boxCFrame.Position + Vector3.new(0, height * 0.05, 0)
					camera.CFrame = CFrame.lookAt(focus + Vector3.new(0, height * 0.02, distance), focus)
				end

				local function toggleAccessory(accessories, accessoryType, itemId)
					for i = #accessories, 1, -1 do
						local info = accessories[i]
						if tonumber(info.AssetId) == tonumber(itemId) then
							table.remove(accessories, i)
							return false
						end
					end
					return true
				end

				local ASSET_TYPE_NAMES = {
					[2] = "TShirt", [8] = "Hat", [11] = "Shirt", [12] = "Pants",
					[17] = "Head", [18] = "Face", [27] = "Torso", [28] = "RightArm",
					[29] = "LeftArm", [30] = "LeftLeg", [31] = "RightLeg",
					[41] = "HairAccessory", [42] = "FaceAccessory", [43] = "NeckAccessory",
					[44] = "ShoulderAccessory", [45] = "FrontAccessory", [46] = "BackAccessory",
					[47] = "WaistAccessory", [64] = "TShirtAccessory", [65] = "ShirtAccessory",
					[66] = "PantsAccessory", [67] = "JacketAccessory", [68] = "SweaterAccessory",
					[69] = "ShortsAccessory", [70] = "LeftShoeAccessory", [71] = "RightShoeAccessory",
					[72] = "DressSkirtAccessory", [79] = "DynamicHead",
				}
				local function normalizeAssetTypeName(value)
					if typeof(value) == "EnumItem" then return value.Name end
					local numeric = tonumber(value)
					if numeric and ASSET_TYPE_NAMES[numeric] then return ASSET_TYPE_NAMES[numeric] end
					local text = tostring(value or "")
					return text:match("Enum%.AvatarAssetType%.(.+)$") or text:match("AvatarAssetType%.(.+)$") or text
				end
				local function resolveItemAssetType(item)
					local itemId = tonumber(item.Id or item.id)
					local name = normalizeAssetTypeName(item.AssetType or item.assetType)
					if name ~= "" and name ~= "nil" and name ~= "Asset" and enumItem(Enum.AvatarAssetType, name) then return name end
					if itemId then
						local ok, details = pcall(function()
							return AvatarEditorService:GetItemDetails(itemId, Enum.AvatarItemType.Asset)
						end)
						if ok and type(details) == "table" then
							name = normalizeAssetTypeName(details.AssetType or details.AssetTypeId)
							item.AssetType = name
						end
					end
					return name
				end

				local bodyProperties = {
					TShirt = "GraphicTShirt",
					Shirt = "Shirt",
					Pants = "Pants",
					Head = "Head",
					DynamicHead = "Head",
					Face = "Face",
					Torso = "Torso",
					RightArm = "RightArm",
					LeftArm = "LeftArm",
					LeftLeg = "LeftLeg",
					RightLeg = "RightLeg",
				}

				local layeredTypes = {
					TShirtAccessory = true,
					ShirtAccessory = true,
					PantsAccessory = true,
					JacketAccessory = true,
					SweaterAccessory = true,
					ShortsAccessory = true,
					LeftShoeAccessory = true,
					RightShoeAccessory = true,
					DressSkirtAccessory = true,
				}

				local function createItemDescription(baseDescription, item)
					local description = baseDescription:Clone()
					local itemId = tonumber(item.Id or item.id)
					local assetTypeName = resolveItemAssetType(item)
					if not itemId then
						error("The item has no asset ID")
					end

					local bodyProperty = bodyProperties[assetTypeName]
					if bodyProperty then
						description[bodyProperty] = itemId
						return description
					end

					local avatarAssetType = enumItem(Enum.AvatarAssetType, assetTypeName)
					if not avatarAssetType then
						error("Unsupported asset type: " .. assetTypeName)
					end

					local accessoryNames = {
						Hat = "Hat", HairAccessory = "Hair", FaceAccessory = "Face",
						NeckAccessory = "Neck", ShoulderAccessory = "Shoulder", FrontAccessory = "Front",
						BackAccessory = "Back", WaistAccessory = "Waist", TShirtAccessory = "TShirt",
						ShirtAccessory = "Shirt", PantsAccessory = "Pants", JacketAccessory = "Jacket",
						SweaterAccessory = "Sweater", ShortsAccessory = "Shorts", LeftShoeAccessory = "LeftShoe",
						RightShoeAccessory = "RightShoe", DressSkirtAccessory = "DressSkirt",
					}
					local accessoryType = accessoryNames[assetTypeName] and enumItem(Enum.AccessoryType, accessoryNames[assetTypeName])
					if not accessoryType then
						local ok, resolved = pcall(function() return AvatarEditorService:GetAccessoryType(avatarAssetType) end)
						if ok then accessoryType = resolved end
					end
					local unknownType = enumItem(Enum.AccessoryType, "Unknown")
					if not accessoryType or (unknownType and accessoryType == unknownType) then
						error("This item cannot be previewed yet: " .. assetTypeName)
					end

					local accessories = description:GetAccessories(true)
					local shouldAdd = toggleAccessory(accessories, accessoryType, itemId)
					if not shouldAdd then
						description:SetAccessories(accessories, true)
						return description
					end

					local entry = {
						AssetId = itemId,
						AccessoryType = accessoryType,
					}

					if layeredTypes[assetTypeName] then
						entry.IsLayered = true
						local maxOrder = 0
						for _, info in ipairs(accessories) do
							local order = tonumber(info.Order) or 0
							maxOrder = math.max(maxOrder, order)
						end
						entry.Order = maxOrder + 1
						entry.Puffiness = 0.5
					end

					table.insert(accessories, entry)
					description:SetAccessories(accessories, true)
					return description
				end

				local function buildPreviewDescription(item)
					local base = rememberOriginal()
					if not base then
						error("Could not get the current avatar")
					end
					return createItemDescription(base, item)
				end

				local function showPreview(item)
					if not item or previewBusy then
						return
					end
					previewBusy = true
					selectedItem = item
					setAvatarText(previewName, tostring(item.Name or "Untitled"))
					local creator = tostring(item.CreatorName or item.creatorName or "Roblox")
					local price = item.Price
					if price == nil then price = item.price end
					local assetType = resolveItemAssetType(item)
					setAvatarText(previewMeta, "@" .. creator .. "\n" .. assetType .. "  \194\183  " .. (price ~= nil and tostring(price) .. " R$" or "Price unavailable"))
					setStatus("Building 3D preview...", false)

					task.spawn(function()
						local success, err = pcall(function()
							local description = buildPreviewDescription(item)
							local model = PlayersService:CreateHumanoidModelFromDescriptionAsync(
								description,
								Enum.HumanoidRigType.R15,
								Enum.AssetTypeVerification.Default
							)
							clearPreview()
							model.Name = "AvatarPreview"
							model.Parent = worldModel
							previewModel = model
							fitCamera(model)
						end)
						previewBusy = false
						if success then
							setStatus("Ready. Click the item again or press \226\128\156Wear\226\128\157.", false)
						else
							clearPreview()
							setStatus("3D preview failed: " .. tostring(err), true)
						end
					end)
				end

				local LOCAL_TAG = "__THEBEST_LOCAL_AVATAR_ITEM"

				local function markLocal(instance)
					pcall(function() instance:SetAttribute(LOCAL_TAG, true) end)
					return instance
				end

				local function loadLocalAsset(assetId)
					assetId = tonumber(assetId)
					if not assetId then
						error("Invalid asset ID")
					end

					-- Executor-friendly path first. This returns the actual catalog instance
					-- instead of trying to call the server-only ApplyDescription API.
					local getObjects = game.GetObjects
					if type(getObjects) == "function" then
						local ok, objects = pcall(function()
							return game:GetObjects("rbxassetid://" .. tostring(assetId))
						end)
						if ok and type(objects) == "table" and #objects > 0 then
							return objects
						end
					end

					local InsertService = game:GetService("InsertService")
					local ok, model = pcall(function()
						return InsertService:LoadAsset(assetId)
					end)
					if ok and model then
						return model:GetChildren()
					end

					return nil, "Roblox did not allow this item to load locally"
				end

				local function findWearable(objects)
					for _, rootObject in ipairs(objects or {}) do
						if rootObject:IsA("Accessory") or rootObject:IsA("Shirt") or rootObject:IsA("Pants") or rootObject:IsA("ShirtGraphic") then
							return rootObject
						end
						local direct = rootObject:FindFirstChildWhichIsA("Accessory", true)
							or rootObject:FindFirstChildWhichIsA("Shirt", true)
							or rootObject:FindFirstChildWhichIsA("Pants", true)
							or rootObject:FindFirstChildWhichIsA("ShirtGraphic", true)
						if direct then
							return direct
						end
					end
					return nil
				end

				local function removeLocalClothing(character, className)
					for _, child in ipairs(character:GetChildren()) do
						if child:IsA(className) and child:GetAttribute(LOCAL_TAG) then
							child:Destroy()
						end
					end
				end

				local function replaceClothing(character, instance, className)
					removeLocalClothing(character, className)
					for _, child in ipairs(character:GetChildren()) do
						if child:IsA(className) and not child:GetAttribute(LOCAL_TAG) then
							if className == "Shirt" then
								child.ShirtTemplate = instance.ShirtTemplate
								return
							elseif className == "Pants" then
								child.PantsTemplate = instance.PantsTemplate
								return
							elseif className == "ShirtGraphic" then
								child.Graphic = instance.Graphic
								return
							end
						end
					end
					local clone = markLocal(instance:Clone())
					clone.Parent = character
				end

				local function applyLocally(item)
					if not item then
						setStatus("Select an item first.", true)
						return
					end
					local character, humanoid = getCharacterHumanoid()
					if not character or not humanoid then
						setStatus("Your character is not ready yet.", true)
						return
					end

					local assetId = tonumber(item.Id or item.id)
					local assetType = resolveItemAssetType(item)
					if not assetId then
						setStatus("The item has no valid asset ID.", true)
						return
					end

					setStatus("Loading the item locally...", false)
					local success, err = pcall(function()
						local objects, loadError = loadLocalAsset(assetId)
						if not objects then
							error(loadError or "could not get the asset object")
						end

						local wearable = findWearable(objects)
						if wearable and wearable:IsA("Accessory") then
							local accessory = markLocal(wearable:Clone())
							accessory.Parent = nil
							humanoid:AddAccessory(accessory)
							accessory.Parent = character
							pcall(function() humanoid:BuildRigFromAttachments() end)
							return
						end

						if wearable and wearable:IsA("Shirt") then
							replaceClothing(character, wearable, "Shirt")
							return
						end
						if wearable and wearable:IsA("Pants") then
							replaceClothing(character, wearable, "Pants")
							return
						end
						if wearable and wearable:IsA("ShirtGraphic") then
							replaceClothing(character, wearable, "ShirtGraphic")
							return
						end

						-- Fallback for face assets: use the preview model's face decal when available.
						if assetType == "Face" and previewModel then
							local sourceHead = previewModel:FindFirstChild("Head", true)
							local targetHead = character:FindFirstChild("Head")
							if sourceHead and targetHead then
								local sourceFace = sourceHead:FindFirstChild("face") or sourceHead:FindFirstChildWhichIsA("Decal")
								if sourceFace and targetHead then
									local oldLocal = targetHead:FindFirstChild("__THEBEST_LOCAL_FACE")
									if oldLocal then oldLocal:Destroy() end
									local newFace = markLocal(sourceFace:Clone())
									newFace.Name = "__THEBEST_LOCAL_FACE"
									newFace.Parent = targetHead
									return
								end
							end
						end

						error("This item type cannot be worn locally in this version")
					end)

					if success then
						setStatus("\226\156\147 Worn locally: " .. tostring(item.Name or "item"), false)
					else
						setStatus("Could not wear item: " .. tostring(err), true)
					end
				end

				local function resetAvatar()
					local character = getCharacterHumanoid()
					if not character then
						setStatus("Your character is not ready yet.", true)
						return
					end
					local success, err = pcall(function()
						for _, descendant in ipairs(character:GetDescendants()) do
							if descendant:GetAttribute(LOCAL_TAG) then
								descendant:Destroy()
							end
						end
					end)
					if success then
						setStatus("\226\156\147 Local avatar changes were reset.", false)
						if selectedItem then
							showPreview(selectedItem)
						end
					else
						setStatus("Reset failed: " .. tostring(err), true)
					end
				end

				local function clearItems()
					for _, child in ipairs(itemsScroll:GetChildren()) do
						if child ~= grid then
							child:Destroy()
						end
					end
				end

				local function setPageButtons()
					local canPrevious = currentPage > 1
					local canNext = httpMode and httpNextCursor ~= nil or (not httpMode and pagesObject and not pagesObject.IsFinished)
					previousButton.AutoButtonColor = canPrevious
					previousButton.TextTransparency = canPrevious and 0 or 0.5
					previousButton.Active = canPrevious
					nextButton.AutoButtonColor = canNext and true or false
					nextButton.TextTransparency = canNext and 0 or 0.5
					nextButton.Active = canNext
					setAvatarText(pageLabel, "Page " .. tostring(currentPage))
				end

				local function createCard(item, index)
					local card = Instance.new("TextButton")
					card.Name = "CatalogItem_" .. tostring(item.Id or index)
					card.BackgroundColor3 = T.surface
					card.BorderSizePixel = 0
					setAvatarText(card, "")
					card.AutoButtonColor = false
					card.LayoutOrder = index
					card.ZIndex = 3
					card.Parent = itemsScroll
					addCorner(card, 7)

					local image = Instance.new("ImageLabel")
					image.Size = UDim2.new(1, -10, 0, 78)
					image.Position = UDim2.fromOffset(5, 5)
					image.BackgroundColor3 = T.dropdownBg
					image.BorderSizePixel = 0
					image.ScaleType = Enum.ScaleType.Fit
					image.Image = "rbxthumb://type=Asset&id=" .. tostring(item.Id or 0) .. "&w=180&h=180"
					image.ZIndex = 4
					image.Parent = card
					addCorner(image, 6)

					local nameLabel = Instance.new("TextLabel")
					nameLabel.Size = UDim2.new(1, -10, 0, 28)
					nameLabel.Position = UDim2.fromOffset(5, 86)
					nameLabel.BackgroundTransparency = 1
					setAvatarText(nameLabel, tostring(item.Name or "Untitled"))
					nameLabel.TextColor3 = T.text
					nameLabel.TextSize = 8
					nameLabel.Font = Enum.Font.GothamBold
					nameLabel.TextWrapped = true
					nameLabel.TextXAlignment = Enum.TextXAlignment.Left
					nameLabel.TextYAlignment = Enum.TextYAlignment.Top
					nameLabel.ZIndex = 4
					nameLabel.Parent = card

					local priceLabel = Instance.new("TextLabel")
					priceLabel.Size = UDim2.new(1, -10, 0, 12)
					priceLabel.Position = UDim2.fromOffset(5, 114)
					priceLabel.BackgroundTransparency = 1
					local price = item.Price
					if price == nil then price = item.price end
					setAvatarText(priceLabel, price ~= nil and tostring(price) .. " R$" or "Not for sale")
					priceLabel.TextColor3 = T.accent
					priceLabel.TextSize = 8
					priceLabel.Font = Enum.Font.GothamBold
					priceLabel.TextXAlignment = Enum.TextXAlignment.Left
					priceLabel.ZIndex = 4
					priceLabel.Parent = card

					card.MouseEnter:Connect(function()
						if selectedItem ~= item then
							card.BackgroundColor3 = T.hover
						end
					end)
					card.MouseLeave:Connect(function()
						if selectedItem ~= item then
							card.BackgroundColor3 = T.surface
						end
					end)
					card.MouseButton1Click:Connect(function()
						selectedItem = item
						for _, child in ipairs(itemsScroll:GetChildren()) do
							if child:IsA("TextButton") then
								child.BackgroundColor3 = T.surface
							end
						end
						card.BackgroundColor3 = T.hover
						showPreview(item)
					end)

					return card
				end

				local function renderItems(items)
					clearItems()
					emptyLabel.Visible = #items == 0
					for index, item in ipairs(items) do
						createCard(item, index)
					end
					task.defer(function()
						local columns = 3
						local rows = math.ceil(#items / columns)
						itemsScroll.CanvasSize = UDim2.fromOffset(0, math.max(320, rows * 133 + 6))
					end)
				end

				local function encode(value)
					local success, result = pcall(function()
						return HttpService:UrlEncode(tostring(value or ""))
					end)
					if success and result then
						return result
					end
					return tostring(value or ""):gsub("([^%w%-%._~])", function(ch)
						return string.format("%%%02X", string.byte(ch))
					end)
				end

				local function httpGet(url)
					local success, result = pcall(function()
						if type(request) == "function" then
							local response = request({ Url = url, Method = "GET" })
							return response and (response.Body or response.body)
						end
						if type(http_request) == "function" then
							local response = http_request({ Url = url, Method = "GET" })
							return response and (response.Body or response.body)
						end
						if type(syn) == "table" and type(syn.request) == "function" then
							local response = syn.request({ Url = url, Method = "GET" })
							return response and (response.Body or response.body)
						end
						return game:HttpGet(url)
					end)
					if success and type(result) == "string" and #result > 0 then
						return true, result
					end
					return false, tostring(result)
				end

				local function normalizeHttpItem(item)
					return {
						Id = tonumber(item.id or item.Id),
						Name = item.name or item.Name,
						AssetType = tonumber(item.assetType or item.AssetType),
						CreatorName = item.creatorName or item.CreatorName,
						Price = item.price ~= nil and item.price or item.Price,
						FavoriteCount = item.favoriteCount or item.FavoriteCount or 0,
						Description = item.description or item.Description or "",
						ItemType = tostring(item.itemType or item.ItemType or "Asset"),
					}
				end

				local function assetTypeNameFromId(typeId)
					return normalizeAssetTypeName(typeId)
				end

				local httpCategory = {
					[1] = { category = 1, subcategory = 1 },
					[2] = { category = 11, subcategory = 20 },
					[3] = { category = 11, subcategory = 9 },
					[4] = { category = 11, subcategory = 21 },
					[5] = { category = 11, subcategory = 22 },
					[6] = { category = 11, subcategory = 23 },
					[7] = { category = 11, subcategory = 25 },
					[8] = { category = 11, subcategory = 24 },
					[9] = { category = 11, subcategory = 26 },
					[10] = { category = 3, subcategory = 3 },
					[11] = { category = 11, subcategory = 64 },
					[12] = { category = 4, subcategory = 15 },
				}

				local function makeHttpUrl(cursor)
					local categoryInfo = httpCategory[selectedCategory] or httpCategory[1]
					local sortType = ({ [1] = 0, [2] = 1, [3] = 3 })[currentSort] or 0
					local url = "https://catalog.roblox.com/v1/search/items/details?Category=" .. tostring(categoryInfo.category)
					url = url .. "&Subcategory=" .. tostring(categoryInfo.subcategory)
					url = url .. "&SortType=" .. tostring(sortType) .. "&SortAggregation=5&Limit=30"
					if tostring(searchBox.Text or "") ~= "" then
						url = url .. "&Keyword=" .. encode(searchBox.Text)
					end
					if cursor and cursor ~= "" then
						url = url .. "&Cursor=" .. encode(cursor)
					end
					return url
				end

				local function makeCatalogParams()
					local params = CatalogSearchParams.new()
					params.SearchKeyword = tostring(searchBox.Text or "")
					params.Limit = 30
					params.IncludeOffSale = false

					local aggregation = tryEnum("CatalogSortAggregation", "AllTime")
					if aggregation then
						pcall(function() params.SortAggregation = aggregation end)
					end

					local sortType = tryEnum("CatalogSortType", sortValues[currentSort])
					if sortType then
						pcall(function() params.SortType = sortType end)
					end

					local definition = categoryDefinitions[selectedCategory]
					if definition and definition.types then
						local types = {}
						for _, typeName in ipairs(definition.types) do
							local value = enumItem(Enum.AvatarAssetType, typeName)
							if value then
								table.insert(types, value)
							end
						end
						if #types > 0 then
							params.AssetTypes = types
						end
					end
					return params
				end

				local function loadCatalog(firstPage)
					if busy then return end
					busy = true
					setStatus("Loading Roblox catalog...", false)
					emptyLabel.Visible = false

					task.spawn(function()
						-- Executor-friendly HTTP path first: it mirrors the public
						-- Roblox Marketplace endpoint. If unavailable, fall back
						-- to AvatarEditorService inside Roblox itself.
						local httpOK, httpBody = httpGet(makeHttpUrl(nil))
						if httpOK then
							local decodeOK, payload = pcall(function()
								return HttpService:JSONDecode(httpBody)
							end)
							if decodeOK and type(payload) == "table" and type(payload.data) == "table" then
								httpMode = true
								pagesObject = nil
								currentPage = 1
								httpNextCursor = payload.nextPageCursor
								httpCursors = { [1] = nil }
								local normalized = {}
								for _, raw in ipairs(payload.data) do
									local item = normalizeHttpItem(raw)
									item.AssetType = assetTypeNameFromId(item.AssetType)
									if item.Id and item.ItemType ~= "Bundle" then table.insert(normalized, item) end
								end
								cachedPages[1] = normalized
								renderItems(normalized)
								setPageButtons()
								setStatus(#normalized > 0 and ("Items found: " .. tostring(#normalized)) or "Nothing found.", false)
								busy = false
								return
							end
						end

						-- Roblox-native fallback.
						local serviceSuccess, result = pcall(function()
							local params = makeCatalogParams()
							return AvatarEditorService:SearchCatalogAsync(params)
						end)
						if not serviceSuccess then
							busy = false
							emptyLabel.Visible = true
							setAvatarText(emptyLabel, "The catalog did not respond. Press \226\128\156Search\226\128\157 again.")
							setStatus("Could not open Marketplace: " .. tostring(result), true)
							return
						end

						httpMode = false
						pagesObject = result
						currentPage = 1
						cachedPages = {}
						local pageData = pagesObject:GetCurrentPage()
						cachedPages[1] = pageData
						renderItems(pageData)
						setPageButtons()
						setStatus(#pageData > 0 and ("Items found: " .. tostring(#pageData)) or "Nothing found.", false)
						busy = false
					end)
				end

				local function nextPage()
					if busy then return end
					local cachedNext = cachedPages[currentPage + 1]
					if cachedNext then
						currentPage += 1
						renderItems(cachedNext)
						setPageButtons()
						setStatus("Page loaded from cache.", false)
						return
					end

					if httpMode then
						if not httpNextCursor then return end
						busy = true
						setStatus("Loading next page...", false)
						task.spawn(function()
							local targetPage = currentPage + 1
							local url = makeHttpUrl(httpNextCursor)
							local ok, body = httpGet(url)
							local decoded, payload = false, nil
							if ok then
								decoded, payload = pcall(function() return HttpService:JSONDecode(body) end)
							end
							if decoded and type(payload) == "table" and type(payload.data) == "table" then
								local normalized = {}
								for _, raw in ipairs(payload.data) do
									local item = normalizeHttpItem(raw)
									item.AssetType = assetTypeNameFromId(item.AssetType)
									if item.Id and item.ItemType ~= "Bundle" then table.insert(normalized, item) end
								end
								currentPage = targetPage
								httpCursors[currentPage] = httpNextCursor
								httpNextCursor = payload.nextPageCursor
								cachedPages[currentPage] = normalized
								renderItems(normalized)
								setStatus("Page loaded.", false)
							else
								setStatus("Could not load the catalog page.", true)
							end
							setPageButtons()
							busy = false
						end)
						return
					end

					if not pagesObject or pagesObject.IsFinished then return end
					busy = true
					setStatus("Loading next page...", false)
					task.spawn(function()
						local success, err = pcall(function()
							pagesObject:AdvanceToNextPageAsync()
							currentPage += 1
							local pageData = pagesObject:GetCurrentPage()
							cachedPages[currentPage] = pageData
							renderItems(pageData)
						end)
						setPageButtons()
						setStatus(success and "Page loaded." or ("Could not load page: " .. tostring(err)), not success)
						busy = false
					end)
				end

				local function previousPage()
					if busy or currentPage <= 1 then return end
					local target = currentPage - 1
					local cached = cachedPages[target]
					if not cached then return end
					currentPage = target
					renderItems(cached)
					setPageButtons()
					setStatus("Page loaded from cache.", false)
				end

				categoryList:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(function()
					categoryScroll.CanvasSize = UDim2.fromOffset(0, categoryList.AbsoluteContentSize.Y + 6)
				end)

				for index, definition in ipairs(categoryDefinitions) do
					local option = Instance.new("TextButton")
					option.Size = UDim2.new(1, -6, 0, 27)
					option.BackgroundColor3 = T.dropdownBg
					option.BorderSizePixel = 0
					setAvatarText(option, definition.name)
					option.TextColor3 = T.text
					option.TextSize = 9
					option.Font = Enum.Font.Gotham
					option.TextXAlignment = Enum.TextXAlignment.Left
					option.LayoutOrder = index
					option.ZIndex = 52
					option.Parent = categoryScroll
					addCorner(option, 5)
					option.MouseButton1Click:Connect(function()
						selectedCategory = index
						setAvatarText(categoryButton, definition.name .. "  \226\150\190")
						categoryMenu.Visible = false
						loadCatalog(true)
					end)
				end

				categoryButton.MouseButton1Click:Connect(function()
					categoryMenu.Visible = not categoryMenu.Visible
				end)

				searchButton.MouseButton1Click:Connect(function()
					currentPage = 1
					loadCatalog(true)
				end)

				searchBox.FocusLost:Connect(function(enterPressed)
					if enterPressed then
						currentPage = 1
						loadCatalog(true)
					end
				end)

				for index, button in ipairs(sortButtons) do
					button.MouseButton1Click:Connect(function()
						currentSort = index
						for i, other in ipairs(sortButtons) do
							other.BackgroundColor3 = i == currentSort and T.accent or T.dropdownBg
							other.TextColor3 = i == currentSort and T.background or T.textDim
						end
						loadCatalog(true)
					end)
				end

				nextButton.MouseButton1Click:Connect(nextPage)
				previousButton.MouseButton1Click:Connect(previousPage)
				tryButton.MouseButton1Click:Connect(function()
					applyLocally(selectedItem)
				end)
				resetButton.MouseButton1Click:Connect(resetAvatar)

				-- Double-click the preview to toggle automatic spin.
				viewport.InputBegan:Connect(function(input)
					if input.UserInputType == Enum.UserInputType.MouseButton1 then
						autoRotate = not autoRotate
						setStatus(autoRotate and "Auto-rotation enabled." or "Auto-rotation disabled.", false)
					end
				end)

				local function previewVisible()
					local object = panel
					while object do
						if object:IsA("GuiObject") and not object.Visible then return false end
						if object:IsA("ScreenGui") then return object.Enabled end
						object = object.Parent
					end
					return false
				end
				local rotationConnection = RunService.RenderStepped:Connect(function(delta)
					if previewModel and previewModel.Parent and autoRotate and previewVisible() then
						previewRotation += delta * 0.65
						local pivot = previewModel:GetPivot()
						previewModel:PivotTo(CFrame.new(pivot.Position) * CFrame.Angles(0, previewRotation, 0))
					end
				end)

				local respawnConnection = localPlayer.CharacterAdded:Connect(function()
					originalDescription = nil
					originalCharacter = nil
				end)

				registerThemeListener(function(theme)
					panel.BackgroundColor3 = theme.surface
					panelStroke.Color = theme.stroke
					title.TextColor3 = theme.text
					subtitle.TextColor3 = theme.textDim
					searchBox.BackgroundColor3 = theme.dropdownBg
					searchBox.TextColor3 = theme.text
					searchBox.PlaceholderColor3 = theme.textDim
					searchButton.BackgroundColor3 = theme.accent
					searchButton.TextColor3 = theme.background
					categoryButton.BackgroundColor3 = theme.dropdownBg
					categoryButton.TextColor3 = theme.text
					categoryMenu.BackgroundColor3 = theme.surface
					status.TextColor3 = theme.textDim
					listFrame.BackgroundColor3 = theme.dropdownBg
					previewFrame.BackgroundColor3 = theme.dropdownBg
					previewTitle.TextColor3 = theme.text
					previewName.TextColor3 = theme.text
					previewMeta.TextColor3 = theme.textDim
					tryButton.BackgroundColor3 = theme.accent
					tryButton.TextColor3 = theme.background
					resetButton.BackgroundColor3 = theme.surface
					resetButton.TextColor3 = theme.text
					bottomBar.BackgroundColor3 = theme.dropdownBg
					pageLabel.TextColor3 = theme.textDim
					previousButton.BackgroundColor3 = theme.dropdownBg
					previousButton.TextColor3 = theme.text
					nextButton.BackgroundColor3 = theme.dropdownBg
					nextButton.TextColor3 = theme.text
					for i, button in ipairs(sortButtons) do
						button.BackgroundColor3 = i == currentSort and theme.accent or theme.dropdownBg
						button.TextColor3 = i == currentSort and theme.background or theme.textDim
					end
					for _, child in ipairs(categoryScroll:GetChildren()) do
						if child:IsA("TextButton") then
							child.BackgroundColor3 = theme.dropdownBg
							child.TextColor3 = theme.text
						end
					end
				end)

				_G.TheBestAvatarCatalogCleanup = function()
					rotationConnection:Disconnect()
					respawnConnection:Disconnect()
					clearPreview()
					if originalDescription then originalDescription:Destroy(); originalDescription = nil end
				end
				setPageButtons()
				setStatus("Starting catalog...", false)
				Library:LayoutFunctionTabs(avatarClass)
				task.delay(0.35, function()
					if panel and panel.Parent then
						loadCatalog(true)
					end
				end)
			end)

			if not ok then
				warn("[THEBEST/AVATAR] " .. tostring(moduleError))
			end
		end)

		end

