		for index,value in ipairs(encoded) do
			local path=string.format("%s/inferno-video-v010-%02d.png",folder,index)
			if not isfile(path) then writefile(path,decodeBase64(value)) end
			assets.sheets[index]=loader(path)
			assert(assets.sheets[index],"Could not register Inferno video sheet")
			task.wait()
		end
		cached=assets;encoded=nil
		return cached
	end
end)()

local function installOrbitThemeEffects(context)
	local frame, orbit, core = context.frame, context.orbit, context.core
	local runService = context.runService or game:GetService("RunService")
	local random = Random.new(48721)
	local theme, activeKey, renderConnection = nil, nil, nil
	local stopped, elapsed = false, 0
	local lifecycle, streams, coreTextState = {}, {}, {}
	local matrixLayer, fireLayer = nil, nil
	local videoAssets, loading, videoError = nil, false, nil
	local videoImages = {}
	local videoFrame, videoSheet, videoAccumulator = 1, nil, 0
	local refresh
	local coreStroke = core:FindFirstChildOfClass("UIStroke")
	local coreTransparency = core.BackgroundTransparency
	local coreThickness = coreStroke and coreStroke.Thickness or 1
	local coreStrokeTransparency = coreStroke and coreStroke.Transparency or 0
	local function make(kind, properties, parent)
		local item = Instance.new(kind)
		for key, value in pairs(properties) do item[key] = value end
		item.Parent = parent
		return item
	end
	local function rounded(item)
		make("UICorner", { CornerRadius = UDim.new(1, 0) }, item)
	end
	local function characters(count)
		local alphabet, result = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ", {}
		for i = 1, count do
			local index = random:NextInteger(1, #alphabet)
			result[i] = alphabet:sub(index, index)
		end
		return table.concat(result, "\n")
	end
	local function createMatrix()
		if matrixLayer then return end
		matrixLayer = make("Frame", {
			Name = "OrbitMatrixRain", BackgroundTransparency = 1,
			Size = UDim2.fromScale(1, 1), ClipsDescendants = true,
			Active = false, Visible = false, ZIndex = 1,
		}, orbit)
		for index = 1, 22 do
			local rows = random:NextInteger(11, 19)
			local text = make("TextLabel", {
				Name = "Rain" .. index, BackgroundTransparency = 1,
				AnchorPoint = Vector2.new(.5, 0), Position = UDim2.new((index - .5) / 22, 0, 0, 0),
				Size = UDim2.fromOffset(20, rows * 15), Font = Enum.Font.Code,
				Text = characters(rows), TextSize = 13, LineHeight = 1.08,
				TextColor3 = Color3.fromRGB(80, 255, 140), TextTransparency = .57,
				TextXAlignment = Enum.TextXAlignment.Center, TextYAlignment = Enum.TextYAlignment.Top,
				Active = false, ZIndex = 1,
			}, matrixLayer)
			make("UIGradient", {
				Rotation = 90,
				Color = ColorSequence.new({
					ColorSequenceKeypoint.new(0, Color3.fromRGB(0, 70, 28)),
					ColorSequenceKeypoint.new(.72, Color3.fromRGB(18, 220, 90)),
					ColorSequenceKeypoint.new(1, Color3.fromRGB(200, 255, 215)),
				}),
				Transparency = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(.2, .25),
					NumberSequenceKeypoint.new(.88, 0), NumberSequenceKeypoint.new(1, .05),
				}),
			}, text)
			streams[index] = {
				object = text, y = random:NextNumber(-650, 450), speed = random:NextNumber(62, 108),
				height = rows * 15, x = (index - .5) / 22, rows = rows,
			}
		end
	end



	local function showVideoFrame(index)
		if not fireLayer or not videoAssets then return end
		local perSheet = videoAssets.columns * videoAssets.rows
		local zero = index - 1
		local sheetIndex = math.floor(zero / perSheet) + 1
		local within = zero % perSheet
		local current = videoImages[sheetIndex]
		if not current then return end
		if videoSheet ~= sheetIndex then
			local previous = videoImages[videoSheet]
			if previous then previous.ImageTransparency = 1 end
			current.ImageTransparency = videoAssets.imageTransparency or 0
			videoSheet = sheetIndex
		end
		local offsetX = videoAssets.frameOffsetX or videoAssets.paddingX or videoAssets.padding or 0
		local offsetY = videoAssets.frameOffsetY or videoAssets.paddingY or videoAssets.padding or 0
		local stepX = videoAssets.cellStepX or videoAssets.strideX or (videoAssets.frameWidth + offsetX * 2)
		local stepY = videoAssets.cellStepY or videoAssets.strideY or (videoAssets.frameHeight + offsetY * 2)
		current.ImageRectOffset = Vector2.new((within % videoAssets.columns) * stepX + offsetX,
			math.floor(within / videoAssets.columns) * stepY + offsetY)
	end
	local function loadInferno()
		if loading or videoAssets or videoError then return end
		if type(context.prepareInfernoVideo) ~= "function" then
			videoError = "Inferno video preparation is unavailable"
			warn("[TheBest] " .. videoError)
			return
		end
		loading = true
		task.spawn(function()
			local ok, assets = pcall(context.prepareInfernoVideo)
			if stopped then return end
			if not ok or type(assets) ~= "table" or type(assets.sheets) ~= "table" or #assets.sheets == 0
				or not assets.frameWidth or assets.frameWidth < 1 or not assets.frameHeight or assets.frameHeight < 1
				or not assets.columns or assets.columns < 1 or not assets.rows or assets.rows < 1
				or not assets.frameCount or assets.frameCount < 1
				or #assets.sheets * assets.columns * assets.rows < assets.frameCount then
				loading, videoError = false, tostring(ok and "Invalid Inferno video assets" or assets)
				warn("[TheBest] Inferno video: " .. videoError)
				return
			end
			local imageWidth = context.infernoWidth or 340
			local imageHeight = context.infernoHeight or math.min(500, imageWidth * assets.frameHeight / assets.frameWidth)
			fireLayer = make("Frame", {
				Name = "OrbitInfernoVideo", BackgroundTransparency = 1, BorderSizePixel = 0,
				AnchorPoint = Vector2.new(.5, 1),
				Position = context.infernoPosition or UDim2.fromOffset(core.Position.X.Offset, core.Position.Y.Offset + 108),
				Size = UDim2.fromOffset(imageWidth, imageHeight), Active = false, Visible = false, ZIndex = 1,
			}, orbit)
			local offsetX = assets.frameOffsetX or assets.paddingX or assets.padding or 0
			local offsetY = assets.frameOffsetY or assets.paddingY or assets.padding or 0
			for index, asset in ipairs(assets.sheets) do
				-- Each resident Image is assigned exactly once. Playback never changes a URI.
				videoImages[index] = make("ImageLabel", {
					Name = "Sheet" .. index, BackgroundTransparency = 1, BorderSizePixel = 0,
					Position = UDim2.fromScale(0, 0), Size = UDim2.fromScale(1, 1),
					Image = asset, ImageColor3 = Color3.fromRGB(255, 255, 255), ImageTransparency = 1,
					ImageRectSize = Vector2.new(assets.frameWidth, assets.frameHeight),
					ImageRectOffset = Vector2.new(offsetX, offsetY), ScaleType = Enum.ScaleType.Stretch,
					Active = false, Visible = true, ZIndex = 1,
				}, fireLayer)
			end
			local provider = context.contentProvider or game:GetService("ContentProvider")
			local fetched = true
			local preloaded, preloadError = pcall(function()
				provider:PreloadAsync(videoImages, function(_, status)
					if status ~= Enum.AssetFetchStatus.Success then fetched = false end
				end)
			end)
			if stopped then return end
			if not preloaded or not fetched then
				loading, videoError = false, tostring(preloaded and "An Inferno atlas failed to preload" or preloadError)
				fireLayer:Destroy(); fireLayer = nil; table.clear(videoImages)
				warn("[TheBest] Inferno preload: " .. videoError)
				return
			end
			videoAssets, loading = assets, false
			core.ZIndex = math.max(core.ZIndex, 3)
			for _, item in ipairs(core:GetDescendants()) do
				if item:IsA("GuiObject") then item.ZIndex = math.max(item.ZIndex, 3) end
			end
			showVideoFrame(1)
			refresh()
		end)
	end
	local function step(dt)
		elapsed += math.min(math.max(dt, 0), .1)
		if activeKey == "Matrix" then
			local height = orbit.Size.Y.Offset > 0 and orbit.Size.Y.Offset or 576
			for _, stream in ipairs(streams) do
				stream.y += stream.speed * math.min(math.max(dt, 0), .1)
				if stream.y > height + 10 then
					stream.y = -stream.height - random:NextNumber(0, 180)
					stream.object.Text = characters(stream.rows)
				end
				stream.object.Position = UDim2.new(stream.x, 0, 0, stream.y)
			end


		elseif activeKey == "Inferno" and videoAssets then
			local duration = 1 / math.max(videoAssets.fps or 30, 1)
			videoAccumulator += math.min(math.max(dt, 0), .25)
			if videoAccumulator >= duration then
				local advance = math.floor(videoAccumulator / duration)
				videoAccumulator -= advance * duration
				videoFrame = ((videoFrame - 1 + advance) % videoAssets.frameCount) + 1
				showVideoFrame(videoFrame)
			end
		end
	end

	refresh = function()
		if stopped then return end
		local enabled = frame.Parent ~= nil and frame.Visible and (activeKey == "Matrix" or (activeKey == "Inferno" and videoAssets ~= nil))
		if matrixLayer then matrixLayer.Visible = enabled and activeKey == "Matrix" end
		if fireLayer then fireLayer.Visible = enabled and activeKey == "Inferno" end
		if enabled and not renderConnection then
			step(0)
			renderConnection = runService.RenderStepped:Connect(step)
		elseif not enabled and renderConnection then
			renderConnection:Disconnect()
			renderConnection = nil
		end
	end
	local controller = {}
	function controller.Apply(nextTheme)
		if stopped then return end
		theme = nextTheme or {}
		activeKey = theme.backgroundKey
		if activeKey == "Matrix" then createMatrix() elseif activeKey == "Inferno" then loadInferno() end
		core.BackgroundTransparency = activeKey == "Inferno" and .08 or coreTransparency
		for _, item in ipairs(core:GetDescendants()) do
			if item:IsA("TextLabel") then
				if not coreTextState[item] then coreTextState[item] = { item.TextStrokeColor3, item.TextStrokeTransparency } end
				local saved = coreTextState[item]
				item.TextStrokeColor3 = activeKey == "Inferno" and Color3.fromRGB(12, 5, 1) or saved[1]
				item.TextStrokeTransparency = activeKey == "Inferno" and .08 or saved[2]
			end
		end
		if coreStroke then
			coreStroke.Color = activeKey == "Inferno" and (theme.accent or theme.stroke or coreStroke.Color) or (theme.stroke or coreStroke.Color)
			coreStroke.Thickness = activeKey == "Inferno" and 1.4 or coreThickness
			coreStroke.Transparency = activeKey == "Inferno" and 0 or coreStrokeTransparency
		end
		refresh()
	end
	function controller.Destroy()
		if stopped then return end
		stopped = true
		if renderConnection then renderConnection:Disconnect(); renderConnection = nil end
		for _, connection in ipairs(lifecycle) do connection:Disconnect() end
		if matrixLayer then matrixLayer:Destroy() end
		if fireLayer then fireLayer:Destroy() end
		table.clear(videoImages)
	end
	function controller.Inspect()
		return { theme = activeKey, renderConnected = renderConnection ~= nil,
			streams = #streams, videoReady = videoAssets ~= nil, videoFrame = videoFrame, videoSheet = videoSheet,
			residentImages = #videoImages, loading = loading, videoError = videoError, destroyed = stopped }
	end
	lifecycle[1] = frame:GetPropertyChangedSignal("Visible"):Connect(refresh)
	lifecycle[2] = frame.Destroying:Connect(controller.Destroy)
	if context.theme then controller.Apply(context.theme) end
	return controller
end

local function installOrbitWindowMotion(context)
	local frame, service = context.frame, context.tweenService
	local baseSize, basePosition, baseRotation = frame.Size, frame.Position, frame.Rotation
	local baseAbsoluteSize = frame.AbsoluteSize
	local selectedStyle, moving, wanted, dead, started, generation = "Bubble",false,frame.Visible,false,false,0
	local motionTweens={}
	local api={LastFallback=nil,LastProxyCount=0}
	local function active(value)
		if context.setMotionActive then context.setMotionActive(value) end
	end
	local function stopTweens()
		for _,item in ipairs(motionTweens) do item:Cancel() end
		table.clear(motionTweens)
	end
	local function factor(value) context.scale.Scale=context.fitScale()*value end
	local function restore()
		frame.Size,frame.Position,frame.Rotation=baseSize,basePosition,baseRotation
		context.openFactor.Value=1
		factor(1)
	end
	local function dock()
		return UDim2.new(basePosition.X.Scale,basePosition.X.Offset-baseAbsoluteSize.X*.2,1,-22)
	end
	local function side()
		return UDim2.new(1,baseAbsoluteSize.X*frame.AnchorPoint.X+56,basePosition.Y.Scale,basePosition.Y.Offset)
	end
	local function startTween(object,duration,easing,direction,goals)
		local tween=service:Create(object,TweenInfo.new(duration,easing,direction),goals)
		table.insert(motionTweens,tween)
		return tween
	end
	function api.SetVisible(visible,onDone)
		if dead or not frame.Parent then return end
		visible=visible==true
		if started and not moving and frame.Visible==visible then
			wanted=visible
			if onDone then onDone(visible) end
			return
		end
		local wasMoving=moving
		local reveal=visible and (not frame.Visible or (not started and context.initialReveal))
		if not wasMoving then
			baseSize,basePosition,baseRotation=frame.Size,frame.Position,frame.Rotation
			baseAbsoluteSize=frame.AbsoluteSize
		end
		generation+=1;local token=generation
		stopTweens()
		started,wanted=true,visible
		local style=selectedStyle
		if style=="No Animation" then
			frame.Visible=visible
			restore();moving=false;active(false)
			if onDone then onDone(visible) end
			return
		end
		moving=true;active(true)
		frame.Visible=true
		if reveal and not wasMoving then
			frame.Size,frame.Rotation=baseSize,baseRotation
			if style=="Slide" then frame.Position=side();factor(1)
			elseif style=="Scale" then frame.Position=dock();factor(.035)
			else frame.Position=basePosition;factor(.08) end
		end
		local duration=style=="Bubble" and .23 or (visible and .39 or .28)
		local direction=visible and Enum.EasingDirection.Out or Enum.EasingDirection.In
		local easing=style=="Bubble" and Enum.EasingStyle.Quad or Enum.EasingStyle.Quint
		local master
		if style=="Slide" then
			master=startTween(frame,duration,easing,direction,{Position=visible and basePosition or side(),Rotation=baseRotation})
			startTween(context.scale,duration,easing,direction,{Scale=context.fitScale()})
		elseif style=="Scale" then
			master=startTween(frame,duration,easing,direction,{Position=visible and basePosition or dock(),Rotation=baseRotation})
			startTween(context.scale,duration,easing,direction,{Scale=context.fitScale()*(visible and 1 or .035)})
		else
			master=startTween(context.scale,duration,easing,direction,{Scale=context.fitScale()*(visible and 1 or .08)})
			if frame.Position~=basePosition or frame.Rotation~=baseRotation then
				startTween(frame,duration,easing,direction,{Position=basePosition,Rotation=baseRotation})
			end
		end
		master.Completed:Once(function(state)
			if dead or token~=generation or state~=Enum.PlaybackState.Completed then return end
			stopTweens()
			frame.Visible=visible
			restore();moving=false;active(false)
			if onDone then onDone(visible) end
		end)
		for _,item in ipairs(motionTweens) do item:Play() end
	end
	function api.Apply(style)
		selectedStyle=(style=="No Animation" or style=="Bubble" or style=="Scale" or style=="Slide") and style or "No Animation"
		return selectedStyle
	end
	function api.IsMoving() return moving end
	function api.Destroy()
		if dead then return end
		generation+=1;stopTweens()
		if frame.Parent then frame.Visible=wanted;restore() end
		moving=false;active(false);dead=true
	end
	return api
end

	if not activeMainUI then return end
