		ScreenGui.ResetOnSpawn = false
		ScreenGui.Parent = PlayerGui
		local Holder = Instance.new("Frame")
		Holder.Name = "Holder"
		Holder.AnchorPoint = Vector2.new(1, 1)
		Holder.Position = UDim2.new(1, -20, 1, -20)
		Holder.Size = UDim2.new(0, 360, 1, -40)
		Holder.BackgroundTransparency = 1
		Holder.Parent = ScreenGui
		local Layout = Instance.new("UIListLayout")
		Layout.Padding = UDim.new(0, 8)
		Layout.HorizontalAlignment = Enum.HorizontalAlignment.Right
		Layout.VerticalAlignment = Enum.VerticalAlignment.Bottom
		Layout.SortOrder = Enum.SortOrder.LayoutOrder
		Layout.Parent = Holder
		local Notifications = {}
		local Order = 0
		function Notifications:Notify(title, text, duration)
			duration = duration or 4
			Order += 1
			local Frame = Instance.new("Frame")
			Frame.Name = "Notification"
			Frame.LayoutOrder = Order
			Frame.Size = UDim2.new(1, 0, 0, 75)
			Frame.BackgroundColor3 = T.surface
			Frame.BackgroundTransparency = 0.05
			Frame.BorderSizePixel = 0
			Frame.Parent = Holder
			local Corner = Instance.new("UICorner")
			Corner.Parent = Frame
			local Stroke = Instance.new("UIStroke")
			Stroke.Color = T.accent
			Stroke.Thickness = 1.5
			Stroke.Transparency = 0.2
			Stroke.Parent = Frame
			local Accent = Instance.new("Frame")
			Accent.Size = UDim2.new(0, 4, 1, 0)
			Accent.BackgroundColor3 = T.accent
			Accent.BorderSizePixel = 0
			Accent.Parent = Frame
			local AccentCorner = Instance.new("UICorner")
			AccentCorner.Parent = Accent
			local Title = Instance.new("TextLabel")
			Title.BackgroundTransparency = 1
			Title.Position = UDim2.new(0, 16, 0, 10)
			Title.Size = UDim2.new(1, -30, 0, 22)
			Title.Font = Enum.Font.GothamBold
			Title.TextSize = 15
			Title.TextColor3 = T.text
			Title.TextXAlignment = Enum.TextXAlignment.Left
				Library.Localization.SetText(Title, title)
			Title.Parent = Frame
			local Body = Instance.new("TextLabel")
			Body.BackgroundTransparency = 1
			Body.Position = UDim2.new(0, 16, 0, 35)
			Body.Size = UDim2.new(1, -30, 0, 25)
			Body.Font = Enum.Font.Gotham
			Body.TextSize = 13
			Body.TextColor3 = T.textDim
			Body.TextXAlignment = Enum.TextXAlignment.Left
				Library.Localization.SetText(Body, text)
			Body.Parent = Frame
			Frame.Position = UDim2.new(1, 400, 0, 0)
			TweenService:Create(
				Frame,
				TweenInfo.new(0.35, Enum.EasingStyle.Quart, Enum.EasingDirection.Out),
				{ Position = UDim2.new(0, 0, 0, 0) }
			):Play()
			task.delay(duration, function()
				local Tween = TweenService:Create(
					Frame,
					TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.In),
					{ Position = UDim2.new(1, 400, 0, 0), BackgroundTransparency = 1 }
				)
				Tween:Play()
				for _, v in ipairs(Frame:GetDescendants()) do
					if v:IsA("TextLabel") then
						TweenService:Create(v, TweenInfo.new(0.25), { TextTransparency = 1 }):Play()
					elseif v:IsA("UIStroke") then
						TweenService:Create(v, TweenInfo.new(0.25), { Transparency = 1 }):Play()
					elseif v:IsA("Frame") then
						TweenService:Create(v, TweenInfo.new(0.25), { BackgroundTransparency = 1 }):Play()
					end
				end
				Tween.Completed:Wait()
				Frame:Destroy()
			end)
		end
		Notifications:Notify(
			"TheBest Loaded!",
			"Press '" .. tostring(_G.Keybinds and _G.Keybinds.OpenMenu or "Delete") .. "' to open the public menu.",
			6
		)
		end)
	end
end)(...)

local totalStartupSeconds = time() - (_G.TheBestStartedAt or time())
_G.TheBestStartupSeconds = totalStartupSeconds
pcall(function()
	if writefile then
		writefile("thebest/startup-timing.txt", ("total_startup_seconds=%.3f"):format(totalStartupSeconds))
	end
end)
